export type ClineTokenResolution = {
	forceRefresh?: boolean;
	refreshBufferMs?: number;
	retryableTokenGraceMs?: number;
};

interface ClineAuthApiUser {
	subject: string | null;
	email: string;
	name: string;
	clineUserId: string | null;
	accounts: string[] | null;
}

interface ClineAuthResponseData {
	accessToken: string;
	refreshToken?: string;
	tokenType: string;
	expiresAt: string;
	userInfo: ClineAuthApiUser;
}

type ClineTokenResponse = {
	success: boolean;
	data: ClineAuthResponseData;
};

type HeaderMap = Record<string, string>;
type HeaderInput = HeaderMap | (() => Promise<HeaderMap> | HeaderMap);

type AuthTokenTelemetryClaims = {
	sessionId?: string;
};

type AuthCredentialTelemetryProperties = {
	sessionDurationMs?: number;
};

type AuthTelemetryDetails = AuthTokenTelemetryClaims &
	AuthCredentialTelemetryProperties;

export interface ClineOAuthProviderOptions {
	apiBaseUrl: string;
	headers?: HeaderInput;
	requestTimeoutMs?: number;
	telemetry?: ITelemetryService;
	useWorkOSDeviceAuth?: boolean;
	callbackPath?: string;
	callbackPorts?: number[];
	/**
	 * Optional identity provider name for token exchange.
	 */
	provider?: string;
}

export interface ClineOAuthCredentials extends OAuthCredentials {
	metadata?: {
		provider?: string;
		tokenType?: string;
		userInfo?: ClineAuthApiUser;
		[key: string]: unknown;
	};
}

class ClineOAuthTokenError extends Error {
	public readonly status?: number;
	public readonly errorCode?: string;
	public readonly requestId?: string;

	constructor(
		message: string,
		opts?: { status?: number; errorCode?: string; requestId?: string },
	) {
		super(message);
		this.name = "ClineOAuthTokenError";
		this.status = opts?.status;
		this.errorCode = opts?.errorCode;
		this.requestId = opts?.requestId;
	}

	public isLikelyInvalidGrant(): boolean {
		if (
			this.errorCode &&
			/invalid_grant|invalid_token|unauthorized/i.test(this.errorCode)
		) {
			return true;
		}
		if (this.status === 400 || this.status === 401 || this.status === 403) {
			return /invalid|expired|revoked|unauthorized/i.test(this.message);
		}
		return false;
	}
}

function toEpochMs(isoDateTime: string): number {
	const epoch = Date.parse(isoDateTime);
	if (Number.isNaN(epoch)) {
		throw new Error(`Invalid expiresAt value: ${isoDateTime}`);
	}
	return epoch;
}

function toClineCredentials(
	responseData: ClineAuthResponseData,
	provider: string | undefined,
	fallback: Partial<ClineOAuthCredentials> = {},
): ClineOAuthCredentials {
	const accountId = responseData.userInfo.clineUserId ?? fallback.accountId;
	const refreshToken = responseData.refreshToken ?? fallback.refresh;
	if (!refreshToken) {
		throw new Error("Token response did not include a refresh token");
	}
	const metadata: Record<string, unknown> = {
		...(fallback.metadata ?? {}),
		provider,
		tokenType: responseData.tokenType,
		userInfo: responseData.userInfo,
	};
	delete metadata.startedAt;

	return {
		access: responseData.accessToken,
		refresh: refreshToken,
		expires: toEpochMs(responseData.expiresAt),
		accountId: accountId ?? undefined,
		email: responseData.userInfo.email || fallback.email,
		metadata,
	};
}

async function resolveHeaders(input?: HeaderInput): Promise<HeaderMap> {
	if (!input) {
		return {};
	}
	return typeof input === "function" ? await input() : input;
}

function toSeconds(value: unknown, fallback: number): number {
	if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
		return fallback;
	}
	return Math.floor(value);
}

function asNonEmptyString(value: unknown): string | undefined {
	return (typeof value === "string" && value.trim()) || undefined;
}

function getAuthTokenTelemetryClaims(token: string): AuthTokenTelemetryClaims {
	const payload = decodeJwtPayload(token);
	if (!payload) {
		return {};
	}

	return {
		sessionId: asNonEmptyString(payload.sid),
	};
}

function getAuthCredentialTelemetryProperties(
	credentials: ClineOAuthCredentials,
): AuthCredentialTelemetryProperties {
	const authProperties: AuthCredentialTelemetryProperties = {};

	const sessionStartedAtMs = credentials.metadata?.sessionStartedAtMs;

	if (
		typeof sessionStartedAtMs === "number" &&
		Number.isFinite(sessionStartedAtMs) &&
		sessionStartedAtMs > 0
	) {
		authProperties.sessionDurationMs = Date.now() - sessionStartedAtMs;
	}

	return authProperties;
}

function getAuthTelemetryDetails(
	credentials: ClineOAuthCredentials,
): AuthTelemetryDetails {
	return {
		...getAuthTokenTelemetryClaims(credentials.access),
		...getAuthCredentialTelemetryProperties(credentials),
	};
}

async function sleep(ms: number): Promise<void> {
	await new Promise((resolve) => setTimeout(resolve, ms));
}

type WorkOSDeviceAuthorizationResponse = {
	device_code?: string;
	user_code?: string;
	verification_uri?: string;
	verification_uri_complete?: string;
	expires_in?: number;
	interval?: number;
	error?: string;
	error_description?: string;
};

type WorkOSTokenResponse = {
	access_token?: string;
	refresh_token?: string;
	token_type?: string;
	expires_in?: number;
	error?: string;
	error_description?: string;
};

type WorkOSTokenSuccess = {
	accessToken: string;
	refreshToken: string;
	tokenType: string;
};

function requireClineTokenResponse(
	payload: ClineTokenResponse,
	message: string,
): ClineAuthResponseData {
	if (!payload.success || !payload.data?.accessToken) {
		throw new Error(message);
	}
	return payload.data;
}

async function requestWorkOSDeviceAuthorization(
	clientId: string,
	options?: { requestTimeoutMs?: number },
): Promise<{
	deviceCode: string;
	userCode: string;
	verificationUri: string;
	verificationUriComplete?: string;
	expiresInSeconds: number;
	pollIntervalSeconds: number;
}> {
	const response = await fetch(
		resolveUrl(
			DEFAULT_WORKOS_API_BASE_URL,
			DEFAULT_WORKOS_ENDPOINTS.deviceAuthorization,
		),
		{
			method: "POST",
			headers: {
				"Content-Type": "application/x-www-form-urlencoded",
			},
			body: new URLSearchParams({ client_id: clientId }),
			signal: AbortSignal.timeout(
				options?.requestTimeoutMs ?? DEFAULT_HTTP_TIMEOUT_MS,
			),
		},
	);

	const json = (await response
		.json()
		.catch(() => ({}))) as WorkOSDeviceAuthorizationResponse;
	if (!response.ok) {
		throw new ClineOAuthTokenError(
			`Device authorization failed: ${response.status}${json.error_description ? ` - ${json.error_description}` : ""}`,
			{
				status: response.status,
				errorCode: json.error,
				requestId: response.headers.get("x-request-id") ?? undefined,
			},
		);
	}
	if (!json.device_code || !json.user_code || !json.verification_uri) {
		throw new Error("Invalid WorkOS device authorization response");
	}

	return {
		deviceCode: json.device_code,
		userCode: json.user_code,
		verificationUri: json.verification_uri,
		verificationUriComplete: json.verification_uri_complete,
		expiresInSeconds: toSeconds(
			json.expires_in,
			DEFAULT_DEVICE_AUTH_EXPIRES_IN_SECONDS,
		),
		pollIntervalSeconds: toSeconds(
			json.interval,
			DEFAULT_DEVICE_AUTH_INTERVAL_SECONDS,
		),
	};
}

async function pollWorkOSTokens(options: {
	clientId: string;
	deviceCode: string;
	expiresInSeconds: number;
	initialPollIntervalSeconds: number;
	requestTimeoutMs: number;
	workosApiBaseUrl: string;
	onProgress?: OAuthLoginCallbacks["onProgress"];
}): Promise<WorkOSTokenSuccess> {
	const deadline = Date.now() + options.expiresInSeconds * 1000;
	let intervalSeconds = Math.max(1, options.initialPollIntervalSeconds);

	while (Date.now() <= deadline) {
		const response = await fetch(
			resolveUrl(
				options.workosApiBaseUrl,
				DEFAULT_WORKOS_ENDPOINTS.authenticate,
			),
			{
				method: "POST",
				headers: {
					"Content-Type": "application/x-www-form-urlencoded",
				},
				body: new URLSearchParams({
					grant_type: "urn:ietf:params:oauth:grant-type:device_code",
					device_code: options.deviceCode,
					client_id: options.clientId,
				}),
				signal: AbortSignal.timeout(options.requestTimeoutMs),
			},
		);
		const payload = (await response
			.json()
			.catch(() => ({}))) as WorkOSTokenResponse;
		if (response.ok) {
			if (!payload.access_token || !payload.refresh_token) {
				throw new Error("Invalid WorkOS token response");
			}
			return {
				accessToken: payload.access_token,
				refreshToken: payload.refresh_token,
				tokenType: payload.token_type ?? "Bearer",
			};
		}

		switch (payload.error) {
			case "authorization_pending": {
				await sleep(intervalSeconds * 1000);
				break;
			}
			case "slow_down": {
				intervalSeconds += 1;
				await sleep(intervalSeconds * 1000);
				break;
			}
			case "access_denied":
			case "expired_token":
			case "invalid_grant": {
				throw new ClineOAuthTokenError(
					payload.error_description || "WorkOS authorization failed",
					{
						status: response.status,
						errorCode: payload.error,
						requestId: response.headers.get("x-request-id") ?? undefined,
					},
				);
			}
			default: {
				throw new ClineOAuthTokenError(
					`WorkOS token polling failed: ${response.status}${payload.error_description ? ` - ${payload.error_description}` : ""}`,
					{
						status: response.status,
						errorCode: payload.error,
						requestId: response.headers.get("x-request-id") ?? undefined,
					},
				);
			}
		}

		options.onProgress?.("Waiting for browser authentication confirmation...");
	}

	throw new Error("WorkOS device authorization timed out");
}

async function registerWorkOSTokens(
	workosTokens: WorkOSTokenSuccess,
	options: ClineOAuthProviderOptions,
	provider?: string,
): Promise<ClineOAuthCredentials> {
	const body = {
		accessToken: workosTokens.accessToken,
		refreshToken: workosTokens.refreshToken,
	};

	const response = await fetch(
		resolveUrl(options.apiBaseUrl, DEFAULT_AUTH_ENDPOINTS.register),
		{
			method: "POST",
			headers: {
				"Content-Type": "application/json",
				...(await resolveHeaders(options.headers)),
			},
			body: JSON.stringify(body),
			signal: AbortSignal.timeout(
				options.requestTimeoutMs ?? DEFAULT_HTTP_TIMEOUT_MS,
			),
		},
	);

	if (!response.ok) {
		const text = await response.text().catch(() => "");
		const details = parseOAuthError(text);
		throw new ClineOAuthTokenError(
			`Token registration failed: ${response.status}${details.message ? ` - ${details.message}` : ""}`,
			{
				status: response.status,
				errorCode: details.code,
				requestId: response.headers.get("x-request-id") ?? undefined,
			},
		);
	}

	const json = (await response.json()) as ClineTokenResponse;
	return toClineCredentials(
		requireClineTokenResponse(json, "Invalid token exchange response"),
		provider ?? options.provider,
		{ metadata: { sessionStartedAtMs: Date.now() } },
	);
}

async function exchangeAuthorizationCode(
	code: string,
	callbackUrl: string,
	options: ClineOAuthProviderOptions,
	provider?: string,
): Promise<ClineOAuthCredentials> {
	const body = {
		grant_type: "authorization_code",
		code,
		client_type: "extension",
		redirect_uri: callbackUrl,
		provider: provider ?? options.provider,
	};

	const response = await fetch(
		resolveUrl(options.apiBaseUrl, DEFAULT_AUTH_ENDPOINTS.token),
		{
			method: "POST",
			headers: {
				"Content-Type": "application/json",
				...(await resolveHeaders(options.headers)),
			},
			body: JSON.stringify(body),
			signal: AbortSignal.timeout(
				options.requestTimeoutMs ?? DEFAULT_HTTP_TIMEOUT_MS,
			),
		},
	);

	if (!response.ok) {
		const text = await response.text().catch(() => "");
		const details = parseOAuthError(text);
		throw new ClineOAuthTokenError(
			`Token exchange failed: ${response.status}${details.message ? ` - ${details.message}` : ""}`,
			{
				status: response.status,
				errorCode: details.code,
				requestId: response.headers.get("x-request-id") ?? undefined,
			},
		);
	}

	const json = (await response.json()) as ClineTokenResponse;
	return toClineCredentials(
		requireClineTokenResponse(json, "Invalid token exchange response"),
		provider ?? options.provider,
		{ metadata: { sessionStartedAtMs: Date.now() } },
	);
}

export async function loginClineOAuth(
	options: ClineOAuthProviderOptions & {
		callbacks: OAuthLoginCallbacks;
	},
): Promise<ClineOAuthCredentials> {
	captureAuthStarted(options.telemetry, options.provider ?? "cline");
	const useWorkOSDeviceAuth = options.useWorkOSDeviceAuth ?? true;
	const callbackPorts = options.callbackPorts?.length
		? options.callbackPorts
		: DEFAULT_CALLBACK_PORTS;
	const callbackPath = options.callbackPath ?? DEFAULT_CALLBACK_PATH;
	const localServer = useWorkOSDeviceAuth
		? null
		: await startLocalOAuthServer({
				ports: callbackPorts,
				callbackPath,
				onListening: options.callbacks.onServerListening,
				onClose: options.callbacks.onServerClose,
			});
	const callbackUrl =
		localServer?.callbackUrl ||
		`http://127.0.0.1:${callbackPorts[0] ?? DEFAULT_CALLBACK_PORTS[0]}${callbackPath}`;

	try {
		let credentials: ClineOAuthCredentials;
		if (useWorkOSDeviceAuth) {
			const clientId = getClineEnvironmentConfig().workOsClientId;
			const deviceAuthorization = await requestWorkOSDeviceAuthorization(
				clientId,
				options,
			);
			options.callbacks.onAuth({
				url:
					deviceAuthorization.verificationUriComplete ??
					deviceAuthorization.verificationUri,
				instructions: `Enter this code in your browser: ${deviceAuthorization.userCode}`,
			});

			const workosTokens = await pollWorkOSTokens({
				clientId,
				deviceCode: deviceAuthorization.deviceCode,
				expiresInSeconds: deviceAuthorization.expiresInSeconds,
				initialPollIntervalSeconds: deviceAuthorization.pollIntervalSeconds,
				requestTimeoutMs: options.requestTimeoutMs ?? DEFAULT_HTTP_TIMEOUT_MS,
				workosApiBaseUrl: DEFAULT_WORKOS_API_BASE_URL,
				onProgress: options.callbacks.onProgress,
			});

			credentials = await registerWorkOSTokens(
				workosTokens,
				options,
				options.provider,
			);
		} else {
			const authUrl = new URL(
				resolveUrl(options.apiBaseUrl, DEFAULT_AUTH_ENDPOINTS.authorize),
			);
			authUrl.searchParams.set("client_type", "extension");
			authUrl.searchParams.set("callback_url", callbackUrl);
			authUrl.searchParams.set("redirect_uri", callbackUrl);
			options.callbacks.onAuth({
				url: authUrl.toString(),
				instructions: "Continue the authentication process in your browser.",
			});

			let code: string | undefined;
			let provider = options.provider;
			const authResult = await resolveAuthorizationCodeInput({
				waitForCallback: localServer?.waitForCallback ?? (async () => null),
				cancelWait: localServer?.cancelWait ?? (() => {}),
				onManualCodeInput: options.callbacks.onManualCodeInput,
				parseOptions: { includeProvider: true },
			});
			if (authResult.error) {
				throw new Error(`OAuth error: ${authResult.error}`);
			}
			code = authResult.code;
			provider = authResult.provider ?? provider;
			if (!code) {
				const input = await options.callbacks.onPrompt({
					message: "Paste the authorization code (or full redirect URL):",
				});
				const parsed = parseAuthorizationInput(input, {
					includeProvider: true,
				});
				code = parsed.code;
				provider = parsed.provider ?? provider;
			}
			if (!code) {
				throw new Error("Missing authorization code");
			}
			credentials = await exchangeAuthorizationCode(
				code,
				callbackUrl,
				options,
				provider,
			);
		}

		captureAuthSucceeded(
			options.telemetry,
			options.provider ?? "cline",
			getAuthTelemetryDetails(credentials),
		);
		identifyAccount(options.telemetry, {
			id: credentials.accountId,
			email: credentials.email,
			provider: options.provider ?? "cline",
		});
		return credentials;
	} catch (error) {
		captureAuthFailed(
			options.telemetry,
			options.provider ?? "cline",
			error instanceof Error ? error.message : String(error),
			{
				requestId:
					error instanceof ClineOAuthTokenError ? error.requestId : undefined,
			},
		);
		throw error;
	} finally {
		localServer?.close();
	}
}

export async function startClineDeviceAuth(options?: {
	requestTimeoutMs?: number;
}): Promise<{
	deviceCode: string;
	userCode: string;
	verificationUri: string;
	verificationUriComplete?: string;
	expiresInSeconds: number;
	pollIntervalSeconds: number;
}> {
	return await requestWorkOSDeviceAuthorization(
		getClineEnvironmentConfig().workOsClientId,
		options,
	);
}

export async function completeClineDeviceAuth(options: {
	deviceCode: string;
	expiresInSeconds: number;
	pollIntervalSeconds: number;
	apiBaseUrl: string;
	provider?: string;
	headers?: HeaderInput;
	requestTimeoutMs?: number;
	telemetry?: ITelemetryService;
}): Promise<ClineOAuthCredentials> {
	const providerName = options.provider ?? "cline";
	captureAuthStarted(options.telemetry, providerName);
	try {
		const workosTokens = await pollWorkOSTokens({
			clientId: getClineEnvironmentConfig().workOsClientId,
			deviceCode: options.deviceCode,
			expiresInSeconds: options.expiresInSeconds,
			initialPollIntervalSeconds: options.pollIntervalSeconds,
			requestTimeoutMs: options.requestTimeoutMs ?? DEFAULT_HTTP_TIMEOUT_MS,
			workosApiBaseUrl: DEFAULT_WORKOS_API_BASE_URL,
		});
		const credentials = await registerWorkOSTokens(
			workosTokens,
			{
				apiBaseUrl: options.apiBaseUrl,
				headers: options.headers,
				requestTimeoutMs: options.requestTimeoutMs,
				provider: options.provider,
			},
			options.provider,
		);
		captureAuthSucceeded(
			options.telemetry,
			providerName,
			getAuthTelemetryDetails(credentials),
		);
		identifyAccount(options.telemetry, {
			id: credentials.accountId,
			email: credentials.email,
			provider: providerName,
		});
		return credentials;
	} catch (error) {
		captureAuthFailed(
			options.telemetry,
			providerName,
			error instanceof Error ? error.message : String(error),
			{
				requestId:
					error instanceof ClineOAuthTokenError ? error.requestId : undefined,
			},
		);
		throw error;
	}
}

export async function refreshClineToken(
	current: ClineOAuthCredentials,
	options: ClineOAuthProviderOptions,
): Promise<ClineOAuthCredentials> {
	const refreshUrl = resolveUrl(
		options.apiBaseUrl,
		DEFAULT_AUTH_ENDPOINTS.refresh,
	);
	sdkDebug(
		`cline.refresh.request url=${refreshUrl} refreshTokenHash=${hashSecret(current.refresh)}`,
	);
	const response = await fetch(refreshUrl, {
		method: "POST",
		headers: {
			"Content-Type": "application/json",
			...(await resolveHeaders(options.headers)),
		},
		body: JSON.stringify({
			refreshToken: current.refresh,
			grantType: "refresh_token",
		}),
		signal: AbortSignal.timeout(
			options.requestTimeoutMs ?? DEFAULT_HTTP_TIMEOUT_MS,
		),
	});

	if (!response.ok) {
		const text = await response.text().catch(() => "");
		const details = parseOAuthError(text);
		const requestId = response.headers.get("x-request-id") ?? undefined;
		sdkDebug(
			`cline.refresh.error status=${response.status} errorCode=${details.code ?? "none"} message=${details.message ?? "none"} requestId=${requestId ?? "none"}`,
		);
		throw new ClineOAuthTokenError(
			`Token refresh failed: ${response.status}${details.message ? ` - ${details.message}` : ""}`,
			{ status: response.status, errorCode: details.code, requestId },
		);
	}

	const json = (await response.json()) as ClineTokenResponse;
	const provider =
		(current.metadata?.provider as string | undefined) ?? options.provider;
	const result = toClineCredentials(
		requireClineTokenResponse(json, "Invalid token refresh response"),
		provider,
		current,
	);
	sdkDebug(
		`cline.refresh.success newAccessTokenHash=${hashSecret(result.access)} newRefreshTokenHash=${hashSecret(result.refresh)} expires=${result.expires}`,
	);
	return result;
}

/**
 * Resolve valid Cline credentials, refreshing when needed.
 *
 * Contract: returns refreshed/current credentials when usable; returns `null`
 * ONLY when the refresh token was rejected (invalid grant — re-auth required);
 * THROWS on transient failures (network, timeout, 5xx) so callers can leave
 * stored credentials untouched and retry later.
 */
export async function getValidClineCredentials(
	currentCredentials: ClineOAuthCredentials | null,
	providerOptions: ClineOAuthProviderOptions,
	options?: ClineTokenResolution,
): Promise<ClineOAuthCredentials | null> {
	if (!currentCredentials) {
		sdkDebug("cline.getCredentials outcome=no_current_credentials");
		return null;
	}

	const refreshBufferMs = options?.refreshBufferMs ?? DEFAULT_REFRESH_BUFFER_MS;
	const retryableTokenGraceMs =
		options?.retryableTokenGraceMs ?? DEFAULT_RETRYABLE_TOKEN_GRACE_MS;
	const forceRefresh = options?.forceRefresh === true;

	if (
		!forceRefresh &&
		!isCredentialLikelyExpired(currentCredentials, refreshBufferMs)
	) {
		sdkDebug(
			`cline.getCredentials outcome=still_valid forceRefresh=${forceRefresh}`,
		);
		return currentCredentials;
	}

	sdkDebug(
		`cline.getCredentials outcome=needs_refresh forceRefresh=${forceRefresh} accessTokenHash=${hashSecret(currentCredentials.access)}`,
	);

	try {
		return await refreshClineToken(currentCredentials, providerOptions);
	} catch (error) {
		const authTelemetryDetails = getAuthTelemetryDetails(currentCredentials);
		const requestIdDetails =
			error instanceof ClineOAuthTokenError && error.requestId
				? { request_id: error.requestId }
				: {};
		const failureDetails = {
			status: error instanceof ClineOAuthTokenError ? error.status : undefined,
			errorCode:
				error instanceof ClineOAuthTokenError ? error.errorCode : undefined,
			...requestIdDetails,
			...authTelemetryDetails,
			errorName: error instanceof Error ? error.name : undefined,
		};
		if (error instanceof ClineOAuthTokenError && error.isLikelyInvalidGrant()) {
			sdkDebug(
				`cline.getCredentials outcome=invalid_grant status=${error.status} errorCode=${error.errorCode ?? "none"}`,
			);
			captureAuthLoggedOut(
				providerOptions.telemetry,
				providerOptions.provider ?? "cline",
				"invalid_grant",
				{
					status: error.status,
					errorCode: error.errorCode,
					...requestIdDetails,
					...authTelemetryDetails,
				},
			);
			return null;
		}
		if (currentCredentials.expires - Date.now() > retryableTokenGraceMs) {
			// Keep current token on transient refresh failures while still valid.
			sdkDebug(
				`cline.getCredentials outcome=transient_failure_kept_current error=${error instanceof Error ? error.message : String(error)}`,
			);
			captureAuthRefreshSoftFailure(
				providerOptions.telemetry,
				providerOptions.provider ?? "cline",
				{ ...failureDetails, tokenExpired: false },
			);
			return currentCredentials;
		}
		// Transient failure with an already-expired token: rethrow instead of
		// returning null. A null from this function means the refresh token was
		// REJECTED (re-auth required); a network blip that happens to land after
		// expiry must not be mistaken for that — callers were wiping stored
		// credentials over it, logging out every Cline process on the machine.
		sdkDebug(
			`cline.getCredentials outcome=transient_failure_rethrown error=${error instanceof Error ? error.message : String(error)}`,
		);
		// Every one of these events was a hard logout before the
		// transient-vs-invalid_grant fix — the "prevented logout" counter.
		captureAuthRefreshSoftFailure(
			providerOptions.telemetry,
			providerOptions.provider ?? "cline",
			{ ...failureDetails, tokenExpired: true },
		);
		throw error;
	}
}

import { afterEach, describe, expect, it, vi } from "vitest";
import {
	getValidOpenAICodexCredentials,
	refreshOpenAICodexToken,
} from "./codex";
import type { OAuthCredentials } from "./types";

function toBase64Url(value: string): string {
	return Buffer.from(value, "utf8").toString("base64url");
}

function createJwt(payload: Record<string, unknown>): string {
	return `${toBase64Url(JSON.stringify({ alg: "none", typ: "JWT" }))}.${toBase64Url(JSON.stringify(payload))}.sig`;
}

function createCredentials(
	overrides: Partial<OAuthCredentials> = {},
): OAuthCredentials {
	return {
		access: "access-old",
		refresh: "refresh-old",
		expires: 0,
		accountId: "acct-old",
		email: "old@example.com",
		metadata: { provider: "openai-codex" },
		...overrides,
	};
}

describe("auth/codex token lifecycle", () => {
	afterEach(() => {
		vi.unstubAllGlobals();
		vi.restoreAllMocks();
	});

	it("returns current credentials when not expired", async () => {
		const nowSpy = vi.spyOn(Date, "now").mockReturnValue(10_000);
		const current = createCredentials({ expires: 400_000 });
		const fetchMock = vi.fn();
		vi.stubGlobal("fetch", fetchMock);

		const result = await getValidOpenAICodexCredentials(current);
		expect(result).toBe(current);
		expect(fetchMock).not.toHaveBeenCalled();
		nowSpy.mockRestore();
	});

	it("refreshes expired credentials and preserves provider metadata", async () => {
		const nowSpy = vi.spyOn(Date, "now").mockReturnValue(100_000);
		const idToken = createJwt({
			"https://api.openai.com/auth": { chatgpt_account_id: "acct-new" },
			email: "new@example.com",
		});
		const accessToken = createJwt({
			"https://api.openai.com/auth": { chatgpt_account_id: "acct-new" },
		});
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						JSON.stringify({
							access_token: accessToken,
							refresh_token: "refresh-new",
							expires_in: 3600,
							email: "new@example.com",
							id_token: idToken,
						}),
						{ status: 200, headers: { "Content-Type": "application/json" } },
					),
			),
		);

		const current = createCredentials({ expires: 110_000 });
		const result = await getValidOpenAICodexCredentials(current);
		expect(result).toMatchObject({
			access: accessToken,
			refresh: "refresh-new",
			accountId: "acct-new",
			email: "new@example.com",
			metadata: { provider: "openai-codex" },
		});
		nowSpy.mockRestore();
	});

	it("returns null on invalid_grant refresh errors", async () => {
		const nowSpy = vi.spyOn(Date, "now").mockReturnValue(100_000);
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						JSON.stringify({
							error: "invalid_grant",
							error_description: "token revoked",
						}),
						{
							status: 400,
							headers: { "Content-Type": "application/json" },
						},
					),
			),
		);

		const result = await getValidOpenAICodexCredentials(
			createCredentials({ expires: 120_000 }),
		);
		expect(result).toBeNull();
		nowSpy.mockRestore();
	});

	it("keeps current credentials on non-invalid transient refresh failures when still valid", async () => {
		const nowSpy = vi.spyOn(Date, "now").mockReturnValue(100_000);
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						JSON.stringify({
							error: "server_error",
							error_description: "try again",
						}),
						{
							status: 500,
							headers: { "Content-Type": "application/json" },
						},
					),
			),
		);

		const current = createCredentials({ expires: 150_000 });
		const result = await getValidOpenAICodexCredentials(current, {
			refreshBufferMs: 60_000,
			retryableTokenGraceMs: 30_000,
		});
		expect(result).toBe(current);
		nowSpy.mockRestore();
	});

	it("refreshOpenAICodexToken throws when response is structurally invalid", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(JSON.stringify({ access_token: "only-access" }), {
						status: 200,
						headers: { "Content-Type": "application/json" },
					}),
			),
		);

		await expect(refreshOpenAICodexToken("refresh")).rejects.toThrow(
			"Failed to refresh OpenAI Codex token",
		);
	});
});

/**
 * OpenAI Codex (ChatGPT OAuth) flow
 *
 * NOTE: This module uses Node.js crypto and http for the OAuth callback.
 * It is only intended for CLI use, not browser environments.
 */

import { decodeJwtPayload, type ITelemetryService } from "@cline/shared";
import { nanoid } from "nanoid";
import {
	captureAuthFailed,
	captureAuthLoggedOut,
	captureAuthStarted,
	captureAuthSucceeded,
	identifyAccount,
} from "../services/telemetry/core-events";
import { startLocalOAuthServer } from "./server";
import type { OAuthCredentials, OAuthPrompt } from "./types";
import {
	getProofKey,
	isCredentialLikelyExpired,
	parseAuthorizationInput,
	parseOAuthError,
	resolveAuthorizationCodeInput,
} from "./utils";

export const OPENAI_CODEX_OAUTH_CONFIG = {
	authorizationEndpoint: "https://auth.openai.com/oauth/authorize",
	tokenEndpoint: "https://auth.openai.com/oauth/token",
	clientId: "app_EMoamEEZ73f0CkXaXp7hrann",
	redirectUri: "http://localhost:1455/auth/callback",
	scopes: "openid profile email offline_access",
	callbackPort: 1455,
	jwtClaimPath: "https://api.openai.com/auth",
	refreshBufferMs: 5 * 60 * 1000,
	retryableTokenGraceMs: 30 * 1000,
	httpTimeoutMs: 30 * 1000,
} as const;

type CodexTokenSuccess = {
	type: "success";
	access: string;
	refresh: string;
	expires: number;
	email?: string;
	idToken?: string;
};
type CodexTokenFailure = { type: "failed" };
type CodexTokenResult = CodexTokenSuccess | CodexTokenFailure;
export type RefreshTokenResolution = {
	forceRefresh?: boolean;
	refreshBufferMs?: number;
	retryableTokenGraceMs?: number;
};

type JwtPayload = {
	[OPENAI_CODEX_OAUTH_CONFIG.jwtClaimPath]?: {
		chatgpt_account_id?: string;
	};
	[key: string]: unknown;
};

class OpenAICodexOAuthTokenError extends Error {
	public readonly status?: number;
	public readonly errorCode?: string;

	constructor(message: string, opts?: { status?: number; errorCode?: string }) {
		super(message);
		this.name = "OpenAICodexOAuthTokenError";
		this.status = opts?.status;
		this.errorCode = opts?.errorCode;
	}

	public isLikelyInvalidGrant(): boolean {
		if (this.errorCode && /invalid_grant/i.test(this.errorCode)) {
			return true;
		}
		if (this.status === 400 || this.status === 401 || this.status === 403) {
			return /invalid_grant|revoked|expired|invalid refresh/i.test(
				this.message,
			);
		}
		return false;
	}
}

async function exchangeAuthorizationCode(
	code: string,
	verifier: string,
	redirectUri: string = OPENAI_CODEX_OAUTH_CONFIG.redirectUri,
): Promise<CodexTokenResult> {
	const response = await fetch(OPENAI_CODEX_OAUTH_CONFIG.tokenEndpoint, {
		method: "POST",
		headers: { "Content-Type": "application/x-www-form-urlencoded" },
		body: new URLSearchParams({
			grant_type: "authorization_code",
			client_id: OPENAI_CODEX_OAUTH_CONFIG.clientId,
			code,
			code_verifier: verifier,
			redirect_uri: redirectUri,
		}),
		signal: AbortSignal.timeout(OPENAI_CODEX_OAUTH_CONFIG.httpTimeoutMs),
	});

	if (!response.ok) {
		return { type: "failed" };
	}

	const json = (await response.json()) as {
		access_token?: string;
		refresh_token?: string;
		expires_in?: number;
		email?: string;
		id_token?: string;
	};

	if (
		!json.access_token ||
		!json.refresh_token ||
		typeof json.expires_in !== "number"
	) {
		return { type: "failed" };
	}

	return {
		type: "success",
		access: json.access_token,
		refresh: json.refresh_token,
		expires: Date.now() + json.expires_in * 1000,
		email: json.email,
		idToken: json.id_token,
	};
}

async function refreshAccessToken(
	refreshToken: string,
): Promise<CodexTokenResult> {
	try {
		const response = await fetch(OPENAI_CODEX_OAUTH_CONFIG.tokenEndpoint, {
			method: "POST",
			headers: { "Content-Type": "application/x-www-form-urlencoded" },
			body: new URLSearchParams({
				grant_type: "refresh_token",
				refresh_token: refreshToken,
				client_id: OPENAI_CODEX_OAUTH_CONFIG.clientId,
			}),
			signal: AbortSignal.timeout(OPENAI_CODEX_OAUTH_CONFIG.httpTimeoutMs),
		});

		if (!response.ok) {
			const text = await response.text().catch(() => "");
			const details = parseOAuthError(text);
			throw new OpenAICodexOAuthTokenError(
				`Token refresh failed: ${response.status}${details.message ? ` - ${details.message}` : ""}`,
				{ status: response.status, errorCode: details.code },
			);
		}

		const json = (await response.json()) as {
			access_token?: string;
			refresh_token?: string;
			expires_in?: number;
			email?: string;
			id_token?: string;
		};

		if (
			!json.access_token ||
			!json.refresh_token ||
			typeof json.expires_in !== "number"
		) {
			return { type: "failed" };
		}

		return {
			type: "success",
			access: json.access_token,
			refresh: json.refresh_token,
			expires: Date.now() + json.expires_in * 1000,
			email: json.email,
			idToken: json.id_token,
		};
	} catch (error) {
		if (error instanceof OpenAICodexOAuthTokenError) {
			throw error;
		}
		return { type: "failed" };
	}
}

async function createAuthorizationFlow(
	originator = "pi",
): Promise<{ verifier: string; state: string; url: string }> {
	const { verifier, challenge } = await getProofKey();
	const state = nanoid(32);

	const url = new URL(OPENAI_CODEX_OAUTH_CONFIG.authorizationEndpoint);
	url.searchParams.set("response_type", "code");
	url.searchParams.set("client_id", OPENAI_CODEX_OAUTH_CONFIG.clientId);
	url.searchParams.set("redirect_uri", OPENAI_CODEX_OAUTH_CONFIG.redirectUri);
	url.searchParams.set("scope", OPENAI_CODEX_OAUTH_CONFIG.scopes);
	url.searchParams.set("code_challenge", challenge);
	url.searchParams.set("code_challenge_method", "S256");
	url.searchParams.set("state", state);
	url.searchParams.set("id_token_add_organizations", "true");
	url.searchParams.set("codex_cli_simplified_flow", "true");
	url.searchParams.set("originator", originator);

	return { verifier, state, url: url.toString() };
}

function resolveCallbackServerConfig(): {
	host: string;
	port: number;
	callbackPath: string;
	redirectUri: string;
} {
	try {
		const redirect = new URL(OPENAI_CODEX_OAUTH_CONFIG.redirectUri);
		const parsedPort =
			redirect.port.length > 0
				? Number.parseInt(redirect.port, 10)
				: OPENAI_CODEX_OAUTH_CONFIG.callbackPort;
		return {
			host: redirect.hostname || "localhost",
			port: Number.isFinite(parsedPort)
				? parsedPort
				: OPENAI_CODEX_OAUTH_CONFIG.callbackPort,
			callbackPath: redirect.pathname || "/auth/callback",
			redirectUri: redirect.toString(),
		};
	} catch {
		return {
			host: "localhost",
			port: OPENAI_CODEX_OAUTH_CONFIG.callbackPort,
			callbackPath: "/auth/callback",
			redirectUri: OPENAI_CODEX_OAUTH_CONFIG.redirectUri,
		};
	}
}

function getAccountId(accessToken: string, idToken?: string): string | null {
	const payload = (
		idToken ? decodeJwtPayload(idToken) : decodeJwtPayload(accessToken)
	) as JwtPayload | null;
	const fallback = (
		payload ? payload : decodeJwtPayload(accessToken)
	) as JwtPayload | null;
	const auth = fallback?.[OPENAI_CODEX_OAUTH_CONFIG.jwtClaimPath];
	const accountId = auth?.chatgpt_account_id;
	if (typeof accountId === "string" && accountId.length > 0) {
		return accountId;
	}

	const organizations = fallback?.organizations;
	if (Array.isArray(organizations) && organizations.length > 0) {
		const first = organizations[0] as { id?: unknown } | undefined;
		if (typeof first?.id === "string" && first.id.length > 0) {
			return first.id;
		}
	}

	const rootAccountId = fallback?.chatgpt_account_id;
	if (typeof rootAccountId === "string" && rootAccountId.length > 0) {
		return rootAccountId;
	}

	return null;
}

function toCodexCredentials(
	result: CodexTokenSuccess,
	fallback?: OAuthCredentials,
): OAuthCredentials {
	const accountId =
		getAccountId(result.access, result.idToken) ?? fallback?.accountId;
	if (!accountId) {
		throw new Error("Failed to extract accountId from token");
	}

	return {
		access: result.access,
		refresh: result.refresh || fallback?.refresh || "",
		expires: result.expires,
		accountId,
		email: result.email ?? fallback?.email,
		metadata: {
			...(fallback?.metadata ?? {}),
			provider: "openai-codex",
		},
	};
}

export async function loginOpenAICodex(options: {
	onAuth: (info: { url: string; instructions?: string }) => void;
	onPrompt: (prompt: OAuthPrompt) => Promise<string>;
	onProgress?: (message: string) => void;
	onManualCodeInput?: () => Promise<string>;
	originator?: string;
	telemetry?: ITelemetryService;
}): Promise<OAuthCredentials> {
	captureAuthStarted(options.telemetry, "openai-codex");
	const callbackConfig = resolveCallbackServerConfig();
	const { verifier, state, url } = await createAuthorizationFlow(
		options.originator,
	);
	const server = await startLocalOAuthServer({
		host: callbackConfig.host,
		ports: [callbackConfig.port],
		callbackPath: callbackConfig.callbackPath,
		expectedState: state,
	});

	options.onAuth({
		url,
		instructions: "Continue the authentication process in your browser.",
	});

	let code: string | undefined;
	try {
		const authResult = await resolveAuthorizationCodeInput({
			waitForCallback: server.waitForCallback,
			cancelWait: server.cancelWait,
			onManualCodeInput: options.onManualCodeInput,
			parseOptions: { allowHashCodeState: true },
		});
		if (authResult.state && authResult.state !== state) {
			throw new Error("State mismatch");
		}
		code = authResult.code;

		// Fallback to onPrompt if still no code
		if (!code) {
			const input = await options.onPrompt({
				message: "Paste the authorization code (or full redirect URL):",
			});
			const parsed = parseAuthorizationInput(input, {
				allowHashCodeState: true,
			});
			if (parsed.state && parsed.state !== state) {
				throw new Error("State mismatch");
			}
			code = parsed.code;
		}

		if (!code) {
			throw new Error("Missing authorization code");
		}

		const tokenResult = await exchangeAuthorizationCode(
			code,
			verifier,
			callbackConfig.redirectUri,
		);
		if (tokenResult.type !== "success") {
			throw new Error("Token exchange failed");
		}

		const credentials = toCodexCredentials(tokenResult);
		captureAuthSucceeded(options.telemetry, "openai-codex");
		identifyAccount(options.telemetry, {
			id: credentials.accountId,
			email: credentials.email,
			provider: "openai-codex",
		});
		return credentials;
	} catch (error) {
		captureAuthFailed(
			options.telemetry,
			"openai-codex",
			error instanceof Error ? error.message : String(error),
		);
		throw error;
	} finally {
		server.close();
	}
}

export async function refreshOpenAICodexToken(
	refreshToken: string,
	fallback?: OAuthCredentials,
): Promise<OAuthCredentials> {
	const result = await refreshAccessToken(refreshToken);
	if (result.type !== "success") {
		throw new Error("Failed to refresh OpenAI Codex token");
	}

	const normalized = toCodexCredentials(result, fallback);
	if (!normalized.refresh) {
		throw new Error(
			"Failed to refresh OpenAI Codex token: missing refresh token",
		);
	}
	return normalized;
}

export async function getValidOpenAICodexCredentials(
	currentCredentials: OAuthCredentials | null,
	options?: RefreshTokenResolution & { telemetry?: ITelemetryService },
): Promise<OAuthCredentials | null> {
	if (!currentCredentials) {
		return null;
	}

	const refreshBufferMs =
		options?.refreshBufferMs ?? OPENAI_CODEX_OAUTH_CONFIG.refreshBufferMs;
	const retryableTokenGraceMs =
		options?.retryableTokenGraceMs ??
		OPENAI_CODEX_OAUTH_CONFIG.retryableTokenGraceMs;
	const forceRefresh = options?.forceRefresh === true;

	if (
		!forceRefresh &&
		!isCredentialLikelyExpired(currentCredentials, refreshBufferMs)
	) {
		return currentCredentials;
	}

	try {
		const refreshed = await refreshOpenAICodexToken(
			currentCredentials.refresh,
			currentCredentials,
		);
		return refreshed;
	} catch (error) {
		if (
			error instanceof OpenAICodexOAuthTokenError &&
			error.isLikelyInvalidGrant()
		) {
			captureAuthLoggedOut(options?.telemetry, "openai-codex", "invalid_grant");
			return null;
		}
		if (currentCredentials.expires - Date.now() > retryableTokenGraceMs) {
			return currentCredentials;
		}
		return null;
	}
}

import { afterEach, describe, expect, it, vi } from "vitest";
