export interface ClineCoreOptions {
	/**
	 * A human-readable name for this SDK client (e.g. `"my-app"`, `"acme-bot"`).
	 * Used to identify the consumer in telemetry and logs.
	 */
	clientName?: string;
	/**
	 * A stable identifier for this machine or user, used for telemetry attribution.
	 * Defaults to the system machine ID, falling back to a generated `cl-<nanoid>` persisted
	 * at `~/.cline/data/machine-id`.
	 */
	distinctId?: string;
	/**
	 * Controls how the runtime host is selected:
	 * - `"auto"` (default) — prefers a compatible local hub when one is available and falls
	 *   back to local in-process execution when not.
	 * - `"hub"` — requires a compatible websocket hub runtime; throws if one is not reachable.
	 * - `"remote"` — requires an explicit remote websocket hub endpoint.
	 * - `"local"` — always uses local in-process execution and local SQLite/file storage.
	 */
	backendMode?: RuntimeHostMode;
	/**
	 * Hub runtime connection options. Used when `backendMode` is `"hub"` or when `"auto"`
	 * should prefer a shared local hub if available.
	 */
	hub?: HubOptions;
	/**
	 * Remote hub connection options. Only relevant when `backendMode` is `"remote"`.
	 */
	remote?: RemoteOptions;
	/**
	 * Client-owned runtime capabilities. Core adapts these handlers to the
	 * selected runtime backend so apps implement interactive behavior once.
	 */
	capabilities?: RuntimeCapabilities;
	/**
	 * Telemetry service instance to use for capturing events and usage.
	 * If omitted, telemetry is a no-op.
	 */
	telemetry?: ITelemetryService;
	/**
	 * Feature flags service for this ClineCore instance.
	 * If omitted, Core uses a no-op provider with default flag values.
	 */
	featureFlags?: FeatureFlagsService;
	/**
	 * Optional structured logger for core-side operational diagnostics such as
	 * runtime-host selection and fallback decisions.
	 */
	logger?: BasicLogger;
	/**
	 * Per-tool approval policies that control whether a tool runs automatically,
	 * requires user confirmation, or is blocked entirely.
	 */
	toolPolicies?: AgentConfig["toolPolicies"];
	/**
	 * Optional hook invoked after `messages.json` is persisted to disk.
	 * Consumers can use this to mirror session transcripts into remote storage.
	 */
	messagesArtifactUploader?: SessionMessagesArtifactUploader;
	/**
	 * Enables file-based and event-driven automation through this ClineCore
	 * instance. When configured, callers use `cline.automation.*` instead of
	 * constructing cron services directly.
	 */
	automation?: boolean | ClineCoreAutomationOptions;
	/**
	 * Custom `fetch` implementation forwarded to the AI gateway providers used
	 * by local sessions. When supplied, it is threaded into each
	 * `ProviderConfig.fetch` built during session bootstrap, which in turn
	 * populates `GatewayProviderSettings.fetch` (and the top-level
	 * `GatewayConfig.fetch` fallback) so hosts can inject custom HTTP behavior
	 * such as proxies, retries, tracing, or test doubles.
	 *
	 * Per-session or per-provider overrides still win: an explicit
	 * `config.fetch` on `CoreSessionConfig` or a stored provider-level `fetch`
	 * takes precedence over this default.
	 *
	 * Applies only to sessions executed in this process (local and fallback-
	 * to-local auto mode). For hub and remote runtimes the HTTP call happens
	 * inside the process that owns the gateway, so configure `fetch` there:
	 *   - `startHubServer({ fetch })` / `ensureHubServer({ fetch })` from
	 *     `@cline/hub`
	 *   - `createLocalHubScheduleRuntimeHandlers({ fetch })` from
	 *     `@cline/core/hub` for the scheduler
	 */
	fetch?: typeof fetch;
	/**
	 * An already-constructed session backend to use instead of resolving one automatically.
	 * Intended for testing or embedding a custom persistence layer.
	 * @internal
	 */
	sessionService?: SessionBackend;
	/**
	 * Optional hook invoked before each session starts.
	 * Use this to prepare workspace-scoped runtime state and then return an
	 * adapter that mutates the shared session input before core starts the run.
	 */
	prepare?: (
		input: ClineCoreStartInput,
	) =>
		| Promise<StartSessionBootstrap | undefined>
		| StartSessionBootstrap
		| undefined;
}

export interface StartSessionBootstrap {
	applyToStartSessionInput(
		input: ClineCoreStartInput,
	): Promise<ClineCoreStartInput> | ClineCoreStartInput;
	dispose?(): Promise<void> | void;
}

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { CronEventSpec } from "@cline/shared";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { SqliteCronStore } from "../store/sqlite-cron-store";
import {
	automationEventMatchesFilters,
	CronEventIngress,
} from "./cron-event-ingress";

describe("automationEventMatchesFilters", () => {
	it("matches attributes by default and supports dot paths", () => {
		expect(
			automationEventMatchesFilters(
				{
					eventId: "evt_1",
					eventType: "github.pull_request.opened",
					source: "github",
					occurredAt: "2026-04-23T10:00:00.000Z",
					attributes: {
						repository: "acme/api",
						pullRequest: { baseBranch: "main" },
					},
				},
				{
					repository: "acme/api",
					"pullRequest.baseBranch": "main",
				},
			),
		).toBe(true);
	});
});

describe("CronEventIngress", () => {
	let dir: string;
	let store: SqliteCronStore;
	let nowMs: number;
	let ingress: CronEventIngress;

	beforeEach(() => {
		dir = mkdtempSync(join(tmpdir(), "cline-event-ingress-"));
		store = new SqliteCronStore({ dbPath: join(dir, "cron.db") });
		nowMs = Date.parse("2026-04-23T10:00:00.000Z");
		ingress = new CronEventIngress({ store, now: () => nowMs });
	});

	afterEach(() => {
		store.close();
		rmSync(dir, { recursive: true, force: true });
	});

	function seedEventSpec(overrides: Partial<CronEventSpec> = {}) {
		const spec: CronEventSpec = {
			triggerKind: "event",
			id: "pr-review",
			title: "PR Review",
			prompt: "Review the PR",
			workspaceRoot: "/ws",
			enabled: true,
			event: "github.pull_request.opened",
			filters: { repository: "acme/api" },
			...overrides,
		};
		return store.upsertSpec({
			externalId: spec.id ?? "pr-review",
			sourcePath: `events/${spec.id ?? "pr-review"}.event.md`,
			triggerKind: "event",
			sourceHash: JSON.stringify(spec),
			parseStatus: "valid",
			spec,
		}).record;
	}

	it("persists a normalized event and queues matching event runs", () => {
		const spec = seedEventSpec({
			filters: {
				repository: "acme/api",
				"pullRequest.baseBranch": "main",
			},
		});

		const result = ingress.ingestEvent({
			eventId: "evt_1",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/api#12",
			occurredAt: "2026-04-23T09:59:59.000Z",
			attributes: {
				repository: "acme/api",
				pullRequest: { baseBranch: "main" },
			},
			payload: { action: "opened" },
		});

		expect(result.duplicate).toBe(false);
		expect(result.matchedSpecs).toHaveLength(1);
		expect(result.queuedRuns).toHaveLength(1);
		expect(result.queuedRuns[0]?.specId).toBe(spec.specId);
		expect(result.queuedRuns[0]?.triggerKind).toBe("event");
		expect(result.queuedRuns[0]?.triggerEventId).toBe("evt_1");
		expect(result.event.processingStatus).toBe("queued");
		expect(result.event.dedupeKey).toBe(
			"github.pull_request.opened:github:acme/api#12",
		);
	});

	it("records unmatched events without queuing", () => {
		seedEventSpec({ filters: { repository: "acme/api" } });

		const result = ingress.ingestEvent({
			eventId: "evt_1",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/web#12",
			occurredAt: "2026-04-23T10:00:00.000Z",
			attributes: { repository: "acme/web" },
		});

		expect(result.matchedSpecs).toHaveLength(0);
		expect(result.queuedRuns).toHaveLength(0);
		expect(result.event.processingStatus).toBe("unmatched");
		expect(store.listRuns()).toHaveLength(0);
	});

	it("queues one run per concurrently matching event spec", () => {
		const first = seedEventSpec({ id: "pr-review-a" });
		const second = seedEventSpec({
			id: "pr-review-b",
			filters: { repository: "acme/api", label: "security" },
		});

		const result = ingress.ingestEvent({
			eventId: "evt_1",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/api#12",
			occurredAt: "2026-04-23T10:00:00.000Z",
			attributes: { repository: "acme/api", label: "security" },
		});

		expect(result.matchedSpecs.map((spec) => spec.specId).sort()).toEqual(
			[first.specId, second.specId].sort(),
		);
		expect(result.queuedRuns).toHaveLength(2);
		expect(store.listRuns()).toHaveLength(2);
	});

	it("treats duplicate event ids as replay and does not requeue", () => {
		seedEventSpec();
		const event = {
			eventId: "evt_1",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/api#12",
			occurredAt: "2026-04-23T10:00:00.000Z",
			attributes: { repository: "acme/api" },
		};

		expect(ingress.ingestEvent(event).queuedRuns).toHaveLength(1);
		const duplicate = ingress.ingestEvent(event);

		expect(duplicate.duplicate).toBe(true);
		expect(duplicate.queuedRuns).toHaveLength(0);
		expect(store.listRuns()).toHaveLength(1);
	});

	it("suppresses events inside a dedupe window", () => {
		seedEventSpec({ dedupeWindowSeconds: 600 });
		ingress.ingestEvent({
			eventId: "evt_1",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/api#12",
			occurredAt: "2026-04-23T10:00:00.000Z",
			dedupeKey: "pr:12",
			attributes: { repository: "acme/api" },
		});
		nowMs = Date.parse("2026-04-23T10:01:00.000Z");

		const suppressed = ingress.ingestEvent({
			eventId: "evt_2",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/api#12",
			occurredAt: "2026-04-23T10:01:00.000Z",
			dedupeKey: "pr:12",
			attributes: { repository: "acme/api" },
		});

		expect(suppressed.queuedRuns).toHaveLength(0);
		expect(suppressed.event.processingStatus).toBe("suppressed");
		expect(suppressed.suppressions[0]?.reason).toBe("dedupe_window");
		expect(store.listRuns()).toHaveLength(1);
	});

	it("extends a pending debounced run instead of creating another run", () => {
		seedEventSpec({ debounceSeconds: 30 });
		const first = ingress.ingestEvent({
			eventId: "evt_1",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/api#12",
			occurredAt: "2026-04-23T10:00:00.000Z",
			dedupeKey: "pr:12",
			attributes: { repository: "acme/api" },
		});
		nowMs = Date.parse("2026-04-23T10:00:10.000Z");

		const second = ingress.ingestEvent({
			eventId: "evt_2",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/api#12",
			occurredAt: "2026-04-23T10:00:10.000Z",
			dedupeKey: "pr:12",
			attributes: { repository: "acme/api" },
		});

		expect(second.queuedRuns).toHaveLength(1);
		expect(second.queuedRuns[0]?.runId).toBe(first.queuedRuns[0]?.runId);
		expect(second.queuedRuns[0]?.triggerEventId).toBe("evt_2");
		expect(second.queuedRuns[0]?.scheduledFor).toBe("2026-04-23T10:00:40.000Z");
		expect(store.listRuns()).toHaveLength(1);
	});

	it("suppresses events during cooldown regardless of dedupe key", () => {
		seedEventSpec({ cooldownSeconds: 300 });
		ingress.ingestEvent({
			eventId: "evt_1",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/api#12",
			occurredAt: "2026-04-23T10:00:00.000Z",
			dedupeKey: "pr:12",
			attributes: { repository: "acme/api" },
		});
		nowMs = Date.parse("2026-04-23T10:02:00.000Z");

		const suppressed = ingress.ingestEvent({
			eventId: "evt_2",
			eventType: "github.pull_request.opened",
			source: "github",
			subject: "acme/api#13",
			occurredAt: "2026-04-23T10:02:00.000Z",
			dedupeKey: "pr:13",
			attributes: { repository: "acme/api" },
		});

		expect(suppressed.queuedRuns).toHaveLength(0);
		expect(suppressed.event.processingStatus).toBe("suppressed");
		expect(suppressed.suppressions[0]?.reason).toBe("cooldown");
		expect(store.listRuns()).toHaveLength(1);
	});
});

import type { AutomationEventEnvelope, BasicLogger } from "@cline/shared";
import type {
	CronEventLogRecord,
	CronRunRecord,
	CronSpecRecord,
	SqliteCronStore,
} from "../store/sqlite-cron-store";

/**
 * Durable ingress for normalized automation events.
 *
 * This layer persists the incoming event before matching, then materializes
 * queued `cron_runs` for matching event specs. It deliberately does not
 * execute agents; the normal runner claim loop owns execution.
 */

export interface CronEventIngressOptions {
	store: SqliteCronStore;
	now?: () => number;
	logger?: BasicLogger;
}

export type CronEventSuppressionReason =
	| "duplicate_event"
	| "filter_mismatch"
	| "dedupe_window"
	| "cooldown";

export interface CronEventSuppression {
	specId?: string;
	externalId?: string;
	reason: CronEventSuppressionReason;
	dedupeKey?: string;
}

export interface CronEventIngressResult {
	event: CronEventLogRecord;
	duplicate: boolean;
	matchedSpecs: CronSpecRecord[];
	queuedRuns: CronRunRecord[];
	suppressions: CronEventSuppression[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return !!value && typeof value === "object" && !Array.isArray(value);
}

function trimOrUndefined(value: string | undefined): string | undefined {
	const trimmed = value?.trim();
	return trimmed ? trimmed : undefined;
}

function normalizeIso(value: string | undefined, fallback: string): string {
	const candidate = value?.trim();
	if (!candidate) return fallback;
	const ms = Date.parse(candidate);
	if (!Number.isFinite(ms)) return fallback;
	return new Date(ms).toISOString();
}

function addSeconds(iso: string, seconds: number): string {
	return new Date(
		new Date(iso).getTime() + Math.max(0, Math.floor(seconds)) * 1000,
	).toISOString();
}

function subtractSeconds(iso: string, seconds: number): string {
	return new Date(
		new Date(iso).getTime() - Math.max(0, Math.floor(seconds)) * 1000,
	).toISOString();
}

function maxIso(a: string | undefined, b: string): string {
	if (!a) return b;
	return new Date(a).getTime() >= new Date(b).getTime() ? a : b;
}

function normalizeEvent(
	event: AutomationEventEnvelope,
	receivedAt: string,
): AutomationEventEnvelope {
	const eventId = event.eventId.trim();
	const eventType = event.eventType.trim();
	const source = event.source.trim();
	const subject = trimOrUndefined(event.subject);
	const dedupeKey =
		trimOrUndefined(event.dedupeKey) ??
		`${eventType}:${source}:${subject ?? eventId}`;
	return {
		eventId,
		eventType,
		source,
		subject,
		occurredAt: normalizeIso(event.occurredAt, receivedAt),
		workspaceRoot: trimOrUndefined(event.workspaceRoot),
		payload: isRecord(event.payload) ? event.payload : undefined,
		attributes: isRecord(event.attributes) ? event.attributes : undefined,
		dedupeKey,
	};
}

function getPath(value: unknown, path: string): unknown {
	if (!path) return undefined;
	const parts = path.split(".");
	let current: unknown = value;
	for (const part of parts) {
		if (!isRecord(current)) return undefined;
		current = current[part];
	}
	return current;
}

function resolveFilterValue(
	event: AutomationEventEnvelope,
	filterKey: string,
): unknown {
	if (event.attributes && Object.hasOwn(event.attributes, filterKey)) {
		return event.attributes[filterKey];
	}
	if (event.payload && Object.hasOwn(event.payload, filterKey)) {
		return event.payload[filterKey];
	}
	const candidate = {
		eventId: event.eventId,
		eventType: event.eventType,
		source: event.source,
		subject: event.subject,
		occurredAt: event.occurredAt,
		workspaceRoot: event.workspaceRoot,
		dedupeKey: event.dedupeKey,
		attributes: event.attributes,
		payload: event.payload,
	};
	const direct = getPath(candidate, filterKey);
	if (direct !== undefined) return direct;
	if (event.attributes) {
		const fromAttributes = getPath(event.attributes, filterKey);
		if (fromAttributes !== undefined) return fromAttributes;
	}
	if (event.payload) {
		return getPath(event.payload, filterKey);
	}
	return undefined;
}

function matchesExpected(actual: unknown, expected: unknown): boolean {
	if (Array.isArray(expected)) {
		return expected.some((item) => matchesExpected(actual, item));
	}
	if (Array.isArray(actual)) {
		return actual.some((item) => matchesExpected(item, expected));
	}
	if (isRecord(expected)) {
		if (!isRecord(actual)) return false;
		return Object.entries(expected).every(([key, value]) =>
			matchesExpected(actual[key], value),
		);
	}
	return Object.is(actual, expected);
}

export function automationEventMatchesFilters(
	event: AutomationEventEnvelope,
	filters: Record<string, unknown> | undefined,
): boolean {
	if (!filters || Object.keys(filters).length === 0) return true;
	return Object.entries(filters).every(([key, expected]) =>
		matchesExpected(resolveFilterValue(event, key), expected),
	);
}

export class CronEventIngress {
	private readonly store: SqliteCronStore;
	private readonly nowFn: () => number;
	private readonly logger?: BasicLogger;

	constructor(options: CronEventIngressOptions) {
		this.store = options.store;
		this.nowFn = options.now ?? (() => Date.now());
		this.logger = options.logger;
	}

	public ingestEvent(event: AutomationEventEnvelope): CronEventIngressResult {
		const receivedAt = new Date(this.nowFn()).toISOString();
		const normalized = normalizeEvent(event, receivedAt);
		const inserted = this.store.insertEventLog(normalized, {
			receivedAtIso: receivedAt,
		});
		if (!inserted.created) {
			this.logger?.debug("cron.event.duplicate", {
				eventId: inserted.record.eventId,
				eventType: inserted.record.eventType,
				source: inserted.record.source,
			});
			return {
				event: inserted.record,
				duplicate: true,
				matchedSpecs: [],
				queuedRuns: [],
				suppressions: [
					{
						reason: "duplicate_event",
						dedupeKey: inserted.record.dedupeKey,
					},
				],
			};
		}

		try {
			const allCandidateSpecs = this.store.listEventSpecsForType(
				normalized.eventType,
			);
			const suppressions: CronEventSuppression[] = [];
			const matchedSpecs: CronSpecRecord[] = [];
			const queuedRuns: CronRunRecord[] = [];

			for (const spec of allCandidateSpecs) {
				if (!automationEventMatchesFilters(normalized, spec.filters)) {
					suppressions.push({
						specId: spec.specId,
						externalId: spec.externalId,
						reason: "filter_mismatch",
						dedupeKey: normalized.dedupeKey,
					});
					continue;
				}
				matchedSpecs.push(spec);
				const run = this.materializeForSpec(
					spec,
					normalized,
					inserted.record.receivedAt,
				);
				if (run.run) {
					queuedRuns.push(run.run);
				} else {
					suppressions.push({
						specId: spec.specId,
						externalId: spec.externalId,
						reason: run.reason,
						dedupeKey: normalized.dedupeKey,
					});
				}
			}

			const status =
				matchedSpecs.length === 0
					? "unmatched"
					: queuedRuns.length > 0
						? "queued"
						: "suppressed";
			this.store.updateEventLogProcessing(inserted.record.eventId, {
				status,
				matchedSpecCount: matchedSpecs.length,
				queuedRunCount: queuedRuns.length,
				suppressedCount: suppressions.filter(
					(s) => s.reason !== "filter_mismatch",
				).length,
			});
			const updated = this.store.getEventLog(inserted.record.eventId);
			this.logger?.debug("cron.event.processed", {
				eventId: inserted.record.eventId,
				eventType: inserted.record.eventType,
				status,
				matchedSpecCount: matchedSpecs.length,
				queuedRunCount: queuedRuns.length,
			});
			return {
				event: updated ?? inserted.record,
				duplicate: false,
				matchedSpecs,
				queuedRuns,
				suppressions,
			};
		} catch (err) {
			this.store.updateEventLogProcessing(inserted.record.eventId, {
				status: "failed",
				error: err instanceof Error ? err.message : String(err),
			});
			if (this.logger?.error) {
				this.logger.error("cron.event.failed", {
					eventId: inserted.record.eventId,
					eventType: inserted.record.eventType,
					error: err,
				});
			}
			throw err;
		}
	}

	private materializeForSpec(
		spec: CronSpecRecord,
		event: AutomationEventEnvelope,
		receivedAt: string,
	): {
		run?: CronRunRecord;
		reason: Exclude<
			CronEventSuppressionReason,
			"duplicate_event" | "filter_mismatch"
		>;
	} {
		const dedupeKey = event.dedupeKey ?? event.eventId;
		const debounceSeconds = spec.debounceSeconds ?? 0;
		if (debounceSeconds > 0) {
			const existing = this.store.findQueuedEventRunForDedupe({
				specId: spec.specId,
				dedupeKey,
			});
			if (existing) {
				const scheduledFor = maxIso(
					existing.scheduledFor,
					addSeconds(receivedAt, debounceSeconds),
				);
				const updated = this.store.updateQueuedEventRunForDebounce({
					runId: existing.runId,
					triggerEventId: event.eventId,
					scheduledFor,
				});
				if (updated) return { run: updated, reason: "dedupe_window" };
			}
		}

		const dedupeWindowSeconds = spec.dedupeWindowSeconds ?? 0;
		if (
			dedupeWindowSeconds > 0 &&
			this.store.hasRecentEventRunForDedupe({
				specId: spec.specId,
				dedupeKey,
				sinceIso: subtractSeconds(receivedAt, dedupeWindowSeconds),
			})
		) {
			return { reason: "dedupe_window" };
		}

		const cooldownSeconds = spec.cooldownSeconds ?? 0;
		if (
			cooldownSeconds > 0 &&
			this.store.hasRecentEventRunForSpec({
				specId: spec.specId,
				sinceIso: subtractSeconds(receivedAt, cooldownSeconds),
			})
		) {
			return { reason: "cooldown" };
		}

		const run = this.store.enqueueRun({
			specId: spec.specId,
			specRevision: spec.revision,
			triggerKind: "event",
			triggerEventId: event.eventId,
			scheduledFor:
				debounceSeconds > 0
					? addSeconds(receivedAt, debounceSeconds)
					: receivedAt,
		});
		return { run, reason: "dedupe_window" };
	}
}

export * from "./events";
export * from "./reports";
export * from "./runner";
export * from "./schedule";
export * from "./service";
export * from "./specs";
export * from "./store";

import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import {
	type ResolveCronSpecsDirOptions,
	resolveCronReportsDir,
} from "@cline/shared/storage";
import type {
	CronEventLogRecord,
	CronRunRecord,
	CronSpecRecord,
} from "../store/sqlite-cron-store";

/**
 * Writes a markdown report for a completed or failed cron run.
 * Reports live under `<cron-specs-dir>/reports/<run-id>.md`.
 * By default that is `~/.cline/cron/reports/<run-id>.md`.
 * and are derived artifacts — the database is still the operational source
 * of truth.
 */

export interface CronRunReportData {
	finalText?: string;
	usage?: {
		inputTokens?: number;
		outputTokens?: number;
		cacheReadTokens?: number;
		cacheWriteTokens?: number;
		totalCost?: number;
	};
	toolCalls?: Array<{ name: string; error?: string; durationMs?: number }>;
	durationMs?: number;
	error?: string;
	triggerEvent?: CronEventLogRecord;
}

export interface WriteReportOptions {
	/**
	 * Cron spec source/report location. Defaults to global `~/.cline/cron`.
	 * Pass `{ scope: "workspace", workspaceRoot }` to write reports beside a
	 * future workspace-scoped cron specs directory.
	 */
	specs?: ResolveCronSpecsDirOptions;
	workspaceRoot: string;
	run: CronRunRecord;
	spec: CronSpecRecord;
	data: CronRunReportData;
}

function escapeYamlString(value: string): string {
	// Minimal escaping: wrap in quotes only when needed.
	if (/[:#\n]/.test(value) || value.includes('"')) {
		return JSON.stringify(value);
	}
	return value;
}

function yamlEntry(key: string, value: string | undefined): string | undefined {
	if (value === undefined || value === null) return undefined;
	return `${key}: ${escapeYamlString(value)}`;
}

function buildFrontmatter(
	run: CronRunRecord,
	spec: CronSpecRecord,
	triggerEvent?: CronEventLogRecord,
): string {
	const entries: string[] = [
		`runId: ${escapeYamlString(run.runId)}`,
		`specId: ${escapeYamlString(spec.specId)}`,
		`externalId: ${escapeYamlString(spec.externalId)}`,
		`title: ${escapeYamlString(spec.title)}`,
		`triggerKind: ${escapeYamlString(run.triggerKind)}`,
		`status: ${escapeYamlString(run.status)}`,
		`sourcePath: ${escapeYamlString(spec.sourcePath)}`,
	];
	const optional = [
		yamlEntry("sessionId", run.sessionId),
		yamlEntry("startedAt", run.startedAt),
		yamlEntry("completedAt", run.completedAt),
		yamlEntry("triggerEventId", run.triggerEventId),
		yamlEntry("triggerEventType", triggerEvent?.eventType),
		yamlEntry("triggerEventSource", triggerEvent?.source),
		yamlEntry("triggerEventSubject", triggerEvent?.subject),
	];
	for (const entry of optional) if (entry) entries.push(entry);
	return `---\n${entries.join("\n")}\n---\n`;
}

function buildBody(data: CronRunReportData): string {
	const sections: string[] = [];
	if (data.triggerEvent) {
		const event = data.triggerEvent;
		const lines = [
			`- eventId: ${event.eventId}`,
			`- eventType: ${event.eventType}`,
			`- source: ${event.source}`,
			event.subject ? `- subject: ${event.subject}` : "",
			`- occurredAt: ${event.occurredAt}`,
			event.dedupeKey ? `- dedupeKey: ${event.dedupeKey}` : "",
			event.attributes
				? `- attributes: ${JSON.stringify(event.attributes)}`
				: "",
		].filter((line) => line.length > 0);
		sections.push(`## Trigger Event\n\n${lines.join("\n")}\n`);
	}
	if (data.error) {
		sections.push(`## Error\n\n${data.error}\n`);
	}
	if (data.finalText && data.finalText.trim().length > 0) {
		sections.push(`## Summary\n\n${data.finalText.trim()}\n`);
	}
	if (data.usage) {
		const u = data.usage;
		const lines = [
			u.inputTokens !== undefined ? `- inputTokens: ${u.inputTokens}` : "",
			u.outputTokens !== undefined ? `- outputTokens: ${u.outputTokens}` : "",
			u.cacheReadTokens !== undefined
				? `- cacheReadTokens: ${u.cacheReadTokens}`
				: "",
			u.cacheWriteTokens !== undefined
				? `- cacheWriteTokens: ${u.cacheWriteTokens}`
				: "",
			u.totalCost !== undefined ? `- totalCostUsd: ${u.totalCost}` : "",
			data.durationMs !== undefined ? `- durationMs: ${data.durationMs}` : "",
		].filter((line) => line.length > 0);
		if (lines.length > 0) {
			sections.push(`## Usage\n\n${lines.join("\n")}\n`);
		}
	}
	if (data.toolCalls && data.toolCalls.length > 0) {
		const bullets = data.toolCalls.map((call) => {
			const parts = [`- ${call.name}`];
			if (call.durationMs !== undefined) parts.push(`(${call.durationMs}ms)`);
			if (call.error) parts.push(`error: ${call.error}`);
			return parts.join(" ");
		});
		sections.push(`## Tool Calls\n\n${bullets.join("\n")}\n`);
	}
	return sections.join("\n");
}

export function writeCronRunReport(options: WriteReportOptions): string {
	const dir = resolveCronReportsDir(options.specs);
	mkdirSync(dir, { recursive: true });
	const path = join(dir, `${options.run.runId}.md`);
	const content = `${buildFrontmatter(
		options.run,
		options.spec,
		options.data.triggerEvent,
	)}\n${buildBody(options.data)}`;
	writeFileSync(path, content, "utf8");
	return path;
}

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
	ONE_TIME_SCHEDULE_CRON_PATTERN,
	ONE_TIME_SCHEDULE_RUN_AT_METADATA_KEY,
} from "@cline/shared";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { SqliteCronStore } from "../store/sqlite-cron-store";
import { CronMaterializer } from "./cron-materializer";

describe("CronMaterializer", () => {
	let dir: string;
	let store: SqliteCronStore;

	beforeEach(() => {
		dir = mkdtempSync(join(tmpdir(), "cline-materializer-"));
		store = new SqliteCronStore({ dbPath: join(dir, "cron.db") });
	});
	afterEach(() => {
		store.close();
		rmSync(dir, { recursive: true, force: true });
	});

	function seedOneOff() {
		return store.upsertSpec({
			externalId: "cleanup",
			sourcePath: "cleanup.md",
			triggerKind: "one_off",
			sourceHash: "h",
			parseStatus: "valid",
			spec: {
				triggerKind: "one_off",
				id: "cleanup",
				title: "Clean",
				prompt: "p",
				workspaceRoot: "/ws",
				enabled: true,
			},
		}).record;
	}

	function requireValue<T>(value: T | undefined): T {
		expect(value).toBeDefined();
		if (value === undefined) {
			throw new Error("Expected value to be defined");
		}
		return value;
	}

	it("queues exactly one run per one-off spec revision", () => {
		seedOneOff();
		const m = new CronMaterializer({ store });
		expect(m.materializeAll().oneOffQueued).toBe(1);
		expect(m.materializeAll().oneOffQueued).toBe(0);
	});

	it("preserves a future run time when materializing a one-off spec", () => {
		const spec = seedOneOff();
		const runAt = new Date(Date.now() + 60_000).toISOString();
		store.updateSpecNextRunAt(spec.specId, runAt);
		const materializer = new CronMaterializer({ store });

		expect(materializer.materializeAll().oneOffQueued).toBe(1);
		expect(store.listRuns({ specId: spec.specId })[0]?.scheduledFor).toBe(
			runAt,
		);
	});

	it("replaces a queued one-time run when its timestamp changes", () => {
		const originalRunAt = Date.now() + 60_000;
		const rescheduledRunAt = originalRunAt + 60 * 60_000;
		const spec = store.createHubSchedule({
			name: "Run once",
			cronPattern: ONE_TIME_SCHEDULE_CRON_PATTERN,
			prompt: "Do the work",
			workspaceRoot: "/ws",
			metadata: {
				[ONE_TIME_SCHEDULE_RUN_AT_METADATA_KEY]: originalRunAt,
			},
		});
		const materializer = new CronMaterializer({ store });
		expect(materializer.materializeAll().oneOffQueued).toBe(1);

		const updated = requireValue(
			store.updateHubSchedule(spec.externalId, {
				scheduleId: spec.externalId,
				metadata: {
					[ONE_TIME_SCHEDULE_RUN_AT_METADATA_KEY]: rescheduledRunAt,
				},
			}),
		);

		expect(updated.revision).toBe(spec.revision + 1);
		expect(updated.nextRunAt).toBe(new Date(rescheduledRunAt).toISOString());
		expect(materializer.materializeAll().oneOffQueued).toBe(1);
		const runs = store.listRuns({ specId: spec.specId });
		expect(runs).toHaveLength(2);
		expect(runs.filter((run) => run.status === "cancelled")).toEqual([
			expect.objectContaining({
				specRevision: spec.revision,
				scheduledFor: new Date(originalRunAt).toISOString(),
			}),
		]);
		expect(runs.filter((run) => run.status === "queued")).toEqual([
			expect.objectContaining({
				specRevision: updated.revision,
				scheduledFor: new Date(rescheduledRunAt).toISOString(),
			}),
		]);
	});

	it("keeps only one queued run after pausing and resuming a one-time schedule", () => {
		const runAt = Date.now() + 60_000;
		const spec = store.createHubSchedule({
			name: "Run once",
			cronPattern: ONE_TIME_SCHEDULE_CRON_PATTERN,
			prompt: "Do the work",
			workspaceRoot: "/ws",
			metadata: { [ONE_TIME_SCHEDULE_RUN_AT_METADATA_KEY]: runAt },
		});
		const materializer = new CronMaterializer({ store });
		expect(materializer.materializeAll().oneOffQueued).toBe(1);

		const paused = requireValue(
			store.updateHubSchedule(spec.externalId, {
				scheduleId: spec.externalId,
				enabled: false,
			}),
		);
		expect(paused.enabled).toBe(false);
		expect(
			store.listRuns({ specId: spec.specId, status: "queued" }),
		).toHaveLength(0);
		expect(materializer.materializeAll().oneOffQueued).toBe(0);

		const resumed = requireValue(
			store.updateHubSchedule(spec.externalId, {
				scheduleId: spec.externalId,
				enabled: true,
			}),
		);
		expect(resumed.revision).toBe(spec.revision + 1);
		expect(materializer.materializeAll().oneOffQueued).toBe(1);
		const runs = store.listRuns({ specId: spec.specId });
		expect(runs).toHaveLength(2);
		expect(runs.filter((run) => run.status === "cancelled")).toHaveLength(1);
		expect(runs.filter((run) => run.status === "queued")).toEqual([
			expect.objectContaining({
				specRevision: resumed.revision,
				scheduledFor: new Date(runAt).toISOString(),
			}),
		]);
	});

	it("queues a new run when the revision bumps", () => {
		const spec = seedOneOff();
		const m = new CronMaterializer({ store });
		m.materializeAll();
		store.upsertSpec({
			externalId: "cleanup",
			sourcePath: "cleanup.md",
			triggerKind: "one_off",
			sourceHash: "h2",
			parseStatus: "valid",
			spec: {
				triggerKind: "one_off",
				id: "cleanup",
				title: "Clean",
				prompt: "new prompt",
				workspaceRoot: "/ws",
				enabled: true,
			},
		});
		const updated = requireValue(store.getSpec(spec.specId));
		expect(updated.revision).toBe(2);
		expect(m.materializeAll().oneOffQueued).toBe(1);
		const runs = store.listRuns({ specId: spec.specId });
		expect(runs.length).toBe(2);
	});

	it("does not requeue a failed one-off run for the same revision", () => {
		const spec = seedOneOff();
		const m = new CronMaterializer({ store });
		expect(m.materializeAll().oneOffQueued).toBe(1);
		const run = requireValue(store.listRuns({ specId: spec.specId })[0]);
		store.completeRun(run.runId, { status: "failed", error: "boom" });

		expect(m.materializeAll().oneOffQueued).toBe(0);
		const runs = store.listRuns({ specId: spec.specId });
		expect(runs).toHaveLength(1);
		expect(runs[0]?.status).toBe("failed");
	});

	it("catches up one overdue schedule run and advances next_run_at", () => {
		const past = new Date(Date.now() - 60_000).toISOString();
		const upserted = store.upsertSpec({
			externalId: "nightly",
			sourcePath: "nightly.cron.md",
			triggerKind: "schedule",
			sourceHash: "h",
			parseStatus: "valid",
			spec: {
				triggerKind: "schedule",
				id: "nightly",
				title: "Nightly",
				prompt: "p",
				workspaceRoot: "/ws",
				enabled: true,
				schedule: "* * * * *",
			},
		});
		// Force an overdue next_run_at.
		store.updateSpecNextRunAt(upserted.record.specId, past);

		const m = new CronMaterializer({ store });
		expect(m.materializeAll().scheduleQueued).toBe(1);
		expect(m.materializeAll().scheduleQueued).toBe(0);
		const after = requireValue(store.getSpec(upserted.record.specId));
		const nextRunAt = requireValue(after.nextRunAt);
		expect(new Date(nextRunAt).getTime()).toBeGreaterThan(Date.now());
	});

	it("does not duplicate a due schedule run when called twice with a stale spec snapshot", () => {
		const nowMs = Date.parse("2026-04-23T10:00:00.000Z");
		const dueAt = new Date(nowMs - 60_000).toISOString();
		const upserted = store.upsertSpec({
			externalId: "nightly",
			sourcePath: "nightly.cron.md",
			triggerKind: "schedule",
			sourceHash: "h",
			parseStatus: "valid",
			spec: {
				triggerKind: "schedule",
				id: "nightly",
				title: "Nightly",
				prompt: "p",
				workspaceRoot: "/ws",
				enabled: true,
				schedule: "* * * * *",
			},
		});
		store.updateSpecNextRunAt(upserted.record.specId, dueAt);
		const staleSpec = requireValue(store.getSpec(upserted.record.specId));
		const m = new CronMaterializer({ store, now: () => nowMs });

		expect(m.materializeSchedule(staleSpec)).toBe(true);
		expect(m.materializeSchedule(staleSpec)).toBe(false);

		const runs = store.listRuns({ specId: upserted.record.specId });
		expect(runs).toHaveLength(1);
		expect(runs[0]?.scheduledFor).toBe(dueAt);
	});
});

import type {
	CronSpecRecord,
	SqliteCronStore,
} from "../store/sqlite-cron-store";

/**
 * Queue materialization rules shared between the reconciler, watcher, and
 * periodic runner tick. Execution stays trigger-agnostic once a row is
 * queued; this module is the only place that decides when to create a row.
 */

export interface CronMaterializerOptions {
	store: SqliteCronStore;
	now?: () => number;
}

export interface MaterializeSummary {
	oneOffQueued: number;
	scheduleQueued: number;
}

export class CronMaterializer {
	private readonly store: SqliteCronStore;
	private readonly nowFn: () => number;

	constructor(options: CronMaterializerOptions) {
		this.store = options.store;
		this.nowFn = options.now ?? (() => Date.now());
	}

	/**
	 * Run materialization for every valid/enabled spec. Typically called at
	 * startup (after reconciliation) and on each runner tick.
	 */
	public materializeAll(): MaterializeSummary {
		const summary: MaterializeSummary = {
			oneOffQueued: 0,
			scheduleQueued: 0,
		};

		const oneOffs = this.store.listSpecs({
			triggerKind: "one_off",
			enabled: true,
			parseStatus: "valid",
		});
		for (const spec of oneOffs) {
			if (this.materializeOneOff(spec)) summary.oneOffQueued += 1;
		}

		const schedules = this.store.listSpecs({
			triggerKind: "schedule",
			enabled: true,
			parseStatus: "valid",
		});
		for (const spec of schedules) {
			try {
				if (this.materializeSchedule(spec)) summary.scheduleQueued += 1;
			} catch {
				// Keep one stale/invalid persisted schedule from blocking other specs.
			}
		}

		return summary;
	}

	/**
	 * Ensure a single one-off spec has exactly one run record for its current
	 * revision unless an explicit rerun path creates a different trigger kind.
	 * Returns true if a new queued run was created.
	 */
	public materializeOneOff(spec: CronSpecRecord): boolean {
		if (spec.triggerKind !== "one_off") return false;
		if (!spec.enabled || spec.removed) return false;
		if (this.store.hasConsumedOneOffRevision(spec.specId, spec.revision)) {
			return false;
		}
		this.store.enqueueRun({
			specId: spec.specId,
			specRevision: spec.revision,
			triggerKind: "one_off",
			scheduledFor: spec.nextRunAt ?? new Date(this.nowFn()).toISOString(),
		});
		return true;
	}

	/**
	 * Materialize schedule runs. Implements the "one overdue catch-up on
	 * startup, then advance" policy described in PLAN.md.
	 */
	public materializeSchedule(spec: CronSpecRecord): boolean {
		if (spec.triggerKind !== "schedule") return false;
		if (!spec.enabled || spec.removed) return false;
		if (!spec.scheduleExpr) return false;

		return this.store.materializeDueScheduleRun({
			specId: spec.specId,
			nowMs: this.nowFn(),
		}).queued;
	}
}

