			leaseMs: 30_000,
		});
		const claimedRun = requireValue(claim);
		expect(claimedRun.run.runId).toBe(run.runId);
		(runner as unknown as { started: boolean }).started = true;
		(
			runner as unknown as {
				activeRuns: Map<string, { claimToken: string; sessionId?: string }>;
			}
		).activeRuns.set(run.runId, {
			claimToken: claimedRun.claimToken,
			sessionId: "sess_stop",
		});
		await runner.stop();
		await runner.dispose();

		expect(aborted).toBe(1);
		const requeued = requireValue(store.getRun(run.runId));
		expect(requeued.status).toBe("queued");
		expect(requeued.claimToken).toBeUndefined();
		expect(requeued.completedAt).toBeUndefined();

		const reclaimed = store.claimDueRuns({
			nowIso: new Date().toISOString(),
			leaseMs: 30_000,
		});
		expect(reclaimed).toHaveLength(1);
		expect(reclaimed[0]?.run.runId).toBe(run.runId);
	});
});

import { basename } from "node:path";
import type {
	BasicLogger,
	ChatRunTurnRequest,
	ChatStartSessionRequest,
} from "@cline/shared";
import { buildClineSystemPrompt } from "@cline/shared";
import { nowIso } from "@cline/shared/db";
import type { ResolveCronSpecsDirOptions } from "@cline/shared/storage";
import { DefaultToolNames } from "../../extensions/tools/constants";
import { mergeRulesForSystemPrompt } from "../../runtime/safety/rules";
import { buildWorkspaceMetadata } from "../../services/workspace/workspace-manifest";
import { writeCronRunReport } from "../reports/cron-report-writer";
import type { HubScheduleRuntimeHandlers } from "../service/schedule-service";
import type {
	ClaimedCronRun,
	CronEventLogRecord,
	CronRunRecord,
	CronSpecRecord,
	SqliteCronStore,
} from "../store/sqlite-cron-store";
import type { CronMaterializer } from "./cron-materializer";
import { ResourceLimiter } from "./resource-limiter";

/**
 * Trigger-agnostic runner for queued cron runs.
 *
 * Polls cron.db every N seconds, atomically claims queued runs, executes
 * them through the existing runtime handlers (also used by the hub schedule
 * command adapter), persists status transitions transactionally,
 * and writes a markdown report per completion/failure.
 */

const DEFAULT_POLL_INTERVAL_MS = 15_000;
const DEFAULT_CLAIM_LEASE_SECONDS = 90;
const DEFAULT_CRON_EXTENSIONS = ["rules", "skills", "plugins"] as const;

interface HubTurnResult {
	text: string;
	usage?: {
		inputTokens?: number;
		outputTokens?: number;
		cacheReadTokens?: number;
		cacheWriteTokens?: number;
		totalCost?: number;
	};
	toolCalls?: Array<{
		name: string;
		error?: string;
		durationMs?: number;
	}>;
}

function cronExtensionEnabled(
	spec: CronSpecRecord,
	extension: (typeof DEFAULT_CRON_EXTENSIONS)[number],
): boolean {
	return new Set(spec.extensions ?? DEFAULT_CRON_EXTENSIONS).has(extension);
}

function buildToolPolicies(
	spec: CronSpecRecord,
	mode: "act" | "plan" | "yolo",
): ChatStartSessionRequest["toolPolicies"] | undefined {
	if (spec.tools === undefined) {
		return { "*": { autoApprove: true } };
	}
	const policies: NonNullable<ChatStartSessionRequest["toolPolicies"]> = {
		"*": { enabled: false, autoApprove: true },
	};
	for (const tool of spec.tools) {
		policies[tool] = { enabled: true, autoApprove: true };
	}
	if (mode === "yolo") {
		policies[DefaultToolNames.SUBMIT_AND_EXIT] = {
			enabled: true,
			autoApprove: true,
		};
	}
	return policies;
}

function buildNotesSystemPromptSection(
	notesDirectory: string | undefined,
): string | undefined {
	const trimmed = notesDirectory?.trim();
	if (!trimmed) return undefined;
	return [
		"# Notes Directory",
		`Use ${trimmed} for durable notes related to this automation.`,
		"Before starting, inspect relevant existing notes there when useful. During or after the run, write concise notes there when they would help future runs continue with context.",
	].join("\n");
}

class TimeoutError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "TimeoutError";
	}
}

async function withTimeout<T>(
	promise: Promise<T>,
	timeoutMs: number,
): Promise<T> {
	if (timeoutMs <= 0) return promise;
	let handle: ReturnType<typeof setTimeout> | undefined;
	const timeoutPromise = new Promise<never>((_, reject) => {
		handle = setTimeout(() => {
			reject(new TimeoutError("cron run timed out"));
		}, timeoutMs);
	});
	try {
		return await Promise.race([promise, timeoutPromise]);
	} finally {
		if (handle) clearTimeout(handle);
	}
}

export interface CronRunnerOptions {
	store: SqliteCronStore;
	materializer: CronMaterializer;
	runtimeHandlers: HubScheduleRuntimeHandlers;
	eventPublisher?: (
		eventType: string,
		payload: Record<string, unknown>,
	) => void;
	/** Default runtime workspace for the hub/daemon process. */
	workspaceRoot: string;
	/** Cron spec source/report location. Defaults to global `~/.cline/cron`. */
	specs?: ResolveCronSpecsDirOptions;
	logger?: BasicLogger;
	pollIntervalMs?: number;
	claimLeaseSeconds?: number;
	globalMaxConcurrency?: number;
}

export class CronRunner {
	private readonly store: SqliteCronStore;
	private readonly materializer: CronMaterializer;
	private readonly options: CronRunnerOptions;
	private readonly limiter: ResourceLimiter;
	private readonly claimLeaseMs: number;
	private timer: ReturnType<typeof setInterval> | undefined;
	private started = false;
	private ticking = false;
	private disposed = false;
	private stopping = false;
	private readonly activeRuns = new Map<
		string,
		{ claimToken: string; sessionId?: string }
	>();

	constructor(options: CronRunnerOptions) {
		this.store = options.store;
		this.materializer = options.materializer;
		this.options = options;
		this.limiter = new ResourceLimiter(options.globalMaxConcurrency ?? 10);
		this.claimLeaseMs = Math.max(
			5_000,
			(options.claimLeaseSeconds ?? DEFAULT_CLAIM_LEASE_SECONDS) * 1000,
		);
	}

	public async start(): Promise<void> {
		if (this.disposed) throw new Error("CronRunner disposed");
		if (this.started) return;
		this.stopping = false;
		this.started = true;
		const interval = Math.max(
			2_000,
			this.options.pollIntervalMs ?? DEFAULT_POLL_INTERVAL_MS,
		);
		await this.tick();
		this.timer = setInterval(() => void this.tick(), interval);
	}

	public async stop(): Promise<void> {
		const wasStarted = this.started;
		this.started = false;
		this.stopping = true;
		if (this.timer) {
			clearInterval(this.timer);
			this.timer = undefined;
		}
		if (!wasStarted) return;
		const active = [...this.activeRuns.entries()];
		await Promise.all(
			active.map(async ([runId, run]) => {
				if (run.sessionId) {
					try {
						await this.options.runtimeHandlers.abortSession(run.sessionId);
					} catch {
						// best effort
					}
				}
				try {
					this.store.requeueRun({
						runId,
						claimToken: run.claimToken,
						error: "runner stopped before completion",
					});
				} catch {
					// best effort
				}
			}),
		);
	}

	public async dispose(): Promise<void> {
		if (this.disposed) return;
		this.disposed = true;
		await this.stop();
	}

	public async tick(): Promise<void> {
		if (this.ticking) return;
		this.ticking = true;
		try {
			this.materializer.materializeAll();
			const claims = this.store.claimDueRuns({
				nowIso: nowIso(),
				leaseMs: this.claimLeaseMs,
			});
			await Promise.allSettled(claims.map((claim) => this.executeClaim(claim)));
		} catch (err) {
			const log = this.options.logger;
			if (log) {
				if (log.error) log.error("cron.runner.tick.failed", { error: err });
				else log.log("cron.runner.tick.failed", { error: err });
			}
		} finally {
			this.ticking = false;
		}
	}

	public getActiveRuns(): Array<
		CronRunRecord & { claimToken: string; sessionId?: string }
	> {
		return [...this.activeRuns.entries()].flatMap(([runId, active]) => {
			const run = this.store.getRun(runId);
			return run ? [{ ...run, ...active }] : [];
		});
	}

	private async executeClaim(claim: ClaimedCronRun): Promise<void> {
		const run = claim.run;
		const spec = this.store.getSpec(run.specId);
		if (!spec) {
			this.store.completeRun(run.runId, {
				status: "failed",
				error: "spec not found",
				claimToken: claim.claimToken,
			});
			return;
		}
		if (!spec.enabled || spec.removed) {
			this.store.completeRun(run.runId, {
				status: "cancelled",
				error: "spec disabled or removed",
				claimToken: claim.claimToken,
			});
			return;
		}

		const maxParallel =
			spec.maxParallel && spec.maxParallel > 0 ? spec.maxParallel : 1;
		const acquired = this.limiter.acquire(spec.specId, run.runId, maxParallel);
		if (!acquired) {
			this.store.requeueRun({
				runId: run.runId,
				claimToken: claim.claimToken,
				error: "concurrency limit reached",
			});
			return;
		}
		if (this.stopping) {
			this.limiter.release(spec.specId, run.runId);
			this.store.requeueRun({
				runId: run.runId,
				claimToken: claim.claimToken,
				error: "runner stopped before execution",
			});
			return;
		}

		this.activeRuns.set(run.runId, { claimToken: claim.claimToken });
		const triggerEvent = run.triggerEventId
			? this.store.getEventLog(run.triggerEventId)
			: undefined;
		let sessionId: string | undefined;
		let releaseLeaseHeartbeat: (() => void) | undefined;
		const startMs = Date.now();
		let executionDeadlineMs: number | undefined;
		if (spec.timeoutSeconds && spec.timeoutSeconds > 0) {
			executionDeadlineMs = startMs + spec.timeoutSeconds * 1000;
		}

		try {
			releaseLeaseHeartbeat = this.startClaimLeaseHeartbeat(claim);
			const startRequest = await this.buildStartRequest(spec);
			const startResp =
				await this.options.runtimeHandlers.startSession(startRequest);
			sessionId = startResp.sessionId.trim();
			if (!sessionId) throw new Error("runtime returned empty sessionId");
			this.activeRuns.set(run.runId, {
				claimToken: claim.claimToken,
				sessionId,
			});
			this.store.attachSessionIdToRun(run.runId, sessionId);

			const turnRequest: ChatRunTurnRequest = {
				config: startRequest,
				prompt: this.buildPrompt(spec, triggerEvent),
			};
			const sendPromise = this.options.runtimeHandlers.sendSession(
				sessionId,
				turnRequest,
			);
			const timeoutMs = executionDeadlineMs
				? Math.max(1, executionDeadlineMs - Date.now())
				: 0;
			const sendResult = await withTimeout(sendPromise, timeoutMs);
			const result = sendResult.result as HubTurnResult;

			const endMs = Date.now();
			const reportPath = writeCronRunReport({
				specs: this.options.specs,
				workspaceRoot: this.options.workspaceRoot,
				run: { ...run, sessionId, status: "done" },
				spec,
				data: {
					finalText: result.text,
					usage: result.usage,
					toolCalls: result.toolCalls,
					durationMs: endMs - startMs,
					triggerEvent,
				},
			});
			this.store.completeRun(run.runId, {
				status: "done",
				sessionId,
				reportPath,
				claimToken: claim.claimToken,
			});
			this.publishScheduleExecutionEvent(
				"schedule.execution.completed",
				spec,
				run.runId,
			);
			this.store.updateSpecLastRunAt(spec.specId, nowIso());
		} catch (err) {
			const isTimeout = err instanceof TimeoutError;
			if (sessionId && isTimeout) {
				try {
					await this.options.runtimeHandlers.abortSession(sessionId);
				} catch {
					// best effort
				}
			}
			const message = err instanceof Error ? err.message : String(err);
			const endMs = Date.now();
			const reportPath = writeCronRunReport({
				specs: this.options.specs,
				workspaceRoot: this.options.workspaceRoot,
				run: { ...run, sessionId, status: "failed" },
				spec,
				data: { error: message, durationMs: endMs - startMs, triggerEvent },
			});
			this.store.completeRun(run.runId, {
				status: "failed",
				sessionId,
				reportPath,
				error: message,
				claimToken: claim.claimToken,
			});
			this.publishScheduleExecutionEvent(
				"schedule.execution.failed",
				spec,
				run.runId,
			);
		} finally {
			if (run.triggerKind === "one_off") {
				this.store.updateSpecNextRunAt(spec.specId, undefined);
			}
			releaseLeaseHeartbeat?.();
			if (sessionId) {
				try {
					await this.options.runtimeHandlers.stopSession(sessionId);
				} catch {
					// best effort
				}
			}
			this.activeRuns.delete(run.runId);
			this.limiter.release(spec.specId, run.runId);
		}
	}

	private publishScheduleExecutionEvent(
		eventType: "schedule.execution.completed" | "schedule.execution.failed",
		spec: CronSpecRecord,
		runId: string,
	): void {
		if (spec.source !== "hub-schedule" || !this.options.eventPublisher) {
			return;
		}
		const run = this.store.getRun(runId);
		if (!run) {
			return;
		}
		const status =
			run.status === "done"
				? "success"
				: run.status === "cancelled"
					? "aborted"
					: run.status === "running"
						? "running"
						: run.status === "queued"
							? "pending"
							: "failed";
		this.options.eventPublisher(eventType, {
			scheduleId: spec.externalId,
			executionId: run.runId,
			sessionId: run.sessionId,
			triggeredAt: new Date(run.scheduledFor ?? run.createdAt).getTime(),
			startedAt: run.startedAt ? new Date(run.startedAt).getTime() : undefined,
			endedAt: run.completedAt
				? new Date(run.completedAt).getTime()
				: undefined,
			status,
			errorMessage: run.error,
		});
	}

	private buildPrompt(
		spec: CronSpecRecord,
		triggerEvent: CronEventLogRecord | undefined,
	): string {
		const prompt = spec.prompt ?? "";
		if (!triggerEvent) return prompt;
		const eventContext = {
			eventId: triggerEvent.eventId,
			eventType: triggerEvent.eventType,
			source: triggerEvent.source,
			subject: triggerEvent.subject,
			occurredAt: triggerEvent.occurredAt,
			workspaceRoot: triggerEvent.workspaceRoot,
			dedupeKey: triggerEvent.dedupeKey,
			attributes: triggerEvent.attributes,
			payload: triggerEvent.payload,
		};
		return `${prompt}\n\nTrigger event:\n${JSON.stringify(eventContext, null, 2)}`;
	}

	private startClaimLeaseHeartbeat(claim: ClaimedCronRun): () => void {
		const heartbeatMs = Math.max(1_000, Math.floor(this.claimLeaseMs / 2));
		const interval = setInterval(() => {
			const leaseUntilAt = new Date(
				Date.now() + this.claimLeaseMs,
			).toISOString();
			const renewed = this.store.renewClaim(
				claim.run.runId,
				claim.claimToken,
				leaseUntilAt,
			);
			if (!renewed) {
				clearInterval(interval);
			}
		}, heartbeatMs);
		return () => clearInterval(interval);
	}

	private async buildSystemPrompt(
		spec: CronSpecRecord,
		workspaceRoot: string,
		mode: "act" | "plan" | "yolo",
		provider: string,
	): Promise<string> {
		const notes = buildNotesSystemPromptSection(spec.notesDirectory);
		const additional = mergeRulesForSystemPrompt(undefined, notes);
		const metadata = await buildWorkspaceMetadata(workspaceRoot);
		const base = buildClineSystemPrompt({
			ide: "Cline Cron",
			workspaceRoot,
			workspaceName: basename(workspaceRoot),
			metadata,
			rules: spec.systemPrompt ? undefined : additional,
			mode,
			providerId: provider,
			overridePrompt: spec.systemPrompt,
			platform:
				(typeof process !== "undefined" && process?.platform) || "unknown",
		});
		return spec.systemPrompt
			? (mergeRulesForSystemPrompt(base, additional) ?? base)
			: base;
	}

	private async buildStartRequest(
		spec: CronSpecRecord,
	): Promise<ChatStartSessionRequest> {
		const workspaceRoot = (spec.workspaceRoot ?? "").trim();
		const provider = (spec.providerId ?? "").trim();
		const model = (spec.modelId ?? "").trim();
		const runtimeOptions =
			spec.metadata?.__hubRuntimeOptions &&
			typeof spec.metadata.__hubRuntimeOptions === "object" &&
			!Array.isArray(spec.metadata.__hubRuntimeOptions)
				? (spec.metadata.__hubRuntimeOptions as {
						enableTools?: boolean;
						enableSpawn?: boolean;
						enableTeams?: boolean;
						autoApproveTools?: boolean;
					})
				: undefined;
		const cwd =
			typeof spec.metadata?.__hubScheduleCwd === "string" &&
			spec.metadata.__hubScheduleCwd.trim()
				? spec.metadata.__hubScheduleCwd.trim()
				: workspaceRoot;
		if (!workspaceRoot) {
			throw new Error("cron spec requires workspaceRoot");
		}
		const mode =
			spec.mode === "plan" ? "plan" : spec.mode === "act" ? "act" : "yolo";
		return {
			workspaceRoot,
			cwd,
			provider,
			model,
			mode,
			source: spec.source?.trim() || "user",
			systemPrompt: await this.buildSystemPrompt(
				spec,
				workspaceRoot,
				mode,
				provider,
			),
			maxIterations: spec.maxIterations,
			enableTools: runtimeOptions?.enableTools ?? true,
			enableSpawn: runtimeOptions?.enableSpawn ?? true,
			enableTeams: runtimeOptions?.enableTeams ?? true,
			autoApproveTools: runtimeOptions?.autoApproveTools ?? true,
			toolPolicies: buildToolPolicies(spec, mode),
			configExtensions: DEFAULT_CRON_EXTENSIONS.filter((extension) =>
				cronExtensionEnabled(spec, extension),
			),
		};
	}
}

export * from "./cron-materializer";
export * from "./cron-runner";
export * from "./resource-limiter";

export class ResourceLimiter {
	private readonly globalMaxConcurrency: number;
	private readonly activeExecutions = new Map<string, Set<string>>();

	constructor(globalMaxConcurrency: number) {
		this.globalMaxConcurrency = Math.max(1, Math.floor(globalMaxConcurrency));
	}

	public acquire(
		scheduleId: string,
		executionId: string,
		maxParallel: number,
	): boolean {
		if (this.getGlobalActiveCount() >= this.globalMaxConcurrency) {
			return false;
		}
		const perScheduleLimit = Math.max(1, Math.floor(maxParallel));
		const scheduleExecutions =
			this.activeExecutions.get(scheduleId) ?? new Set<string>();
		if (scheduleExecutions.size >= perScheduleLimit) {
			return false;
		}
		scheduleExecutions.add(executionId);
		this.activeExecutions.set(scheduleId, scheduleExecutions);
		return true;
	}

	public release(scheduleId: string, executionId: string): void {
		const executions = this.activeExecutions.get(scheduleId);
		if (!executions) {
			return;
		}
		executions.delete(executionId);
		if (executions.size === 0) {
			this.activeExecutions.delete(scheduleId);
		}
	}

	public getGlobalActiveCount(): number {
		let total = 0;
		for (const executions of this.activeExecutions.values()) {
			total += executions.size;
		}
		return total;
	}
}

import { describe, expect, it } from "vitest";
import { getNextCronTime } from "./scheduler";

describe("hub scheduler cron helpers", () => {
	it("computes the next matching cron timestamp", () => {
		const after = new Date(2026, 3, 21, 10, 3, 12).getTime();
		const next = getNextCronTime("*/15 * * * *", after);
		expect(next).toBe(new Date(2026, 3, 21, 10, 15, 0).getTime());
	});

	it("computes the next matching cron timestamp in an explicit timezone", () => {
		const after = Date.parse("2026-04-21T15:30:00.000Z");
		const next = getNextCronTime("0 9 * * *", after, "America/New_York");
		expect(next).toBe(Date.parse("2026-04-22T13:00:00.000Z"));
	});
});

function parseCronField(
	token: string,
	min: number,
	max: number,
	names?: readonly string[],
): number[] {
	const results = new Set<number>();

	function resolveValue(raw: string): number {
		const lower = raw.toLowerCase();
		if (names) {
			const index = names.indexOf(lower);
			if (index !== -1) {
				return index + min;
			}
		}
		const value = Number(raw);
		if (!Number.isInteger(value) || value < min || value > max) {
			throw new Error(`Invalid cron value "${raw}" for range [${min}-${max}]`);
		}
		return value;
	}

	for (const part of token.split(",")) {
		if (part === "*") {
			for (let value = min; value <= max; value += 1) {
				results.add(value);
			}
			continue;
		}

		const stepSeparator = part.indexOf("/");
		if (stepSeparator !== -1) {
			const rangePart = part.slice(0, stepSeparator);
			const step = Number(part.slice(stepSeparator + 1));
			if (!Number.isInteger(step) || step < 1) {
				throw new Error(`Invalid step "${part.slice(stepSeparator + 1)}"`);
			}
			let from = min;
			let to = max;
			if (rangePart !== "*") {
				const dashIndex = rangePart.indexOf("-");
				if (dashIndex !== -1) {
					from = resolveValue(rangePart.slice(0, dashIndex));
					to = resolveValue(rangePart.slice(dashIndex + 1));
				} else {
					from = resolveValue(rangePart);
				}
			}
			if (from > to) {
				throw new Error(`Invalid cron range "${rangePart}"`);
			}
			for (let value = from; value <= to; value += step) {
				results.add(value);
			}
			continue;
		}

		const dashIndex = part.indexOf("-");
		if (dashIndex !== -1) {
			const from = resolveValue(part.slice(0, dashIndex));
			const to = resolveValue(part.slice(dashIndex + 1));
			if (from > to) {
				throw new Error(`Invalid cron range "${part}"`);
			}
			for (let value = from; value <= to; value += 1) {
				results.add(value);
			}
			continue;
		}

		results.add(resolveValue(part));
	}

	return [...results].sort((left, right) => left - right);
}

const MONTH_NAMES = [
	"jan",
	"feb",
	"mar",
	"apr",
	"may",
	"jun",
	"jul",
	"aug",
	"sep",
	"oct",
	"nov",
	"dec",
] as const;

const DOW_NAMES = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"] as const;

export interface ParsedCron {
	minutes: number[];
	hours: number[];
	daysOfMonth: number[];
	months: number[];
	daysOfWeek: number[];
}

interface CronDateParts {
	month: number;
	dayOfMonth: number;
	dayOfWeek: number;
	hour: number;
	minute: number;
}

function getRequiredField(
	fields: readonly string[],
	index: number,
	pattern: string,
): string {
	const value = fields[index];
	if (typeof value !== "string") {
		throw new Error(
			`Invalid cron pattern "${pattern}": missing field ${index + 1}`,
		);
	}
	return value;
}

function getFirstCronValue(values: readonly number[], label: string): number {
	const value = values[0];
	if (typeof value !== "number") {
		throw new Error(`Invalid cron pattern: no values parsed for ${label}`);
	}
	return value;
}

export function parseCron(pattern: string): ParsedCron {
	const fields = pattern.trim().split(/\s+/);
	if (fields.length !== 5) {
		throw new Error(
			`Invalid cron pattern "${pattern}": expected 5 fields, got ${fields.length}`,
		);
	}
	return {
		minutes: parseCronField(getRequiredField(fields, 0, pattern), 0, 59),
		hours: parseCronField(getRequiredField(fields, 1, pattern), 0, 23),
		daysOfMonth: parseCronField(getRequiredField(fields, 2, pattern), 1, 31),
		months: parseCronField(
			getRequiredField(fields, 3, pattern),
			1,
			12,
			MONTH_NAMES,
		),
		daysOfWeek: parseCronField(
			getRequiredField(fields, 4, pattern),
			0,
			6,
			DOW_NAMES,
		),
	};
}

export function validateCronPattern(pattern: string): void {
	parseCron(pattern);
}

export function validateCronSchedule(
	pattern: string,
	timezone?: string,
	after: number = Date.now(),
): void {
	getNextCronTime(pattern, after, timezone);
}

const TIMEZONE_FORMATTERS = new Map<string, Intl.DateTimeFormat>();
const DOW_BY_SHORT_NAME = new Map(
	DOW_NAMES.map((name, index) => [name, index] as const),
);

function normalizeTimezone(timezone: string | undefined): string | undefined {
	const trimmed = timezone?.trim();
	return trimmed ? trimmed : undefined;
}

function getTimezoneFormatter(timezone: string): Intl.DateTimeFormat {
	const existing = TIMEZONE_FORMATTERS.get(timezone);
	if (existing) return existing;
	const formatter = new Intl.DateTimeFormat("en-US", {
		timeZone: timezone,
		calendar: "gregory",
		numberingSystem: "latn",
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
		weekday: "short",
		hour: "2-digit",
		minute: "2-digit",
		hourCycle: "h23",
	});
	TIMEZONE_FORMATTERS.set(timezone, formatter);
	return formatter;
}

export function validateTimezone(timezone: string | undefined): void {
	const normalized = normalizeTimezone(timezone);
	if (!normalized) return;
	getTimezoneFormatter(normalized).format(new Date());
}

function getZonedCronDateParts(
	timestampMs: number,
	timezone: string,
): CronDateParts {
	const parts = getTimezoneFormatter(timezone).formatToParts(
		new Date(timestampMs),
	);
	const byType = new Map(parts.map((part) => [part.type, part.value]));
	const weekdayRaw = byType.get("weekday")?.toLowerCase().slice(0, 3) ?? "";
	const dayOfWeek = DOW_BY_SHORT_NAME.get(
		weekdayRaw as (typeof DOW_NAMES)[number],
	);
	if (dayOfWeek === undefined) {
		throw new Error(`Unable to resolve weekday for timezone "${timezone}"`);
	}
	return {
		month: Number(byType.get("month")),
		dayOfMonth: Number(byType.get("day")),
		dayOfWeek,
		hour: Number(byType.get("hour")),
		minute: Number(byType.get("minute")),
	};
}

function getLocalCronDateParts(timestampMs: number): CronDateParts {
	const date = new Date(timestampMs);
	return {
		month: date.getMonth() + 1,
		dayOfMonth: date.getDate(),
		dayOfWeek: date.getDay(),
		hour: date.getHours(),
		minute: date.getMinutes(),
	};
}

function cronMatchesParts(cron: ParsedCron, parts: CronDateParts): boolean {
	return (
		cron.months.includes(parts.month) &&
		cron.daysOfMonth.includes(parts.dayOfMonth) &&
		cron.daysOfWeek.includes(parts.dayOfWeek) &&
		cron.hours.includes(parts.hour) &&
		cron.minutes.includes(parts.minute)
	);
}

function getNextCronTimeByMinuteScan(
	pattern: string,
	after: number,
	timezone: string,
): number {
	const cron = parseCron(pattern);
	const next = new Date(after);
	next.setSeconds(0, 0);
	let nextMs = next.getTime() + 60_000;

	const limit = new Date(after);
	limit.setFullYear(limit.getFullYear() + 4);
	const limitMs = limit.getTime();

	while (nextMs <= limitMs) {
		if (cronMatchesParts(cron, getZonedCronDateParts(nextMs, timezone))) {
			return nextMs;
		}
		nextMs += 60_000;
	}

	throw new Error(
		`No cron occurrence found within 4 years for pattern "${pattern}" in timezone "${timezone}"`,
	);
}

export function getNextCronTime(
	pattern: string,
	after: number,
	timezone?: string,
): number {
	const normalizedTimezone = normalizeTimezone(timezone);
	if (normalizedTimezone) {
		validateTimezone(normalizedTimezone);
		return getNextCronTimeByMinuteScan(pattern, after, normalizedTimezone);
	}

	const cron = parseCron(pattern);
	let next = new Date(after);
	next.setSeconds(0, 0);
	next = new Date(next.getTime() + 60_000);

	const limit = new Date(after);
	limit.setFullYear(limit.getFullYear() + 4);

	while (next <= limit) {
		const { month, dayOfMonth, dayOfWeek, hour, minute } =
			getLocalCronDateParts(next.getTime());

		if (!cron.months.includes(month)) {
			const targetMonth =
				cron.months.find((value) => value > month) ??
				getFirstCronValue(cron.months, "months");
			const yearDelta = targetMonth <= month ? 1 : 0;
			next = new Date(
				next.getFullYear() + yearDelta,
				targetMonth - 1,
				1,
				0,
				0,
				0,
				0,
			);
			continue;
		}

		if (
			!cron.daysOfMonth.includes(dayOfMonth) ||
			!cron.daysOfWeek.includes(dayOfWeek)
		) {
			next = new Date(
				next.getFullYear(),
				next.getMonth(),
				dayOfMonth + 1,
				0,
				0,
				0,
				0,
			);
			continue;
		}

		if (!cron.hours.includes(hour)) {
			const targetHour =
				cron.hours.find((value) => value > hour) ??
				getFirstCronValue(cron.hours, "hours");
			const dayDelta = targetHour <= hour ? 1 : 0;
			next = new Date(
				next.getFullYear(),
				next.getMonth(),
				next.getDate() + dayDelta,
				targetHour,
				0,
				0,
				0,
			);
			continue;
		}

		if (!cron.minutes.includes(minute)) {
			const targetMinute =
				cron.minutes.find((value) => value > minute) ??
				getFirstCronValue(cron.minutes, "minutes");
			const hourDelta = targetMinute <= minute ? 1 : 0;
			next = new Date(
				next.getFullYear(),
				next.getMonth(),
				next.getDate(),
				next.getHours() + hourDelta,
				targetMinute,
				0,
				0,
			);
			continue;
		}

		return next.getTime();
	}

	throw new Error(
		`No cron occurrence found within 4 years for pattern "${pattern}"`,
	);
}

import type { AutomationEventEnvelope, BasicLogger } from "@cline/shared";
import type { ResolveCronSpecsDirOptions } from "@cline/shared/storage";
import {
	CronEventIngress,
	type CronEventIngressResult,
} from "../events/cron-event-ingress";
import { CronMaterializer } from "../runner/cron-materializer";
import { CronRunner } from "../runner/cron-runner";
import { CronReconciler } from "../specs/cron-reconciler";
import { CronWatcher } from "../specs/cron-watcher";
import type {
	CronRunRecord,
	CronSpecRecord,
	ListEventLogsOptions,
	ListRunsOptions,
	ListSpecsOptions,
} from "../store/sqlite-cron-store";
import { SqliteCronStore } from "../store/sqlite-cron-store";
import type { HubScheduleRuntimeHandlers } from "./schedule-service";

/**
 * Top-level orchestrator for file-based cron automation.
 *
 * Wires together:
 *   - `SqliteCronStore` (cron.db)
 *   - `CronReconciler` (disk -> DB)
 *   - `CronWatcher` (cron specs directory filesystem events)
 *   - `CronMaterializer` (queue materialization)
 *   - `CronRunner` (claim + execute + report)
 *
 * This service is the forward path: the legacy `HubScheduleService`
 * continues to serve programmatic schedules, while `CronService` handles
 * everything sourced from the configured file-based cron directory.
 */

export interface CronServiceOptions {
	/** Default runtime workspace for the hub/daemon process. */
	workspaceRoot: string;
	/** Cron spec source/report location. Defaults to global `~/.cline/cron`. */
	specs?: ResolveCronSpecsDirOptions;
	runtimeHandlers: HubScheduleRuntimeHandlers;
	dbPath?: string;
	logger?: BasicLogger;
	pollIntervalMs?: number;
	claimLeaseSeconds?: number;
	globalMaxConcurrency?: number;
	watcherDebounceMs?: number;
}

export class CronService {
	private readonly store: SqliteCronStore;
	private readonly reconciler: CronReconciler;
	private readonly watcher: CronWatcher;
	private readonly eventIngress: CronEventIngress;
	private readonly materializer: CronMaterializer;
	private readonly runner: CronRunner;
	private started = false;
	private disposed = false;

	constructor(options: CronServiceOptions) {
		this.store = new SqliteCronStore({ dbPath: options.dbPath });
		const specs = options.specs;
		this.reconciler = new CronReconciler({
			store: this.store,
			specs,
		});
		this.materializer = new CronMaterializer({ store: this.store });
		this.eventIngress = new CronEventIngress({
			store: this.store,
			logger: options.logger,
		});
		this.runner = new CronRunner({
			store: this.store,
			materializer: this.materializer,
			runtimeHandlers: options.runtimeHandlers,
			workspaceRoot: options.workspaceRoot,
			specs,
			logger: options.logger,
			pollIntervalMs: options.pollIntervalMs,
			claimLeaseSeconds: options.claimLeaseSeconds,
			globalMaxConcurrency: options.globalMaxConcurrency,
		});
		this.watcher = new CronWatcher({
			reconciler: this.reconciler,
			debounceMs: options.watcherDebounceMs,
			onReconciled: () => {
				this.materializer.materializeAll();
			},
			onError: (err) => {
				const log = options.logger;
				if (log) {
					if (log.error) log.error("cron.watcher.failed", { error: err });
					else log.log("cron.watcher.failed", { error: err });
				}
			},
		});
	}

	public async start(): Promise<void> {
		if (this.disposed) throw new Error("CronService disposed");
		if (this.started) return;
		this.started = true;
		await this.reconciler.reconcileAll();
		this.materializer.materializeAll();
		this.watcher.start();
		await this.runner.start();
	}

	public async stop(): Promise<void> {
		this.watcher.stop();
		await this.runner.stop();
		this.started = false;
	}

	public async dispose(): Promise<void> {
		if (this.disposed) return;
		this.disposed = true;
		this.watcher.dispose();
		await this.runner.dispose();
		this.store.close();
	}

	public listSpecs(options?: ListSpecsOptions): CronSpecRecord[] {
		return this.store.listSpecs(options);
	}

	public getSpec(specId: string): CronSpecRecord | undefined {
		return this.store.getSpec(specId);
	}

	public listRuns(options?: ListRunsOptions): CronRunRecord[] {
		return this.store.listRuns(options);
	}

	public getRun(runId: string): CronRunRecord | undefined {
		return this.store.getRun(runId);
	}

	public listActiveRuns(): CronRunRecord[] {
		return this.store.listRuns({ status: "running", limit: 200 });
	}

	public listUpcomingRuns(limit = 20): CronRunRecord[] {
		return this.store.listRuns({ status: "queued", limit });
	}

	public async reconcileNow(): Promise<void> {
		await this.reconciler.reconcileAll();
		this.materializer.materializeAll();
	}

	public ingestEvent(event: AutomationEventEnvelope): CronEventIngressResult {
		return this.eventIngress.ingestEvent(event);
	}

	public listEventLogs(options?: ListEventLogsOptions) {
		return this.store.listEventLogs(options);
	}

	public getEventLog(eventId: string) {
		return this.store.getEventLog(eventId);
	}
}

export * from "./cron-service";
