function toMillis(value: string | undefined): number | undefined {
	return value ? new Date(value).getTime() : undefined;
}

function scheduleMetadata(
	spec: CronSpecRecord,
): Record<string, unknown> | undefined {
	const metadata = spec.metadata ? { ...spec.metadata } : undefined;
	if (metadata) {
		delete metadata.__hubScheduleCreatedBy;
		delete metadata.__hubScheduleCwd;
		delete metadata.__hubRuntimeOptions;
	}
	return metadata;
}

function specToSchedule(spec: CronSpecRecord): ScheduleRecord {
	const metadata = spec.metadata;
	return {
		scheduleId: spec.externalId,
		name: spec.title,
		cronPattern:
			spec.triggerKind === "one_off"
				? ONE_TIME_SCHEDULE_CRON_PATTERN
				: (spec.scheduleExpr ?? ""),
		prompt: spec.prompt ?? "",
		workspaceRoot: spec.workspaceRoot ?? "",
		cwd:
			typeof metadata?.__hubScheduleCwd === "string"
				? metadata.__hubScheduleCwd
				: undefined,
		modelSelection:
			spec.providerId || spec.modelId
				? {
						providerId: spec.providerId ?? "",
						modelId: spec.modelId ?? "",
					}
				: undefined,
		enabled: spec.enabled && !spec.removed && spec.parseStatus === "valid",
		mode: spec.mode === "plan" ? "plan" : spec.mode === "yolo" ? "yolo" : "act",
		systemPrompt: spec.systemPrompt,
		maxIterations: spec.maxIterations,
		timeoutSeconds: spec.timeoutSeconds,
		maxParallel: spec.maxParallel ?? 1,
		createdAt: new Date(spec.createdAt).getTime(),
		updatedAt: new Date(spec.updatedAt).getTime(),
		nextRunAt: toMillis(spec.nextRunAt),
		lastRunAt: toMillis(spec.lastRunAt),
		createdBy:
			typeof metadata?.__hubScheduleCreatedBy === "string"
				? metadata.__hubScheduleCreatedBy
				: undefined,
		tags: spec.tags,
		runtimeOptions:
			metadata?.__hubRuntimeOptions &&
			typeof metadata.__hubRuntimeOptions === "object" &&
			!Array.isArray(metadata.__hubRuntimeOptions)
				? (metadata.__hubRuntimeOptions as ScheduleRecord["runtimeOptions"])
				: undefined,
		metadata: scheduleMetadata(spec) as ScheduleRecord["metadata"],
	};
}

function runStatusToScheduleStatus(
	status: CronRunRecord["status"],
): ScheduleExecutionStatus {
	switch (status) {
		case "done":
			return "success";
		case "cancelled":
			return "aborted";
		case "running":
			return "running";
		case "queued":
			return "pending";
		default:
			return "failed";
	}
}

function runToExecution(
	run: CronRunRecord,
	scheduleId: string,
): ScheduleExecutionRecord {
	return {
		executionId: run.runId,
		scheduleId,
		sessionId: run.sessionId,
		triggeredAt: new Date(run.scheduledFor ?? run.createdAt).getTime(),
		startedAt: toMillis(run.startedAt),
		endedAt: toMillis(run.completedAt),
		status: runStatusToScheduleStatus(run.status),
		errorMessage: run.error,
	};
}

export class HubScheduleService {
	private readonly store: SqliteCronStore;
	private readonly materializer: CronMaterializer;
	private readonly runner: CronRunner;
	private started = false;
	private disposed = false;

	constructor(options: HubScheduleServiceOptions) {
		this.store = new SqliteCronStore({
			dbPath: options.dbPath,
		});
		this.materializer = new CronMaterializer({ store: this.store });
		this.runner = new CronRunner({
			store: this.store,
			materializer: this.materializer,
			runtimeHandlers: options.runtimeHandlers,
			eventPublisher: options.eventPublisher,
			workspaceRoot: "",
			logger: options.logger,
			pollIntervalMs: options.pollIntervalMs,
			claimLeaseSeconds: options.claimLeaseSeconds,
			globalMaxConcurrency: options.globalMaxConcurrency,
		});
	}

	public async start(): Promise<void> {
		if (this.disposed) throw new Error("HubScheduleService has been disposed");
		if (this.started) return;
		this.started = true;
		await this.runner.start();
	}

	public async stop(): Promise<void> {
		await this.runner.stop();
		this.started = false;
	}

	public async dispose(): Promise<void> {
		if (this.disposed) return;
		this.disposed = true;
		await this.runner.dispose();
		this.store.close();
	}

	public createSchedule(input: HubScheduleCreateInput): ScheduleRecord {
		this.validateScheduleTiming(input.cronPattern, input.metadata, true);
		if (!input.workspaceRoot?.trim()) {
			throw new Error("workspaceRoot is required for schedules");
		}
		return specToSchedule(this.store.createHubSchedule(input));
	}

	public getSchedule(scheduleId: string): ScheduleRecord | undefined {
		const spec = this.store.getHubSchedule(scheduleId);
		return spec ? specToSchedule(spec) : undefined;
	}

	public listSchedules(options: ListSchedulesOptions = {}): ScheduleRecord[] {
		return this.store
			.listHubSchedules(options)
			.map((spec) => specToSchedule(spec));
	}

	public updateSchedule(
		scheduleId: string,
		updates: HubScheduleUpdateInput,
	): ScheduleRecord | undefined {
		const current = this.store.getHubSchedule(scheduleId);
		if (!current) return undefined;
		const nextWorkspaceRoot =
			updates.workspaceRoot !== undefined
				? updates.workspaceRoot.trim()
				: current.workspaceRoot;
		const nextEnabled = updates.enabled ?? current.enabled;
		const currentSchedule = specToSchedule(current);
		this.validateScheduleTiming(
			updates.cronPattern ?? currentSchedule.cronPattern,
			updates.metadata ?? currentSchedule.metadata,
			nextEnabled,
		);
		if (nextEnabled && !nextWorkspaceRoot) {
			throw new Error("workspaceRoot is required for enabled schedules");
		}
		const updated = this.store.updateHubSchedule(scheduleId, {
			...updates,
			scheduleId,
		});
		return updated ? specToSchedule(updated) : undefined;
	}

	private validateScheduleTiming(
		cronPattern: string,
		metadata: HubScheduleCreateInput["metadata"],
		requireFutureRunAt: boolean,
	): void {
		if (cronPattern.trim() !== ONE_TIME_SCHEDULE_CRON_PATTERN) {
			validateCronPattern(cronPattern);
			return;
		}
		const runAt = metadata?.[ONE_TIME_SCHEDULE_RUN_AT_METADATA_KEY];
		if (
			typeof runAt !== "number" ||
			!Number.isFinite(runAt) ||
			(requireFutureRunAt && runAt <= Date.now())
		) {
			throw new Error("runAt must be a future timestamp");
		}
	}

	public deleteSchedule(scheduleId: string): boolean {
		return this.store.deleteHubSchedule(scheduleId);
	}

	public pauseSchedule(scheduleId: string): ScheduleRecord | undefined {
		return this.updateSchedule(scheduleId, { scheduleId, enabled: false });
	}

	public resumeSchedule(scheduleId: string): ScheduleRecord | undefined {
		return this.updateSchedule(scheduleId, { scheduleId, enabled: true });
	}

	public async triggerScheduleNow(
		scheduleId: string,
	): Promise<ScheduleExecutionRecord | undefined> {
		const run = this.store.enqueueHubScheduleRun(scheduleId, "manual");
		if (!run) return undefined;
		await this.runner.tick();
		const completed = this.store.getRun(run.runId) ?? run;
		return runToExecution(completed, scheduleId);
	}

	public triggerScheduleNowDetached(
		scheduleId: string,
	): ScheduleExecutionRecord | undefined {
		const run = this.store.enqueueHubScheduleRun(scheduleId, "manual");
		if (!run) return undefined;
		void this.runner.tick().catch(() => undefined);
		return runToExecution(run, scheduleId);
	}

	public listScheduleExecutions(
		options: ListScheduleExecutionsOptions,
	): ScheduleExecutionRecord[] {
		const spec = options.scheduleId
			? this.store.getHubSchedule(options.scheduleId)
			: undefined;
		const runOptions: ListRunsOptions = {
			specId: spec?.specId,
			limit: options.limit,
		};
		const runs = this.store.listRuns(runOptions);
		return runs
			.map((run) => {
				const runSpec = spec ?? this.store.getSpec(run.specId);
				if (!runSpec || runSpec.source !== "hub-schedule") return undefined;
				return runToExecution(run, runSpec.externalId);
			})
			.filter((record): record is ScheduleExecutionRecord => {
				if (!record) return false;
				return !options.status || record.status === options.status;
			});
	}

	public getScheduleStats(scheduleId: string): ScheduleExecutionStats {
		const all = this.listScheduleExecutions({ scheduleId, limit: 10_000 });
		if (all.length === 0) {
			return { totalRuns: 0, successRate: 0, avgDurationSeconds: 0 };
		}
		let success = 0;
		let withDuration = 0;
		let durationMsTotal = 0;
		let lastFailure: ScheduleExecutionRecord | undefined;
		for (const execution of all) {
			if (execution.status === "success" || execution.status === "completed") {
				success += 1;
			}
			if (
				!lastFailure &&
				execution.status !== "success" &&
				execution.status !== "completed"
			) {
				lastFailure = execution;
			}
			if (execution.startedAt && execution.endedAt) {
				durationMsTotal += execution.endedAt - execution.startedAt;
				withDuration += 1;
			}
		}
		return {
			totalRuns: all.length,
			successRate: success / all.length,
			avgDurationSeconds:
				withDuration > 0 ? durationMsTotal / withDuration / 1000 : 0,
			lastFailure,
		};
	}

	public getActiveExecutions(): ActiveScheduledExecution[] {
		return this.runner.getActiveRuns().flatMap((run) => {
			const spec = this.store.getSpec(run.specId);
			if (!spec || spec.source !== "hub-schedule" || !run.sessionId) return [];
			return [
				{
					executionId: run.runId,
					scheduleId: spec.externalId,
					sessionId: run.sessionId,
					startedAt: run.startedAt ?? new Date().toISOString(),
					timeoutAt:
						spec.timeoutSeconds && run.startedAt
							? new Date(
									new Date(run.startedAt).getTime() +
										spec.timeoutSeconds * 1000,
								).toISOString()
							: undefined,
				},
			];
		});
	}

	public getUpcomingRuns(limit = 20): Array<{
		scheduleId: string;
		name: string;
		nextRunAt: string;
	}> {
		const options: ListSpecsOptions = {
			triggerKind: "schedule",
			enabled: true,
			limit,
		};
		return this.store
			.listSpecs(options)
			.flatMap((spec) =>
				spec.source === "hub-schedule" && spec.nextRunAt
					? [{ spec, nextRunAt: spec.nextRunAt }]
					: [],
			)
			.sort((a, b) => String(a.nextRunAt).localeCompare(String(b.nextRunAt)))
			.slice(0, limit)
			.map(({ spec, nextRunAt }) => ({
				scheduleId: spec.externalId,
				name: spec.title,
				nextRunAt,
			}));
	}
}

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { SqliteCronStore } from "../store/sqlite-cron-store";
import { CronReconciler } from "./cron-reconciler";

describe("CronReconciler", () => {
	let root: string;
	let cronDir: string;
	let dbPath: string;
	let store: SqliteCronStore;
	let reconciler: CronReconciler;

	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "cline-reconciler-"));
		cronDir = join(root, "cron-specs");
		mkdirSync(cronDir, { recursive: true });
		dbPath = join(root, "cron.db");
		store = new SqliteCronStore({ dbPath });
		reconciler = new CronReconciler({
			store,
			specs: { cronSpecsDir: cronDir },
		});
	});

	afterEach(() => {
		store.close();
		rmSync(root, { recursive: true, force: true });
	});

	function writeSpec(rel: string, content: string) {
		const full = join(cronDir, rel);
		mkdirSync(join(full, ".."), { recursive: true });
		writeFileSync(full, content, "utf8");
	}

	function requireValue<T>(value: T | undefined): T {
		expect(value).toBeDefined();
		if (value === undefined) {
			throw new Error("Expected value to be defined");
		}
		return value;
	}

	it("imports valid one-off and schedule specs on startup", async () => {
		writeSpec(
			"cleanup.md",
			`---\nid: cleanup\nworkspaceRoot: /ws\n---\nRemove stale files`,
		);
		writeSpec(
			"nightly.cron.md",
			`---\nid: nightly\nworkspaceRoot: /ws\nschedule: "0 2 * * *"\n---\nNightly`,
		);

		const summary = await reconciler.reconcileAll();
		expect(summary.scanned).toBe(2);
		expect(summary.upserted).toBe(2);
		expect(summary.invalidParses).toBe(0);

		const specs = store.listSpecs();
		expect(specs.length).toBe(2);
		const schedule = specs.find((s) => s.triggerKind === "schedule");
		expect(schedule?.scheduleExpr).toBe("0 2 * * *");
		expect(schedule?.nextRunAt).toBeDefined();
	});

	it("records invalid specs without failing the whole scan", async () => {
		writeSpec("bad.md", `---\nid: [unclosed\n---\nbody`);
		writeSpec(
			"good.md",
			`---\nid: good\nworkspaceRoot: /ws\n---\nDo good work`,
		);

		const summary = await reconciler.reconcileAll();
		expect(summary.upserted).toBe(2);
		expect(summary.invalidParses).toBe(1);

		const invalid = store
			.listSpecs({ parseStatus: "invalid" })
			.find((s) => s.sourcePath === "bad.md");
		expect(invalid).toBeDefined();
		expect(invalid?.parseError).toBeTruthy();
		expect(invalid?.enabled).toBe(false);

		const valid = store
			.listSpecs({ parseStatus: "valid" })
			.find((s) => s.sourcePath === "good.md");
		expect(valid?.enabled).toBe(true);
	});

	it("marks specs as removed when source files disappear", async () => {
		writeSpec("cleanup.md", `---\nid: cleanup\nworkspaceRoot: /ws\n---\nBody`);
		await reconciler.reconcileAll();
		rmSync(join(cronDir, "cleanup.md"));

		const summary = await reconciler.reconcileAll();
		expect(summary.removed).toBe(1);

		const remaining = store.listSpecs({ includeRemoved: false });
		expect(remaining.length).toBe(0);
		const all = store.listSpecs({ includeRemoved: true });
		expect(all[0]?.removed).toBe(true);
	});

	it("cancels queued runs when spec is removed", async () => {
		writeSpec("cleanup.md", `---\nid: cleanup\nworkspaceRoot: /ws\n---\nBody`);
		await reconciler.reconcileAll();
		const spec = requireValue(store.listSpecs()[0]);
		store.enqueueRun({
			specId: spec.specId,
			specRevision: spec.revision,
			triggerKind: "one_off",
		});

		rmSync(join(cronDir, "cleanup.md"));
		await reconciler.reconcileAll();

		const run = requireValue(store.listRuns({ specId: spec.specId })[0]);
		expect(run.status).toBe("cancelled");
	});

	it("preserves overdue schedule next_run_at on startup refresh", async () => {
		writeSpec(
			"nightly.cron.md",
			`---\nid: nightly\nworkspaceRoot: /ws\nschedule: "* * * * *"\n---\nNightly`,
		);
		await reconciler.reconcileAll();
		const spec = requireValue(store.listSpecs({ triggerKind: "schedule" })[0]);
		const overdue = new Date(Date.now() - 60_000).toISOString();
		store.updateSpecNextRunAt(spec.specId, overdue);

		reconciler.refreshScheduleNextRunAt();

		const refreshed = requireValue(store.getSpec(spec.specId));
		expect(refreshed.nextRunAt).toBe(overdue);
	});
});

import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { relative } from "node:path";
import type { CronSpecParseResult } from "@cline/shared";
import {
	type ResolveCronSpecsDirOptions,
	resolveCronSpecsDir,
} from "@cline/shared/storage";
import { getNextCronTime } from "../schedule/scheduler";
import type {
	CronSpecRecord,
	SqliteCronStore,
	UpsertSpecResult,
} from "../store/sqlite-cron-store";
import { type ParseCronSpecInput, parseCronSpecFile } from "./cron-spec-parser";

/**
 * Scan the configured cron specs directory on disk, parse every file, and
 * upsert spec state into the cron DB. This is the startup source of truth:
 * watcher events are triggers to re-run reconciliation for one file, not a
 * replacement.
 */

export interface CronReconcilerOptions {
	store: SqliteCronStore;
	/**
	 * Cron spec source location. Defaults to global `~/.cline/cron`.
	 * Pass `{ scope: "workspace", workspaceRoot }` later to enable
	 * workspace-level cron sources without changing reconciler internals.
	 */
	specs?: ResolveCronSpecsDirOptions;
	/** @deprecated Use `specs: { scope: "workspace", workspaceRoot }`. */
	workspaceRoot?: string;
}

export interface ReconcileChange {
	relativePath: string;
	result: UpsertSpecResult;
	parse: CronSpecParseResult;
}

export interface ReconcileSummary {
	scanned: number;
	upserted: number;
	invalidParses: number;
	removed: number;
	changes: ReconcileChange[];
}

function toPosixRelative(fromDir: string, absolutePath: string): string {
	return relative(fromDir, absolutePath).replace(/\\/g, "/");
}

function walk(dir: string): string[] {
	if (!existsSync(dir)) return [];
	const result: string[] = [];
	const stack: string[] = [dir];
	while (stack.length > 0) {
		const current = stack.pop();
		if (!current) continue;
		let entries: import("node:fs").Dirent[];
		try {
			entries = readdirSync(current, { withFileTypes: true });
		} catch {
			continue;
		}
		for (const entry of entries) {
			const full = `${current}/${entry.name}`;
			if (entry.isDirectory()) {
				// Skip the generated reports subdirectory — not spec sources.
				if (entry.name === "reports") continue;
				stack.push(full);
				continue;
			}
			if (!entry.isFile()) continue;
			if (!entry.name.endsWith(".md")) continue;
			result.push(full);
		}
	}
	return result;
}

export class CronReconciler {
	private readonly store: SqliteCronStore;
	private readonly cronDir: string;

	constructor(options: CronReconcilerOptions) {
		this.store = options.store;
		this.cronDir = resolveCronSpecsDir(
			options.specs ??
				(options.workspaceRoot
					? { scope: "workspace", workspaceRoot: options.workspaceRoot }
					: undefined),
		);
	}

	public getCronDir(): string {
		return this.cronDir;
	}

	/**
	 * Reconcile every file under the cron specs directory into the DB and mark specs
	 * whose source files no longer exist as `removed=1`.
	 */
	public async reconcileAll(): Promise<ReconcileSummary> {
		const summary: ReconcileSummary = {
			scanned: 0,
			upserted: 0,
			invalidParses: 0,
			removed: 0,
			changes: [],
		};

		const files = walk(this.cronDir);
		const seenPaths = new Set<string>();

		for (const abs of files) {
			const rel = toPosixRelative(this.cronDir, abs);
			seenPaths.add(rel);
			summary.scanned += 1;
			const change = await this.reconcileFile(rel, abs);
			if (change) {
				summary.changes.push(change);
				summary.upserted += 1;
				if (change.parse.error) summary.invalidParses += 1;
			}
		}

		const existing = this.store.listSpecs({
			includeRemoved: false,
			limit: 10_000,
		});
		for (const spec of existing) {
			if (!seenPaths.has(spec.sourcePath)) {
				this.handleFileDeleted(spec);
				summary.removed += 1;
			}
		}

		this.refreshScheduleNextRunAt();

		return summary;
	}

	/**
	 * Reconcile a single file (absolute path). `relativePath` is expected to
	 * be POSIX-relative to the cron specs directory. Returns the reconciliation change
	 * or undefined if the file could not be read.
	 */
	public async reconcileFile(
		relativePath: string,
		absolutePath: string,
	): Promise<ReconcileChange | undefined> {
		const existing = this.store.getSpecBySourcePath(relativePath);
		let raw: string;
		let mtimeMs: number | undefined;
		try {
			raw = readFileSync(absolutePath, "utf8");
			mtimeMs = statSync(absolutePath).mtimeMs;
		} catch {
			return undefined;
		}
		const input: ParseCronSpecInput = { relativePath, raw };
		const parse = parseCronSpecFile(input);
		const result = this.store.upsertSpec({
			externalId: parse.externalId,
			sourcePath: relativePath,
			triggerKind: parse.triggerKind,
			sourceMtimeMs: mtimeMs,
			sourceHash: parse.contentHash,
			parseStatus: parse.error ? "invalid" : "valid",
			parseError: parse.error,
			spec: parse.spec,
		});

		// For valid schedule specs, compute next_run_at if missing or reset
		// when schedule_expr changed.
		if (
			!parse.error &&
			parse.triggerKind === "schedule" &&
			result.record.enabled
		) {
			this.applyScheduleNextRunAt(result.record, {
				forceReset:
					!existing ||
					existing.removed ||
					!existing.enabled ||
					existing.scheduleExpr !== result.record.scheduleExpr ||
					existing.timezone !== result.record.timezone,
			});
		}

		return { relativePath, result, parse };
	}

	/**
	 * Handle a file that disappeared from disk between reconciliations.
	 * Marks the spec as removed and cancels any queued runs for it.
	 */
	public handleFileDeleted(spec: CronSpecRecord): void {
		this.store.markSpecRemoved(spec.specId);
		this.store.cancelQueuedRunsForSpec(spec.specId);
	}

	/**
	 * Refresh next_run_at for every enabled schedule spec.
	 * Used at startup to handle the "one overdue catch-up on startup then
	 * advance to next slot" policy.
	 */
	public refreshScheduleNextRunAt(): void {
		const schedules = this.store.listSpecs({
			triggerKind: "schedule",
			enabled: true,
			parseStatus: "valid",
		});
		for (const spec of schedules) {
			this.applyScheduleNextRunAt(spec, { forceReset: false });
		}
	}

	private applyScheduleNextRunAt(
		spec: CronSpecRecord,
		options: { forceReset: boolean },
	): void {
		if (!spec.scheduleExpr) return;
		if (!options.forceReset && spec.nextRunAt) return;
		try {
			const now = Date.now();
			const base = spec.lastRunAt
				? Math.max(now, new Date(spec.lastRunAt).getTime())
				: now;
			const nextMs = getNextCronTime(spec.scheduleExpr, base, spec.timezone);
			const nextIso = new Date(nextMs).toISOString();
			if (spec.nextRunAt !== nextIso) {
				this.store.updateSpecNextRunAt(spec.specId, nextIso);
			}
		} catch {
			// Invalid cron pattern — leave next_run_at as is; the upsert's
			// parse_status already reflects the spec correctness.
		}
	}
}

import { describe, expect, it } from "vitest";
import {
	computeContentHash,
	inferTriggerKindFromPath,
	parseCronSpecFile,
	splitFrontmatter,
} from "./cron-spec-parser";

describe("inferTriggerKindFromPath", () => {
	it("classifies *.cron.md as schedule", () => {
		expect(inferTriggerKindFromPath("nightly.cron.md")).toBe("schedule");
	});
	it("classifies events/*.event.md as event", () => {
		expect(inferTriggerKindFromPath("events/pr.event.md")).toBe("event");
	});
	it("classifies other *.md as one_off", () => {
		expect(inferTriggerKindFromPath("repo-cleanup.md")).toBe("one_off");
	});
	it("does not classify *.event.md outside events/ as event", () => {
		expect(inferTriggerKindFromPath("weird.event.md")).toBe("one_off");
	});
});

describe("splitFrontmatter", () => {
	it("returns undefined when no frontmatter", () => {
		const result = splitFrontmatter("hello");
		expect(result.frontmatter).toBeUndefined();
		expect(result.body).toBe("hello");
	});
	it("splits frontmatter and body", () => {
		const { frontmatter, body } = splitFrontmatter(
			`---\nid: x\n---\nBody here`,
		);
		expect(frontmatter).toContain("id: x");
		expect(body).toBe("Body here");
	});
});

describe("computeContentHash", () => {
	it("is stable under key order", () => {
		expect(computeContentHash({ b: 1, a: 2 }, "body")).toBe(
			computeContentHash({ a: 2, b: 1 }, "body"),
		);
	});

	describe("parseCronSpecFile: one-off", () => {
		it("parses with body prompt", () => {
			const raw = `---\nid: cleanup\ntitle: Clean\nworkspaceRoot: /ws\nmode: act\n---\nRemove stale files.`;
			const r = parseCronSpecFile({ relativePath: "cleanup.md", raw });
			expect(r.error).toBeUndefined();
			expect(r.externalId).toBe("cleanup");
			expect(r.triggerKind).toBe("one_off");
			expect(r.spec?.title).toBe("Clean");
			expect(r.spec?.prompt).toBe("Remove stale files.");
		});

		it("defaults to yolo and parses cron runtime fields", () => {
			const raw = `---\nid: cleanup\nworkspaceRoot: /ws\ntools: run_commands,read_files\nnotesDirectory: /notes\nextensions:\n  - rules\n  - skills\nsource: automation\n---\nBody`;
			const r = parseCronSpecFile({ relativePath: "cleanup.md", raw });
			expect(r.error).toBeUndefined();
			expect(r.spec?.mode).toBe("yolo");
			expect(r.spec?.tools).toEqual(["run_commands", "read_files"]);
			expect(r.spec?.notesDirectory).toBe("/notes");
			expect(r.spec?.extensions).toEqual(["rules", "skills"]);
			expect(r.spec?.source).toBe("automation");
		});

		it("preserves explicit empty tools and extensions lists", () => {
			const raw = `---\nid: cleanup\nworkspaceRoot: /ws\ntools: []\nextensions: []\n---\nBody`;
			const r = parseCronSpecFile({ relativePath: "cleanup.md", raw });
			expect(r.error).toBeUndefined();
			expect(r.spec?.tools).toEqual([]);
			expect(r.spec?.extensions).toEqual([]);
		});

		it("falls back to filename stem title", () => {
			const raw = `---\nworkspaceRoot: /ws\n---\ndo work`;
			const r = parseCronSpecFile({
				relativePath: "nested/fix-thing.md",
				raw,
			});
			expect(r.error).toBeUndefined();
			expect(r.externalId).toBe("nested/fix-thing.md");
			expect(r.spec?.title).toBe("fix-thing");
		});

		it("fails without workspaceRoot", () => {
			const r = parseCronSpecFile({
				relativePath: "x.md",
				raw: `---\nid: x\n---\nbody`,
			});
			expect(r.error).toMatch(/workspaceRoot/);
		});

		it("fails when prompt and body both empty", () => {
			const r = parseCronSpecFile({
				relativePath: "x.md",
				raw: `---\nworkspaceRoot: /ws\n---\n`,
			});
			expect(r.error).toMatch(/prompt is required/);
		});

		it("rejects schedule fields on one-off", () => {
			const r = parseCronSpecFile({
				relativePath: "x.md",
				raw: `---\nworkspaceRoot: /ws\nschedule: "* * * * *"\n---\nbody`,
			});
			expect(r.error).toMatch(/schedule/);
		});

		it("rejects event fields on one-off", () => {
			const r = parseCronSpecFile({
				relativePath: "x.md",
				raw: `---\nworkspaceRoot: /ws\nevent: github.pr\n---\nbody`,
			});
			expect(r.error).toMatch(/event/);
		});

		it("rejects removed cwd field", () => {
			const r = parseCronSpecFile({
				relativePath: "x.md",
				raw: `---\nworkspaceRoot: /ws\ncwd: /ws/subdir\n---\nbody`,
			});
			expect(r.error).toMatch(/cwd/);
		});

		it("rejects invalid mode values", () => {
			const r = parseCronSpecFile({
				relativePath: "x.md",
				raw: `---\nworkspaceRoot: /ws\nmode: autopilot\n---\nbody`,
			});
			expect(r.error).toMatch(/mode/);
		});
	});

	describe("parseCronSpecFile: schedule", () => {
		it("parses a valid *.cron.md", () => {
			const raw = `---\nid: nightly\nworkspaceRoot: /ws\nschedule: "0 2 * * *"\ntimezone: UTC\n---\nDo work.`;
			const r = parseCronSpecFile({ relativePath: "nightly.cron.md", raw });
			expect(r.error).toBeUndefined();
			expect(r.spec?.triggerKind).toBe("schedule");
			if (r.spec?.triggerKind === "schedule") {
				expect(r.spec.schedule).toBe("0 2 * * *");
				expect(r.spec.timezone).toBe("UTC");
			}
		});
		it("fails on *.cron.md without schedule", () => {
			const r = parseCronSpecFile({
				relativePath: "x.cron.md",
				raw: `---\nworkspaceRoot: /ws\n---\nbody`,
			});
			expect(r.error).toMatch(/schedule/);
		});

		it("fails on invalid cron pattern", () => {
			const r = parseCronSpecFile({
				relativePath: "x.cron.md",
				raw: `---\nworkspaceRoot: /ws\nschedule: "bad cron"\n---\nbody`,
			});
			expect(r.error).toMatch(/Invalid cron pattern/);
		});
	});

	describe("parseCronSpecFile: event", () => {
		it("parses events/*.event.md", () => {
			const raw = `---\nid: pr\nworkspaceRoot: /ws\nevent: gh.pr.opened\nfilters:\n  repo: acme\ndebounceSeconds: 30\nmaxParallel: 2\n---\nReview PR.`;
			const r = parseCronSpecFile({
				relativePath: "events/pr.event.md",
				raw,
			});
			expect(r.error).toBeUndefined();
			expect(r.triggerKind).toBe("event");
			if (r.spec?.triggerKind === "event") {
				expect(r.spec.event).toBe("gh.pr.opened");
				expect(r.spec.filters?.repo).toBe("acme");
				expect(r.spec.maxParallel).toBe(2);
			}
		});
		it("fails on event spec without event", () => {
			const r = parseCronSpecFile({
				relativePath: "events/x.event.md",
				raw: `---\nworkspaceRoot: /ws\n---\nbody`,
			});
			expect(r.error).toMatch(/event/);
		});
	});

	describe("parseCronSpecFile: invalid frontmatter", () => {
		it("records parse error without throwing", () => {
			const r = parseCronSpecFile({
				relativePath: "bad.md",
				raw: `---\nid: [unclosed\n---\nbody`,
			});
			expect(r.error).toBeDefined();
			expect(r.spec).toBeUndefined();
		});
	});
});

import { createHash } from "node:crypto";
import type {
	CronEventSpec,
	CronOneOffSpec,
	CronScheduleSpec,
	CronSpec,
	CronSpecExtensionKind,
	CronSpecMode,
	CronSpecParseResult,
	CronTriggerKind,
} from "@cline/shared";
import YAML from "yaml";
import { ALL_DEFAULT_TOOL_NAMES } from "../../extensions/tools/constants";
import { validateCronSchedule } from "../schedule/scheduler";

/**
 * Markdown frontmatter parser for `.cline/cron/*.md` automation specs.
 *
 * Lives in @cline/core because it depends on `yaml`. The spec types
 * themselves live in @cline/shared so other packages can consume them
 * without pulling in a YAML parser.
 *
 * The parser never throws for a single bad file — it produces a
 * `CronSpecParseResult` with an `error` message so the reconciler can record
 * `parse_status='invalid'` durably instead of dropping state.
 */

export function inferTriggerKindFromPath(
	relativePath: string,
): CronTriggerKind {
	const normalized = relativePath.replace(/\\/g, "/");
	if (normalized.startsWith("events/") && normalized.endsWith(".event.md")) {
		return "event";
	}
	if (normalized.endsWith(".cron.md")) {
		return "schedule";
	}
	return "one_off";
}

export function splitFrontmatter(raw: string): {
	frontmatter: string | undefined;
	body: string;
} {
	const text = raw.replace(/\r\n/g, "\n");
	if (!text.startsWith("---\n")) {
		return { frontmatter: undefined, body: raw };
	}
	const afterOpen = text.slice(4);
	const closeIdx = afterOpen.indexOf("\n---");
	if (closeIdx === -1) {
		return { frontmatter: undefined, body: raw };
	}
	const frontmatter = afterOpen.slice(0, closeIdx);
	let rest = afterOpen.slice(closeIdx + 4);
	if (rest.startsWith("\n")) rest = rest.slice(1);
	return { frontmatter, body: rest };
}

function trimOrUndefined(value: unknown): string | undefined {
	if (typeof value !== "string") return undefined;
	const trimmed = value.trim();
	return trimmed.length > 0 ? trimmed : undefined;
}

function normalizeTags(value: unknown): string[] | undefined {
	if (!Array.isArray(value)) return undefined;
	const tags = value
		.map((item) => (typeof item === "string" ? item.trim() : ""))
		.filter((item) => item.length > 0);
	return tags.length > 0 ? tags : undefined;
}

function normalizeRecord(value: unknown): Record<string, unknown> | undefined {
	if (!value || typeof value !== "object" || Array.isArray(value)) {
		return undefined;
	}
	return value as Record<string, unknown>;
}

function normalizeModelSelection(
	value: unknown,
): { providerId?: string; modelId?: string } | undefined {
	const obj = normalizeRecord(value);
	if (!obj) return undefined;
	const providerId = trimOrUndefined(obj.providerId);
	const modelId = trimOrUndefined(obj.modelId);
	if (providerId === undefined && modelId === undefined) return undefined;
	return { providerId, modelId };
}

function normalizeMode(value: unknown): CronSpecMode | undefined {
	if (typeof value !== "string") return undefined;
	const lower = value.trim().toLowerCase();
	if (lower === "act" || lower === "plan" || lower === "yolo") return lower;
	return undefined;
}

function normalizeStringList(
	value: unknown,
	options: { preserveEmptyArray?: boolean } = {},
): string[] | undefined {
	const raw = Array.isArray(value)
		? value
		: typeof value === "string"
			? value.split(",")
			: undefined;
	if (!raw) return undefined;
	const normalized = [
		...new Set(
			raw
				.map((item) => (typeof item === "string" ? item.trim() : ""))
				.filter((item) => item.length > 0),
		),
	];
	if (Array.isArray(value) && options.preserveEmptyArray) {
		return normalized;
	}
	return normalized.length > 0 ? normalized : undefined;
}

const DEFAULT_TOOL_NAME_SET = new Set<string>(ALL_DEFAULT_TOOL_NAMES);

function normalizeToolList(value: unknown): string[] | undefined {
	const tools = normalizeStringList(value, { preserveEmptyArray: true });
	if (!tools) return undefined;
	const invalid = tools.filter((tool) => !DEFAULT_TOOL_NAME_SET.has(tool));
	if (invalid.length > 0) {
		throw new Error(`unknown tool(s): ${invalid.join(", ")}`);
	}
	return tools;
}

const CRON_EXTENSION_KINDS = new Set<CronSpecExtensionKind>([
	"rules",
	"skills",
	"plugins",
]);

function normalizeExtensions(
	value: unknown,
): CronSpecExtensionKind[] | undefined {
	const extensions = normalizeStringList(value, { preserveEmptyArray: true });
	if (!extensions) return undefined;
	const invalid = extensions.filter(
		(extension) =>
			!CRON_EXTENSION_KINDS.has(extension as CronSpecExtensionKind),
	);
	if (invalid.length > 0) {
		throw new Error(`unknown extension(s): ${invalid.join(", ")}`);
	}
	return extensions as CronSpecExtensionKind[];
}

function asPositiveInt(value: unknown): number | undefined {
	if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
		return undefined;
	}
	return Math.floor(value);
}

function asNonNegativeInt(value: unknown): number | undefined {
	if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
		return undefined;
	}
	return Math.floor(value);
}

function stableStringify(value: unknown): string {
	if (value === null || typeof value !== "object") {
		return JSON.stringify(value ?? null);
	}
	if (Array.isArray(value)) {
		return `[${value.map((item) => stableStringify(item)).join(",")}]`;
	}
	const entries = Object.entries(value as Record<string, unknown>).filter(
		([, v]) => v !== undefined,
	);
	entries.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
	return `{${entries
		.map(([k, v]) => `${JSON.stringify(k)}:${stableStringify(v)}`)
		.join(",")}}`;
}

export function computeContentHash(
	frontmatterJson: unknown,
	body: string,
): string {
	const hash = createHash("sha256");
	hash.update(stableStringify(frontmatterJson));
	hash.update("\n");
	hash.update(body);
	return hash.digest("hex");
}

function filenameStem(relativePath: string): string {
	const base = relativePath.split("/").pop() ?? relativePath;
	return base
		.replace(/\.event\.md$/, "")
		.replace(/\.cron\.md$/, "")
		.replace(/\.md$/, "");
}

const SCHEDULE_ONLY_FIELDS = ["schedule", "timezone"] as const;
const EVENT_ONLY_FIELDS = [
	"event",
	"filters",
	"debounceSeconds",
	"dedupeWindowSeconds",
	"cooldownSeconds",
	"maxParallel",
] as const;
const REMOVED_FIELDS = ["cwd"] as const;

export interface ParseCronSpecInput {
	relativePath: string;
	raw: string;
}

function invalid(
	relativePath: string,
	triggerKind: CronTriggerKind,
	body: string,
	frontmatter: Record<string, unknown>,
	error: string,
): CronSpecParseResult {
	return {
		externalId: relativePath,
		relativePath,
		triggerKind,
		body,
		contentHash: computeContentHash(frontmatter, body),
		error,
	};
}

function invalidWithHash(
	externalId: string,
	relativePath: string,
	triggerKind: CronTriggerKind,
	body: string,
	contentHash: string,
	error: string,
): CronSpecParseResult {
	return {
		externalId,
		relativePath,
		triggerKind,
		body,
		contentHash,
		error,
	};
}

/**
 * Parse a single cron spec file. Never throws; always returns a result.
 */
export function parseCronSpecFile(
	input: ParseCronSpecInput,
): CronSpecParseResult {
	const relativePath = input.relativePath.replace(/\\/g, "/");
	const triggerKind = inferTriggerKindFromPath(relativePath);
	const { frontmatter, body } = splitFrontmatter(input.raw);

	let frontmatterData: Record<string, unknown> = {};
	if (frontmatter !== undefined && frontmatter.trim().length > 0) {
		try {
			const parsed = YAML.parse(frontmatter) as unknown;
			if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
				frontmatterData = parsed as Record<string, unknown>;
			} else if (parsed !== null && parsed !== undefined) {
				return invalid(
					relativePath,
					triggerKind,
					body,
					{},
					"frontmatter must be a YAML mapping",
				);
			}
		} catch (err) {
			return invalid(
				relativePath,
				triggerKind,
				body,
				{},
				err instanceof Error
					? `failed to parse frontmatter: ${err.message}`
					: "failed to parse frontmatter",
			);
		}
	}

	const contentHash = computeContentHash(frontmatterData, body);
	const externalIdRaw = trimOrUndefined(frontmatterData.id);
	const externalId = externalIdRaw ?? relativePath;

	if (triggerKind !== "schedule") {
		for (const key of SCHEDULE_ONLY_FIELDS) {
			if (frontmatterData[key] !== undefined) {
				return invalidWithHash(
					externalId,
					relativePath,
					triggerKind,
					body,
					contentHash,
					`field "${key}" is only allowed on *.cron.md specs`,
				);
			}
		}
	}
	for (const key of REMOVED_FIELDS) {
		if (frontmatterData[key] !== undefined) {
			return invalidWithHash(
				externalId,
				relativePath,
				triggerKind,
				body,
				contentHash,
				`field "${key}" is no longer supported; cron specs use workspaceRoot as cwd`,
			);
		}
	}
	if (triggerKind !== "event") {
		for (const key of EVENT_ONLY_FIELDS) {
			if (frontmatterData[key] !== undefined) {
				return invalidWithHash(
					externalId,
					relativePath,
					triggerKind,
					body,
					contentHash,
					`field "${key}" is only allowed on .event.md specs`,
				);
			}
		}
	}

	const frontmatterPrompt = trimOrUndefined(frontmatterData.prompt);
	const bodyTrimmed = body.trim();
	const prompt =
		frontmatterPrompt ?? (bodyTrimmed.length > 0 ? bodyTrimmed : undefined);
	if (!prompt) {
		return invalidWithHash(
			externalId,
			relativePath,
			triggerKind,
			body,
			contentHash,
			"prompt is required (frontmatter `prompt` or markdown body)",
		);
	}

	const workspaceRoot = trimOrUndefined(frontmatterData.workspaceRoot);
	if (!workspaceRoot) {
		return invalidWithHash(
			externalId,
			relativePath,
			triggerKind,
			body,
			contentHash,
			"workspaceRoot is required",
		);
	}

	let tools: string[] | undefined;
	let extensions: CronSpecExtensionKind[] | undefined;
	try {
		tools = normalizeToolList(frontmatterData.tools);
		extensions = normalizeExtensions(frontmatterData.extensions);
	} catch (err) {
		return invalidWithHash(
			externalId,
			relativePath,
			triggerKind,
			body,
			contentHash,
			err instanceof Error ? err.message : String(err),
		);
	}

	const mode = normalizeMode(frontmatterData.mode);
	if (frontmatterData.mode !== undefined && mode === undefined) {
		return invalidWithHash(
			externalId,
			relativePath,
			triggerKind,
			body,
			contentHash,
			"mode must be one of: act, plan, yolo",
		);
	}

	const common = {
		id: externalIdRaw,
		title:
			trimOrUndefined(frontmatterData.title) ??
			externalIdRaw ??
			filenameStem(relativePath),
		prompt,
		workspaceRoot,
		mode: mode ?? "yolo",
		systemPrompt: trimOrUndefined(frontmatterData.systemPrompt),
		modelSelection: normalizeModelSelection(frontmatterData.modelSelection),
		maxIterations: asPositiveInt(frontmatterData.maxIterations),
		timeoutSeconds: asPositiveInt(frontmatterData.timeoutSeconds),
		tools,
		notesDirectory: trimOrUndefined(frontmatterData.notesDirectory),
		extensions,
		source: trimOrUndefined(frontmatterData.source) ?? "user",
		tags: normalizeTags(frontmatterData.tags),
		enabled:
			typeof frontmatterData.enabled === "boolean"
				? frontmatterData.enabled
				: true,
		metadata: normalizeRecord(frontmatterData.metadata),
	};

	let spec: CronSpec;
	if (triggerKind === "schedule") {
		const schedule = trimOrUndefined(frontmatterData.schedule);
		if (!schedule) {
			return invalidWithHash(
				externalId,
				relativePath,
				triggerKind,
				body,
				contentHash,
				"schedule is required for *.cron.md specs",
			);
		}
		const timezone = trimOrUndefined(frontmatterData.timezone);
		try {
			validateCronSchedule(schedule, timezone);
		} catch (err) {
			return invalidWithHash(
				externalId,
				relativePath,
				triggerKind,
				body,
				contentHash,
				err instanceof Error ? err.message : String(err),
			);
		}
		const s: CronScheduleSpec = {
			...common,
			triggerKind: "schedule",
			schedule,
			timezone,
		};
		spec = s;
	} else if (triggerKind === "event") {
		const event = trimOrUndefined(frontmatterData.event);
		if (!event) {
			return invalidWithHash(
				externalId,
				relativePath,
				triggerKind,
				body,
				contentHash,
				"event is required for .event.md specs",
			);
		}
		const e: CronEventSpec = {
			...common,
			triggerKind: "event",
			event,
			filters: normalizeRecord(frontmatterData.filters),
			debounceSeconds: asNonNegativeInt(frontmatterData.debounceSeconds),
			dedupeWindowSeconds: asNonNegativeInt(
				frontmatterData.dedupeWindowSeconds,
			),
			cooldownSeconds: asNonNegativeInt(frontmatterData.cooldownSeconds),
			maxParallel: asPositiveInt(frontmatterData.maxParallel),
		};
		spec = e;
	} else {
		const o: CronOneOffSpec = { ...common, triggerKind: "one_off" };
		spec = o;
	}

	return {
		externalId,
		relativePath,
		triggerKind,
		body,
		contentHash,
		spec,
	};
}

import {
	existsSync,
	mkdirSync,
	mkdtempSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { CronMaterializer } from "../runner/cron-materializer";
import { SqliteCronStore } from "../store/sqlite-cron-store";
import { CronReconciler } from "./cron-reconciler";
import { CronWatcher } from "./cron-watcher";

describe("CronWatcher", () => {
	let root: string;
	let cronDir: string;
	let store: SqliteCronStore;
	let reconciler: CronReconciler;
	let materializer: CronMaterializer;

	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "cline-watcher-"));
		cronDir = join(root, "cron-specs");
		mkdirSync(cronDir, { recursive: true });
		store = new SqliteCronStore({ dbPath: join(root, "cron.db") });
		reconciler = new CronReconciler({
			store,
			specs: { cronSpecsDir: cronDir },
		});
		materializer = new CronMaterializer({ store });
	});

	afterEach(() => {
		store.close();
		rmSync(root, { recursive: true, force: true });
	});

	function requireValue<T>(value: T | undefined): T {
		expect(value).toBeDefined();
		if (value === undefined) {
			throw new Error("Expected value to be defined");
		}
		return value;
	}

	it("materializes after a watched file reconcile", async () => {
		const specPath = join(cronDir, "cleanup.md");
		writeFileSync(
			specPath,
			`---\nid: cleanup\nworkspaceRoot: /ws\n---\nRemove stale files`,
			"utf8",
		);
		let materialized = 0;
		const watcher = new CronWatcher({
			reconciler,
			onReconciled: () => {
				materialized += materializer.materializeAll().oneOffQueued;
			},
		});

		await (
			watcher as unknown as { reconcileNow(path: string): Promise<void> }
		).reconcileNow("cleanup.md");

		expect(materialized).toBe(1);
		const spec = requireValue(store.listSpecs()[0]);
		const runs = store.listRuns({ specId: spec.specId });
		expect(runs).toHaveLength(1);
		expect(runs[0]?.status).toBe("queued");
	});

	it("creates the cron directory before starting the watcher", () => {
		const missingCronDir = join(root, "missing-cron-specs");
		const watcherReconciler = new CronReconciler({
			store,
			specs: { cronSpecsDir: missingCronDir },
		});
		const watcher = new CronWatcher({ reconciler: watcherReconciler });

		watcher.start();
		watcher.stop();

		expect(existsSync(missingCronDir)).toBe(true);
	});
});

import type { FSWatcher } from "node:fs";
import { existsSync, mkdirSync, watch } from "node:fs";
import { relative, resolve } from "node:path";
import type { CronReconciler } from "./cron-reconciler";

/**
 * Filesystem watcher for the configured cron specs directory.
 *
 * Uses `node:fs` `watch` with `{ recursive: true }`. Emits a re-reconcile
 * request for each change, debounced per path, so rapid save bursts from
 * editors don't cause redundant DB churn.
 */

const DEFAULT_DEBOUNCE_MS = 250;

export interface CronWatcherOptions {
	reconciler: CronReconciler;
	debounceMs?: number;
	onError?: (error: unknown) => void;
	onReconciled?: () => void | Promise<void>;
}

export class CronWatcher {
	private readonly reconciler: CronReconciler;
	private readonly debounceMs: number;
	private readonly onError: (error: unknown) => void;
	private readonly onReconciled: () => void | Promise<void>;
	private watcher?: FSWatcher;
	private readonly pending = new Map<string, ReturnType<typeof setTimeout>>();
	private disposed = false;

	constructor(options: CronWatcherOptions) {
		this.reconciler = options.reconciler;
		this.debounceMs = Math.max(0, options.debounceMs ?? DEFAULT_DEBOUNCE_MS);
		this.onError = options.onError ?? (() => {});
		this.onReconciled = options.onReconciled ?? (() => {});
	}

	public start(): void {
		if (this.disposed) throw new Error("CronWatcher disposed");
		if (this.watcher) return;
		const dir = this.reconciler.getCronDir();
		try {
			mkdirSync(dir, { recursive: true });
			this.watcher = watch(dir, { recursive: true }, (_eventType, filename) => {
				if (!filename) return;
				const rel = String(filename).replace(/\\/g, "/");
				if (!rel.endsWith(".md")) return;
				if (rel.startsWith("reports/")) return;
				this.scheduleReconcile(rel);
			});
			this.watcher.on("error", this.onError);
		} catch (err) {
			this.onError(err);
		}
	}

	public stop(): void {
		for (const timer of this.pending.values()) clearTimeout(timer);
		this.pending.clear();
		this.watcher?.close();
		this.watcher = undefined;
	}

	public dispose(): void {
		this.disposed = true;
		this.stop();
	}

	private scheduleReconcile(relativePath: string): void {
		const existing = this.pending.get(relativePath);
		if (existing) clearTimeout(existing);
		const timer = setTimeout(() => {
			this.pending.delete(relativePath);
			void this.reconcileNow(relativePath);
		}, this.debounceMs);
		this.pending.set(relativePath, timer);
	}

	private async reconcileNow(relativePath: string): Promise<void> {
		try {
			const abs = resolve(this.reconciler.getCronDir(), relativePath);
			if (!existsSync(abs)) {
				// File was deleted — force a full reconcile to catch the
				// missing source and mark the spec removed.
				await this.reconciler.reconcileAll();
				await this.onReconciled();
				return;
			}
			// Normalize relative path through the reconciler dir to defend
			// against a watcher emitting an unexpected format.
			const normalizedRel = relative(this.reconciler.getCronDir(), abs).replace(
				/\\/g,
				"/",
			);
			await this.reconciler.reconcileFile(normalizedRel, abs);
			await this.onReconciled();
		} catch (err) {
			this.onError(err);
		}
	}
}

