	public claimDueRuns(options: ClaimRunOptions): ClaimedCronRun[] {
		const referenceIso = options.nowIso;
		const boundedLease = Math.max(1_000, Math.floor(options.leaseMs));
		const leaseUntilIso = new Date(
			new Date(referenceIso).getTime() + boundedLease,
		).toISOString();
		const limit = Math.max(1, Math.floor(options.limit ?? 25));
		const claimed: ClaimedCronRun[] = [];
		this.db.exec("BEGIN IMMEDIATE;");
		try {
			const rows = this.db
				.prepare(
					`SELECT * FROM cron_runs
						WHERE (
								status = 'queued'
								OR (
									status = 'running'
									AND claim_until_at IS NOT NULL
									AND claim_until_at <= ?
									AND completed_at IS NULL
								)
							)
							AND (scheduled_for IS NULL OR scheduled_for <= ?)
						ORDER BY COALESCE(scheduled_for, created_at) ASC
						LIMIT ?`,
				)
				.all(referenceIso, referenceIso, limit);
			for (const row of rows) {
				const runId = asString(row.run_id);
				if (!runId) continue;
				const claimToken = `cclaim_${randomUUID()}`;
				const changes =
					this.db
						.prepare(
							`UPDATE cron_runs SET
								status = 'running',
								claim_token = ?,
								claim_started_at = ?,
								claim_until_at = ?,
								started_at = ?,
								completed_at = NULL,
								session_id = NULL,
								report_path = NULL,
								error = NULL,
								attempt_count = attempt_count + 1,
								updated_at = ?
							WHERE run_id = ?
								AND (
									status = 'queued'
									OR (
										status = 'running'
										AND claim_until_at IS NOT NULL
										AND claim_until_at <= ?
										AND completed_at IS NULL
									)
								)`,
						)
						.run(
							claimToken,
							referenceIso,
							leaseUntilIso,
							referenceIso,
							referenceIso,
							runId,
							referenceIso,
						).changes ?? 0;
				if (changes !== 1) continue;
				const run = this.getRun(runId);
				if (!run) continue;
				claimed.push({ run, claimToken, claimUntilAt: leaseUntilIso });
			}
			this.db.exec("COMMIT;");
		} catch (err) {
			this.db.exec("ROLLBACK;");
			throw err;
		}
		return claimed;
	}

	public renewClaim(
		runId: string,
		claimToken: string,
		leaseUntilAt: string,
	): boolean {
		const changes =
			this.db
				.prepare(
					`UPDATE cron_runs SET claim_until_at = ?, updated_at = ?
						WHERE run_id = ? AND claim_token = ?`,
				)
				.run(leaseUntilAt, nowIso(), runId, claimToken).changes ?? 0;
		return changes === 1;
	}

	public completeRun(
		runId: string,
		update: {
			status: "done" | "failed" | "cancelled";
			sessionId?: string;
			reportPath?: string;
			error?: string;
			completedAtIso?: string;
			claimToken?: string;
		},
	): boolean {
		const completedAt = update.completedAtIso ?? nowIso();
		const whereClause = update.claimToken
			? "WHERE run_id = ? AND claim_token = ?"
			: "WHERE run_id = ?";
		const changes =
			this.db
				.prepare(
					`UPDATE cron_runs SET
						status = ?,
						session_id = COALESCE(?, session_id),
						report_path = COALESCE(?, report_path),
						error = ?,
						completed_at = ?,
						claim_started_at = NULL,
						claim_token = NULL,
						claim_until_at = NULL,
						updated_at = ?
					${whereClause}`,
				)
				.run(
					update.status,
					update.sessionId ?? null,
					update.reportPath ?? null,
					update.error ?? null,
					completedAt,
					completedAt,
					runId,
					...(update.claimToken ? [update.claimToken] : []),
				).changes ?? 0;
		return changes > 0;
	}

	public requeueRun(
		update: ClaimBoundUpdate & {
			error?: string;
			scheduledFor?: string;
		},
	): boolean {
		const updatedAt = nowIso();
		const changes =
			this.db
				.prepare(
					`UPDATE cron_runs SET
						status = 'queued',
						claim_started_at = NULL,
						claim_token = NULL,
						claim_until_at = NULL,
						started_at = NULL,
						completed_at = NULL,
						session_id = NULL,
						report_path = NULL,
						error = ?,
						scheduled_for = COALESCE(?, scheduled_for),
						updated_at = ?
					WHERE run_id = ? AND claim_token = ?`,
				)
				.run(
					update.error ?? null,
					update.scheduledFor ?? null,
					updatedAt,
					update.runId,
					update.claimToken,
				).changes ?? 0;
		return changes > 0;
	}

