describe("skill frontmatter toggle", () => {
	const tempRoots: string[] = [];

	afterEach(async () => {
		await Promise.all(
			tempRoots.map((dir) => rm(dir, { recursive: true, force: true })),
		);
		tempRoots.length = 0;
	});

	it("disables an enabled skill with existing frontmatter", () => {
		const content = `---
name: code-review
description: Review code carefully
---
First line.

Second line.`;

		const updated = updateSkillMarkdownEnabledState(content, false);
		const parsed = parseSkillConfigFromMarkdown(updated, "fallback");

		expect(parsed.disabled).toBe(true);
		expect(parsed.frontmatter.name).toBe("code-review");
		expect(parsed.frontmatter.description).toBe("Review code carefully");
		expect(updated.endsWith("First line.\n\nSecond line.")).toBe(true);
	});

	it("enables a disabled skill", () => {
		const content = `---
name: code-review
disabled: true
---
Use the review checklist.`;

		const updated = updateSkillMarkdownEnabledState(content, true);
		const parsed = parseSkillConfigFromMarkdown(updated, "fallback");

		expect(parsed.disabled).toBeUndefined();
		expect(parsed.frontmatter).not.toHaveProperty("disabled");
		expect(updated.endsWith("Use the review checklist.")).toBe(true);
	});

	it("enables a legacy enabled false skill", () => {
		const content = `---
name: legacy-skill
enabled: false
---
Use legacy instructions.`;

		const updated = updateSkillMarkdownEnabledState(content, true);
		const parsed = parseSkillConfigFromMarkdown(updated, "fallback");

		expect(parsed.disabled).toBeUndefined();
		expect(parsed.frontmatter).not.toHaveProperty("enabled");
		expect(updated.endsWith("Use legacy instructions.")).toBe(true);
	});

	it("prepends frontmatter when disabling a skill without frontmatter", () => {
		const content = "Follow the incident response runbook.";

		const updated = updateSkillMarkdownEnabledState(content, false);
		const parsed = parseSkillConfigFromMarkdown(updated, "incident-response");

		expect(parsed.disabled).toBe(true);
		expect(parsed.instructions).toBe(content);
		expect(updated).toBe(`---
disabled: true
---
${content}`);
	});

	it("leaves a skill without frontmatter unchanged when enabling", () => {
		const content = "Follow the incident response runbook.";

		expect(updateSkillMarkdownEnabledState(content, true)).toBe(content);
	});

	// Regression test for https://github.com/cline/cline/issues/12151: a leading UTF-8 BOM
	// (e.g. saved by Windows Notepad's "UTF-8 with BOM" encoding) must not prevent frontmatter
	// from being recognized when toggling a skill's enabled state.
	it("disables a skill whose content starts with a UTF-8 BOM", () => {
		const content = `\uFEFF---
name: code-review
description: Review code carefully
---
First line.`;

		const updated = updateSkillMarkdownEnabledState(content, false);
		const parsed = parseSkillConfigFromMarkdown(updated, "fallback");

		expect(parsed.disabled).toBe(true);
		expect(parsed.frontmatter.name).toBe("code-review");
		expect(parsed.frontmatter.description).toBe("Review code carefully");
	});

	it("writes toggled content and returns the resulting state", async () => {
		const tempRoot = await mkdtemp(join(tmpdir(), "core-skill-toggle-"));
		tempRoots.push(tempRoot);
		const filePath = join(tempRoot, "SKILL.md");
		await writeFile(
			filePath,
			`---
name: file-skill
---
Use file-backed instructions.`,
		);

		const result = await toggleSkillFrontmatter({ filePath, enabled: false });
		const written = await readFile(filePath, "utf8");
		const parsed = parseSkillConfigFromMarkdown(written, "fallback");

		expect(result).toEqual({ filePath, enabled: false, disabled: true });
		expect(parsed.disabled).toBe(true);
		expect(written.endsWith("Use file-backed instructions.")).toBe(true);
	});
});

import { readFile, writeFile } from "node:fs/promises";
import { stripUtf8Bom } from "@cline/shared";
import YAML from "yaml";

export interface ToggleSkillFrontmatterOptions {
	filePath: string;
	enabled: boolean;
}

export interface ToggleSkillFrontmatterResult {
	filePath: string;
	enabled: boolean;
	disabled: boolean;
}

interface MarkdownFrontmatterParts {
	data: Record<string, unknown>;
	body: string;
	hadFrontmatter: boolean;
}

function parseMarkdownFrontmatter(content: string): MarkdownFrontmatterParts {
	// Strip a leading UTF-8 BOM (e.g. added by Windows Notepad's "UTF-8 with BOM" encoding),
	// which Node's `utf-8` decoding does not strip on its own. Without this the frontmatter
	// regex below never matches a file that starts with "\uFEFF---" (see cline/cline#12151).
	const normalizedContent = stripUtf8Bom(content);

	const frontmatterRegex = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/;
	const match = normalizedContent.match(frontmatterRegex);
	if (!match) {
		return { data: {}, body: normalizedContent, hadFrontmatter: false };
	}

	const [, yamlContent, body] = match;
	const parsed = YAML.parse(yamlContent);
	const data =
		parsed && typeof parsed === "object" && !Array.isArray(parsed)
			? (parsed as Record<string, unknown>)
			: {};
	return { data, body, hadFrontmatter: true };
}

function serializeMarkdownFrontmatter(
	data: Record<string, unknown>,
	body: string,
): string {
	const yaml = YAML.stringify(data).trimEnd();
	return `---\n${yaml}\n---\n${body}`;
}

export function updateSkillMarkdownEnabledState(
	content: string,
	enabled: boolean,
): string {
	const { data, body, hadFrontmatter } = parseMarkdownFrontmatter(content);

	if (!hadFrontmatter && enabled) {
		return content;
	}

	if (enabled) {
		delete data.disabled;
		if (data.enabled === false) {
			delete data.enabled;
		}
		if (Object.keys(data).length === 0) {
			return body;
		}
		return serializeMarkdownFrontmatter(data, body);
	}

	data.disabled = true;
	return serializeMarkdownFrontmatter(data, body);
}

export async function toggleSkillFrontmatter({
	filePath,
	enabled,
}: ToggleSkillFrontmatterOptions): Promise<ToggleSkillFrontmatterResult> {
	const content = await readFile(filePath, "utf8");
	const updated = updateSkillMarkdownEnabledState(content, enabled);
	await writeFile(filePath, updated);

	return {
		filePath,
		enabled,
		disabled: !enabled,
	};
}

import { mkdir, mkdtemp, rm, unlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import {
	UnifiedConfigFileWatcher,
	type UnifiedConfigWatcherEvent,
} from "./unified-config-file-watcher";

const WAIT_TIMEOUT_MS = 8_000;
const WAIT_INTERVAL_MS = 25;

interface TestProfileConfig {
	name: string;
	body: string;
}

function parseTestProfileConfig(content: string): TestProfileConfig {
	const match = content.match(/^name:\s*(.+)\n\n([\s\S]*)$/);
	if (!match) {
		throw new Error("Invalid test profile config.");
	}
	return {
		name: match[1].trim(),
		body: match[2].trim(),
	};
}

async function waitForEvent<TType extends string, TItem>(
	events: Array<UnifiedConfigWatcherEvent<TType, TItem>>,
	predicate: (event: UnifiedConfigWatcherEvent<TType, TItem>) => boolean,
	timeoutMs = WAIT_TIMEOUT_MS,
): Promise<UnifiedConfigWatcherEvent<TType, TItem>> {
	const startedAt = Date.now();
	while (Date.now() - startedAt < timeoutMs) {
		const match = events.find(predicate);
		if (match) {
			return match;
		}
		await new Promise((resolve) => setTimeout(resolve, WAIT_INTERVAL_MS));
	}
	throw new Error("Timed out waiting for watcher event.");
}

describe("UnifiedConfigFileWatcher", () => {
	const tempRoots: string[] = [];

	afterEach(async () => {
		await Promise.all(
			tempRoots.map((dir) => rm(dir, { recursive: true, force: true })),
		);
		tempRoots.length = 0;
	});

	it("emits upsert and remove events with config type", async () => {
		const tempRoot = await mkdtemp(
			join(tmpdir(), "core-unified-config-watcher-"),
		);
		tempRoots.push(tempRoot);
		const profilesDir = join(tempRoot, "profiles");
		await mkdir(profilesDir, { recursive: true });
		const profileFilePath = join(profilesDir, "reviewer.profile");
		await writeFile(
			profileFilePath,
			"name: Reviewer\n\nReview code carefully.",
		);

		const watcher = new UnifiedConfigFileWatcher([
			{
				type: "profile" as const,
				directories: [profilesDir],
				includeFile: (fileName) => fileName.endsWith(".profile"),
				parseFile: (context) => parseTestProfileConfig(context.content),
				resolveId: (config) => config.name.toLowerCase(),
			},
		]);

		const events: Array<
			UnifiedConfigWatcherEvent<
				"profile",
				ReturnType<typeof parseTestProfileConfig>
			>
		> = [];
		const unsubscribe = watcher.subscribe((event) => events.push(event));

		try {
			await watcher.refreshAll();
			await waitForEvent(
				events,
				(event) => event.kind === "upsert" && event.record.id === "reviewer",
			);

			events.length = 0;
			await writeFile(
				profileFilePath,
				"name: Reviewer\n\nReview code with strictness.",
			);
			await watcher.refreshType("profile");
			await waitForEvent(
				events,
				(event) => event.kind === "upsert" && event.record.type === "profile",
			);

			events.length = 0;
			await unlink(profileFilePath);
			await watcher.refreshType("profile");
			await waitForEvent(
				events,
				(event) => event.kind === "remove" && event.type === "profile",
			);
		} finally {
			unsubscribe();
		}
	}, 15_000);

	it("supports one watcher instance for multiple config types", async () => {
		const tempRoot = await mkdtemp(
			join(tmpdir(), "core-unified-config-watcher-"),
		);
		tempRoots.push(tempRoot);
		const profilesDir = join(tempRoot, "profiles");
		const skillsDir = join(tempRoot, "skills");
		await mkdir(profilesDir, { recursive: true });
		await mkdir(skillsDir, { recursive: true });

		await writeFile(
			join(profilesDir, "researcher.profile"),
			"name: Researcher\n\nInvestigate related code paths.",
		);
		await writeFile(
			join(skillsDir, "SKILL.md"),
			`---
name: incident-response
description: Handle incidents
---
Escalation playbook`,
		);

		const watcher = new UnifiedConfigFileWatcher<
			"profile" | "skill",
			TestProfileConfig | { path: string }
		>([
			{
				type: "profile" as const,
				directories: [profilesDir],
				includeFile: (fileName) => fileName.endsWith(".profile"),
				parseFile: (context) =>
					parseTestProfileConfig(context.content) as
						| TestProfileConfig
						| { path: string },
				resolveId: (config) =>
					"name" in config ? config.name.toLowerCase() : "invalid-profile",
			},
			{
				type: "skill" as const,
				directories: [skillsDir],
				includeFile: (fileName) => fileName === "SKILL.md",
				parseFile: (context) => ({ path: context.filePath }),
				resolveId: (_parsed, context) => basename(context.directoryPath),
			},
		]);

		const events: Array<
			UnifiedConfigWatcherEvent<
				"profile" | "skill",
				TestProfileConfig | { path: string }
			>
		> = [];
		const unsubscribe = watcher.subscribe((event) => events.push(event));

		try {
			await watcher.refreshAll();
			await waitForEvent(
				events,
				(event) =>
					event.kind === "upsert" &&
					(event.record.type === "profile" || event.record.type === "skill"),
			);
			expect(
				events.some(
					(event) => event.kind === "upsert" && event.record.type === "profile",
				),
			).toBe(true);
			expect(
				events.some(
					(event) => event.kind === "upsert" && event.record.type === "skill",
				),
			).toBe(true);
		} finally {
			unsubscribe();
		}
	});
});

import { createHash } from "node:crypto";
import { type FSWatcher, watch } from "node:fs";
import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";

export interface UnifiedConfigFileContext<TType extends string = string> {
	type: TType;
	directoryPath: string;
	fileName: string;
	filePath: string;
	content: string;
}

export interface UnifiedConfigFileCandidate {
	directoryPath: string;
	fileName: string;
	filePath: string;
}

export interface UnifiedConfigDefinition<
	TType extends string = string,
	TItem = unknown,
> {
	type: TType;
	directories: ReadonlyArray<string>;
	discoverFiles?: (
		directoryPath: string,
	) => Promise<ReadonlyArray<UnifiedConfigFileCandidate>>;
	includeFile?: (fileName: string, filePath: string) => boolean;
	parseFile: (context: UnifiedConfigFileContext<TType>) => TItem;
	resolveId: (item: TItem, context: UnifiedConfigFileContext<TType>) => string;
}

export interface UnifiedConfigWatcherOptions {
	debounceMs?: number;
	emitParseErrors?: boolean;
}

export interface UnifiedConfigRecord<
	TType extends string = string,
	TItem = unknown,
> {
	type: TType;
	id: string;
	item: TItem;
	filePath: string;
}

export type UnifiedConfigWatcherEvent<
	TType extends string = string,
	TItem = unknown,
> =
	| {
			kind: "upsert";
			record: UnifiedConfigRecord<TType, TItem>;
	  }
	| {
			kind: "remove";
			type: TType;
			id: string;
			filePath: string;
	  }
	| {
			kind: "error";
			type: TType;
			error: unknown;
			filePath?: string;
	  };

interface InternalRecord<TType extends string, TItem>
	extends UnifiedConfigRecord<TType, TItem> {
	fingerprint: string;
}

function toFingerprint(content: string): string {
	return createHash("sha1").update(content).digest("hex");
}

function isErrnoException(error: unknown): error is NodeJS.ErrnoException {
	return Boolean(error && typeof error === "object" && "code" in error);
}

function isMissingDirectoryError(error: unknown): boolean {
	return isErrnoException(error) && error.code === "ENOENT";
}

function isInaccessibleDirectoryError(error: unknown): boolean {
	return (
		isErrnoException(error) &&
		(error.code === "EACCES" || error.code === "EPERM")
	);
}

export class UnifiedConfigFileWatcher<
	TType extends string = string,
	TItem = unknown,
> {
	private readonly definitions: ReadonlyArray<
		UnifiedConfigDefinition<TType, TItem>
	>;
	private readonly debounceMs: number;
	private readonly emitParseErrors: boolean;
	private readonly listeners = new Set<
		(event: UnifiedConfigWatcherEvent<TType, TItem>) => void
	>();
	private readonly recordsByType = new Map<
		TType,
		Map<string, InternalRecord<TType, TItem>>
	>();
	private readonly watchersByDirectory = new Map<string, FSWatcher>();
	private readonly baseTypesByDirectory = new Map<string, Set<TType>>();
	private watchedTypesByDirectory = new Map<string, Set<TType>>();
	private readonly discoveredDirectoriesByType = new Map<TType, Set<string>>();
	private readonly definitionsByType = new Map<
		TType,
		UnifiedConfigDefinition<TType, TItem>
	>();
	private readonly pendingTypes = new Set<TType>();
	private flushTimer: NodeJS.Timeout | undefined;
	private refreshQueue: Promise<void> = Promise.resolve();
	private started = false;

	constructor(
		definitions: ReadonlyArray<UnifiedConfigDefinition<TType, TItem>>,
		options?: UnifiedConfigWatcherOptions,
	) {
		if (definitions.length === 0) {
			throw new Error(
				"UnifiedConfigFileWatcher requires at least one definition.",
			);
		}

		this.definitions = definitions;
		this.debounceMs = options?.debounceMs ?? 75;
		this.emitParseErrors = options?.emitParseErrors ?? false;

		for (const definition of definitions) {
			if (this.definitionsByType.has(definition.type)) {
				throw new Error(
					`Duplicate unified config definition type '${definition.type}'.`,
				);
			}
			this.definitionsByType.set(definition.type, definition);
			this.recordsByType.set(definition.type, new Map());
			this.discoveredDirectoriesByType.set(definition.type, new Set());
			for (const directoryPath of definition.directories) {
				const existing = this.baseTypesByDirectory.get(directoryPath);
				if (existing) {
					existing.add(definition.type);
				} else {
					this.baseTypesByDirectory.set(
						directoryPath,
						new Set([definition.type]),
					);
				}
			}
		}
	}

	subscribe(
		listener: (event: UnifiedConfigWatcherEvent<TType, TItem>) => void,
	): () => void {
		this.listeners.add(listener);
		return () => {
			this.listeners.delete(listener);
		};
	}

	async start(): Promise<void> {
		if (this.started) {
			return;
		}
		this.started = true;
		await this.refreshAll();
		this.startDirectoryWatchers();
	}

	stop(): void {
		this.started = false;
		if (this.flushTimer) {
			clearTimeout(this.flushTimer);
			this.flushTimer = undefined;
		}
		this.pendingTypes.clear();
		for (const watcher of this.watchersByDirectory.values()) {
			watcher.close();
		}
		this.watchersByDirectory.clear();
		this.watchedTypesByDirectory = new Map();
	}

	async refreshAll(): Promise<void> {
		await this.enqueueRefresh(async () => {
			for (const definition of this.definitions) {
				await this.refreshTypeInternal(definition);
			}
		});
	}

	async refreshType(type: TType): Promise<void> {
		const definition = this.definitionsByType.get(type);
		if (!definition) {
			throw new Error(`Unknown unified config type '${type}'.`);
		}
		await this.enqueueRefresh(async () => {
			await this.refreshTypeInternal(definition);
		});
	}

	getSnapshot(type: TType): Map<string, UnifiedConfigRecord<TType, TItem>> {
		const records = this.recordsByType.get(type);
		return new Map(
			[...(records?.entries() ?? [])].map(([id, record]) => [
				id,
				{ ...record },
			]),
		);
	}

	getAllSnapshots(): Map<
		TType,
		Map<string, UnifiedConfigRecord<TType, TItem>>
	> {
		const snapshot = new Map<
			TType,
			Map<string, UnifiedConfigRecord<TType, TItem>>
		>();
		for (const [type, records] of this.recordsByType.entries()) {
			snapshot.set(
				type,
				new Map(
					[...records.entries()].map(([id, record]) => [id, { ...record }]),
				),
			);
		}
		return snapshot;
	}

	private emit(event: UnifiedConfigWatcherEvent<TType, TItem>): void {
		for (const listener of this.listeners) {
			listener(event);
		}
	}

	private enqueueRefresh(action: () => Promise<void>): Promise<void> {
		this.refreshQueue = this.refreshQueue.then(action, action);
		return this.refreshQueue;
	}

	private startDirectoryWatchers(): void {
		this.syncDirectoryWatchers();
	}

	private syncDirectoryWatchers(): void {
		const desiredTypesByDirectory = this.buildDesiredTypesByDirectory();

		for (const [directoryPath, watcher] of this.watchersByDirectory.entries()) {
			if (desiredTypesByDirectory.has(directoryPath)) {
				continue;
			}
			watcher.close();
			this.watchersByDirectory.delete(directoryPath);
		}

		this.watchedTypesByDirectory = desiredTypesByDirectory;

		for (const directoryPath of desiredTypesByDirectory.keys()) {
			if (this.watchersByDirectory.has(directoryPath)) {
				continue;
			}

			try {
				const watcher = watch(directoryPath, () => {
					const types = this.watchedTypesByDirectory.get(directoryPath);
					if (!types) {
						return;
					}
					for (const type of types) {
						this.pendingTypes.add(type);
					}
					this.scheduleFlush();
				});
				this.watchersByDirectory.set(directoryPath, watcher);
				watcher.on("error", (error) => {
					const types = this.watchedTypesByDirectory.get(directoryPath);
					if (!types) {
						return;
					}
					for (const type of types) {
						this.emit({
							kind: "error",
							type,
							error,
							filePath: directoryPath,
						});
					}
				});
			} catch (error) {
				if (
					!isMissingDirectoryError(error) &&
					!isInaccessibleDirectoryError(error)
				) {
					const types = desiredTypesByDirectory.get(directoryPath);
					if (!types) {
						continue;
					}
					for (const type of types) {
						this.emit({
							kind: "error",
							type,
							error,
							filePath: directoryPath,
						});
					}
				}
			}
		}
	}

	private scheduleFlush(): void {
		if (this.flushTimer) {
			clearTimeout(this.flushTimer);
		}
		this.flushTimer = setTimeout(() => {
			this.flushTimer = undefined;
			const types = [...this.pendingTypes];
			this.pendingTypes.clear();
			void this.enqueueRefresh(async () => {
				for (const type of types) {
					const definition = this.definitionsByType.get(type);
					if (!definition) {
						continue;
					}
					await this.refreshTypeInternal(definition);
				}
			});
		}, this.debounceMs);
	}

	private async refreshTypeInternal(
		definition: UnifiedConfigDefinition<TType, TItem>,
	): Promise<void> {
		const { records: nextRecords, discoveredDirectories } =
			await this.loadDefinition(definition);
		const previousRecords =
			this.recordsByType.get(definition.type) ??
			new Map<string, InternalRecord<TType, TItem>>();

		for (const [id, previousRecord] of previousRecords.entries()) {
			if (nextRecords.has(id)) {
				continue;
			}
			this.emit({
				kind: "remove",
				type: definition.type,
				id,
				filePath: previousRecord.filePath,
			});
		}

		for (const [id, nextRecord] of nextRecords.entries()) {
			const previousRecord = previousRecords.get(id);
			if (
				previousRecord &&
				previousRecord.filePath === nextRecord.filePath &&
				previousRecord.fingerprint === nextRecord.fingerprint
			) {
				continue;
			}
			this.emit({
				kind: "upsert",
				record: {
					type: nextRecord.type,
					id,
					item: nextRecord.item,
					filePath: nextRecord.filePath,
				},
			});
		}

		this.recordsByType.set(definition.type, nextRecords);
		this.discoveredDirectoriesByType.set(
			definition.type,
			discoveredDirectories,
		);
		if (this.started) {
			this.syncDirectoryWatchers();
		}
	}

	private async loadDefinition(
		definition: UnifiedConfigDefinition<TType, TItem>,
	): Promise<{
		records: Map<string, InternalRecord<TType, TItem>>;
		discoveredDirectories: Set<string>;
	}> {
		const records = new Map<string, InternalRecord<TType, TItem>>();
		const discoveredDirectories = new Set<string>();

		for (const directoryPath of definition.directories) {
			discoveredDirectories.add(directoryPath);
			const fileCandidates = definition.discoverFiles
				? await definition.discoverFiles(directoryPath)
				: await this.readDirectoryFileCandidates(directoryPath);

			for (const candidate of fileCandidates) {
				const fileName = candidate.fileName;
				const filePath = candidate.filePath;
				discoveredDirectories.add(candidate.directoryPath);
				if (
					definition.includeFile &&
					!definition.includeFile(fileName, filePath)
				) {
					continue;
				}
				try {
					const content = await readFile(filePath, "utf8");
					const context: UnifiedConfigFileContext<TType> = {
						type: definition.type,
						directoryPath: candidate.directoryPath,
						fileName,
						filePath,
						content,
					};
					const parsed = definition.parseFile(context);
					const id = definition.resolveId(parsed, context).trim();
					if (!id) {
						continue;
					}
					records.set(id, {
						type: definition.type,
						id,
						item: parsed,
						filePath,
						fingerprint: toFingerprint(content),
					});
				} catch (error) {
					if (this.emitParseErrors) {
						this.emit({
							kind: "error",
							type: definition.type,
							error,
							filePath,
						});
					}
				}
			}
		}
		return { records, discoveredDirectories };
	}

	private buildDesiredTypesByDirectory(): Map<string, Set<TType>> {
		const desired = new Map<string, Set<TType>>();
		for (const [directoryPath, types] of this.baseTypesByDirectory.entries()) {
			desired.set(directoryPath, new Set(types));
		}
		for (const [
			type,
			directories,
		] of this.discoveredDirectoriesByType.entries()) {
			for (const directoryPath of directories) {
				const existing = desired.get(directoryPath);
				if (existing) {
					existing.add(type);
				} else {
					desired.set(directoryPath, new Set([type]));
				}
			}
		}
		return desired;
	}

	private async readDirectoryFileCandidates(
		directoryPath: string,
	): Promise<UnifiedConfigFileCandidate[]> {
		try {
			const entries = await readdir(directoryPath, { withFileTypes: true });
			return entries
				.filter((entry) => entry.isFile())
				.map((entry) => ({
					directoryPath,
					fileName: entry.name,
					filePath: join(directoryPath, entry.name),
				}))
				.sort((a, b) => a.fileName.localeCompare(b.fileName));
		} catch (error) {
			if (
				isMissingDirectoryError(error) ||
				isInaccessibleDirectoryError(error)
			) {
				return [];
			}
			throw error;
		}
	}
}

