				join(workspacePath, ".agents", "skills"),
			]),
		);
		expect(resolveRulesConfigSearchPaths(workspacePath)).toEqual(
			expect.arrayContaining([
				join(workspacePath, "AGENTS.md"),
				join(workspacePath, ".clinerules"),
				join(workspacePath, ".cline", "rules"),
