}

async function discoverSkillFiles(
	directoryPath: string,
): Promise<ReadonlyArray<UnifiedConfigFileCandidate>> {
	if (basename(directoryPath) === ".cline") {
		const pluginRoots = await discoverManagedPluginRoots(directoryPath);
		const nestedCandidates = await Promise.all(
			pluginRoots.map((pluginRoot) =>
				discoverSkillFiles(join(pluginRoot, SKILLS_CONFIG_DIRECTORY_NAME)),
			),
		);
		return nestedCandidates.flat();
	}

	try {
		const entries = await readdir(directoryPath, { withFileTypes: true });
		const candidates: UnifiedConfigFileCandidate[] = [];
		for (const entry of entries) {
			if (entry.isFile() && entry.name === SKILL_FILE_NAME) {
				candidates.push({
					directoryPath,
					fileName: entry.name,
					filePath: join(directoryPath, entry.name),
				});
				continue;
			}
			const entryPath = join(directoryPath, entry.name);
			const isDirectory =
				entry.isDirectory() ||
				(entry.isSymbolicLink() &&
					(await stat(entryPath)
						.then((entryStat) => entryStat.isDirectory())
						.catch((error) => {
							if (isIgnorableDirectoryError(error)) {
								return false;
							}
							throw error;
						})));
			if (isDirectory) {
				candidates.push({
					directoryPath: entryPath,
					fileName: SKILL_FILE_NAME,
					filePath: join(entryPath, SKILL_FILE_NAME),
				});
			}
		}
		return candidates;
	} catch (error) {
		if (isIgnorableDirectoryError(error)) {
			return [];
		}
		throw error;
	}
}

async function discoverRulesLikeFiles(
	directoryPath: string,
): Promise<ReadonlyArray<UnifiedConfigFileCandidate>> {
	if (basename(directoryPath) === ".cline") {
		const pluginRoots = await discoverManagedPluginRoots(directoryPath);
		const nestedCandidates = await Promise.all(
			pluginRoots.map((pluginRoot) =>
				discoverRulesLikeFiles(join(pluginRoot, "rules.md")),
			),
		);
		return nestedCandidates.flat();
	}

	try {
		const entryStat = await stat(directoryPath);
		if (entryStat.isFile()) {
			return [
				{
					directoryPath: dirname(directoryPath),
					fileName: basename(directoryPath),
					filePath: directoryPath,
				},
			];
		}
	} catch (error) {
		if (!isIgnorableDirectoryError(error)) {
			throw error;
		}
	}

	try {
		const entries = await readdir(directoryPath, { withFileTypes: true });
		const candidates = entries
			.filter((entry) => entry.isFile() && isMarkdownFile(entry.name))
			.map((entry) => ({
				directoryPath,
				fileName: entry.name,
				filePath: join(directoryPath, entry.name),
			}));

		// Special case: if this is a workspace root directory, also check for AGENTS.md
		const agentsPath = join(directoryPath, "AGENTS.md");
		try {
			const agentsStat = await stat(agentsPath);
			if (agentsStat.isFile()) {
				// Check if AGENTS.md is not already in the candidates
				const alreadyIncluded = candidates.some(
					(c) => c.fileName === "AGENTS.md",
				);
				if (!alreadyIncluded) {
					candidates.push({
						directoryPath,
						fileName: "AGENTS.md",
						filePath: agentsPath,
					});
				}
			}
		} catch {
			// AGENTS.md doesn't exist or is not accessible, which is fine
		}

		return candidates;
	} catch (error) {
		if (isIgnorableDirectoryError(error)) {
			return [];
		}
		throw error;
	}
}

async function discoverManagedWorkflowFiles(
	directoryPath: string,
): Promise<ReadonlyArray<UnifiedConfigFileCandidate>> {
	if (basename(directoryPath) === ".cline") {
		const pluginRoots = await discoverManagedPluginRoots(directoryPath);
		const nestedCandidates = await Promise.all(
			pluginRoots.map((pluginRoot) =>
				discoverRulesLikeFiles(
					join(pluginRoot, WORKFLOWS_CONFIG_DIRECTORY_NAME),
				),
			),
		);
		return nestedCandidates.flat();
	}
	return discoverRulesLikeFiles(directoryPath);
}

export function createSkillsConfigDefinition(
	options?: CreateSkillsConfigDefinitionOptions,
): UnifiedConfigDefinition<"skill", SkillConfig> {
	const directories = resolveSkillDirectories(options);
	const managedRoot = options?.workspacePath
		? join(options.workspacePath, ".cline")
		: undefined;

	return {
		type: "skill",
		directories: managedRoot
			? dedupeDirectoryPaths([...directories, managedRoot])
			: directories,
		discoverFiles: discoverSkillFiles,
		includeFile: (fileName) => fileName === SKILL_FILE_NAME,
		parseFile: (context) =>
			parseSkillConfigFromMarkdown(
				context.content,
				basename(context.directoryPath),
			),
		resolveId: (skill) => normalizeName(skill.name),
	};
}

export function createRulesConfigDefinition(
	options?: CreateRulesConfigDefinitionOptions,
): UnifiedConfigDefinition<"rule", RuleConfig> {
	const directories =
		options?.directories ??
		resolveRulesConfigSearchPaths(options?.workspacePath);
	const managedRoot = options?.workspacePath
		? join(options.workspacePath, ".cline")
		: undefined;

	return {
		type: "rule",
		directories: managedRoot ? [...directories, managedRoot] : directories,
		discoverFiles: discoverRulesLikeFiles,
		includeFile: (fileName, filePath) =>
			fileName === ".clinerules" ||
			isMarkdownFile(fileName) ||
			isMarkdownFile(filePath),
		parseFile: (context) =>
			parseRuleConfigFromMarkdown(
				context.content,
				resolveRuleFallbackName(context, options?.workspacePath),
			),
		resolveId: (rule) => normalizeName(rule.name),
	};
}

export function createWorkflowsConfigDefinition(
	options?: CreateWorkflowsConfigDefinitionOptions,
): UnifiedConfigDefinition<"workflow", WorkflowConfig> {
	const directories =
		options?.directories ??
		resolveWorkflowsConfigSearchPaths(options?.workspacePath);
	const managedRoot = options?.workspacePath
		? join(options.workspacePath, ".cline")
		: undefined;

	return {
		type: "workflow",
		directories: managedRoot ? [...directories, managedRoot] : directories,
		discoverFiles: discoverManagedWorkflowFiles,
		includeFile: (fileName) => isMarkdownFile(fileName),
		parseFile: (context) =>
			parseWorkflowConfigFromMarkdown(
				context.content,
				basename(context.filePath, extname(context.filePath)),
			),
		resolveId: (workflow) => normalizeName(workflow.name),
	};
}

export interface CreateUserInstructionConfigWatcherOptions
	extends CreateInstructionWatcherOptions {
	skills?: CreateSkillsConfigDefinitionOptions;
	rules?: CreateRulesConfigDefinitionOptions;
	workflows?: CreateWorkflowsConfigDefinitionOptions;
}

export function createUserInstructionConfigWatcher(
	options?: CreateUserInstructionConfigWatcherOptions,
): UserInstructionConfigWatcher {
	const definitions: ReadonlyArray<
		UnifiedConfigDefinition<UserInstructionConfigType, UserInstructionConfig>
	> = [
		createSkillsConfigDefinition(options?.skills) as UnifiedConfigDefinition<
			UserInstructionConfigType,
			UserInstructionConfig
		>,
		createRulesConfigDefinition(options?.rules) as UnifiedConfigDefinition<
			UserInstructionConfigType,
			UserInstructionConfig
		>,
		createWorkflowsConfigDefinition(
			options?.workflows,
		) as UnifiedConfigDefinition<
			UserInstructionConfigType,
			UserInstructionConfig
		>,
	];

	return new UnifiedConfigFileWatcher(definitions, {
		debounceMs: options?.debounceMs,
		emitParseErrors: options?.emitParseErrors,
	});
}

import type { AgentExtension, AgentTool } from "@cline/shared";
import { loadRulesForSystemPromptFromWatcher } from "../../runtime/safety/rules";
import {
	createSkillsTool,
	type SkillsExecutor,
	type SkillsExecutorWithMetadata,
} from "../tools";
import { listAvailableRuntimeCommandsFromWatcher } from "./runtime-commands";
import type {
	SkillConfig,
	UserInstructionConfigWatcher,
} from "./user-instruction-config-loader";

type SkillsExecutorMetadataItem = {
	id: string;
	name: string;
	description?: string;
	disabled: boolean;
};

type ConfiguredSkill = SkillsExecutorMetadataItem & {
	skill: SkillConfig;
};

export interface CreateUserInstructionPluginOptions {
	watcher: UserInstructionConfigWatcher;
	watcherReady?: Promise<void>;
	includeRules?: boolean;
	includeSkills?: boolean;
	includeWorkflows?: boolean;
	registerSkillsTool?: boolean;
	allowedSkillNames?: ReadonlyArray<string>;
}

function normalizeSkillToken(token: string): string {
	return token.trim().replace(/^\/+/, "").toLowerCase();
}

function toAllowedSkillSet(
	allowedSkillNames?: ReadonlyArray<string>,
): Set<string> | undefined {
	if (!allowedSkillNames || allowedSkillNames.length === 0) {
		return undefined;
	}
	const normalized = allowedSkillNames
		.map(normalizeSkillToken)
		.filter((token) => token.length > 0);
	return normalized.length > 0 ? new Set(normalized) : undefined;
}

function isSkillAllowed(
	skillId: string,
	skillName: string,
	allowedSkills?: Set<string>,
): boolean {
	if (!allowedSkills) {
		return true;
	}
	const normalizedId = normalizeSkillToken(skillId);
	const normalizedName = normalizeSkillToken(skillName);
	const bareId = normalizedId.includes(":")
		? (normalizedId.split(":").at(-1) ?? normalizedId)
		: normalizedId;
	const bareName = normalizedName.includes(":")
		? (normalizedName.split(":").at(-1) ?? normalizedName)
		: normalizedName;
	return (
		allowedSkills.has(normalizedId) ||
		allowedSkills.has(normalizedName) ||
		allowedSkills.has(bareId) ||
		allowedSkills.has(bareName)
	);
}

export function getConfiguredSkillsFromWatcher(
	watcher: UserInstructionConfigWatcher,
	allowedSkillNames?: ReadonlyArray<string>,
): ConfiguredSkill[] {
	const allowedSkills = toAllowedSkillSet(allowedSkillNames);
	const snapshot = watcher.getSnapshot("skill");
	return [...snapshot.entries()]
		.map(([id, record]) => {
			const skill = record.item as SkillConfig;
			return {
				id,
				name: skill.name.trim(),
				description: skill.description?.trim(),
				disabled: skill.disabled === true,
				skill,
			};
		})
		.filter((skill) => isSkillAllowed(skill.id, skill.name, allowedSkills));
}

function listAvailableSkillNames(
	watcher: UserInstructionConfigWatcher,
	allowedSkillNames?: ReadonlyArray<string>,
): string[] {
	return getConfiguredSkillsFromWatcher(watcher, allowedSkillNames)
		.filter((skill) => !skill.disabled)
		.map((skill) => skill.name.trim())
		.filter((name) => name.length > 0)
		.sort((a, b) => a.localeCompare(b));
}

function resolveSkillRecord(
	watcher: UserInstructionConfigWatcher,
	requestedSkill: string,
	allowedSkillNames?: ReadonlyArray<string>,
): { id: string; skill: SkillConfig } | { error: string } {
	const normalized = normalizeSkillToken(requestedSkill);
	if (!normalized) {
		return { error: "Missing skill name." };
	}

	const configuredSkills = getConfiguredSkillsFromWatcher(
		watcher,
		allowedSkillNames,
	);
	const exact = configuredSkills.find((entry) => entry.id === normalized);
	if (exact) {
		const { skill } = exact;
		if (skill.disabled === true) {
			return {
				error: `Skill "${skill.name}" is configured but disabled.`,
			};
		}
		return { id: exact.id, skill };
	}

	const bareName = normalized.includes(":")
		? (normalized.split(":").at(-1) ?? normalized)
		: normalized;
	const suffixMatches = configuredSkills.filter(({ id }) => {
		if (id === bareName) {
			return true;
		}
		return id.endsWith(`:${bareName}`);
	});
	const enabledSuffixMatches = suffixMatches.filter(
		({ skill }) => skill.disabled !== true,
	);

	if (enabledSuffixMatches.length === 1) {
		const { id, skill } = enabledSuffixMatches[0];
		return { id, skill };
	}
	if (enabledSuffixMatches.length > 1) {
		return {
			error: `Skill "${requestedSkill}" is ambiguous. Use one of: ${enabledSuffixMatches.map(({ id }) => id).join(", ")}`,
		};
	}
	if (suffixMatches.length === 1) {
		const { skill } = suffixMatches[0];
		return {
			error: `Skill "${skill.name}" is configured but disabled.`,
		};
	}
	if (suffixMatches.length > 1) {
		return {
			error: `Skill "${requestedSkill}" is ambiguous, and all matches are disabled: ${suffixMatches.map(({ id }) => id).join(", ")}`,
		};
	}

	const available = listAvailableSkillNames(watcher, allowedSkillNames);
	return {
		error:
			available.length > 0
				? `Skill "${requestedSkill}" not found. Available skills: ${available.join(", ")}`
				: "No skills are currently available.",
	};
}

export function createUserInstructionSkillsExecutor(
	watcher: UserInstructionConfigWatcher,
	watcherReady: Promise<void> = Promise.resolve(),
	allowedSkillNames?: ReadonlyArray<string>,
): SkillsExecutorWithMetadata {
	const runningSkills = new Set<string>();
	const executor: SkillsExecutorWithMetadata = (async (skillName, args) => {
		await watcherReady;
		const resolved = resolveSkillRecord(watcher, skillName, allowedSkillNames);
		if ("error" in resolved) {
			return resolved.error;
		}

		const { id, skill } = resolved;
		if (runningSkills.has(id)) {
			return `Skill "${skill.name}" is already running.`;
		}

		runningSkills.add(id);
		try {
			const trimmedArgs = args?.trim();
			const argsTag = trimmedArgs
				? `\n<command-args>${trimmedArgs}</command-args>`
				: "";
			const description = skill.description?.trim()
				? `Description: ${skill.description.trim()}\n\n`
				: "";

			return `<command-name>${skill.name}</command-name>${argsTag}\n<command-instructions>\n${description}${skill.instructions}\n</command-instructions>`;
		} finally {
			runningSkills.delete(id);
		}
	}) as SkillsExecutor;

	Object.defineProperty(executor, "configuredSkills", {
		get: () =>
			getConfiguredSkillsFromWatcher(watcher, allowedSkillNames).map(
				({ skill: _skill, ...metadata }) => metadata,
			),
		enumerable: true,
		configurable: false,
	});
	return executor;
}

export function createUserInstructionPlugin(
	options: CreateUserInstructionPluginOptions,
): AgentExtension {
	const watcherReady = options.watcherReady ?? Promise.resolve();
	const capabilities = [
		options.includeRules ? "rules" : undefined,
		options.registerSkillsTool ? "tools" : undefined,
		options.includeSkills || options.includeWorkflows ? "commands" : undefined,
	].filter((value): value is "rules" | "tools" | "commands" => Boolean(value));

	return {
		name: "cline-user-instructions",
		manifest: {
			capabilities,
		},
		async setup(api) {
			await watcherReady;

			if (options.includeRules) {
				api.registerRule({
					id: "cline-user-instructions:rules",
					source: "user-instruction-watcher",
					content: () => loadRulesForSystemPromptFromWatcher(options.watcher),
				});
			}

			if (options.registerSkillsTool) {
				api.registerTool(
					createSkillsTool(
						createUserInstructionSkillsExecutor(
							options.watcher,
							watcherReady,
							options.allowedSkillNames,
						),
					) as AgentTool,
				);
			}

			for (const command of listAvailableRuntimeCommandsFromWatcher(
				options.watcher,
			).filter(
				(command) =>
					(command.kind === "skill" && options.includeSkills) ||
					(command.kind === "workflow" && options.includeWorkflows),
			)) {
				api.registerCommand({
					name: command.name,
					description: command.description,
					handler: (input) => {
						const trimmed = input.trim();
						return trimmed
							? `${command.instructions}\n\n${trimmed}`
							: command.instructions;
					},
				});
			}
		},
	};
}

import type { AgentExtension } from "@cline/shared";
import type { SkillsExecutorWithMetadata } from "../tools";
import {
	type AvailableRuntimeCommand,
	listAvailableRuntimeCommandsFromWatcher,
	resolveRuntimeSlashCommandFromWatcher,
} from "./runtime-commands";
import {
	type CreateUserInstructionConfigWatcherOptions,
	createUserInstructionConfigWatcher,
	type UserInstructionConfig,
	type UserInstructionConfigType,
	type UserInstructionConfigWatcher,
} from "./user-instruction-config-loader";
import {
	type CreateUserInstructionPluginOptions,
	createUserInstructionPlugin,
	createUserInstructionSkillsExecutor,
	getConfiguredSkillsFromWatcher,
} from "./user-instruction-plugin";

export interface UserInstructionConfigRecord<
	TConfig extends UserInstructionConfig = UserInstructionConfig,
> {
	type: UserInstructionConfigType;
	id: string;
	filePath: string;
	item: TConfig;
}

export interface CreateUserInstructionConfigServiceOptions
	extends CreateUserInstructionConfigWatcherOptions {}

export interface UserInstructionConfigService {
	start(): Promise<void>;
	stop(): void;
	refreshType(type: UserInstructionConfigType): Promise<void>;
	listRecords<TConfig extends UserInstructionConfig = UserInstructionConfig>(
		type: UserInstructionConfigType,
	): UserInstructionConfigRecord<TConfig>[];
	listRuntimeCommands(): AvailableRuntimeCommand[];
	resolveRuntimeSlashCommand(input: string): string;
	hasConfiguredSkills(allowedSkillNames?: ReadonlyArray<string>): boolean;
	createSkillsExecutor?(
		allowedSkillNames?: ReadonlyArray<string>,
	): SkillsExecutorWithMetadata;
	createExtension(
		options: Omit<
			CreateUserInstructionPluginOptions,
			"watcher" | "watcherReady"
		>,
	): AgentExtension;
}

class DefaultUserInstructionConfigService
	implements UserInstructionConfigService
{
	private readonly watcher: UserInstructionConfigWatcher;
	private ready: Promise<void> | undefined;
	private stopped = false;

	constructor(options?: CreateUserInstructionConfigServiceOptions) {
		this.watcher = createUserInstructionConfigWatcher(options);
	}

	start(): Promise<void> {
		if (!this.ready) {
			this.stopped = false;
			this.ready = this.watcher.start();
		}
		return this.ready;
	}

	stop(): void {
		if (this.stopped) {
			return;
		}
		this.stopped = true;
		this.watcher.stop();
		this.ready = undefined;
	}

	async refreshType(type: UserInstructionConfigType): Promise<void> {
		await this.start();
		await this.watcher.refreshType(type);
	}

	listRecords<TConfig extends UserInstructionConfig = UserInstructionConfig>(
		type: UserInstructionConfigType,
	): UserInstructionConfigRecord<TConfig>[] {
		return [...this.watcher.getSnapshot(type).entries()].map(
			([id, record]) => ({
				type,
				id,
				filePath: record.filePath,
				item: record.item as TConfig,
			}),
		);
	}

	listRuntimeCommands(): AvailableRuntimeCommand[] {
		return listAvailableRuntimeCommandsFromWatcher(this.watcher);
	}

	resolveRuntimeSlashCommand(input: string): string {
		return resolveRuntimeSlashCommandFromWatcher(input, this.watcher);
	}

	hasConfiguredSkills(allowedSkillNames?: ReadonlyArray<string>): boolean {
		return getConfiguredSkillsFromWatcher(this.watcher, allowedSkillNames).some(
			(skill) => !skill.disabled,
		);
	}

	createSkillsExecutor(
		allowedSkillNames?: ReadonlyArray<string>,
	): SkillsExecutorWithMetadata {
		return createUserInstructionSkillsExecutor(
			this.watcher,
			(this.ready ?? Promise.resolve()).catch(() => {}),
			allowedSkillNames,
		);
	}

	createExtension(
		options: Omit<
			CreateUserInstructionPluginOptions,
			"watcher" | "watcherReady"
		>,
	): AgentExtension {
		return createUserInstructionPlugin({
			...options,
			watcher: this.watcher,
			watcherReady: (this.ready ?? Promise.resolve()).catch(() => {}),
		});
	}
}

export function createUserInstructionConfigService(
	options?: CreateUserInstructionConfigServiceOptions,
): UserInstructionConfigService {
	return new DefaultUserInstructionConfigService(options);
}

import { createHandlerAsync } from "@cline/llms";
import type { BasicLogger } from "@cline/shared";
import type {
	CoreCompactionContext,
	CoreCompactionResult,
	CoreCompactionSummarizerConfig,
} from "../../types/config";
import type { ProviderConfig } from "../../types/provider-settings";
import {
	type BudgetProjectionResult,
	buildBudgetProjection,
} from "./budget-projection";
import {
	buildSummaryMessage,
	buildSummaryRequest,
	type EstimateMessageTokens,
	ensureFilesSection,
	estimateTokens,
	extractFileOps,
	findCutIndex,
	findLatestSummaryIndex,
	getCompactionSummaryMetadata,
	resolveEffectiveMaxInputTokens,
	resolveSummarizerConfig,
	serializeConversation,
} from "./compaction-shared";

const MIN_AGENTIC_SUMMARY_INPUT_TOKENS = 1_024;

function resolveProviderMaxInputTokens(
	providerConfig: ProviderConfig,
): number | undefined {
	const modelInfoLimit = resolveEffectiveMaxInputTokens({
		maxInputTokens:
			providerConfig.maxInputTokens ?? providerConfig.modelInfo?.maxInputTokens,
		contextWindow: providerConfig.modelInfo?.contextWindow,
	});
	if (modelInfoLimit !== undefined) {
		return modelInfoLimit;
	}
	const knownModelInfo = providerConfig.knownModels?.[providerConfig.modelId];
	return resolveEffectiveMaxInputTokens({
		maxInputTokens: knownModelInfo?.maxInputTokens,
		contextWindow: knownModelInfo?.contextWindow,
	});
}

export function buildAgenticSummaryInputBudget(options: {
	messages: CoreCompactionContext["messages"];
	targetTokens: number;
	estimateMessageTokens: EstimateMessageTokens;
}): BudgetProjectionResult {
	return buildBudgetProjection({
		messages: options.messages,
		targetTokens: Math.max(1, options.targetTokens),
		policyIntent: "agentic_summary",
		estimateMessageTokens: options.estimateMessageTokens,
	});
}

async function generateSummary(options: {
	providerConfig: ProviderConfig;
	request: string;
	logger?: BasicLogger;
}): Promise<string> {
	const handler = await createHandlerAsync(options.providerConfig);
	let text = "";
	for await (const chunk of handler.createMessage(
		"Summarize the provided coding session into a concise continuation note with detailed next steps.",
		[{ role: "user", content: options.request }],
	)) {
		if (chunk.type === "text") {
			text += chunk.text;
			continue;
		}
		if (chunk.type === "done" && !chunk.success && chunk.error) {
			throw new Error(chunk.error);
		}
	}
	options.logger?.debug("Generated compaction summary", {
		outputChars: text.length,
		modelId: options.providerConfig.modelId,
		providerId: options.providerConfig.providerId,
	});
	return text.trim();
}

function safeJsonSize(value: unknown): number {
	try {
		return JSON.stringify(value).length;
	} catch {
		return String(value).length;
	}
}

export async function runAgenticCompaction(options: {
	context: CoreCompactionContext;
	providerConfig: ProviderConfig;
	summarizer?: CoreCompactionSummarizerConfig;
	preserveRecentTokens: number;
	estimateMessageTokens: EstimateMessageTokens;
	logger?: BasicLogger;
}): Promise<CoreCompactionResult | undefined> {
	const messages = options.context.messages;
	if (messages.length < 2) {
		return undefined;
	}

	const cutIndex = findCutIndex(
		messages,
		options.preserveRecentTokens,
		options.estimateMessageTokens,
	);
	if (cutIndex <= 0 || cutIndex >= messages.length) {
		return undefined;
	}

	const messagesToSummarize = messages.slice(0, cutIndex);
	const latestSummaryIndex = findLatestSummaryIndex(messagesToSummarize);
	const previousSummary =
		latestSummaryIndex >= 0
			? getCompactionSummaryMetadata(messagesToSummarize[latestSummaryIndex])
					?.summary
			: undefined;
	const newMessagesToFold =
		latestSummaryIndex >= 0
			? messagesToSummarize.slice(latestSummaryIndex + 1)
			: messagesToSummarize;
	if (newMessagesToFold.length === 0) {
		return undefined;
	}

	const preProjectionFileOps = extractFileOps(messagesToSummarize);
	const summarizerProviderConfig = resolveSummarizerConfig({
		activeProviderConfig: options.providerConfig,
		summarizer: options.summarizer,
	});
	const resolvedSummarizerInputLimit = resolveProviderMaxInputTokens(
		summarizerProviderConfig,
	);
	const canUseActiveContextLimit = options.summarizer === undefined;
	const activeCompactionInputLimit = Math.max(
		options.context.budget.request.maxInputTokens,
		options.context.budget.request.triggerTokens,
		MIN_AGENTIC_SUMMARY_INPUT_TOKENS,
	);
	if (resolvedSummarizerInputLimit === undefined && !canUseActiveContextLimit) {
		options.logger?.log(
			"Agentic compaction summarizer has no known input limit; using conservative summary budget",
			{
				severity: "warn",
				summarizerProviderId: summarizerProviderConfig.providerId,
				summarizerModelId: summarizerProviderConfig.modelId,
				fallbackInputLimit: MIN_AGENTIC_SUMMARY_INPUT_TOKENS,
			},
		);
	}
	const summarizerInputLimit =
		resolvedSummarizerInputLimit ??
		(canUseActiveContextLimit
			? activeCompactionInputLimit
			: MIN_AGENTIC_SUMMARY_INPUT_TOKENS);
	const summaryRequestOverheadTokens = estimateTokens(
		buildSummaryRequest({
			previousSummary,
			conversationText: "",
			fileOps: preProjectionFileOps,
		}).length,
	);
	const availableSummaryInputTokens =
		summarizerInputLimit - summaryRequestOverheadTokens;
	if (availableSummaryInputTokens <= 0) {
		options.logger?.debug(
			"Skipped agentic compaction: summarizer budget exhausted",
			{
				summarizerProviderId: summarizerProviderConfig.providerId,
				summarizerModelId: summarizerProviderConfig.modelId,
				summarizerInputLimit,
				summaryRequestOverheadTokens,
			},
		);
		return undefined;
	}
	const summaryInputBudget = buildAgenticSummaryInputBudget({
		messages: newMessagesToFold,
		targetTokens: availableSummaryInputTokens,
		estimateMessageTokens: options.estimateMessageTokens,
	});
	if (summaryInputBudget.status === "failed") {
		options.logger?.log(
			"Skipped agentic compaction: summary input budget failed",
			{
				severity: "warn",
				budgetWarnings: summaryInputBudget.warnings.map(
					(warning) => warning.code,
				),
				summaryInputEstimatedTokens: summaryInputBudget.estimatedTokens,
				targetTokens: availableSummaryInputTokens,
				summarizerProviderId: summarizerProviderConfig.providerId,
				summarizerModelId: summarizerProviderConfig.modelId,
			},
		);
		return undefined;
	}
	const fileOps = extractFileOps(summaryInputBudget.messages);
	const conversationText = serializeConversation(summaryInputBudget.messages);
	const summaryRequest = buildSummaryRequest({
		previousSummary,
		conversationText,
		fileOps,
	});
	options.logger?.debug("Agentic compaction summarizer diagnostics", {
		messagesToSummarize: messagesToSummarize.length,
		newMessagesToFold: newMessagesToFold.length,
		preservedMessages: messages.length - cutIndex,
		previousSummaryChars: previousSummary?.length ?? 0,
		conversationTextChars: conversationText.length,
		summaryRequestChars: summaryRequest.length,
		summaryRequestEstimatedTokens: estimateTokens(summaryRequest.length),
		newMessagesJsonChars: safeJsonSize(newMessagesToFold),
		summaryInputEstimatedTokens: summaryInputBudget.estimatedTokens,
		summaryInputActions: summaryInputBudget.actions.length,
		summaryInputWarnings: summaryInputBudget.warnings.map(
			(warning) => warning.code,
		),
		summaryRequestOverheadTokens,
		summarizerProviderId: summarizerProviderConfig.providerId,
		summarizerModelId: summarizerProviderConfig.modelId,
		summarizerInputLimit,
		maxInputTokens: options.context.budget.request.maxInputTokens,
		triggerTokens: options.context.budget.request.triggerTokens,
	});
	const rawSummary = await generateSummary({
		providerConfig: summarizerProviderConfig,
		request: summaryRequest,
		logger: options.logger,
	});
	if (!rawSummary.trim()) {
		return undefined;
	}

	const summary = ensureFilesSection(rawSummary, fileOps);
	const tokensBefore = messages.reduce(
		(total, message) => total + options.estimateMessageTokens(message),
		0,
	);
	const resultMessages = [
		buildSummaryMessage({
			summary,
			fileOps,
			tokensBefore,
		}),
		...messages.slice(cutIndex),
	];
	const tokensAfter = resultMessages.reduce(
		(total, message) => total + options.estimateMessageTokens(message),
		0,
	);
	options.logger?.debug("Performed agentic compaction", {
		messagesBefore: messages.length,
		messagesAfter: resultMessages.length,
		messagesSummarized: cutIndex,
		messagesPreserved: messages.length - cutIndex,
		tokensBefore,
		tokensAfter,
		maxInputTokens: options.context.budget.request.maxInputTokens,
	});
	const budgetActionCount = summaryInputBudget.actions.filter(
		(action) =>
			action.reason === "over_budget" || action.reason === "tool_pair_boundary",
	).length;
	return {
		messages: resultMessages,
		budget: {
			policyIntent: "agentic_summary",
			actionCount: budgetActionCount,
			warningCount: summaryInputBudget.warnings.length,
			liveTailHandling: summaryInputBudget.liveTailHandling,
		},
	};
}

import type {
	BasicLogger,
	ContentBlock,
	MessageWithMetadata,
} from "@cline/shared";
import type {
	CoreCompactionContext,
	CoreCompactionResult,
} from "../../types/config";
import { buildBudgetProjection } from "./budget-projection";
import {
	type EstimateMessageTokens,
	formatToolActivitySummary,
	hasToolActivity,
	isTurnStartMessage,
	summarizeToolActivity,
	type ToolActivitySummary,
} from "./compaction-shared";

function getTotalTokens(
	messages: MessageWithMetadata[],
	estimateMessageTokens: EstimateMessageTokens,
): number {
	return messages.reduce(
		(total, message) => total + estimateMessageTokens(message),
		0,
	);
}

function sanitizeTypedUserMessage(
	message: MessageWithMetadata,
): MessageWithMetadata | undefined {
	if (typeof message.content === "string") {
		const text = message.content.trim();
		return text ? { ...message, content: text } : undefined;
	}
	const kept = message.content.filter(
		(block) => block.type !== "text" || block.text.trim(),
	);
	if (kept.length === 0) {
		return undefined;
	}
	return {
		...message,
		content: kept.map((block) =>
			block.type === "text" ? { ...block, text: block.text.trim() } : block,
		),
	};
}

function haveMessagesChanged(
	original: MessageWithMetadata[],
	next: MessageWithMetadata[],
): boolean {
	return JSON.stringify(original) !== JSON.stringify(next);
}

/** How many of the conversation's most recent assistant text contents
 * survive verbatim inside the dropped-work summaries. */
const PRESERVED_ASSISTANT_TEXT_COUNT = 3;

function assistantTextContent(
	message: MessageWithMetadata,
): string | undefined {
	if (message.role !== "assistant") {
		return undefined;
	}
	if (typeof message.content === "string") {
		const text = message.content.trim();
		return text || undefined;
	}
	const text = message.content
		.filter((block) => block.type === "text")
		.map((block) => block.text.trim())
		.filter(Boolean)
		.join("\n");
	return text || undefined;
}

function buildDroppedWorkSummaryBlock(
	summary: ToolActivitySummary,
	preservedResponses: string[],
): ContentBlock {
	const responsesSection =
		preservedResponses.length > 0
			? `\n\nYour recent responses:\n${preservedResponses.join("\n---\n")}`
			: "";
	return {
		type: "text",
		text: `<SYSTEM_NOTICE>\nEarlier context was compacted. Summary of your actions after the request above:\n${formatToolActivitySummary(summary)}${responsesSection}</SYSTEM_NOTICE>`,
	};
}

function userContentBlocks(
	message: MessageWithMetadata,
	keepAttachments: boolean,
): ContentBlock[] {
	if (typeof message.content === "string") {
		return message.content.trim()
			? [{ type: "text", text: message.content }]
			: [];
	}
	if (keepAttachments) {
		return [...message.content];
	}
	// Attached files and images are stale context bloat once the turn is
	// old enough to compact; the dropped-work summaries carry file paths.
	// Only the latest typed prompt keeps its attachments — they may be
	// load-bearing for the active request.
	return message.content.filter(
		(block) => block.type !== "file" && block.type !== "image",
	);
}

/**
 * Collapse runs of adjacent typed user messages — left behind when the
 * assistant turns between them were removed — into a single user message.
 * Each gap is bridged with a summary of the tool work that was dropped
 * there, resolved by message id against the original transcript. Work
 * dropped after a typed user message with no surviving messages in
 * between (e.g. the current turn's tool calls) gets a trailing summary
 * appended to that message.
 */
function mergeAdjacentUserTurns(
	messages: MessageWithMetadata[],
	originalMessages: MessageWithMetadata[],
): MessageWithMetadata[] {
	const originalIndexById = new Map<string, number>();
	originalMessages.forEach((message, index) => {
		if (message.id) {
			originalIndexById.set(message.id, index);
		}
	});
	const resolveOriginalIndex = (
		message: MessageWithMetadata,
	): number | undefined =>
		message.id ? originalIndexById.get(message.id) : undefined;

	// The conversation's most recent assistant text contents survive
	// verbatim inside the summary block covering the span they were
	// dropped from.
	const preservedTextIndices = new Set<number>();
	for (
		let scan = originalMessages.length - 1;
		scan >= 0 && preservedTextIndices.size < PRESERVED_ASSISTANT_TEXT_COUNT;
		scan -= 1
	) {
		if (assistantTextContent(originalMessages[scan])) {
			preservedTextIndices.add(scan);
		}
	}
	const collectPreservedResponses = (start: number, end: number): string[] => {
		const responses: string[] = [];
		for (let position = start; position < end; position += 1) {
			if (!preservedTextIndices.has(position)) {
				continue;
			}
			const text = assistantTextContent(originalMessages[position]);
			if (text) {
				responses.push(text);
			}
		}
		return responses;
	};

	interface MergedEntry {
		message: MessageWithMetadata;
		firstOriginalIndex: number | undefined;
		lastOriginalIndex: number | undefined;
		isTypedUser: boolean;
	}

	let latestTypedIndex = -1;
	for (let scan = messages.length - 1; scan >= 0; scan -= 1) {
		if (isTurnStartMessage(messages[scan])) {
			latestTypedIndex = scan;
			break;
		}
	}

	const entries: MergedEntry[] = [];
	let index = 0;
	while (index < messages.length) {
		if (!isTurnStartMessage(messages[index])) {
			const originalIndex = resolveOriginalIndex(messages[index]);
			entries.push({
				message: messages[index],
				firstOriginalIndex: originalIndex,
				lastOriginalIndex: originalIndex,
				isTypedUser: false,
			});
			index += 1;
			continue;
		}
		let runEnd = index;
		while (
			runEnd + 1 < messages.length &&
			isTurnStartMessage(messages[runEnd + 1])
		) {
			runEnd += 1;
		}
		let message = messages[index];
		if (runEnd > index) {
			const blocks: ContentBlock[] = [];
			for (let member = index; member <= runEnd; member += 1) {
				if (member > index) {
					const previousIndex = resolveOriginalIndex(messages[member - 1]);
					const currentIndex = resolveOriginalIndex(messages[member]);
					if (
						previousIndex !== undefined &&
						currentIndex !== undefined &&
						currentIndex > previousIndex + 1
					) {
						const summary = summarizeToolActivity(
							originalMessages.slice(previousIndex + 1, currentIndex),
						);
						const responses = collectPreservedResponses(
							previousIndex + 1,
							currentIndex,
						);
						if (hasToolActivity(summary) || responses.length > 0) {
							blocks.push(buildDroppedWorkSummaryBlock(summary, responses));
						}
					}
				}
				blocks.push(
					...userContentBlocks(messages[member], member === latestTypedIndex),
				);
			}
			message = { ...messages[index], content: blocks };
		} else {
			const blocks = userContentBlocks(message, index === latestTypedIndex);
			if (
				Array.isArray(message.content) &&
				blocks.length !== message.content.length
			) {
				message = { ...message, content: blocks };
			}
		}
		entries.push({
			message,
			firstOriginalIndex: resolveOriginalIndex(messages[index]),
			lastOriginalIndex: resolveOriginalIndex(messages[runEnd]),
			isTypedUser: true,
		});
		index = runEnd + 1;
	}

	// Trailing gaps: dropped work between a typed user message and the next
	// surviving message (or the end of the transcript) is summarized into
	// that user message so the model keeps a trace of its own actions.
	for (let entry = 0; entry < entries.length; entry += 1) {
		const current = entries[entry];
		if (!current.isTypedUser || current.lastOriginalIndex === undefined) {
			continue;
		}
		const next = entries[entry + 1];
		const gapEnd = next ? next.firstOriginalIndex : originalMessages.length;
		if (gapEnd === undefined || gapEnd <= current.lastOriginalIndex + 1) {
			continue;
		}
		const summary = summarizeToolActivity(
			originalMessages.slice(current.lastOriginalIndex + 1, gapEnd),
		);
		const responses = collectPreservedResponses(
			current.lastOriginalIndex + 1,
			gapEnd,
		);
		if (!hasToolActivity(summary) && responses.length === 0) {
			continue;
		}
		current.message = {
			...current.message,
			content: [
				...userContentBlocks(current.message, true),
				buildDroppedWorkSummaryBlock(summary, responses),
			],
		};
	}
	return entries.map((entry) => entry.message);
}

/**
 * Per-message token metrics describe the request context at the time the
 * message was produced; after compaction rewrites the transcript they no
 * longer add up, so they are dropped from the compacted result.
 */
function stripStaleMetrics(message: MessageWithMetadata): MessageWithMetadata {
	if (!message.metrics) {
		return message;
	}
	const { metrics: _metrics, ...rest } = message;
	return rest;
}

interface AggregatedUsage {
	inputTokens: number;
	outputTokens: number;
	cacheReadTokens: number;
	cacheWriteTokens: number;
	cost: number;
}

/**
 * Sum the per-message usage metrics that compaction is about to strip, so
 * the aggregate survives on the compaction message's metadata.
 */
function aggregateUsageMetrics(
	messages: MessageWithMetadata[],
): AggregatedUsage | undefined {
	let found = false;
	const totals = {
		inputTokens: 0,
		outputTokens: 0,
		cacheReadTokens: 0,
		cacheWriteTokens: 0,
		cost: 0,
	};
	for (const message of messages) {
		const metrics = message.metrics;
		if (!metrics) {
			continue;
		}
		found = true;
		totals.inputTokens += metrics.inputTokens ?? 0;
		totals.outputTokens += metrics.outputTokens ?? 0;
		totals.cacheReadTokens += metrics.cacheReadTokens ?? 0;
		totals.cacheWriteTokens += metrics.cacheWriteTokens ?? 0;
		totals.cost += metrics.cost ?? 0;
	}
	return found ? totals : undefined;
}

function addAggregatedUsage(
	first: AggregatedUsage | undefined,
	second: AggregatedUsage | undefined,
): AggregatedUsage | undefined {
	if (!first) {
		return second;
	}
	if (!second) {
		return first;
	}
	return {
		inputTokens: first.inputTokens + second.inputTokens,
		outputTokens: first.outputTokens + second.outputTokens,
		cacheReadTokens: first.cacheReadTokens + second.cacheReadTokens,
		cacheWriteTokens: first.cacheWriteTokens + second.cacheWriteTokens,
		cost: first.cost + second.cost,
	};
}

/**
 * Compaction stats accumulate across repeated compactions: the folded
 * first message carries the running totals, and each new pass adds only
 * what it removed this time.
 */
function readPriorCompactionStats(message: MessageWithMetadata | undefined): {
	messagesRemoved: number;
	usageBefore: AggregatedUsage | undefined;
} {
	const metadata = message?.metadata as Record<string, unknown> | undefined;
	if (!metadata || metadata.kind !== "compaction") {
		return { messagesRemoved: 0, usageBefore: undefined };
	}
	const usage = metadata.usageBefore as Partial<AggregatedUsage> | undefined;
	return {
		messagesRemoved:
			typeof metadata.messagesRemoved === "number"
				? metadata.messagesRemoved
				: 0,
		usageBefore:
			usage && typeof usage === "object"
				? {
						inputTokens: usage.inputTokens ?? 0,
						outputTokens: usage.outputTokens ?? 0,
						cacheReadTokens: usage.cacheReadTokens ?? 0,
						cacheWriteTokens: usage.cacheWriteTokens ?? 0,
						cost: usage.cost ?? 0,
					}
				: undefined,
	};
}

const COMPACTION_PRESERVED_MARKER = "preserved";

/**
 * Messages that survived an earlier compaction are frozen: a later
 * compaction never re-folds them, so repeated compactions only process
 * the messages added since. Without this, each pass would re-drop the
 * previously preserved answers and stack duplicate summary blocks onto
 * the already-folded prompts.
 */
function isPreservedByCompaction(message: MessageWithMetadata): boolean {
	return (
		(message.metadata as { compaction?: string } | undefined)?.compaction ===
		COMPACTION_PRESERVED_MARKER
	);
}

function markPreservedByCompaction(
	message: MessageWithMetadata,
): MessageWithMetadata {
	if (isPreservedByCompaction(message)) {
		return message;
	}
	return {
		...message,
		metadata: { ...message.metadata, compaction: COMPACTION_PRESERVED_MARKER },
	};
}

/**
 * The concluding assistant answer of an older turn is kept as archive:
 * thinking blocks carry no value there and are dropped. Returns undefined
 * when nothing text-bearing remains.
 */
function sanitizeOlderAssistantFinal(
	message: MessageWithMetadata,
): MessageWithMetadata | undefined {
	if (typeof message.content === "string") {
		return message.content.trim() ? message : undefined;
	}
	const kept = message.content.filter(
		(block) => block.type !== "thinking" && block.type !== "redacted_thinking",
	);
	if (!kept.some((block) => block.type === "text" && block.text.trim())) {
		return undefined;
	}
	return { ...message, content: kept };
}

/**
 * Fold the conversation history without a summarizer model. Typed user
 * prompts always survive. The latest typed turn keeps its newest messages
 * verbatim within the token target, dropping only the oldest ones (the
 * kept suffix starts at an assistant message so no tool pair is split).
 * Older turns keep their concluding assistant answer when it fits, newest
 * turns first. Everything else is dropped and re-surfaced as dropped-work
 * summaries attached to the surviving prompts.
 */
export function runBasicCompaction(options: {
	context: CoreCompactionContext;
	estimateMessageTokens: EstimateMessageTokens;
	logger?: BasicLogger;
}): CoreCompactionResult | undefined {
	const originalMessages = options.context.messages;
	const estimate = options.estimateMessageTokens;
	// A lone message has nothing to compact around it; truncating the only
	// prompt would just corrupt the active request.
	if (originalMessages.length < 2) {
		return undefined;
	}
	const totalTargetTokens = Math.max(
		1,
		Math.min(
			options.context.budget.messages.targetTokens,
			options.context.budget.messages.triggerTokens,
		),
	);

	const typedIndices: number[] = [];
	for (let index = 0; index < originalMessages.length; index += 1) {
		if (isTurnStartMessage(originalMessages[index])) {
			typedIndices.push(index);
		}
	}
	const sanitizedTypedByIndex = new Map<number, MessageWithMetadata>();
	for (const index of typedIndices) {
		const sanitized = sanitizeTypedUserMessage(originalMessages[index]);
		if (sanitized) {
			sanitizedTypedByIndex.set(index, sanitized);
		}
	}
	if (sanitizedTypedByIndex.size === 0) {
		return undefined;
	}
	const latestTypedOriginalIndex = typedIndices[typedIndices.length - 1];

	// Typed prompts are mandatory; budget them at their post-merge shape
	// (attachments survive only on the latest prompt).
	let totalTokens = 0;
	for (const [index, sanitized] of sanitizedTypedByIndex) {
		totalTokens += estimate({
			...sanitized,
			content: userContentBlocks(sanitized, index === latestTypedOriginalIndex),
		});
	}

	// Output of an earlier compaction is frozen: those messages are kept
	// as-is and never re-folded, so this pass only processes new messages.
	const frozenIndices = new Set<number>();
	for (let index = 0; index < originalMessages.length; index += 1) {
		if (sanitizedTypedByIndex.has(index)) {
			continue;
		}
		if (isPreservedByCompaction(originalMessages[index])) {
			frozenIndices.add(index);
			totalTokens += estimate(originalMessages[index]);
		}
	}

	// Latest typed turn: preserve the newest messages that fit, dropping
	// only the oldest. Snapping the kept suffix forward to an assistant
	// message keeps tool pairs intact (a tool_use holds its result in the
	// user message that follows it).
	const keptExtraIndices = new Set<number>();
	{
		let start = originalMessages.length;
		let accumulated = 0;
		for (
			let index = originalMessages.length - 1;
			index > latestTypedOriginalIndex;
			index -= 1
		) {
			// Reaching frozen messages means the rest is a previous
			// compaction's output — already kept, nothing left to walk.
			if (frozenIndices.has(index)) {
				break;
			}
			const cost = estimate(originalMessages[index]);
			if (totalTokens + accumulated + cost > totalTargetTokens) {
				break;
			}
			accumulated += cost;
			start = index;
		}
		while (
			start < originalMessages.length &&
			originalMessages[start].role !== "assistant"
		) {
			start += 1;
		}
		for (let index = start; index < originalMessages.length; index += 1) {
			keptExtraIndices.add(index);
			totalTokens += estimate(originalMessages[index]);
		}
	}

	// Older typed turns: keep each turn's concluding assistant answer when
	// it fits, newest turns first.
	const olderFinalByIndex = new Map<number, MessageWithMetadata>();
	for (let block = typedIndices.length - 2; block >= 0; block -= 1) {
		const blockStart = typedIndices[block] + 1;
		const blockEnd = typedIndices[block + 1];
		for (let index = blockEnd - 1; index >= blockStart; index -= 1) {
			const candidate = originalMessages[index];
			// A frozen answer from an earlier compaction already covers this
			// turn.
			if (frozenIndices.has(index)) {
				break;
			}
			if (candidate.role !== "assistant") {
				continue;
			}
			// An assistant message with a tool_use cannot stand alone (its
			// result is dropped); look further back for the turn's answer.
			if (
				Array.isArray(candidate.content) &&
				candidate.content.some((b) => b.type === "tool_use")
			) {
				continue;
			}
			const preserved = sanitizeOlderAssistantFinal(candidate);
			if (preserved) {
				const cost = estimate(preserved);
				if (totalTokens + cost <= totalTargetTokens) {
					olderFinalByIndex.set(index, preserved);
					totalTokens += cost;
				}
			}
			break;
		}
	}

	const keptMessages: MessageWithMetadata[] = [];
	for (let index = 0; index < originalMessages.length; index += 1) {
		const typed = sanitizedTypedByIndex.get(index);
		if (typed) {
			keptMessages.push(typed);
			continue;
		}
		if (frozenIndices.has(index) || keptExtraIndices.has(index)) {
			keptMessages.push(originalMessages[index]);
			continue;
		}
		const olderFinal = olderFinalByIndex.get(index);
		if (olderFinal) {
			keptMessages.push(olderFinal);
		}
	}
	const beforeTokens = getTotalTokens(
		originalMessages,
		options.estimateMessageTokens,
	);
	// Safety valve for estimator drift. The floor is whatever the selection
	// deliberately kept: typed prompts and frozen output of earlier
	// compactions must not be trimmed to chase a target that is already
	// below their size (e.g. a repeated manual compaction halving its
	// target each run). The trigger stays a hard ceiling — content that
	// cannot fit the window at all is still trimmed best-effort.
	const projectionTargetTokens = Math.min(
		Math.max(totalTargetTokens, totalTokens),
		Math.max(1, options.context.budget.messages.triggerTokens),
	);
	const budgeted = buildBudgetProjection({
		messages: keptMessages,
		targetTokens: projectionTargetTokens,
		policyIntent: "basic_compaction_projection",
		estimateMessageTokens: options.estimateMessageTokens,
	});
	if (budgeted.status === "failed") {
		options.logger?.debug("Basic compaction returned best-effort projection", {
			budgetWarnings: budgeted.warnings.map((warning) => warning.code),
			projectedTokens: budgeted.estimatedTokens,
			targetTokens: totalTargetTokens,
			maxInputTokens: options.context.budget.request.maxInputTokens,
		});
	}
	const mergedMessages = mergeAdjacentUserTurns(
		budgeted.messages,
		originalMessages,
	);

	if (!haveMessagesChanged(originalMessages, mergedMessages)) {
		return undefined;
	}
	// Mirror the recovery_notice metadata convention: mark the folded
	// message as system-inserted and record what the fold removed, since
	// the per-message metrics it aggregates are stripped below. Stats
	// accumulate across repeated compactions — earlier passes already
	// stripped their metrics, so this pass only sees the new tail's.
	const prior = readPriorCompactionStats(mergedMessages[0]);
	const usageBefore = addAggregatedUsage(
		prior.usageBefore,
		aggregateUsageMetrics(originalMessages),
	);
	const compactionMetadata = {
		kind: "compaction",
		reason:
			options.context.mode === "manual"
				? "manual_compaction"
				: "auto_compaction",
		displayRole: "system",
		messagesRemoved:
			prior.messagesRemoved + (originalMessages.length - mergedMessages.length),
		...(usageBefore ? { usageBefore } : {}),
	};
	const resultMessages = mergedMessages.map((message, index) => {
		if (index === 0 && isTurnStartMessage(message)) {
			return stripStaleMetrics({
				...message,
				metadata: { ...message.metadata, ...compactionMetadata },
			});
		}
		// Non-typed survivors (kept tool pairs and preserved answers) are
		// frozen so the next compaction leaves them alone.
		return stripStaleMetrics(
			isTurnStartMessage(message)
				? message
				: markPreservedByCompaction(message),
		);
	});

	const afterTokens = getTotalTokens(
		resultMessages,
		options.estimateMessageTokens,
	);
	const budgetActionCount = budgeted.actions.filter(
		(action) =>
			action.reason === "over_budget" || action.reason === "tool_pair_boundary",
	).length;
	options.logger?.debug("Performed basic compaction", {
		messagesBefore: originalMessages.length,
		messagesAfter: resultMessages.length,
		messagesRemoved: originalMessages.length - resultMessages.length,
		tokensBefore: beforeTokens,
		tokensAfter: afterTokens,
		budgetStatus: budgeted.status,
		budgetActions: budgetActionCount,
		budgetWarnings: budgeted.warnings.map((warning) => warning.code),
		targetTokens: totalTargetTokens,
		maxInputTokens: options.context.budget.request.maxInputTokens,
	});

	return {
		messages: resultMessages,
		budget: {
			policyIntent: "basic_compaction_projection",
			actionCount: budgetActionCount,
			warningCount: budgeted.warnings.length,
			liveTailHandling: budgeted.liveTailHandling,
		},
	};
}

