});

import type {
	ContentBlock,
	MessageWithMetadata,
	ToolResultContent,
} from "@cline/shared";
import type {
	BudgetAction,
	BudgetMutationAction,
	BudgetProjectionOptions,
	BudgetProjectionResult,
	BudgetProjectionWarning,
	BudgetPolicyIntent,
} from "./types";

type EstimateMessageTokens = (message: MessageWithMetadata) => number;

interface ProjectionPolicy {
	protectLatestTypedUser: boolean;
	protectLiveTailFromDrop: boolean;
	dropUnsafeOutsideLiveTail: boolean;
	dropThinkingBlocks: boolean;
}

function resolveProjectionPolicy(intent: BudgetPolicyIntent): ProjectionPolicy {
	switch (intent) {
		case "agentic_summary":
		case "basic_compaction_projection":
			return {
				protectLatestTypedUser: true,
				protectLiveTailFromDrop: true,
				dropUnsafeOutsideLiveTail: true,
				dropThinkingBlocks: true,
			};
		case "normal_provider_request":
			return {
				protectLatestTypedUser: true,
				protectLiveTailFromDrop: true,
				dropUnsafeOutsideLiveTail: false,
				dropThinkingBlocks: false,
			};
	}
}

function cloneMessages(messages: MessageWithMetadata[]): MessageWithMetadata[] {
	return messages.map((message) => ({
		...message,
		content: Array.isArray(message.content)
			? message.content.map((block) => ({ ...block }) as ContentBlock)
			: message.content,
		...(message.metadata ? { metadata: { ...message.metadata } } : {}),
	}));
}

function safeJsonSize(value: unknown): number {
	try {
		return JSON.stringify(value).length;
	} catch {
		return String(value).length;
	}
}

function totalTokens(
	messages: MessageWithMetadata[],
	estimateMessageTokens: EstimateMessageTokens,
): number {
	return messages.reduce(
		(total, message) => total + estimateMessageTokens(message),
		0,
	);
}

function isToolResultOnlyUserMessage(message: MessageWithMetadata): boolean {
	return (
		message.role === "user" &&
		Array.isArray(message.content) &&
		message.content.length > 0 &&
		message.content.every((block) => block.type === "tool_result")
	);
}

export function findLatestTypedUserMessageIndex(
	messages: MessageWithMetadata[],
): number {
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		const message = messages[index];
		if (message.role === "user" && !isToolResultOnlyUserMessage(message)) {
			return index;
		}
	}
	return -1;
}

function findFirstTypedUserMessageIndex(
	messages: MessageWithMetadata[],
): number {
	for (let index = 0; index < messages.length; index += 1) {
		const message = messages[index];
		if (message.role === "user" && !isToolResultOnlyUserMessage(message)) {
			return index;
		}
	}
	return -1;
}

function collectToolIds(message: MessageWithMetadata): Set<string> {
	const ids = new Set<string>();
	if (!Array.isArray(message.content)) {
		return ids;
	}
	for (const block of message.content) {
		if (block.type === "tool_use") {
			ids.add(block.id);
		} else if (block.type === "tool_result") {
			ids.add(block.tool_use_id);
		}
	}
	return ids;
}

function buildToolPairIndex(
	messages: MessageWithMetadata[],
): Map<string, Set<number>> {
	const index = new Map<string, Set<number>>();
	for (
		let messageIndex = 0;
		messageIndex < messages.length;
		messageIndex += 1
	) {
		for (const id of collectToolIds(messages[messageIndex])) {
			const existing = index.get(id);
			if (existing) {
				existing.add(messageIndex);
			} else {
				index.set(id, new Set([messageIndex]));
			}
		}
	}
	return index;
}

function findProtectedTailStartIndex(messages: MessageWithMetadata[]): number {
	const resolvedToolUseIds = new Set<string>();
	for (const message of messages) {
		if (!Array.isArray(message.content)) {
			continue;
		}
		for (const block of message.content) {
			if (block.type === "tool_result") {
				resolvedToolUseIds.add(block.tool_use_id);
			}
		}
	}
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		const message = messages[index];
		if (!Array.isArray(message.content)) {
			continue;
		}
		if (
			message.content.some(
				(block) =>
					block.type === "tool_use" && !resolvedToolUseIds.has(block.id),
			)
		) {
			return index;
		}
	}
	return messages.length;
}

function collectMessageClosure(
	messages: MessageWithMetadata[],
	startIndex: number,
): Set<number> {
	const pairIndex = buildToolPairIndex(messages);
	const removal = new Set<number>();
	const queue = [startIndex];
	while (queue.length > 0) {
		const index = queue.shift();
		if (index === undefined || removal.has(index)) {
			continue;
		}
		removal.add(index);
		for (const id of collectToolIds(messages[index])) {
			for (const linked of pairIndex.get(id) ?? []) {
				if (!removal.has(linked)) {
					queue.push(linked);
				}
			}
		}
	}
	return removal;
}

function isUnsafeBlock(block: ContentBlock): boolean {
	return block.type === "image" || block.type === "redacted_thinking";
}

function isNestedUnsafeToolResultBlock(
	block: Extract<ToolResultContent["content"], unknown[]>[number],
): boolean {
	return block.type === "image";
}

function shouldDropWholeBlock(
	block: ContentBlock,
	policy: ProjectionPolicy,
	isProtected: boolean,
): boolean {
	if (policy.dropThinkingBlocks && block.type === "thinking") {
		return true;
	}
	return (
		policy.dropUnsafeOutsideLiveTail && !isProtected && isUnsafeBlock(block)
	);
}

function pruneEmptyMessages(
	messages: MessageWithMetadata[],
	originalIndexes: number[],
	actions: BudgetAction[],
	reason: BudgetMutationAction["reason"] = "over_budget",
): { messages: MessageWithMetadata[]; originalIndexes: number[] } {
	const next: MessageWithMetadata[] = [];
	const nextOriginalIndexes: number[] = [];
	for (let index = 0; index < messages.length; index += 1) {
		const message = messages[index];
		if (Array.isArray(message.content) && message.content.length === 0) {
			actions.push({
				kind: "dropped_message",
				path: { messageIndex: originalIndexes[index] },
				reason,
				originalSize: safeJsonSize(message),
				finalSize: 0,
			});
			continue;
		}
		next.push(message);
		nextOriginalIndexes.push(originalIndexes[index]);
	}
	return { messages: next, originalIndexes: nextOriginalIndexes };
}

function dropUnsafeBlocks(
	messages: MessageWithMetadata[],
	originalIndexes: number[],
	actions: BudgetAction[],
	latestTypedUserIndex: number,
	protectedTailStartIndex: number,
	policy: ProjectionPolicy,
): MessageWithMetadata[] {
	return messages.map((message, messageIndex) => {
		if (!Array.isArray(message.content)) {
			return message;
		}
		let changed = false;
		const protectedBlock =
			messageIndex === latestTypedUserIndex ||
			messageIndex >= protectedTailStartIndex;
		const content = message.content.flatMap((block, blockIndex) => {
			if (shouldDropWholeBlock(block, policy, protectedBlock)) {
				changed = true;
				actions.push({
					kind: "dropped_block",
					path: { messageIndex: originalIndexes[messageIndex], blockIndex },
					reason: "unsafe_to_truncate",
					originalSize: safeJsonSize(block),
					finalSize: 0,
				});
				return [];
			}
			if (block.type === "tool_result" && Array.isArray(block.content)) {
				const nestedContent = block.content.filter((nestedBlock) => {
					if (
						policy.dropUnsafeOutsideLiveTail &&
						!protectedBlock &&
						isNestedUnsafeToolResultBlock(nestedBlock)
					) {
						return false;
					}
					return true;
				});
				if (nestedContent.length !== block.content.length) {
					changed = true;
					const nextBlock = { ...block, content: nestedContent };
					actions.push({
						kind: "dropped_block",
						path: { messageIndex: originalIndexes[messageIndex], blockIndex },
						reason: "unsafe_to_truncate",
						originalSize: safeJsonSize(block),
						finalSize: safeJsonSize(nextBlock),
					});
					return [nextBlock];
				}
			}
			return [block];
		});
		return changed ? { ...message, content } : message;
	});
}

function dropThinkingBlocks(
	messages: MessageWithMetadata[],
	originalIndexes: number[],
	actions: BudgetAction[],
): MessageWithMetadata[] {
	return messages.map((message, messageIndex) => {
		if (!Array.isArray(message.content)) {
			return message;
		}
		let changed = false;
		const content = message.content.filter((block, blockIndex) => {
			if (block.type !== "thinking") {
				return true;
			}
			changed = true;
			actions.push({
				kind: "dropped_block",
				path: { messageIndex: originalIndexes[messageIndex], blockIndex },
				reason: "unsafe_to_truncate",
				originalSize: safeJsonSize(block),
				finalSize: 0,
			});
			return false;
		});
		return changed ? { ...message, content } : message;
	});
}

function truncateText(text: string, maxChars: number): string {
	if (maxChars <= 0) {
		return "";
	}
	if (text.length <= maxChars) {
		return text;
	}
	if (maxChars <= 16) {
		return text.slice(0, Math.max(1, maxChars));
	}
	const estimateMarker = `\n...[truncated ${text.length - maxChars} chars]`;
	const keep = Math.max(1, maxChars - estimateMarker.length);
	const marker = `\n...[truncated ${text.length - keep} chars]`;
	return `${text.slice(0, keep)}${marker}`;
}

function truncateToolResultContent(
	content: ToolResultContent["content"],
	maxChars: number,
): ToolResultContent["content"] {
	if (typeof content === "string") {
		return truncateText(content, maxChars);
	}
	let remaining = maxChars;
	return content.map((block) => {
		if (remaining <= 0) {
			if (block.type === "text") {
				return { ...block, text: "" };
			}
			if (block.type === "file") {
				return { ...block, content: "" };
			}
			return block;
		}
		if (block.type === "text") {
			const text = truncateText(block.text, remaining);
			remaining -= text.length;
			return { ...block, text };
		}
		if (block.type === "file") {
			const content = truncateText(block.content, remaining);
			remaining -= content.length;
			return { ...block, content };
		}
		return block;
	});
}

function toolResultTextLength(content: ToolResultContent["content"]): number {
	if (typeof content === "string") {
		return content.length;
	}
	return content.reduce((total, block) => {
		if (block.type === "text") {
			return total + block.text.length;
		}
		if (block.type === "file") {
			return total + block.content.length;
		}
		return total;
	}, 0);
}

function truncateMessageText(
	message: MessageWithMetadata,
	maxChars: number,
): MessageWithMetadata {
	if (typeof message.content === "string") {
		return { ...message, content: truncateText(message.content, maxChars) };
	}
	let remaining = maxChars;
	return {
		...message,
		content: message.content.map((block) => {
			if (remaining <= 0) {
				if (block.type === "text") {
					return { ...block, text: "" };
				}
				if (block.type === "file") {
					return { ...block, content: "" };
				}
				if (block.type === "tool_result") {
					return {
						...block,
						content: truncateToolResultContent(block.content, 0),
					};
				}
				return block;
			}
			if (block.type === "text") {
				const text = truncateText(block.text, remaining);
				remaining -= text.length;
				return { ...block, text };
			}
			if (block.type === "file") {
				const content = truncateText(block.content, remaining);
				remaining -= content.length;
				return { ...block, content };
			}
			if (block.type === "tool_result") {
				const content = truncateToolResultContent(block.content, remaining);
				remaining -= toolResultTextLength(content);
				return { ...block, content };
			}
			return block;
		}),
	};
}

function hasTruncatableText(message: MessageWithMetadata): boolean {
	if (typeof message.content === "string") {
		return message.content.length > 0;
	}
	return message.content.some(
		(block) =>
			block.type === "text" ||
			block.type === "file" ||
			block.type === "tool_result",
	);
}

function removeMessagesAt(
	messages: MessageWithMetadata[],
	originalIndexes: number[],
	removal: Set<number>,
): { messages: MessageWithMetadata[]; originalIndexes: number[] } {
	return {
		messages: messages.filter((_, index) => !removal.has(index)),
		originalIndexes: originalIndexes.filter((_, index) => !removal.has(index)),
	};
}

function closureTouchesProtectedTail(
	closure: Set<number>,
	protectedStartIndex: number,
): boolean {
	if (protectedStartIndex < 0) {
		return false;
	}
	for (const removalIndex of closure) {
		if (removalIndex >= protectedStartIndex) {
			return true;
		}
	}
	return false;
}

function closureTouchesPinnedMessage(
	closure: Set<number>,
	pinnedIndex: number,
): boolean {
	return pinnedIndex >= 0 && closure.has(pinnedIndex);
}

export function buildBudgetProjection(
	options: BudgetProjectionOptions,
): BudgetProjectionResult {
	const actions: BudgetAction[] = [];
	const warnings: BudgetProjectionWarning[] = [];
	const policy = resolveProjectionPolicy(options.policyIntent);
	if (options.targetTokens <= 0) {
		return {
			status: "failed",
			messages: cloneMessages(options.messages),
			actions,
			liveTailHandling: "preserved_out_of_band",
			estimatedTokens: totalTokens(
				options.messages,
				options.estimateMessageTokens,
			),
			warnings: [
				{
					code: "budget_impossible",
					message: "Target budget must be greater than zero.",
				},
			],
		};
	}

	let messages = cloneMessages(options.messages);
	let originalIndexes = messages.map((_, index) => index);
	if (policy.dropThinkingBlocks) {
		const prunedThinking = pruneEmptyMessages(
			dropThinkingBlocks(messages, originalIndexes, actions),
			originalIndexes,
			actions,
			"unsafe_to_truncate",
		);
		messages = prunedThinking.messages;
		originalIndexes = prunedThinking.originalIndexes;
	}
	const latestTypedUserIndex = policy.protectLatestTypedUser
		? findLatestTypedUserMessageIndex(messages)
		: -1;
	const protectedTailStartIndex = policy.protectLiveTailFromDrop
		? findProtectedTailStartIndex(messages)
		: messages.length;
	if (policy.dropUnsafeOutsideLiveTail) {
		const prunedUnsafe = pruneEmptyMessages(
			dropUnsafeBlocks(
				messages,
				originalIndexes,
				actions,
				latestTypedUserIndex,
				protectedTailStartIndex,
				policy,
			),
			originalIndexes,
			actions,
		);
		messages = prunedUnsafe.messages;
		originalIndexes = prunedUnsafe.originalIndexes;
	}
	let estimatedTokens = totalTokens(messages, options.estimateMessageTokens);
	if (estimatedTokens <= options.targetTokens) {
		return {
			status: "ok",
			messages,
			actions,
			liveTailHandling:
				actions.length > 0 ? "included_degraded" : "included_verbatim",
			estimatedTokens,
			warnings,
		};
	}

	for (
		let index = messages.length - 1;
		index >= 0 && estimatedTokens > options.targetTokens;
		index -= 1
	) {
		const latestTypedUserIndex = findLatestTypedUserMessageIndex(messages);
		if (index === latestTypedUserIndex) {
			continue;
		}
		if (
			policy.protectLiveTailFromDrop &&
			index >= findProtectedTailStartIndex(messages)
		) {
			continue;
		}
		if (!hasTruncatableText(messages[index])) {
			continue;
		}
		const originalSize = safeJsonSize(messages[index]);
		const charsPerToken = Math.max(
			1,
			originalSize /
				Math.max(1, options.estimateMessageTokens(messages[index])),
		);
		const targetChars = Math.max(
			16,
			Math.floor(
				(options.targetTokens * charsPerToken) / Math.max(1, messages.length),
			),
		);
		messages[index] = truncateMessageText(messages[index], targetChars);
		actions.push({
			kind: "truncated_text",
			path: { messageIndex: originalIndexes[index] },
			reason: "over_budget",
			originalSize,
			finalSize: safeJsonSize(messages[index]),
		});
		estimatedTokens = totalTokens(messages, options.estimateMessageTokens);
	}

	for (
		let index = 0;
		index < messages.length && estimatedTokens > options.targetTokens;
	) {
		const firstTypedUserIndex = findFirstTypedUserMessageIndex(messages);
		const latestTypedUserIndex = findLatestTypedUserMessageIndex(messages);
		const protectedStartIndex = policy.protectLiveTailFromDrop
			? findProtectedTailStartIndex(messages)
			: messages.length;
		if (index === firstTypedUserIndex || index === latestTypedUserIndex) {
			actions.push({
				kind: "preserved",
				path: { messageIndex: originalIndexes[index] },
				reason: "protected_live_tail",
				originalSize: safeJsonSize(messages[index]),
				finalSize: safeJsonSize(messages[index]),
			});
			index += 1;
			continue;
		}
		const closure = collectMessageClosure(messages, index);
		if (closureTouchesPinnedMessage(closure, firstTypedUserIndex)) {
			index += 1;
			continue;
		}
		if (closureTouchesPinnedMessage(closure, latestTypedUserIndex)) {
			index += 1;
			continue;
		}
		if (closureTouchesProtectedTail(closure, protectedStartIndex)) {
			index += 1;
			continue;
		}
		for (const removalIndex of closure) {
			actions.push({
				kind: "dropped_message",
				path: { messageIndex: originalIndexes[removalIndex] },
				reason:
					closure.size > 1 || collectToolIds(messages[removalIndex]).size > 0
						? "tool_pair_boundary"
						: "over_budget",
				originalSize: safeJsonSize(messages[removalIndex]),
				finalSize: 0,
			});
		}
		const removed = removeMessagesAt(messages, originalIndexes, closure);
		messages = removed.messages;
		originalIndexes = removed.originalIndexes;
		estimatedTokens = totalTokens(messages, options.estimateMessageTokens);
	}

	if (estimatedTokens > options.targetTokens) {
		warnings.push({
			code: "budget_unachievable_with_protections",
			message:
				"Projection could not reach budget without violating protected content.",
		});
		return {
			status: "failed",
			messages,
			actions,
			liveTailHandling: "included_degraded",
			estimatedTokens,
			warnings,
		};
	}

	return {
		status: "ok",
		messages,
		actions,
		liveTailHandling:
			actions.length > 0 ? "included_degraded" : "included_verbatim",
		estimatedTokens,
		warnings,
	};
}

import type { ContentBlock, MessageWithMetadata } from "@cline/shared";

export type BudgetPolicyIntent =
	| "agentic_summary"
	| "basic_compaction_projection"
	| "normal_provider_request";

export type BudgetActionKind =
	| "truncated_text"
	| "dropped_block"
	| "dropped_message"
	| "preserved";

export type BudgetActionReason =
	| "over_budget"
	| "unsafe_to_truncate"
	| "tool_pair_boundary"
	| "protected_live_tail";

export type LiveTailHandling =
	| "included_verbatim"
	| "included_degraded"
	| "summarized_as_context"
	| "omitted_with_warning"
	| "preserved_out_of_band";

export type BlockBudgetClass =
	| "text"
	| "thinking"
	| "tool_use"
	| "tool_result"
	| "unsafe_binary"
	| "unsafe_encrypted"
	| "opaque";

export interface BudgetPath {
	messageIndex: number;
	blockIndex?: number;
}

interface BaseBudgetAction {
	path: BudgetPath;
	originalSize: number;
	finalSize: number;
}

export type BudgetMutationAction =
	| (BaseBudgetAction & {
			kind: "truncated_text";
			reason: Extract<BudgetActionReason, "over_budget">;
	  })
	| (BaseBudgetAction & {
			kind: "dropped_block";
			path: Required<BudgetPath>;
			reason: Exclude<BudgetActionReason, "protected_live_tail">;
	  })
	| (BaseBudgetAction & {
			kind: "dropped_message";
			reason: Exclude<BudgetActionReason, "protected_live_tail">;
	  });

export interface BudgetPreservedAction extends BaseBudgetAction {
	kind: "preserved";
	reason: Extract<
		BudgetActionReason,
		"protected_live_tail" | "tool_pair_boundary"
	>;
}

export type BudgetAction = BudgetMutationAction | BudgetPreservedAction;

export type BudgetProjectionWarningCode =
	| "budget_impossible"
	| "budget_unachievable_with_protections";

export interface BudgetProjectionWarning {
	code: BudgetProjectionWarningCode;
	message: string;
	path?: BudgetPath;
}

export interface BudgetProjectionOptions {
	messages: MessageWithMetadata[];
	targetTokens: number;
	policyIntent: BudgetPolicyIntent;
	estimateMessageTokens: (message: MessageWithMetadata) => number;
}

export interface BudgetProjectionResult {
	status: "ok" | "failed";
	messages: MessageWithMetadata[];
	actions: BudgetAction[];
	liveTailHandling: LiveTailHandling;
	estimatedTokens: number;
	warnings: BudgetProjectionWarning[];
}

export interface ContentBlockBudgetClassification {
	block: ContentBlock;
	budgetClass: BlockBudgetClass;
	canStringTruncate: boolean;
	canDropWholeBlock: boolean;
}

import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const SCRIPT_PATH = fileURLToPath(
	new URL("../../../scripts/compact-session.ts", import.meta.url),
);
const FIXTURE_DIRECTORY = fileURLToPath(
	new URL("../../../fixtures/session", import.meta.url),
);

function runScript(strategy: "agentic" | "basic") {
	return spawnSync(
		"bun",
		[
			"--conditions=development",
			"run",
			SCRIPT_PATH,
			FIXTURE_DIRECTORY,
			"--strategy",
			strategy,
			"--provider",
			"anthropic",
			"--model",
			"claude-sonnet-4-6",
		],
		{
			encoding: "utf8",
			env: { ...process.env, ANTHROPIC_API_KEY: "" },
		},
	);
}

describe("test:compaction script", () => {
	it("allows provider metadata for basic compaction without an API key", () => {
		const result = runScript("basic");

		expect(result.status, result.stderr).toBe(0);
		expect(result.stderr).toContain("Running basic compaction");
		expect(result.stderr).not.toContain("Missing API key");
	});

	it("still requires an API key for agentic compaction", () => {
		const result = runScript("agentic");

		expect(result.status).not.toBe(0);
		expect(result.stderr).toContain("Missing API key in ANTHROPIC_API_KEY");
	});
});

import type { ModelInfo, ToolResultContent } from "@cline/llms";
import {
	CHARS_PER_TOKEN,
	estimateTokens,
	type MessageWithMetadata,
} from "@cline/shared";

export { CHARS_PER_TOKEN, estimateTokens };

import type { CoreCompactionSummarizerConfig } from "../../types/config";
import type { ProviderConfig } from "../../types/provider-settings";

export const DEFAULT_MAX_INPUT_TOKENS = 128_000;
/** Estimate the usable input share when only a context window is reported. */
export const CONTEXT_WINDOW_INPUT_RATIO = 0.9;
/** Compact once the transcript consumes this share of the usable input budget. */
export const COMPACTION_TRIGGER_RATIO = 0.9;
export const DEFAULT_TARGET_RATIO = 0.7;
export const DEFAULT_PRESERVE_RECENT_TOKENS = 20_000;
export const DEFAULT_SUMMARY_MAX_OUTPUT_TOKENS = 1_024;
export const TOOL_RESULT_CHAR_LIMIT = 2_000;
export const FILE_CONTENT_CHAR_LIMIT = 2_000;
export const MIN_TRUNCATED_MESSAGE_TOKENS = 8;

export interface FileOperationSummary {
	readFiles: string[];
	modifiedFiles: string[];
}

export interface CompactionSummaryMetadata {
	kind: "compaction_summary";
	summary: string;
	details: FileOperationSummary;
	tokensBefore: number;
	generatedAt: number;
}

export type EstimateMessageTokens = (message: MessageWithMetadata) => number;

function isPositiveFiniteNumber(value: unknown): value is number {
	return typeof value === "number" && Number.isFinite(value) && value > 0;
}

/**
 * Resolve the model's usable prompt budget. A reported input limit is
 * authoritative but cannot exceed the context window. When the model only
 * reports a context window, retain a conservative margin for request overhead.
 */
export function resolveEffectiveMaxInputTokens(
	input: Pick<ModelInfo, "maxInputTokens" | "contextWindow">,
): number | undefined {
	const contextWindow = isPositiveFiniteNumber(input.contextWindow)
		? input.contextWindow
		: undefined;
	const maxInputTokens = isPositiveFiniteNumber(input.maxInputTokens)
		? input.maxInputTokens
		: undefined;

	if (maxInputTokens !== undefined) {
		return contextWindow === undefined
			? maxInputTokens
			: Math.min(maxInputTokens, contextWindow);
	}

	return contextWindow === undefined
		? undefined
		: contextWindow * CONTEXT_WINDOW_INPUT_RATIO;
}

export function truncateText(text: string, limit: number): string {
	if (text.length <= limit) {
		return text;
	}
	return `${text.slice(0, limit)}\n...[truncated ${text.length - limit} chars]`;
}

export function flattenToolResultContent(
	content: ToolResultContent["content"],
): string {
	const truncated = truncateToolResultContentForCompaction(content);
	if (typeof truncated === "string") {
		return truncated;
	}
	return truncated
		.map((block) => {
			switch (block.type) {
				case "text":
					return block.text;
				case "file":
					return `<file path="${block.path}">\n${block.content}\n</file>`;
				case "image":
					return `[image:${block.mediaType}]`;
				default:
					return "";
			}
		})
		.join("\n");
}

export function truncateToolResultContentForCompaction(
	content: ToolResultContent["content"],
): ToolResultContent["content"] {
	if (typeof content === "string") {
		return truncateText(content, TOOL_RESULT_CHAR_LIMIT);
	}
	return content.map((block) => {
		switch (block.type) {
			case "text":
				return {
					...block,
					text: truncateText(block.text, TOOL_RESULT_CHAR_LIMIT),
				};
			case "file":
				return {
					...block,
					content: truncateText(block.content, FILE_CONTENT_CHAR_LIMIT),
				};
			case "image":
				return block;
			default:
				return block;
		}
	});
}

export function formatToolInput(input: Record<string, unknown>): string {
	return Object.entries(input)
		.map(([key, value]) => `${key}=${JSON.stringify(value)}`)
		.join(", ");
}

export function serializeMessage(message: MessageWithMetadata): string {
	if (typeof message.content === "string") {
		return `[${message.role === "user" ? "User" : "Bot"}]: ${message.content}`;
	}
	const lines: string[] = [];
	for (const block of message.content) {
		switch (block.type) {
			case "text":
				lines.push(
					`[${message.role === "user" ? "User" : "Bot"}]: ${block.text}`,
				);
				break;
			case "thinking":
				lines.push(`[Bot thinking]: ${truncateText(block.thinking, 2_000)}`);
				break;
			case "redacted_thinking":
				lines.push("[Bot thinking]: [redacted]");
				break;
			case "tool_use":
				lines.push(
					`[Bot tool calls]: ${block.name}(${formatToolInput(block.input)})`,
				);
				break;
			case "tool_result":
				lines.push(`[Tool result]: ${flattenToolResultContent(block.content)}`);
				break;
			case "file":
				lines.push(
					`[${message.role === "user" ? "User" : "Bot"} file ${block.path}]: ${truncateText(block.content, FILE_CONTENT_CHAR_LIMIT)}`,
				);
				break;
			case "image":
				lines.push(
					`[${message.role === "user" ? "User" : "Bot"} image]: ${block.mediaType}`,
				);
				break;
		}
	}
	return lines.join("\n");
}

export function serializeConversation(messages: MessageWithMetadata[]): string {
	return messages.map(serializeMessage).join("\n\n").trim();
}

export function createTokenEstimator(): EstimateMessageTokens {
	const cache = new WeakMap<object, number>();
	return (message) => {
		const ref = message as unknown as object;
		const cached = cache.get(ref);
		if (typeof cached === "number") {
			return cached;
		}
		let serialized: string;
		try {
			serialized = JSON.stringify(message);
		} catch {
			serialized = serializeMessage(message);
		}
		const value = estimateTokens(serialized.length);
		cache.set(ref, value);
		return value;
	};
}

export function isCompactionSummaryMessage(
	message: MessageWithMetadata,
): boolean {
	return (
		(message.metadata as { kind?: string } | undefined)?.kind ===
		"compaction_summary"
	);
}

export function getCompactionSummaryMetadata(
	message: MessageWithMetadata,
): CompactionSummaryMetadata | undefined {
	if (!isCompactionSummaryMessage(message)) {
		return undefined;
	}
	const metadata = message.metadata as Record<string, unknown> | undefined;
	if (!metadata) {
		return undefined;
	}
	const details = metadata.details as Record<string, unknown> | undefined;
	return {
		kind: "compaction_summary",
		summary: String(metadata.summary ?? ""),
		details: {
			readFiles: Array.isArray(details?.readFiles)
				? details.readFiles
						.filter((value): value is string => typeof value === "string")
						.map((value) => value.trim())
						.filter((value) => value.length > 0)
				: [],
			modifiedFiles: Array.isArray(details?.modifiedFiles)
				? details.modifiedFiles
						.filter((value): value is string => typeof value === "string")
						.map((value) => value.trim())
						.filter((value) => value.length > 0)
				: [],
		},
		tokensBefore: Number(metadata.tokensBefore ?? 0),
		generatedAt: Number(metadata.generatedAt ?? 0),
	};
}

export function isToolResultOnlyUserMessage(
	message: MessageWithMetadata,
): boolean {
	if (message.role !== "user" || !Array.isArray(message.content)) {
		return false;
	}
	return (
		message.content.length > 0 &&
		message.content.every((block) => block.type === "tool_result")
	);
}

export function isTurnStartMessage(message: MessageWithMetadata): boolean {
	return (
		message.role === "user" &&
		!isToolResultOnlyUserMessage(message) &&
		!isCompactionSummaryMessage(message)
	);
}

export function findFirstUserMessageIndex(
	messages: MessageWithMetadata[],
): number {
	for (let index = 0; index < messages.length; index += 1) {
		if (isTurnStartMessage(messages[index])) {
			return index;
		}
	}
	return -1;
}

export function findLastTurnStartIndex(
	messages: MessageWithMetadata[],
): number {
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		if (isTurnStartMessage(messages[index])) {
			return index;
		}
	}
	return 0;
}

export function findLastAssistantIndex(
	messages: MessageWithMetadata[],
): number {
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		if (messages[index].role === "assistant") {
			return index;
		}
	}
	return -1;
}

export function findLatestSummaryIndex(
	messages: MessageWithMetadata[],
): number {
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		if (isCompactionSummaryMessage(messages[index])) {
			return index;
		}
	}
	return -1;
}

/**
 * A cut boundary is safe when starting the preserved tail there cannot
 * orphan half of a tool_use/tool_result pair. Typed user turns qualify,
 * and so do assistant messages: an assistant's tool_use keeps its results
 * in the user message that follows it, so both halves stay on the same
 * side of the cut. A tool_result-only user message is never safe — its
 * matching tool_use sits in the preceding assistant message and would be
 * folded into the summary, leaving an orphaned tool_result the provider
 * rejects.
 */
function isSafeCutBoundary(message: MessageWithMetadata): boolean {
	return message.role === "assistant" || isTurnStartMessage(message);
}

export function findCutIndex(
	messages: MessageWithMetadata[],
	preserveRecentTokens: number,
	estimateMessageTokens: EstimateMessageTokens,
): number {
	let total = 0;
	let candidate = messages.length;
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		total += estimateMessageTokens(messages[index]);
		candidate = index;
		if (total >= preserveRecentTokens) {
			break;
		}
	}

	if (candidate <= 0) {
		return 0;
	}

	// Never summarize away the latest typed user prompt: when one exists
	// past index 0, the cut stays at or before it so that whole turn
	// survives verbatim. Transcripts without a later typed turn (a single
	// task followed by one long tool loop, or a projection that starts
	// with a compaction summary) still cut at the token-budget candidate.
	const lastTurnStartIndex = findLastTurnStartIndex(messages);
	let cut =
		lastTurnStartIndex > 0
			? Math.min(candidate, lastTurnStartIndex)
			: candidate;
	while (cut > 0 && !isSafeCutBoundary(messages[cut])) {
		cut -= 1;
	}
	return cut;
}

export function collectPaths(value: unknown): string[] {
	if (typeof value === "string" && value.trim().length > 0) {
		return [value];
	}
	if (Array.isArray(value)) {
		return value.flatMap((item) => collectPaths(item));
	}
	if (value && typeof value === "object") {
		const record = value as Record<string, unknown>;
		const paths: string[] = [];
		for (const key of [
			"path",
			"file_path",
			"target_file",
			"new_file_path",
			"old_file_path",
		]) {
			paths.push(...collectPaths(record[key]));
		}
		if (Array.isArray(record.files)) {
			for (const item of record.files) {
				if (item && typeof item === "object") {
					paths.push(...collectPaths((item as Record<string, unknown>).path));
				}
			}
		}
		if (Array.isArray(record.file_paths)) {
			paths.push(...collectPaths(record.file_paths));
		}
		return paths;
	}
	return [];
}

export function mergeUnique(base: string[], next: Iterable<string>): string[] {
	const seen = new Set(base);
	for (const value of next) {
		const trimmed = value.trim();
		if (!trimmed) {
			continue;
		}
		seen.add(trimmed);
	}
	return [...seen].sort((a, b) => a.localeCompare(b));
}

export function extractFileOps(
	messages: MessageWithMetadata[],
): FileOperationSummary {
	let readFiles: string[] = [];
	let modifiedFiles: string[] = [];
	for (const message of messages) {
		const summaryMetadata = getCompactionSummaryMetadata(message);
		if (summaryMetadata) {
			readFiles = mergeUnique(readFiles, summaryMetadata.details.readFiles);
			modifiedFiles = mergeUnique(
				modifiedFiles,
				summaryMetadata.details.modifiedFiles,
			);
			continue;
		}
		if (!Array.isArray(message.content)) {
			continue;
		}
		for (const block of message.content) {
			if (block.type === "file") {
				readFiles = mergeUnique(readFiles, [block.path]);
				continue;
			}
			if (block.type !== "tool_use") {
				continue;
			}
			const paths = collectPaths(block.input);
			if (block.name === "read_files") {
				readFiles = mergeUnique(readFiles, paths);
				continue;
			}
			if (block.name === "editor" || block.name === "apply_patch") {
				modifiedFiles = mergeUnique(modifiedFiles, paths);
			}
		}
	}
	return { readFiles, modifiedFiles };
}

/** Commands longer than this are truncated in dropped-work summaries. */
export const COMMAND_SUMMARY_CHAR_LIMIT = 100;

/**
 * Compact record of the tool work performed inside a span of dropped
 * messages: which files were read and edited (with line ranges when
 * known) and which commands ran.
 */
export interface ToolActivitySummary {
	readFiles: string[];
	editedFiles: string[];
	commands: string[];
}

export function hasToolActivity(summary: ToolActivitySummary): boolean {
	return (
		summary.readFiles.length > 0 ||
		summary.editedFiles.length > 0 ||
		summary.commands.length > 0
	);
}

function pushUniqueEntry(list: string[], value: string): void {
	const trimmed = value.trim();
	if (trimmed && !list.includes(trimmed)) {
		list.push(trimmed);
	}
}

function truncateCommandForSummary(command: string): string {
	if (command.length <= COMMAND_SUMMARY_CHAR_LIMIT) {
		return command;
	}
	return `${command.slice(0, COMMAND_SUMMARY_CHAR_LIMIT)}...`;
}

function formatReadFileEntry(
	record: Record<string, unknown>,
): string | undefined {
	const path = typeof record.path === "string" ? record.path.trim() : "";
	if (!path) {
		return undefined;
	}
	const start = record.start_line;
	const end = record.end_line;
	if (typeof start === "number" && typeof end === "number") {
		return `${path}:${start}-${end}`;
	}
	return path;
}

/**
 * Pull the edited line range out of an editor tool result. Editor results
 * embed a numbered diff (`-467: ...` / `+467: ...`), usually inside a
 * JSON-encoded payload's `result` field; the range is the min/max line
 * number seen. Returns undefined when no diff line numbers are found.
 */
function extractDiffLineRange(
	content: ToolResultContent["content"],
): { start: number; end: number } | undefined {
	let text =
		typeof content === "string"
			? content
			: content
					.map((block) =>
						block.type === "text"
							? block.text
							: block.type === "file"
								? block.content
								: "",
					)
					.join("\n");
	try {
		const parsed = JSON.parse(text) as { result?: unknown };
		if (parsed && typeof parsed.result === "string") {
			text = parsed.result;
		}
	} catch {
		// Not JSON-encoded; scan the raw text.
	}
	let start = Number.POSITIVE_INFINITY;
	let end = Number.NEGATIVE_INFINITY;
	for (const match of text.matchAll(/(?:^|\n|\\n)[-+](\d+): /g)) {
		const line = Number(match[1]);
		if (!Number.isFinite(line)) {
			continue;
		}
		start = Math.min(start, line);
		end = Math.max(end, line);
	}
	return start <= end ? { start, end } : undefined;
}

/**
 * Summarize the tool work inside a span of messages that compaction is
 * dropping. Read ranges come from read_files inputs; edited ranges come
 * from the numbered diff in the matching editor result when present.
 */
export function summarizeToolActivity(
	messages: MessageWithMetadata[],
): ToolActivitySummary {
	const readFiles: string[] = [];
	const editedFiles: string[] = [];
	const commands: string[] = [];
	const editorPathsByToolUseId = new Map<string, string>();
	for (const message of messages) {
		if (!Array.isArray(message.content)) {
			continue;
		}
		for (const block of message.content) {
			if (block.type === "tool_use") {
				const input = (block.input ?? {}) as Record<string, unknown>;
				if (block.name === "read_files") {
					if (Array.isArray(input.files)) {
						for (const file of input.files) {
							if (file && typeof file === "object") {
								const entry = formatReadFileEntry(
									file as Record<string, unknown>,
								);
								if (entry) {
									pushUniqueEntry(readFiles, entry);
								}
							}
						}
					} else {
						for (const path of collectPaths(input)) {
							pushUniqueEntry(readFiles, path);
						}
					}
					continue;
				}
				if (block.name === "editor" || block.name === "apply_patch") {
					const path = collectPaths(input)[0];
					if (path) {
						editorPathsByToolUseId.set(block.id, path);
					}
					continue;
				}
				if (block.name === "run_commands") {
					const commandList = Array.isArray(input.commands)
						? input.commands
						: [];
					for (const command of commandList) {
						if (typeof command === "string" && command.trim()) {
							pushUniqueEntry(
								commands,
								truncateCommandForSummary(command.trim()),
							);
						}
					}
				}
				continue;
			}
			if (block.type === "tool_result") {
				const path = editorPathsByToolUseId.get(block.tool_use_id);
				if (!path) {
					continue;
				}
				const range = extractDiffLineRange(block.content);
				pushUniqueEntry(
					editedFiles,
					range ? `${path}:${range.start}-${range.end}` : path,
				);
				editorPathsByToolUseId.delete(block.tool_use_id);
			}
		}
	}
	// Editor calls whose results fell outside the span still count as edits.
	for (const path of editorPathsByToolUseId.values()) {
		pushUniqueEntry(editedFiles, path);
	}
	return { readFiles, editedFiles, commands };
}

export function formatToolActivitySummary(
	summary: ToolActivitySummary,
): string {
	return [
		`Files read:\n${summary.readFiles.join("\n")}`,
		`Files edited:\n${summary.editedFiles.join("\n")}`,
		`Commands ran:\n${summary.commands.join("\n")}`,
	].join("\n\n");
}

export function renderFilesSection(fileOps: FileOperationSummary): string {
	const readLines =
		fileOps.readFiles.length > 0
			? fileOps.readFiles.map((path) => `- ${path}`).join("\n")
			: "- none";
	const modifiedLines =
		fileOps.modifiedFiles.length > 0
			? fileOps.modifiedFiles.map((path) => `- ${path}`).join("\n")
			: "- none";
	return `## Files\nRead:\n${readLines}\nModified:\n${modifiedLines}`;
}

export function ensureFilesSection(
	summary: string,
	fileOps: FileOperationSummary,
): string {
	if (/^## Files$/im.test(summary)) {
		return summary.trim();
	}
	return `${summary.trim()}\n\n${renderFilesSection(fileOps)}`.trim();
}

export function buildSummaryRequest(options: {
	previousSummary?: string;
	conversationText: string;
	fileOps: FileOperationSummary;
}): string {
	const parts: string[] = [
		`Summarize this session for continuation. Be concise and factual.

## Goal
One sentence: what is being built or fixed.

## State
- Done: completed steps
- In Progress: current work
- Blocked: blockers or open questions

## Highlights
Key technical choices or notable findings (omit if none).

## Next
Immediate next steps.

## Files
Read: ${options.fileOps.readFiles.join(", ") || "none"}
Edited: ${options.fileOps.modifiedFiles.join(", ") || "none"}`,
	];

	if (options.previousSummary?.trim()) {
		parts.push(`Previous summary:\n${options.previousSummary.trim()}`);
	}

	parts.push(`Conversation:\n${options.conversationText || "(empty)"}`);

	return parts.join("\n\n");
}

export function resolveSummarizerConfig(options: {
	activeProviderConfig: ProviderConfig;
	summarizer?: CoreCompactionSummarizerConfig;
}): ProviderConfig {
	const summarizer = options.summarizer;
	const withSummarizerDefaults = (config: ProviderConfig): ProviderConfig => {
		if (config.providerId === "openai-codex") {
			const { maxOutputTokens: _maxOutputTokens, ...rest } = config;
			return {
				...rest,
				thinking: false,
			};
		}
		return {
			...config,
			maxOutputTokens:
				config.maxOutputTokens ?? DEFAULT_SUMMARY_MAX_OUTPUT_TOKENS,
			thinking: false,
		};
	};
	if (!summarizer) {
		return withSummarizerDefaults(options.activeProviderConfig);
	}
	const baseProviderConfig =
		summarizer.providerConfig?.providerId === summarizer.providerId
			? summarizer.providerConfig
			: undefined;
	return withSummarizerDefaults({
		...(baseProviderConfig ?? {}),
		providerId: summarizer.providerId,
		modelId: summarizer.modelId,
		apiKey: summarizer.apiKey ?? baseProviderConfig?.apiKey,
		baseUrl: summarizer.baseUrl ?? baseProviderConfig?.baseUrl,
		headers: summarizer.headers ?? baseProviderConfig?.headers,
		modelInfo: summarizer.modelInfo ?? baseProviderConfig?.modelInfo,
		knownModels: summarizer.knownModels ?? baseProviderConfig?.knownModels,
		maxOutputTokens:
			summarizer.maxOutputTokens ?? DEFAULT_SUMMARY_MAX_OUTPUT_TOKENS,
	});
}

