describe("updateMcpSettingsFile (async acquisition)", () => {
	const tempRoots: string[] = [];

	afterEach(async () => {
		await Promise.all(
			tempRoots.map((directory) =>
				rm(directory, { recursive: true, force: true }),
			),
		);
		tempRoots.length = 0;
	});

	async function makeSettingsFile(): Promise<string> {
		const tempRoot = await mkdtemp(
			join(tmpdir(), "core-mcp-config-loader-async-"),
		);
		tempRoots.push(tempRoot);
		const filePath = join(tempRoot, "cline_mcp_settings.json");
		await writeFile(
			filePath,
			JSON.stringify({ mcpServers: {} }, null, 2),
			"utf8",
		);
		return filePath;
	}

	it("runs the mutator and releases the lock on the uncontended path", async () => {
		const filePath = await makeSettingsFile();
		let mutatorRan = false;

		const result = await updateMcpSettingsFile(filePath, (settings) => {
			mutatorRan = true;
			settings.mcpServers = {
				alpha: { transport: { type: "stdio", command: "node" } },
			};
			return "ok";
		});

		// The mutator (a synchronous, pure function) ran, the write landed, and the
		// lock directory is gone — i.e. the lock is never left held after resolution.
		// (That the lock is never held *across* an await is covered by the contended
		// test below, which asserts serialization without any Atomics.wait.)
		expect(mutatorRan).toBe(true);
		expect(result).toBe("ok");
		expect(existsSync(`${filePath}.lock`)).toBe(false);
		const written = JSON.parse(await readFile(filePath, "utf8"));
		expect(written.mcpServers.alpha.transport.command).toBe("node");
	});

	it("serializes contended async updates without losing a write and never blocks the event loop", async () => {
		const filePath = await makeSettingsFile();
		const waitSpy = vi.spyOn(Atomics, "wait");
		try {
			// Pre-place a held lock owned by a fictional live process so the first
			// real update has to wait (and therefore exercise the await-delay path).
			const lockDir = `${filePath}.lock`;
			mkdirSync(lockDir);
			writeFileSync(join(lockDir, "owner.holder"), "holder");

			const linear = updateMcpSettingsFile(
				filePath,
				(settings) => {
					const servers = settings.mcpServers as Record<
						string,
						Record<string, unknown>
					>;
					servers.linear.oauth = { tokens: { access_token: "linear-token" } };
				},
				{ timeoutMs: 5_000 },
			).catch(() => undefined);
			const github = updateMcpSettingsFile(
				filePath,
				(settings) => {
					const servers = settings.mcpServers as Record<
						string,
						Record<string, unknown>
					>;
					servers.github.oauth = { tokens: { access_token: "github-token" } };
				},
				{ timeoutMs: 5_000 },
			).catch(() => undefined);

			// Seed the two servers while the contender(s) are parked on the lock,
			// then release the held lock so the waiters can proceed.
			await writeFile(
				filePath,
				JSON.stringify(
					{
						mcpServers: {
							linear: {
								transport: {
									type: "streamableHttp",
									url: "https://linear.example.com",
								},
							},
							github: {
								transport: {
									type: "streamableHttp",
									url: "https://github.example.com",
								},
							},
						},
					},
					null,
					2,
				),
				"utf8",
			);
			unlinkSync(join(lockDir, "owner.holder"));
			rmdirSync(lockDir);

			await Promise.all([linear, github]);

			const written = JSON.parse(await readFile(filePath, "utf8"));
			expect(written.mcpServers.linear.oauth?.tokens?.access_token).toBe(
				"linear-token",
			);
			expect(written.mcpServers.github.oauth?.tokens?.access_token).toBe(
				"github-token",
			);
			// Lock released after each critical section.
			expect(existsSync(lockDir)).toBe(false);
			// The whole point of the async path: it must never freeze the loop.
			expect(waitSpy).not.toHaveBeenCalled();
		} finally {
			waitSpy.mockRestore();
		}
	});

	it("creates a missing settings file inside the lock", async () => {
		const tempRoot = await mkdtemp(
			join(tmpdir(), "core-mcp-config-loader-async-"),
		);
		tempRoots.push(tempRoot);
		const filePath = join(tempRoot, "cline_mcp_settings.json");

		await updateMcpSettingsFile(filePath, (settings) => {
			const servers = settings.mcpServers as Record<string, unknown>;
			servers.docs = { transport: { type: "stdio", command: "node" } };
		});

		const written = JSON.parse(await readFile(filePath, "utf8"));
		expect(Object.keys(written.mcpServers)).toEqual(["docs"]);
	});

	it("reclaims a stale lock directory on the async path", async () => {
		const filePath = await makeSettingsFile();
		const lockDir = `${filePath}.lock`;
		mkdirSync(lockDir);
		writeFileSync(join(lockDir, "owner.dead"), "dead-owner");
		const stale = new Date(Date.now() - 60_000);
		const { utimesSync } = await import("node:fs");
		utimesSync(lockDir, stale, stale);

		let ran = false;
		await updateMcpSettingsFile(filePath, () => {
			ran = true;
		});

		expect(ran).toBe(true);
		expect(existsSync(lockDir)).toBe(false);
	});

	it("fails fast on a reentrant settings update instead of deadlocking the loop", async () => {
		const filePath = await makeSettingsFile();

		await expect(
			updateMcpSettingsFile(filePath, () => {
				// A nested write on the same file would deadlock against the lock we
				// already hold; the shared reentrancy guard must reject it instead.
				updateMcpSettingsFileSync(filePath, () => {});
			}),
		).rejects.toThrow(/Reentrant MCP settings update/);

		// Guard ran inside the mutator, but the outer lock is still cleaned up.
		expect(existsSync(`${filePath}.lock`)).toBe(false);
	});
});

import {
	existsSync,
	mkdirSync,
	readFileSync,
	renameSync,
	rmdirSync,
	rmSync,
	statSync,
	unlinkSync,
	writeFileSync,
} from "node:fs";
import { randomUUID } from "node:crypto";
import { dirname, join } from "node:path";
import { setTimeout as delay } from "node:timers/promises";
import type { BasicLogger } from "@cline/shared";
import { resolveMcpSettingsPath } from "@cline/shared/storage";
import { z } from "zod";
import type {
	McpManager,
	McpServerOAuthState,
	McpServerOAuthStatus,
	McpServerRegistration,
} from "./types";

const stringRecordSchema = z.record(z.string(), z.string());
const metadataSchema = z.record(z.string(), z.unknown());
const oauthStateSchema = z
	.object({
		clientInformation: z.record(z.string(), z.unknown()).optional(),
		tokens: z.record(z.string(), z.unknown()).optional(),
		codeVerifier: z.string().optional(),
		discoveryState: z.record(z.string(), z.unknown()).optional(),
		redirectUrl: z.string().url().optional(),
		lastError: z.string().optional(),
		lastAuthenticatedAt: z.number().int().positive().optional(),
	})
	.strip();

const stdioTransportSchema = z.object({
	type: z.literal("stdio"),
	command: z.string().min(1),
	args: z.array(z.string()).optional(),
	cwd: z.string().min(1).optional(),
	env: stringRecordSchema.optional(),
});

const sseTransportSchema = z.object({
	type: z.literal("sse"),
	url: z.string().url(),
	headers: stringRecordSchema.optional(),
});

const streamableHttpTransportSchema = z.object({
	type: z.literal("streamableHttp"),
	url: z.string().url(),
	headers: stringRecordSchema.optional(),
});

const mcpTransportSchema = z.discriminatedUnion("type", [
	stdioTransportSchema,
	sseTransportSchema,
	streamableHttpTransportSchema,
]);

const nestedRegistrationBodySchema = z.object({
	transport: mcpTransportSchema,
	disabled: z.boolean().optional(),
	metadata: metadataSchema.optional(),
	oauth: oauthStateSchema.optional(),
});

const legacyTransportTypeSchema = z
	.enum(["stdio", "sse", "http", "streamableHttp"])
	.optional();

const legacyRegistrationBaseSchema = z.object({
	type: z.enum(["stdio", "sse", "streamableHttp"]).optional(),
	transportType: legacyTransportTypeSchema,
	disabled: z.boolean().optional(),
	metadata: metadataSchema.optional(),
	oauth: oauthStateSchema.optional(),
});

function mapLegacyTransportType(
	transportType: z.infer<typeof legacyTransportTypeSchema>,
): "stdio" | "sse" | "streamableHttp" | undefined {
	if (!transportType) {
		return undefined;
	}
	if (transportType === "http") {
		return "streamableHttp";
	}
	return transportType;
}

const legacyStdioRegistrationSchema = legacyRegistrationBaseSchema
	.extend({
		command: z.string().min(1),
		args: z.array(z.string()).optional(),
		cwd: z.string().min(1).optional(),
		env: stringRecordSchema.optional(),
	})
	.superRefine((value, ctx) => {
		const resolvedType =
			value.type ?? mapLegacyTransportType(value.transportType);
		if (resolvedType && resolvedType !== "stdio") {
			ctx.addIssue({
				code: z.ZodIssueCode.custom,
				message: 'Expected type "stdio" for command-based MCP server',
				path: ["type"],
			});
		}
	})
	.transform((value) => ({
		transport: {
			type: "stdio" as const,
			command: value.command,
			args: value.args,
			cwd: value.cwd,
			env: value.env,
		},
		disabled: value.disabled,
		metadata: value.metadata,
		oauth: value.oauth,
	}));

const legacyUrlRegistrationSchema = legacyRegistrationBaseSchema
	.extend({
		url: z.string().url(),
		headers: stringRecordSchema.optional(),
	})
	.superRefine((value, ctx) => {
		const resolvedType =
			value.type ?? mapLegacyTransportType(value.transportType) ?? "sse";
		if (resolvedType !== "sse" && resolvedType !== "streamableHttp") {
			ctx.addIssue({
				code: z.ZodIssueCode.custom,
				message:
					'Expected type "sse" or "streamableHttp" for URL-based MCP server',
				path: ["type"],
			});
		}
	})
	.transform((value) => {
		const resolvedType =
			value.type ?? mapLegacyTransportType(value.transportType) ?? "sse";
		if (resolvedType === "streamableHttp") {
			return {
				transport: {
					type: "streamableHttp" as const,
					url: value.url,
					headers: value.headers,
				},
				disabled: value.disabled,
				metadata: value.metadata,
				oauth: value.oauth,
			};
		}
		return {
			transport: {
				type: "sse" as const,
				url: value.url,
				headers: value.headers,
			},
			disabled: value.disabled,
			metadata: value.metadata,
			oauth: value.oauth,
		};
	});

const mcpRegistrationBodySchema = z.union([
	nestedRegistrationBodySchema,
	legacyStdioRegistrationSchema,
	legacyUrlRegistrationSchema,
]);

const mcpSettingsSchema = z
	.object({
		mcpServers: z.record(z.string(), mcpRegistrationBodySchema),
	})
	.passthrough();

export interface McpSettingsFile {
	mcpServers: Record<string, Omit<McpServerRegistration, "name">>;
}

