import type {
	McpConnectionStatus,
	McpManager,
	McpManagerOptions,
	McpServerClient,
	McpServerRegistration,
	McpServerSnapshot,
	McpToolCallRequest,
	McpToolCallResult,
	McpToolDescriptor,
} from "./types";

const DEFAULT_TOOLS_CACHE_TTL_MS = 5000;

type ManagedServerState = {
	registration: McpServerRegistration;
	client?: McpServerClient;
	status: McpConnectionStatus;
	lastError?: string;
	updatedAt: number;
	toolCache?: readonly McpToolDescriptor[];
	toolCacheUpdatedAt?: number;
};

function nowMs(): number {
	return Date.now();
}

function cloneTools(
	tools: readonly McpToolDescriptor[],
): readonly McpToolDescriptor[] {
	return tools.map((tool) => ({
		name: tool.name,
		description: tool.description,
		inputSchema: tool.inputSchema,
	}));
}

export class InMemoryMcpManager implements McpManager {
	private readonly toolsCacheTtlMs: number;
	private readonly clientFactory: McpManagerOptions["clientFactory"];
	private readonly servers = new Map<string, ManagedServerState>();
	private readonly operationLocks = new Map<string, Promise<void>>();

	constructor(options: McpManagerOptions) {
		this.clientFactory = options.clientFactory;
		this.toolsCacheTtlMs =
			options.toolsCacheTtlMs ?? DEFAULT_TOOLS_CACHE_TTL_MS;
	}

	async registerServer(registration: McpServerRegistration): Promise<void> {
		await this.runExclusive(registration.name, async () => {
			const existing = this.servers.get(registration.name);
			if (!existing) {
				this.servers.set(registration.name, {
					registration: { ...registration },
					status: "disconnected",
					updatedAt: nowMs(),
				});
				return;
			}

			const didTransportChange =
				JSON.stringify(existing.registration.transport) !==
				JSON.stringify(registration.transport);
			existing.registration = { ...registration };
			existing.updatedAt = nowMs();

			if (didTransportChange) {
				await this.disconnectState(existing);
				existing.client = undefined;
				existing.toolCache = undefined;
				existing.toolCacheUpdatedAt = undefined;
			}
		});
	}

	async unregisterServer(serverName: string): Promise<void> {
		await this.runExclusive(serverName, async () => {
			const state = this.requireServer(serverName);
			await this.disconnectState(state);
			this.servers.delete(serverName);
		});
	}

	async connectServer(serverName: string): Promise<void> {
		await this.runExclusive(serverName, async () => {
			const state = this.requireServer(serverName);
			await this.connectState(state);
		});
	}

	async disconnectServer(serverName: string): Promise<void> {
		await this.runExclusive(serverName, async () => {
			const state = this.requireServer(serverName);
			await this.disconnectState(state);
		});
	}

	async setServerDisabled(
		serverName: string,
		disabled: boolean,
	): Promise<void> {
		await this.runExclusive(serverName, async () => {
			const state = this.requireServer(serverName);
			state.registration = {
				...state.registration,
				disabled,
			};
			state.updatedAt = nowMs();
			if (disabled) {
				await this.disconnectState(state);
			}
		});
	}

	listServers(): readonly McpServerSnapshot[] {
		return [...this.servers.values()]
			.map((state) => ({
				name: state.registration.name,
				status: state.status,
				disabled: state.registration.disabled === true,
				lastError: state.lastError,
				toolCount: state.toolCache?.length ?? 0,
				updatedAt: state.updatedAt,
				metadata: state.registration.metadata,
			}))
			.sort((a, b) => a.name.localeCompare(b.name));
	}

	async listTools(serverName: string): Promise<readonly McpToolDescriptor[]> {
		const state = this.requireServer(serverName);
		const fetchedAt = state.toolCacheUpdatedAt ?? 0;
		if (state.toolCache && nowMs() - fetchedAt <= this.toolsCacheTtlMs) {
			return state.toolCache;
		}
		return this.refreshTools(serverName);
	}

	async refreshTools(
		serverName: string,
	): Promise<readonly McpToolDescriptor[]> {
		return this.runExclusive(serverName, async () => {
			const state = this.requireServer(serverName);
			const client = await this.ensureConnectedClient(state);
			const tools = await client.listTools();
			const cloned = cloneTools(tools);
			state.toolCache = cloned;
			state.toolCacheUpdatedAt = nowMs();
			state.updatedAt = nowMs();
			return cloned;
		});
	}

	async callTool(request: McpToolCallRequest): Promise<McpToolCallResult> {
		return this.runExclusive(request.serverName, async () => {
			const state = this.requireServer(request.serverName);
			const client = await this.ensureConnectedClient(state);
			state.updatedAt = nowMs();
			return client.callTool({
				name: request.toolName,
				arguments: request.arguments,
				context: request.context,
			});
		});
	}

	async dispose(): Promise<void> {
		const names = [...this.servers.keys()];
		for (const name of names) {
			await this.unregisterServer(name);
		}
	}

	private async ensureConnectedClient(
		state: ManagedServerState,
	): Promise<McpServerClient> {
		await this.connectState(state);
		if (!state.client) {
			throw new Error(
				`MCP server "${state.registration.name}" does not have an initialized client.`,
			);
		}
		return state.client;
	}

	private async connectState(state: ManagedServerState): Promise<void> {
		if (state.registration.disabled) {
			throw new Error(
				`MCP server "${state.registration.name}" is disabled and cannot be connected.`,
			);
		}
		if (state.status === "connected" && state.client) {
			return;
		}
		state.status = "connecting";
		state.updatedAt = nowMs();
		try {
			const client =
				state.client ?? (await this.clientFactory(state.registration));
			await client.connect();
			state.client = client;
			state.status = "connected";
			state.lastError = undefined;
			state.updatedAt = nowMs();
		} catch (error) {
			state.status = "disconnected";
			state.lastError = error instanceof Error ? error.message : String(error);
			state.updatedAt = nowMs();
			throw error;
		}
	}

	private async disconnectState(state: ManagedServerState): Promise<void> {
		if (!state.client) {
			state.status = "disconnected";
			state.updatedAt = nowMs();
			return;
		}

		try {
			await state.client.disconnect();
		} finally {
			state.status = "disconnected";
			state.updatedAt = nowMs();
		}
	}

	private requireServer(serverName: string): ManagedServerState {
		const state = this.servers.get(serverName);
		if (!state) {
			throw new Error(`Unknown MCP server: ${serverName}`);
		}
		return state;
	}

	private async runExclusive<T>(
		serverName: string,
		operation: () => Promise<T>,
	): Promise<T> {
		const previous = this.operationLocks.get(serverName) ?? Promise.resolve();
		let releaseCurrent: (() => void) | undefined;
		const current = new Promise<void>((resolve) => {
			releaseCurrent = resolve;
		});
		const queued = previous.catch(() => undefined).then(() => current);
		this.operationLocks.set(serverName, queued);

		await previous.catch(() => undefined);
		try {
			return await operation();
		} finally {
			releaseCurrent?.();
			const lock = this.operationLocks.get(serverName);
			if (lock === queued) {
				this.operationLocks.delete(serverName);
			}
		}
	}
}

import { describe, expect, it } from "vitest";
import { defaultMcpToolNameTransform } from "./name-transform";

const MAX_LENGTH = 64;
const VALID_PATTERN = /^[a-zA-Z0-9_-]+$/;

describe("defaultMcpToolNameTransform", () => {
	it("passes through short, valid names unchanged", () => {
		expect(
			defaultMcpToolNameTransform({ serverName: "mock", toolName: "echo" }),
		).toBe("mock__echo");
	});

	it("sanitizes invalid characters", () => {
		const result = defaultMcpToolNameTransform({
			serverName: "my.server",
			toolName: "tool/name",
		});
		expect(result).toMatch(VALID_PATTERN);
		expect(result).not.toContain(".");
		expect(result).not.toContain("/");
	});

	it("truncates valid names longer than 64 characters", () => {
		const toolName = "a".repeat(100);
		const result = defaultMcpToolNameTransform({
			serverName: "server",
			toolName,
		});
		expect(result.length).toBeLessThanOrEqual(MAX_LENGTH);
		expect(result).toMatch(VALID_PATTERN);
	});

	it("keeps names that are exactly at the limit unchanged", () => {
		const toolName = "a".repeat(MAX_LENGTH - "server__".length);
		const rawName = `server__${toolName}`;
		expect(rawName.length).toBe(MAX_LENGTH);
		expect(
			defaultMcpToolNameTransform({ serverName: "server", toolName }),
		).toBe(rawName);
	});

	it("produces distinct names for distinct long inputs via the hash suffix", () => {
		const a = defaultMcpToolNameTransform({
			serverName: "server",
			toolName: `${"x".repeat(80)}_a`,
		});
		const b = defaultMcpToolNameTransform({
			serverName: "server",
			toolName: `${"x".repeat(80)}_b`,
		});
		expect(a).not.toBe(b);
		expect(a.length).toBeLessThanOrEqual(MAX_LENGTH);
		expect(b.length).toBeLessThanOrEqual(MAX_LENGTH);
	});
});

import { createHash } from "node:crypto";
import type { McpToolNameTransform } from "./types";

// 64 is OpenAI's function-name limit; Anthropic allows 128. Cap at the lower
// bound so OpenAI-compatible providers don't reject long MCP tool names.
const MAX_MCP_TOOL_NAME_LENGTH = 64;
const INVALID_MCP_TOOL_NAME_CHARACTERS = /[^a-zA-Z0-9_-]+/g;
const HASH_LENGTH = 8;
const HASH_SEPARATOR_LENGTH = 1;
const FALLBACK_BASE_NAME = "mcp_tool";

function buildMcpToolNameHash(value: string): string {
	return createHash("sha1").update(value).digest("hex").slice(0, HASH_LENGTH);
}

function sanitizeMcpToolNameCandidate(value: string): string {
	return value.replace(INVALID_MCP_TOOL_NAME_CHARACTERS, "_");
}

export const defaultMcpToolNameTransform: McpToolNameTransform = ({
	serverName,
	toolName,
}): string => {
	const rawName = `${serverName}__${toolName}`;
	const sanitizedName = sanitizeMcpToolNameCandidate(rawName);
	if (sanitizedName === rawName && rawName.length <= MAX_MCP_TOOL_NAME_LENGTH) {
		return rawName;
	}

	const hash = buildMcpToolNameHash(rawName);
	const maxBaseLength =
		MAX_MCP_TOOL_NAME_LENGTH - HASH_SEPARATOR_LENGTH - HASH_LENGTH;
	const baseName = sanitizedName.slice(0, maxBaseLength) || FALLBACK_BASE_NAME;
	return `${baseName}_${hash}`;
};

import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { createMcpOAuthProviderContext } from "./oauth";

describe("mcp oauth", () => {
	const tempRoots: string[] = [];

	afterEach(async () => {
		await Promise.all(
			tempRoots.map((directory) =>
				rm(directory, { recursive: true, force: true }),
			),
		);
		tempRoots.length = 0;
	});

	async function createSettingsFile(): Promise<string> {
		const tempRoot = await mkdtemp(join(tmpdir(), "core-mcp-oauth-"));
		tempRoots.push(tempRoot);
		const filePath = join(tempRoot, "cline_mcp_settings.json");
		await writeFile(
			filePath,
			JSON.stringify(
				{
					mcpServers: {
						linear: {
							transport: {
								type: "streamableHttp",
								url: "https://mcp.linear.app/mcp",
							},
						},
					},
				},
				null,
				2,
			),
			"utf8",
		);
		return filePath;
	}

	it("tracks the most recent generated OAuth state", async () => {
		const settingsPath = await createSettingsFile();
		const context = createMcpOAuthProviderContext({
			settingsPath,
			serverName: "linear",
			redirectUrl: "http://127.0.0.1:1456/mcp/oauth/callback",
		});

		expect(context.getLastOAuthState()).toBeUndefined();

		const createState = context.provider.state;
		if (!createState) {
			throw new Error("Expected OAuth provider to expose state generator.");
		}

		const firstState = createState();
		expect(context.getLastOAuthState()).toBe(firstState);

		const secondState = createState();
		expect(secondState).not.toBe(firstState);
		expect(context.getLastOAuthState()).toBe(secondState);
	});

	it("does not write redirect state when creating a provider context", async () => {
		const settingsPath = await createSettingsFile();
		const before = await readFile(settingsPath, "utf8");

		createMcpOAuthProviderContext({
			settingsPath,
			serverName: "linear",
			redirectUrl: "http://127.0.0.1:1456/mcp/oauth/callback",
		});

		await expect(readFile(settingsPath, "utf8")).resolves.toBe(before);
	});
});

import { randomUUID } from "node:crypto";
import type {
	OAuthClientProvider,
	OAuthDiscoveryState,
} from "@modelcontextprotocol/sdk/client/auth.js";
import { UnauthorizedError } from "@modelcontextprotocol/sdk/client/auth.js";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { SSEClientTransport } from "@modelcontextprotocol/sdk/client/sse.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import type {
	OAuthClientInformationMixed,
	OAuthClientMetadata,
	OAuthTokens,
} from "@modelcontextprotocol/sdk/shared/auth.js";
import type { FetchLike } from "@modelcontextprotocol/sdk/shared/transport.js";
import {
	type OAuthServerCloseInfo,
	type OAuthServerListeningInfo,
	startLocalOAuthServer,
} from "../../auth/server";
import {
	getMcpServerOAuthState,
	normalizeMcpServerOAuthState,
	updateMcpServerOAuthState,
} from "./config-loader";
import type { McpServerOAuthState, McpServerRegistration } from "./types";

const DEFAULT_MCP_OAUTH_CALLBACK_PATH = "/mcp/oauth/callback";
const DEFAULT_MCP_OAUTH_CALLBACK_PORTS = [1456, 1457, 1458];
const DEFAULT_MCP_OAUTH_TIMEOUT_MS = 5 * 60 * 1000;

export type McpSdkAuthCapableTransport =
	| SSEClientTransport
	| StreamableHTTPClientTransport;

export interface CreateMcpOAuthProviderContextOptions {
	settingsPath?: string;
	serverName: string;
	redirectUrl: string;
	onAuthorizationUrl?: (url: string) => void | Promise<void>;
}

export interface McpOAuthProviderContext {
	provider: OAuthClientProvider;
	getLastAuthorizationUrl(): string | undefined;
	getLastOAuthState(): string | undefined;
	resetInteractiveState(): Promise<void>;
	markError(errorMessage: string): Promise<void>;
	clearError(): Promise<void>;
}

export interface AuthorizeMcpServerOAuthOptions {
	serverName: string;
	filePath?: string;
	clientName?: string;
	clientVersion?: string;
	fetch?: FetchLike;
	openUrl?: (url: string) => void | Promise<void>;
	callbackHost?: string;
	callbackPorts?: number[];
	callbackPath?: string;
	timeoutMs?: number;
	successHtml?: string;
	onServerListening?: (info: OAuthServerListeningInfo) => void | Promise<void>;
	onServerClose?: (info: OAuthServerCloseInfo) => void | Promise<void>;
}

export interface AuthorizeMcpServerOAuthResult {
	serverName: string;
	authorized: true;
	message: string;
}

function toErrorMessage(error: unknown): string {
	if (error instanceof Error) {
		const message = error.message.trim();
		if (message.length > 0) {
			return message;
		}
	}
	return String(error);
}

function createOAuthClientMetadata(redirectUrl: string): OAuthClientMetadata {
	return {
		client_name: "Cline",
		redirect_uris: [redirectUrl],
		grant_types: ["authorization_code", "refresh_token"],
		response_types: ["code"],
		token_endpoint_auth_method: "none",
	};
}

export function createMcpOAuthProviderContext(
	options: CreateMcpOAuthProviderContextOptions,
): McpOAuthProviderContext {
	let state: McpServerOAuthState = {};
	try {
		state =
			getMcpServerOAuthState(options.serverName, {
				filePath: options.settingsPath,
			}) ?? {};
	} catch {
		state = {};
	}
	let lastAuthorizationUrl: string | undefined;
	let lastOAuthState: string | undefined;

	const patch = async (
		updater: (current: McpServerOAuthState) => McpServerOAuthState,
	): Promise<void> => {
		const nextState = normalizeMcpServerOAuthState(updater(state)) ?? {};
		try {
			state = updateMcpServerOAuthState(options.serverName, () => nextState, {
				filePath: options.settingsPath,
			});
		} catch {
			state = nextState;
		}
	};

	const provider: OAuthClientProvider = {
		get redirectUrl() {
			return state.redirectUrl ?? options.redirectUrl;
		},
		get clientMetadata() {
			return createOAuthClientMetadata(
				state.redirectUrl ?? options.redirectUrl,
			);
		},
		state: () => {
			lastOAuthState = randomUUID();
			return lastOAuthState;
		},
		clientInformation: () =>
			state.clientInformation as OAuthClientInformationMixed | undefined,
		saveClientInformation: async (clientInformation) => {
			await patch((current) => ({
				...current,
				clientInformation: clientInformation as Record<string, unknown>,
				redirectUrl: options.redirectUrl,
				lastError: undefined,
			}));
		},
		tokens: () => state.tokens as OAuthTokens | undefined,
		saveTokens: async (tokens) => {
			const lastAuthenticatedAt = Date.now();
			await patch((current) => ({
				...current,
				tokens: tokens as Record<string, unknown>,
				redirectUrl: options.redirectUrl,
				lastError: undefined,
				lastAuthenticatedAt,
			}));
		},
		redirectToAuthorization: async (authorizationUrl) => {
			lastAuthorizationUrl = authorizationUrl.toString();
			await options.onAuthorizationUrl?.(lastAuthorizationUrl);
		},
		saveCodeVerifier: async (codeVerifier) => {
			await patch((current) => ({
				...current,
				codeVerifier,
				redirectUrl: options.redirectUrl,
			}));
		},
		codeVerifier: () => {
			if (!state.codeVerifier) {
				throw new Error(
					`Missing OAuth code verifier for MCP server "${options.serverName}".`,
				);
			}
			return state.codeVerifier;
		},
		invalidateCredentials: async (scope) => {
			await patch((current) => {
				if (scope === "all") {
					return {
						lastError: current.lastError,
						redirectUrl: current.redirectUrl,
					};
				}
				return {
					...current,
					...(scope === "client" ? { clientInformation: undefined } : {}),
					...(scope === "tokens"
						? { tokens: undefined, lastAuthenticatedAt: undefined }
						: {}),
					...(scope === "verifier" ? { codeVerifier: undefined } : {}),
					...(scope === "discovery" ? { discoveryState: undefined } : {}),
				};
			});
		},
		saveDiscoveryState: async (discoveryState) => {
			await patch((current) => ({
				...current,
				discoveryState: discoveryState as unknown as Record<string, unknown>,
			}));
		},
		discoveryState: () =>
			state.discoveryState as OAuthDiscoveryState | undefined,
	};

	return {
		provider,
		getLastAuthorizationUrl: () => lastAuthorizationUrl,
		getLastOAuthState: () => lastOAuthState,
		resetInteractiveState: async () => {
			await patch((current) => ({
				...current,
				clientInformation: undefined,
				codeVerifier: undefined,
				discoveryState: undefined,
				lastError: undefined,
				redirectUrl: options.redirectUrl,
			}));
		},
		markError: async (errorMessage) => {
			await patch((current) => ({
				...current,
				lastError: errorMessage,
			}));
		},
		clearError: async () => {
			await patch((current) => ({
				...current,
				lastError: undefined,
			}));
		},
	};
}

export function createMcpSdkTransport(input: {
	registration: McpServerRegistration;
	oauthProvider?: OAuthClientProvider;
	fetch?: FetchLike;
}): McpSdkAuthCapableTransport {
	const transport = input.registration.transport;
	if (transport.type === "stdio") {
		throw new Error(
			`MCP server "${input.registration.name}" uses stdio transport and does not support OAuth browser flow.`,
		);
	}

	const requestInit = transport.headers
		? {
				headers: transport.headers,
			}
		: undefined;
	if (transport.type === "sse") {
		return new SSEClientTransport(new URL(transport.url), {
			authProvider: input.oauthProvider,
			requestInit,
			fetch: input.fetch,
		});
	}

	return new StreamableHTTPClientTransport(new URL(transport.url), {
		authProvider: input.oauthProvider,
		requestInit,
		fetch: input.fetch,
	});
}

function buildClient(input: {
	clientName?: string;
	clientVersion?: string;
}): Client {
	return new Client({
		name: input.clientName?.trim() || "@cline/core",
		version: input.clientVersion?.trim() || "0.0.0",
	});
}

export async function authorizeMcpServerOAuth(
	options: AuthorizeMcpServerOAuthOptions,
): Promise<AuthorizeMcpServerOAuthResult> {
	const serverName = options.serverName.trim();
	if (!serverName) {
		throw new Error("MCP server name cannot be empty.");
	}

	const { resolveMcpServerRegistrations } = await import("./config-loader");
	const registration = resolveMcpServerRegistrations({
		filePath: options.filePath,
	}).find((entry) => entry.name === serverName);
	if (!registration) {
		throw new Error(`MCP server "${serverName}" is not configured.`);
	}
	if (registration.disabled) {
		throw new Error(
			`MCP server "${serverName}" is disabled. Enable it before running OAuth.`,
		);
	}
	if (registration.transport.type === "stdio") {
		throw new Error(
			`MCP server "${serverName}" uses stdio transport and does not support OAuth browser flow.`,
		);
	}

	const callbackServer = await startLocalOAuthServer({
		host: options.callbackHost,
		ports: options.callbackPorts?.length
			? options.callbackPorts
			: DEFAULT_MCP_OAUTH_CALLBACK_PORTS,
		callbackPath: options.callbackPath ?? DEFAULT_MCP_OAUTH_CALLBACK_PATH,
		timeoutMs: options.timeoutMs ?? DEFAULT_MCP_OAUTH_TIMEOUT_MS,
		successHtml: options.successHtml,
		onListening: options.onServerListening,
		onClose: options.onServerClose,
	});
	if (!callbackServer.callbackUrl) {
		throw new Error("Unable to bind local MCP OAuth callback server.");
	}

	const oauthContext = createMcpOAuthProviderContext({
		settingsPath: options.filePath,
		serverName,
		redirectUrl: callbackServer.callbackUrl,
		onAuthorizationUrl: async (url) => {
			await options.openUrl?.(url);
		},
	});
	await oauthContext.resetInteractiveState();

	const client = buildClient(options);
	let retryClient: Client | undefined;
	try {
		const transport = createMcpSdkTransport({
			registration,
			oauthProvider: oauthContext.provider,
			fetch: options.fetch,
		});
		try {
			await client.connect(transport);
			await client.listTools();
			await oauthContext.clearError();
			return {
				serverName,
				authorized: true,
				message: `MCP server "${serverName}" is already authorized.`,
			};
		} catch (error) {
			if (!(error instanceof UnauthorizedError)) {
				throw error;
			}
			const authUrl = oauthContext.getLastAuthorizationUrl();
			if (!authUrl) {
				throw new Error(
					`MCP server "${serverName}" did not provide an authorization URL.`,
				);
			}
			const callback = await callbackServer.waitForCallback();
			if (!callback) {
				throw new Error(
					"Timed out waiting for MCP OAuth authorization callback.",
				);
			}
			if (callback.error) {
				throw new Error(`OAuth authorization failed: ${callback.error}`);
			}
			if (!callback.code) {
				throw new Error(
					"OAuth callback did not include an authorization code.",
				);
			}
			const expectedState = oauthContext.getLastOAuthState();
			if (!expectedState) {
				throw new Error(
					`MCP server "${serverName}" did not start an OAuth stateful authorization flow.`,
				);
			}
			if (callback.state !== expectedState) {
				throw new Error("OAuth authorization failed: state mismatch.");
			}

			await transport.finishAuth(callback.code);
			retryClient = buildClient(options);
			const retryTransport = createMcpSdkTransport({
				registration,
				oauthProvider: oauthContext.provider,
				fetch: options.fetch,
			});
			await retryClient.connect(retryTransport);
			await retryClient.listTools();
			await oauthContext.clearError();
			return {
				serverName,
				authorized: true,
				message: `MCP server "${serverName}" OAuth authorization completed.`,
			};
		}
	} catch (error) {
		const message = toErrorMessage(error);
		await oauthContext.markError(message);
		throw new Error(message);
	} finally {
		await client.close().catch(() => undefined);
		await retryClient?.close().catch(() => undefined);
		callbackServer.close();
	}
}

