function registerTools(
	api: AgentExtensionApi,
	sandbox: SubprocessSandbox,
	descriptor: SandboxedPluginDescriptor,
	timeoutMs: number,
	reinitialize: () => Promise<void>,
): void {
	for (const td of descriptor.contributions?.tools ?? []) {
		const tool: AgentTool = {
			name: td.name,
			description: td.description ?? "",
			inputSchema: (td.inputSchema ?? {
				type: "object",
				properties: {},
			}) as AgentTool["inputSchema"],
			timeoutMs: td.timeoutMs,
			retryable: td.retryable,
			execute: async (input: unknown, context: unknown) => {
				try {
					return await sandbox.call(
						"executeTool",
						{
							pluginId: descriptor.pluginId,
							contributionId: td.id,
							input,
							context,
						},
						{ timeoutMs },
					);
				} catch (error) {
					if (!isUnknownPluginIdError(error)) {
						throw error;
					}
					await reinitialize();
					return await sandbox.call(
						"executeTool",
						{
							pluginId: descriptor.pluginId,
							contributionId: td.id,
							input,
							context,
						},
						{ timeoutMs },
					);
				}
			},
		};
		api.registerTool(tool);
	}
}

function registerCommands(
	api: AgentExtensionApi,
	sandbox: SubprocessSandbox,
	descriptor: SandboxedPluginDescriptor,
	timeoutMs: number,
	reinitialize: () => Promise<void>,
): void {
	for (const cd of descriptor.contributions?.commands ?? []) {
		api.registerCommand({
			name: cd.name,
			description: cd.description,
			handler: async (input: string) => {
				try {
					return await sandbox.call<AgentExtensionCommandResult>(
						"executeCommand",
						{
							pluginId: descriptor.pluginId,
							contributionId: cd.id,
							input,
						},
						{ timeoutMs },
					);
				} catch (error) {
					if (!isUnknownPluginIdError(error)) {
						throw error;
					}
					await reinitialize();
					return await sandbox.call<AgentExtensionCommandResult>(
						"executeCommand",
						{
							pluginId: descriptor.pluginId,
							contributionId: cd.id,
							input,
						},
						{ timeoutMs },
					);
				}
			},
		});
	}
}

function registerRules(
	api: AgentExtensionApi,
	sandbox: SubprocessSandbox,
	descriptor: SandboxedPluginDescriptor,
	timeoutMs: number,
	reinitialize: () => Promise<void>,
): void {
	for (const rule of descriptor.contributions?.rules ?? []) {
		api.registerRule({
			id: rule.ruleId,
			source: rule.source,
			content:
				rule.hasContentHandler === true
					? async () => {
							try {
								return await sandbox.call<string>(
									"resolveRuleContent",
									{
										pluginId: descriptor.pluginId,
										contributionId: rule.id,
									},
									{ timeoutMs },
								);
							} catch (error) {
								if (!isUnknownPluginIdError(error)) {
									throw error;
								}
								await reinitialize();
								return await sandbox.call<string>(
									"resolveRuleContent",
									{
										pluginId: descriptor.pluginId,
										contributionId: rule.id,
									},
									{ timeoutMs },
								);
							}
						}
					: (rule.content ?? ""),
		});
	}
}

function registerSimpleContributions(
	api: AgentExtensionApi,
	descriptor: SandboxedPluginDescriptor,
): void {
	for (const pd of descriptor.contributions?.providers ?? []) {
		api.registerProvider({
			name: pd.name,
			description: pd.description,
			metadata: pd.metadata,
		});
	}

	for (const eventType of descriptor.contributions?.automationEventTypes ??
		[]) {
		api.registerAutomationEventType({
			eventType: eventType.eventType,
			source: eventType.source,
			description: eventType.description,
			attributesSchema: eventType.attributesSchema,
			payloadSchema: eventType.payloadSchema,
			examples: eventType.examples,
			metadata: eventType.metadata,
		});
	}

	for (const mcpServer of descriptor.contributions?.mcpServers ?? []) {
		api.registerMcpServer(mcpServer);
	}
}

function registerMessageBuilders(
	api: AgentExtensionApi,
	sandbox: SubprocessSandbox,
	descriptor: SandboxedPluginDescriptor,
	timeoutMs: number,
	reinitialize: () => Promise<void>,
): void {
	for (const bd of descriptor.contributions?.messageBuilders ?? []) {
		api.registerMessageBuilder({
			name: bd.name,
			async build(messages) {
				try {
					const result = await sandbox.call<unknown[]>(
						"buildMessages",
						{
							pluginId: descriptor.pluginId,
							contributionId: bd.id,
							messages,
						},
						{ timeoutMs },
					);
					return isMessageArray(result) ? result : messages;
				} catch (error) {
					if (!isUnknownPluginIdError(error)) {
						throw error;
					}
					await reinitialize();
					const result = await sandbox.call<unknown[]>(
						"buildMessages",
						{
							pluginId: descriptor.pluginId,
							contributionId: bd.id,
							messages,
						},
						{ timeoutMs },
					);
					return isMessageArray(result) ? result : messages;
				}
			},
		});
	}
}

function isMessageArray(value: unknown): value is Message[] {
	return (
		Array.isArray(value) &&
		value.every(
			(entry) =>
				typeof entry === "object" &&
				entry !== null &&
				"role" in entry &&
				"content" in entry,
		)
	);
}

function makeHookHandler(
	sandbox: SubprocessSandbox,
	pluginId: string,
	hookName: string,
	timeoutMs: number,
	reinitialize: () => Promise<void>,
): (payload: unknown) => Promise<unknown> {
	return async (payload: unknown) => {
		try {
			return await sandbox.call(
				"invokeHook",
				{ pluginId, hookName, payload },
				{ timeoutMs },
			);
		} catch (error) {
			if (!isUnknownPluginIdError(error)) {
				throw error;
			}
			await reinitialize();
			return await sandbox.call(
				"invokeHook",
				{ pluginId, hookName, payload },
				{ timeoutMs },
			);
		}
	};
}

function createSandboxRuntimeHooks(
	sandbox: SubprocessSandbox,
	descriptor: SandboxedPluginDescriptor,
	hookTimeoutMs: number,
	reinitialize: () => Promise<void>,
): Partial<AgentRuntimeHooks> | undefined {
	const hooks: Partial<
		Record<keyof AgentRuntimeHooks, (payload: unknown) => Promise<unknown>>
	> = {};
	for (const hookName of descriptor.hooks ?? []) {
		hooks[hookName] = makeHookHandler(
			sandbox,
			descriptor.pluginId,
			hookName,
			hookTimeoutMs,
			reinitialize,
		);
	}
	return Object.keys(hooks).length > 0
		? (hooks as Partial<AgentRuntimeHooks>)
		: undefined;
}

import type { PluginManifest } from "@cline/shared";

export interface PluginTargeting {
	providerId?: string;
	modelId?: string;
}

export function matchesPluginManifestTargeting(
	manifest: PluginManifest | undefined,
	targeting: PluginTargeting | undefined,
): boolean {
	if (!manifest) {
		return true;
	}

	if (manifest.providerIds?.length) {
		if (
			!targeting?.providerId ||
			!manifest.providerIds.includes(targeting.providerId)
		) {
			return false;
		}
	}

	if (manifest.modelIds?.length) {
		if (!targeting?.modelId || !manifest.modelIds.includes(targeting.modelId)) {
			return false;
		}
	}

	return true;
}

