		await tool.execute({ paths: "/tmp/c.ts" } as never, {
			agentId: "agent-1",
			conversationId: "conv-1",
			iteration: 2,
		});

		expect(execute).toHaveBeenNthCalledWith(
			1,
			{ path: "/tmp/a.ts" },
			expect.objectContaining({ iteration: 1 }),
