		expect(execute).toHaveBeenNthCalledWith(
			2,
			{ path: "/tmp/b.ts", start_line: 2 },
			expect.objectContaining({ iteration: 1 }),
		);
		expect(execute).toHaveBeenNthCalledWith(
			3,
			{ path: "/tmp/c.ts" },
			expect.objectContaining({ iteration: 2 }),
		);
