				conversationId: "conv-1",
				iteration: 1,
			}),
		);
		expect(execute).toHaveBeenNthCalledWith(
			2,
			{
				path: "/tmp/valid-b.ts",
			},
			expect.objectContaining({
				agentId: "agent-1",
				conversationId: "conv-1",
				iteration: 1,
			}),
		);
	});
