					updatedAt: Date.now(),
					workspaceRoot: "/tmp/project",
					cwd: "/tmp/project",
				},
			},
		});
		let receivedSignal: AbortSignal | undefined;
		let resolveExecutor: ((value: string) => void) | undefined;
		const askQuestion = vi.fn(
			async (
				_question: string,
				_options: string[],
				context: AgentToolContext,
			) => {
				receivedSignal = context.signal;
				return await new Promise<string>((resolve) => {
					resolveExecutor = resolve;
				});
			},
		);

		const { HubRuntimeHost } = await import("./hub-runtime-host");
		const host = new HubRuntimeHost({ url: "ws://127.0.0.1:25463/hub" });
		await host.startSession({
			config: createConfig(),
			source: SessionSource.CLI,
			capabilities: { toolExecutors: { askQuestion } },
		});

		onEvent?.({
			version: "v1",
			event: "capability.requested",
			sessionId: "sess-1",
			payload: {
				requestId: "capreq-1",
				targetClientId: "client-1",
				capabilityName: "tool_executor.askQuestion",
				payload: {
					args: ["Which approach?", ["Use the SDK"]],
					context: {
						agentId: "agent-1",
						conversationId: "conversation-1",
						iteration: 1,
					},
				},
			},
		});
		await new Promise((resolve) => setTimeout(resolve, 0));

		expect(receivedSignal).toBeDefined();
		expect(receivedSignal?.aborted).toBe(false);
		onEvent?.({
			version: "v1",
			event: "capability.resolved",
			sessionId: "sess-1",
			payload: {
				requestId: "capreq-1",
				capabilityName: "tool_executor.askQuestion",
				targetClientId: "client-1",
				ok: false,
				cancelled: true,
				error: "user cancelled",
			},
		});

		expect(receivedSignal?.aborted).toBe(true);
		resolveExecutor?.("Use the SDK");
		await new Promise((resolve) => setTimeout(resolve, 0));
		expect(commandMock).not.toHaveBeenLastCalledWith(
			"capability.respond",
			expect.anything(),
			"sess-1",
		);
	});

