import { dirname, join } from "node:path";
import type {
	ActiveConnectorRecord,
	ConfiguredConnectorRecord,
	ConnectorChannelsResponse,
	ConnectorFieldDef,
	ConnectorPlatformDef,
	HubCommandEnvelope,
	HubReplyEnvelope,
} from "@cline/shared";
