import type {
	HubClientRecord,
	HubCommandEnvelope,
	HubEventEnvelope,
	HubReplyEnvelope,
	SessionRecord as HubSessionRecord,
	ITelemetryService,
	JsonValue,
	SessionParticipant,
} from "@cline/shared";
import { createSessionId } from "@cline/shared";
import type {
	PendingPromptsRuntimeService,
	RuntimeHost,
	SessionConnectionRuntimeService,
	SessionUsageRuntimeService,
} from "../../../runtime/host/runtime-host";
import {
	type CoreSessionSnapshot,
	createCoreSessionSnapshot,
} from "../../../session/session-snapshot";
import {
	type HubSessionState,
	toHubSessionRecord,
} from "../hub-session-records";

export type PendingApproval = {
	sessionId: string;
	resolve: (result: { approved: boolean; reason?: string }) => void;
};

export type PendingCapabilityRequest = {
	sessionId: string;
	targetClientId: string;
	capabilityName: string;
	onProgress?: (payload: Record<string, unknown>) => void;
	resolve: (result: {
		ok: boolean;
		payload?: Record<string, unknown>;
		error?: string;
	}) => void;
};

/**
 * Shared mutable state and helpers passed to every command-handler module.
 * The transport class owns the maps; handlers get a stable read/write surface.
 */
export interface HubTransportContext {
	readonly clients: Map<string, HubClientRecord>;
	readonly sessionState: Map<string, HubSessionState>;
	readonly pendingApprovals: Map<string, PendingApproval>;
	readonly pendingCapabilityRequests: Map<string, PendingCapabilityRequest>;
	readonly suppressNextTerminalEventBySession: Map<string, string>;
	readonly telemetry?: ITelemetryService;
	readonly sessionHost: RuntimeHost &
		Partial<
			PendingPromptsRuntimeService &
				SessionUsageRuntimeService &
				SessionConnectionRuntimeService
		>;
	publish(event: HubEventEnvelope): void;
	buildEvent(
		event: HubEventEnvelope["event"],
		payload?: Record<string, unknown>,
		sessionId?: string,
	): HubEventEnvelope;
	requestCapability(
		sessionId: string,
		capabilityName: string,
		payload: Record<string, unknown>,
		targetClientId: string,
		onProgress?: (payload: Record<string, unknown>) => void,
	): Promise<Record<string, unknown> | undefined>;
}

type EnvelopeRef = Pick<HubCommandEnvelope, "version" | "requestId">;

export function okReply(
	envelope: EnvelopeRef,
	payload?: HubReplyEnvelope["payload"],
): HubReplyEnvelope {
	return {
		version: envelope.version,
		requestId: envelope.requestId,
		ok: true,
		...(payload !== undefined ? { payload } : {}),
	};
}

export function errorReply(
	envelope: EnvelopeRef,
	code: string,
	message: string,
): HubReplyEnvelope {
	return {
		version: envelope.version,
		requestId: envelope.requestId,
		ok: false,
		error: { code, message },
	};
}

/** Returns the value when it's a plain object, or undefined otherwise. */
export function asPlainRecord(
	value: unknown,
): Record<string, JsonValue | undefined> | undefined {
	return value && typeof value === "object" && !Array.isArray(value)
		? (value as Record<string, JsonValue | undefined>)
		: undefined;
}

/**
 * Pulls the session id from the envelope. Handlers accept either
 * `payload.sessionId` (top-level command argument) or `envelope.sessionId`
 * (envelope-level addressing). Returns "" when neither is present so handlers
 * can branch on truthiness.
 */
export function extractSessionId(envelope: HubCommandEnvelope): string {
	if (typeof envelope.payload?.sessionId === "string") {
		return envelope.payload.sessionId.trim();
	}
	return envelope.sessionId?.trim() ?? "";
}

export function buildHubEvent(
	event: HubEventEnvelope["event"],
	payload?: Record<string, unknown>,
	sessionId?: string,
): HubEventEnvelope {
	return {
		version: "v1",
		event,
		eventId: createSessionId("hevt_"),
		sessionId,
		timestamp: Date.now(),
		payload,
	};
}

export async function readHubSessionRecord(
	ctx: HubTransportContext,
	sessionId: string,
): Promise<HubSessionRecord | undefined> {
	const session = await ctx.sessionHost.getSession(sessionId);
	if (!session) {
		return undefined;
	}
	const usageSummary = await ctx.sessionHost.getAccumulatedUsage?.(sessionId);
	return toHubSessionRecord(
		session,
		ctx.sessionState.get(sessionId),
		usageSummary?.usage,
		usageSummary?.aggregateUsage,
	);
}

export async function readCoreSessionSnapshot(
	ctx: HubTransportContext,
	sessionId: string,
): Promise<CoreSessionSnapshot | undefined> {
	const session = await ctx.sessionHost.getSession(sessionId);
	if (!session) {
		return undefined;
	}
	const [messages, usageSummary] = await Promise.all([
		typeof ctx.sessionHost.readSessionMessages === "function"
			? ctx.sessionHost.readSessionMessages(sessionId)
			: [],
		ctx.sessionHost.getAccumulatedUsage?.(sessionId),
	]);
	return createCoreSessionSnapshot({
		session,
		messages,
		usage: usageSummary?.usage,
		aggregateUsage: usageSummary?.aggregateUsage,
	});
}

export function ensureSessionState(
	ctx: HubTransportContext,
	sessionId: string,
	clientId: string,
	role: SessionParticipant["role"],
	options: { interactive?: boolean } = {},
): HubSessionState {
	const existing = ctx.sessionState.get(sessionId);
	if (existing) {
		if (options.interactive !== undefined) {
			existing.interactive = options.interactive;
		}
		if (role === "creator" && !existing.createdByClientId) {
			existing.createdByClientId = clientId;
		}
		if (!existing.participants.has(clientId)) {
			existing.participants.set(clientId, {
				clientId,
				attachedAt: Date.now(),
				role,
			});
		}
		return existing;
	}
	const state: HubSessionState = {
		createdByClientId: clientId,
		interactive: options.interactive ?? true,
		participants: new Map([
			[
				clientId,
				{
					clientId,
					attachedAt: Date.now(),
					role,
				},
			],
		]),
	};
	ctx.sessionState.set(sessionId, state);
	return state;
}

export function ensureSessionParticipant(
	ctx: HubTransportContext,
	sessionId: string,
	clientId: string,
	role: SessionParticipant["role"],
	options: { interactive?: boolean } = {},
): HubSessionState {
	const existing = ctx.sessionState.get(sessionId);
	if (existing) {
		if (options.interactive !== undefined) {
			existing.interactive = options.interactive;
		}
		if (!existing.participants.has(clientId)) {
			existing.participants.set(clientId, {
				clientId,
				attachedAt: Date.now(),
				role,
			});
		}
		return existing;
	}
	const state: HubSessionState = {
		interactive: options.interactive ?? true,
		participants: new Map([
			[
				clientId,
				{
					clientId,
					attachedAt: Date.now(),
					role,
				},
			],
		]),
	};
	ctx.sessionState.set(sessionId, state);
	return state;
}

import type { HubEventEnvelope } from "@cline/shared";
import { afterEach, describe, expect, it, vi } from "vitest";
import type { RuntimeHost } from "../../../runtime/host/runtime-host";
import { buildHubEvent, type HubTransportContext } from "./context";
import { handleRunAbort, handleSessionInput } from "./run-handlers";

function createContext(
	overrides: Partial<RuntimeHost> = {},
): HubTransportContext & { events: HubEventEnvelope[] } {
	const events: HubEventEnvelope[] = [];
	return {
		clients: new Map(),
		sessionState: new Map(),
		pendingApprovals: new Map(),
		pendingCapabilityRequests: new Map(),
		suppressNextTerminalEventBySession: new Map(),
		sessionHost: {
			startSession: vi.fn(),
			runTurn: vi.fn(),
			restoreSession: vi.fn(),
			abort: vi.fn().mockResolvedValue(undefined),
			stopSession: vi.fn(),
			dispose: vi.fn(),
			getSession: vi.fn(),
			listSessions: vi.fn(),
			...overrides,
		} as RuntimeHost,
		publish: (event) => {
			events.push(event);
		},
		buildEvent: buildHubEvent,
		requestCapability: vi.fn(),
		events,
	};
}

describe("run handlers", () => {
	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	it("aborts through the runtime host when a run timeout is configured", async () => {
		vi.useFakeTimers();
		vi.spyOn(console, "error").mockImplementation(() => {});
		const abort = vi.fn().mockResolvedValue(undefined);
		const ctx = createContext({
			runTurn: vi.fn(() => new Promise<undefined>(() => {})),
			abort,
		});

		const promise = handleSessionInput(ctx, {
			version: "v1",
			command: "run.start",
			requestId: "req-timeout",
			sessionId: "session-1",
			payload: {
				sessionId: "session-1",
				prompt: "go",
				timeoutMs: 50,
			},
		});
		const expectation = expect(promise).rejects.toThrow(
			"Hub run run.start timed out after 50ms.",
		);

		await vi.advanceTimersByTimeAsync(51);

		await expectation;
		expect(abort).toHaveBeenCalledWith(
			"session-1",
			"Hub run run.start timed out after 50ms.",
		);
		expect(ctx.events).toContainEqual(
			expect.objectContaining({
				event: "run.failed",
				payload: expect.objectContaining({
					error: "Hub run run.start timed out after 50ms.",
				}),
			}),
		);
	});

	it("rejects promptly when timeout abort remains pending", async () => {
		vi.useFakeTimers();
		vi.spyOn(console, "error").mockImplementation(() => {});
		let resolveAbort: (() => void) | undefined;
		const abort = vi.fn(
			() =>
				new Promise<void>((resolve) => {
					resolveAbort = resolve;
				}),
		);
		const ctx = createContext({
			runTurn: vi.fn(() => new Promise<undefined>(() => {})),
			abort,
		});

		let rejection: string | undefined;
		const promise = handleSessionInput(ctx, {
			version: "v1",
			command: "run.start",
			requestId: "req-timeout-prompt",
			sessionId: "session-1",
			payload: {
				sessionId: "session-1",
				prompt: "go",
				timeoutMs: 50,
			},
		}).catch((error: unknown) => {
			rejection = error instanceof Error ? error.message : String(error);
		});

		await vi.advanceTimersByTimeAsync(51);

		expect(rejection).toBe("Hub run run.start timed out after 50ms.");
		expect(abort).toHaveBeenCalledWith(
			"session-1",
			"Hub run run.start timed out after 50ms.",
		);

		resolveAbort?.();
		await promise;
	});

	it("publishes heartbeat events while a run remains pending", async () => {
		vi.useFakeTimers();
		vi.spyOn(console, "error").mockImplementation(() => {});
		let resolveRun: ((result: undefined) => void) | undefined;
		const ctx = createContext({
			runTurn: vi.fn(
				() =>
					new Promise<undefined>((resolve) => {
						resolveRun = resolve;
					}),
			),
		});

		const promise = handleSessionInput(ctx, {
			version: "v1",
			command: "run.start",
			requestId: "req-heartbeat",
			sessionId: "session-1",
			payload: { sessionId: "session-1", prompt: "go" },
		});

		await vi.advanceTimersByTimeAsync(30_001);

		expect(ctx.events).toContainEqual(
			expect.objectContaining({
				event: "run.heartbeat",
				sessionId: "session-1",
				payload: expect.objectContaining({
					requestId: "req-heartbeat",
					elapsedMs: expect.any(Number),
				}),
			}),
		);

		resolveRun?.(undefined);
		await expect(promise).resolves.toMatchObject({ ok: true });
	});

	it("treats abort as applied when the runtime abort hook rejects", async () => {
		const abort = vi.fn().mockRejectedValue(new Error("Run aborted"));
		const ctx = createContext({ abort });

		const reply = await handleRunAbort(ctx, {
			version: "v1",
			command: "run.abort",
			requestId: "req-abort",
			clientId: "client-1",
			sessionId: "session-1",
			payload: {
				sessionId: "session-1",
				reason: "user cancelled",
			},
		});

		expect(reply).toMatchObject({
			ok: true,
			payload: { applied: true },
		});
		expect(abort).toHaveBeenCalledWith("session-1", "user cancelled");
	});
});

import type {
	AgentMode,
	AgentResult,
	HubCommandEnvelope,
	HubReplyEnvelope,
} from "@cline/shared";
import { parseHookEventPayload } from "../../../hooks";
import {
	isSessionNotFoundError,
	SESSION_NOT_FOUND_ERROR_CODE,
	type SendSessionInput,
} from "../../../runtime/host/runtime-host";
import { logHubMessage } from "../hub-server-logging";
import { cancelPendingApprovals } from "./approval-handlers";
import { cancelPendingCapabilityRequests } from "./capability-handlers";
import {
	errorReply,
	extractSessionId,
	type HubTransportContext,
	okReply,
	readCoreSessionSnapshot,
} from "./context";

const HUB_RUN_HEARTBEAT_MS = 30_000;

function terminalRunEventForReason(
	reason: string,
): "run.aborted" | "run.completed" | "run.failed" {
	if (reason === "aborted") return "run.aborted";
	if (reason === "error" || reason === "failed") return "run.failed";
	return "run.completed";
}

function errorMessageForResult(result: AgentResult): string | undefined {
	if (result.finishReason !== "error") {
		return undefined;
	}
	const text = result.text.trim();
	return text || undefined;
}

function sessionNotFoundReply(
	envelope: HubCommandEnvelope,
	sessionId: string,
	error?: unknown,
): HubReplyEnvelope {
	const message =
		error instanceof Error && error.message.trim()
			? error.message
			: `Unknown session: ${sessionId}`;
	return errorReply(envelope, SESSION_NOT_FOUND_ERROR_CODE, message);
}

function parseTurnMode(mode?: unknown): AgentMode | undefined {
	// Unknown truthy values flow through and formatModePrompt treats them as act.
	return mode ? (mode as AgentMode) : undefined;
}

function parseRunTimeoutMs(
	payload: Record<string, unknown>,
): number | undefined {
	const timeoutMs =
		typeof payload.timeoutMs === "number"
			? payload.timeoutMs
			: typeof payload.timeout_ms === "number"
				? payload.timeout_ms
				: undefined;
	if (timeoutMs && Number.isFinite(timeoutMs) && timeoutMs > 0) {
		return Math.floor(timeoutMs);
	}
	const timeoutSeconds =
		typeof payload.timeoutSeconds === "number"
			? payload.timeoutSeconds
			: typeof payload.timeout_seconds === "number"
				? payload.timeout_seconds
				: undefined;
	if (timeoutSeconds && Number.isFinite(timeoutSeconds) && timeoutSeconds > 0) {
		return Math.floor(timeoutSeconds * 1000);
	}
	return undefined;
}

async function runTurnWithRuntimeHealth(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
	input: SendSessionInput,
	timeoutMs: number | undefined,
): Promise<AgentResult | undefined> {
	const startedAt = performance.now();
	let settled = false;
	const baseContext = {
		command: envelope.command,
		requestId: envelope.requestId,
		clientId: envelope.clientId,
		sessionId: input.sessionId,
		timeoutMs,
	};
	const heartbeat = setInterval(() => {
		if (settled) return;
		const elapsedMs = Math.round(performance.now() - startedAt);
		logHubMessage("warn", "run.heartbeat", {
			...baseContext,
			elapsedMs,
		});
		ctx.publish(
			ctx.buildEvent(
				"run.heartbeat",
				{
					requestId: envelope.requestId,
					elapsedMs,
					...(timeoutMs ? { timeoutMs } : {}),
				},
				input.sessionId,
			),
		);
	}, HUB_RUN_HEARTBEAT_MS);
	const runPromise = ctx.sessionHost.runTurn(input);
	runPromise.then(
		(result) => {
			if (!settled) return;
			logHubMessage("warn", "run.late_end", {
				...baseContext,
				elapsedMs: Math.round(performance.now() - startedAt),
				finishReason: result?.finishReason,
			});
		},
		(error) => {
			if (!settled) return;
			logHubMessage("error", "run.late_error", {
				...baseContext,
				elapsedMs: Math.round(performance.now() - startedAt),
				error,
			});
		},
	);
	let timeout: ReturnType<typeof setTimeout> | undefined;
	try {
		if (!timeoutMs) {
			return await runPromise;
		}
		return await Promise.race([
			runPromise,
			new Promise<never>((_, reject) => {
				timeout = setTimeout(() => {
					const reason = `Hub run ${envelope.command} timed out after ${timeoutMs}ms.`;
					settled = true;
					clearInterval(heartbeat);
					reject(new Error(reason));
					logHubMessage("error", "run.timeout", {
						...baseContext,
						elapsedMs: Math.round(performance.now() - startedAt),
					});
					cancelPendingApprovals(
						ctx,
						(approval) => approval.sessionId === input.sessionId,
						reason,
					);
					cancelPendingCapabilityRequests(
						ctx,
						(request) => request.sessionId === input.sessionId,
						reason,
					);
					void ctx.sessionHost.abort(input.sessionId, reason).catch((error) => {
						logHubMessage("error", "run.timeout_abort_failed", {
							...baseContext,
							error,
						});
					});
				}, timeoutMs);
			}),
		]);
	} finally {
		settled = true;
		clearInterval(heartbeat);
		if (timeout) clearTimeout(timeout);
	}
}

export async function handleSessionInput(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): Promise<HubReplyEnvelope> {
	const sessionId = extractSessionId(envelope);
	const payload =
		envelope.payload && typeof envelope.payload === "object"
			? envelope.payload
			: {};
	const prompt =
		typeof payload.prompt === "string"
			? payload.prompt
			: typeof payload.input === "string"
				? payload.input
				: "";
	if (!prompt.trim()) {
		return errorReply(
			envelope,
			"invalid_session_input",
			"session input requires a prompt string",
		);
	}
	ctx.publish(ctx.buildEvent("run.started", undefined, sessionId));
	const attachments =
		payload.attachments &&
		typeof payload.attachments === "object" &&
		!Array.isArray(payload.attachments)
			? (payload.attachments as Record<string, unknown>)
			: undefined;
	const userFiles = Array.isArray(attachments?.userFiles)
		? attachments.userFiles.filter((filePath) => typeof filePath === "string")
		: undefined;
	const timeoutMs = parseRunTimeoutMs(payload);
	ctx.suppressNextTerminalEventBySession.set(sessionId, "run.start.reply");
	let result: AgentResult | undefined;
	try {
		result = await runTurnWithRuntimeHealth(
			ctx,
			envelope,
			{
				sessionId,
				prompt,
				mode: parseTurnMode(payload.mode),
				delivery:
					payload.delivery === "queue" || payload.delivery === "steer"
						? payload.delivery
						: undefined,
				userImages: Array.isArray(attachments?.userImages)
					? (attachments.userImages as string[])
					: undefined,
				userFiles,
				timeoutMs,
			},
			timeoutMs,
		);
	} catch (error) {
		if (
			ctx.suppressNextTerminalEventBySession.get(sessionId) ===
			"run.start.reply"
		) {
			ctx.suppressNextTerminalEventBySession.delete(sessionId);
		}
		if (isSessionNotFoundError(error)) {
			return sessionNotFoundReply(envelope, sessionId, error);
		}
		ctx.publish(
			ctx.buildEvent(
				"run.failed",
				{
					reason: "error",
					error: error instanceof Error ? error.message : String(error),
				},
				sessionId,
			),
		);
		throw error;
	}
	if (result) {
		const snapshot = await readCoreSessionSnapshot(ctx, sessionId);
		const error = errorMessageForResult(result);
		ctx.publish(
			ctx.buildEvent(
				terminalRunEventForReason(result.finishReason),
				{
					reason: result.finishReason,
					...(error ? { error } : {}),
					result,
					...(snapshot ? { snapshot } : {}),
				},
				sessionId,
			),
		);
		if (
			ctx.suppressNextTerminalEventBySession.get(sessionId) ===
			"run.start.reply"
		) {
			ctx.suppressNextTerminalEventBySession.delete(sessionId);
		}
	} else {
		ctx.suppressNextTerminalEventBySession.delete(sessionId);
	}
	const snapshot = await readCoreSessionSnapshot(ctx, sessionId);
	return okReply(
		envelope,
		result || snapshot
			? { ...(result ? { result } : {}), ...(snapshot ? { snapshot } : {}) }
			: undefined,
	);
}

export async function handleRunAbort(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): Promise<HubReplyEnvelope> {
	const sessionId = extractSessionId(envelope);
	const reason =
		typeof envelope.payload?.reason === "string"
			? envelope.payload.reason
			: "Run was aborted before pending approval or capability request was resolved.";
	cancelPendingApprovals(
		ctx,
		(approval) => approval.sessionId === sessionId,
		reason,
	);
	try {
		await ctx.sessionHost.abort(sessionId, envelope.payload?.reason);
	} catch (error) {
		logHubMessage("warn", "run.abort_failed", {
			command: envelope.command,
			requestId: envelope.requestId,
			clientId: envelope.clientId,
			sessionId,
			error,
		});
	} finally {
		cancelPendingCapabilityRequests(
			ctx,
			(request) => request.sessionId === sessionId,
			reason,
		);
	}
	return okReply(envelope, { applied: true });
}

export async function handleSessionHook(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): Promise<HubReplyEnvelope> {
	const parsed = parseHookEventPayload(envelope.payload?.payload);
	if (!parsed) {
		return errorReply(
			envelope,
			"invalid_hook_payload",
			"session.hook requires a valid hook event payload",
		);
	}
	await ctx.sessionHost.dispatchHookEvent(parsed);
	return okReply(envelope, { applied: true });
}

import type { TeamProgressProjectionEvent } from "@cline/shared";
import type { SessionUsageSummary } from "../../../runtime/host/runtime-host";
import type {
	CoreSessionEvent,
	SessionPendingPrompt,
} from "../../../types/events";
import { buildCompletionNotification } from "../hub-notifications";
import {
	type HubTransportContext,
	readCoreSessionSnapshot,
	readHubSessionRecord,
} from "./context";

/**
 * Translates internal `CoreSessionEvent`s emitted by the session host into the
 * outward-facing `HubEventEnvelope` stream.
 */
export async function projectSessionEvent(
	ctx: HubTransportContext,
	event: CoreSessionEvent,
): Promise<void> {
	switch (event.type) {
		case "chunk":
			// Ignore raw agent chunks here. In this runtime they can contain
			// serialized event envelopes rather than user-facing assistant text.
			// Structured live content is forwarded via the "agent_event" branch.
			return;
		case "agent_event":
			await projectAgentEvent(ctx, event);
			return;
		case "hook":
			if (event.payload.hookEventName === "tool_call") {
				ctx.publish(
					ctx.buildEvent(
						"tool.started",
						{ toolName: event.payload.toolName },
						event.payload.sessionId,
					),
				);
			} else if (event.payload.hookEventName === "tool_result") {
				ctx.publish(
					ctx.buildEvent(
						"tool.finished",
						{ toolName: event.payload.toolName },
						event.payload.sessionId,
					),
				);
			}
			return;
		case "team_progress": {
			const projection: TeamProgressProjectionEvent = {
				type: "team_progress_projection",
				version: 1,
				sessionId: event.payload.sessionId,
				summary: event.payload.summary,
				lastEvent: event.payload.lifecycle,
			};
			ctx.publish(
				ctx.buildEvent(
					"team.progress",
					projection as unknown as Record<string, unknown>,
					event.payload.sessionId,
				),
			);
			return;
		}
		case "pending_prompts":
			ctx.publish(
				ctx.buildEvent(
					"session.pending_prompts",
					{
						sessionId: event.payload.sessionId,
						prompts: event.payload.prompts,
					},
					event.payload.sessionId,
				),
			);
			return;
		case "pending_prompt_submitted": {
			const prompt: SessionPendingPrompt = {
				id: event.payload.id,
				prompt: event.payload.prompt,
				delivery: event.payload.delivery,
				attachmentCount: event.payload.attachmentCount,
				userImages: event.payload.userImages,
				userFiles: event.payload.userFiles,
			};
			ctx.publish(
				ctx.buildEvent(
					"session.pending_prompt_submitted",
					{ sessionId: event.payload.sessionId, prompt },
					event.payload.sessionId,
				),
			);
			return;
		}
		case "session_snapshot":
			ctx.publish(
				ctx.buildEvent(
					"session.updated",
					{
						sessionId: event.payload.sessionId,
						snapshot: event.payload.snapshot,
					},
					event.payload.sessionId,
				),
			);
			return;
		case "status": {
			const [session, snapshot] = await Promise.all([
				readHubSessionRecord(ctx, event.payload.sessionId),
				readCoreSessionSnapshot(ctx, event.payload.sessionId),
			]);
			if (session) {
				ctx.publish(
					ctx.buildEvent(
						"session.updated",
						{ session, ...(snapshot ? { snapshot } : {}) },
						event.payload.sessionId,
					),
				);
			}
			return;
		}
		case "ended":
			await projectSessionEnded(ctx, event);
			return;
		default:
			return;
	}
}

async function projectAgentEvent(
	ctx: HubTransportContext,
	event: Extract<CoreSessionEvent, { type: "agent_event" }>,
): Promise<void> {
	const { sessionId, event: agentEvent } = event.payload;
	if (agentEvent.type === "iteration_start") {
		ctx.publish(
			ctx.buildEvent(
				"iteration.started",
				{ iteration: agentEvent.iteration },
				sessionId,
			),
		);
		return;
	}
	if (agentEvent.type === "iteration_end") {
		ctx.publish(
			ctx.buildEvent(
				"iteration.finished",
				{
					iteration: agentEvent.iteration,
					hadToolCalls: agentEvent.hadToolCalls,
					toolCallCount: agentEvent.toolCallCount,
				},
				sessionId,
			),
		);
		return;
	}
	if (agentEvent.type === "content_start") {
		if (
			agentEvent.contentType === "text" &&
			typeof agentEvent.text === "string" &&
			agentEvent.text.length > 0
		) {
			ctx.publish(
				ctx.buildEvent("assistant.delta", { text: agentEvent.text }, sessionId),
			);
			return;
		}
		if (agentEvent.contentType === "reasoning") {
			if (agentEvent.redacted && !agentEvent.reasoning) {
				ctx.publish(
					ctx.buildEvent(
						"reasoning.delta",
						{ text: "", redacted: true },
						sessionId,
					),
				);
				return;
			}
			if (
				typeof agentEvent.reasoning === "string" &&
				agentEvent.reasoning.length > 0
			) {
				ctx.publish(
					ctx.buildEvent(
						"reasoning.delta",
						{
							text: agentEvent.reasoning,
							redacted: agentEvent.redacted === true,
						},
						sessionId,
					),
				);
			}
			return;
		}
		if (agentEvent.contentType === "tool") {
			ctx.publish(
				ctx.buildEvent(
					"tool.started",
					{
						toolCallId: agentEvent.toolCallId,
						toolName: agentEvent.toolName,
						input: agentEvent.input,
					},
					sessionId,
				),
			);
			return;
		}
	}
	if (agentEvent.type === "content_end") {
		switch (agentEvent.contentType) {
			case "text":
				ctx.publish(
					ctx.buildEvent(
						"assistant.finished",
						{ text: agentEvent.text },
						sessionId,
					),
				);
				break;
			case "reasoning":
				ctx.publish(
					ctx.buildEvent(
						"reasoning.finished",
						{ reasoning: agentEvent.reasoning },
						sessionId,
					),
				);
				break;
			case "tool":
				ctx.publish(
					ctx.buildEvent(
						"tool.finished",
						{
							toolCallId: agentEvent.toolCallId,
							toolName: agentEvent.toolName,
							output: agentEvent.output,
							error: agentEvent.error,
						},
						sessionId,
					),
				);
				break;
		}
		return;
	}
	if (agentEvent.type === "notice") {
		ctx.publish(
			ctx.buildEvent(
				"session.notice",
				{
					sessionId,
					message: agentEvent.message,
					noticeType: agentEvent.noticeType,
					...(agentEvent.displayRole
						? { displayRole: agentEvent.displayRole }
						: {}),
					...(agentEvent.reason ? { reason: agentEvent.reason } : {}),
					...(agentEvent.metadata ? { metadata: agentEvent.metadata } : {}),
					agent: {
						kind:
							event.payload.teamRole === "teammate"
								? "teammate"
								: agentEvent.parentAgentId
									? "subagent"
									: "lead",
						agentId: agentEvent.agentId,
						conversationId: agentEvent.conversationId,
						parentAgentId: agentEvent.parentAgentId,
						teamAgentId: event.payload.teamAgentId,
						teamRole: event.payload.teamRole,
					},
				},
				sessionId,
			),
		);
		return;
	}
	if (agentEvent.type === "usage") {
		let usageSummary: SessionUsageSummary | undefined;
		try {
			usageSummary = await ctx.sessionHost.getAccumulatedUsage?.(sessionId);
		} catch {
			usageSummary = undefined;
		}
		ctx.publish(
			ctx.buildEvent(
				"usage.updated",
				{
					sessionId,
					delta: {
						inputTokens: agentEvent.inputTokens,
						outputTokens: agentEvent.outputTokens,
						cacheReadTokens: agentEvent.cacheReadTokens ?? 0,
						cacheWriteTokens: agentEvent.cacheWriteTokens ?? 0,
						totalCost: agentEvent.cost ?? 0,
					},
					totals: {
						inputTokens: agentEvent.totalInputTokens,
						outputTokens: agentEvent.totalOutputTokens,
						cacheReadTokens: agentEvent.totalCacheReadTokens ?? 0,
						cacheWriteTokens: agentEvent.totalCacheWriteTokens ?? 0,
						totalCost: agentEvent.totalCost ?? 0,
					},
					usage: usageSummary?.usage,
					aggregateUsage: usageSummary?.aggregateUsage,
					agent: {
						kind:
							event.payload.teamRole === "teammate"
								? "teammate"
								: agentEvent.parentAgentId
									? "subagent"
									: "lead",
						agentId: agentEvent.agentId,
						conversationId: agentEvent.conversationId,
						parentAgentId: agentEvent.parentAgentId,
						teamAgentId: event.payload.teamAgentId,
						teamRole: event.payload.teamRole,
					},
				},
				sessionId,
			),
		);
		return;
	}
	if (agentEvent.type === "done") {
		ctx.publish(
			ctx.buildEvent(
				"agent.done",
				{
					reason: agentEvent.reason,
					text: agentEvent.text,
					iterations: agentEvent.iterations,
					usage: agentEvent.usage,
				},
				sessionId,
			),
		);
	}
}

async function projectSessionEnded(
	ctx: HubTransportContext,
	event: Extract<CoreSessionEvent, { type: "ended" }>,
): Promise<void> {
	// `run.start` publishes the result-bearing terminal event after `send`
	// returns. The local runtime emits `ended` synchronously during that send, so
	// this token suppresses the earlier projector event. If session events move
	// to an async transport, terminal-event correlation must move with them.
	const suppressToken = ctx.suppressNextTerminalEventBySession.get(
		event.payload.sessionId,
	);
	const suppressDuplicateTerminalEvent =
		suppressToken === event.payload.reason ||
		suppressToken === "run.start.reply";
	if (suppressDuplicateTerminalEvent) {
		ctx.suppressNextTerminalEventBySession.delete(event.payload.sessionId);
	}
	const [session, snapshot] = await Promise.all([
		readHubSessionRecord(ctx, event.payload.sessionId),
		readCoreSessionSnapshot(ctx, event.payload.sessionId),
	]);
	if (event.payload.reason === "completed") {
		const notification = await buildCompletionNotification(session);
		ctx.publish(
			ctx.buildEvent("ui.notify", notification, event.payload.sessionId),
		);
	}
	if (suppressDuplicateTerminalEvent) {
		return;
	}
	ctx.publish(
		ctx.buildEvent(
			event.payload.reason === "aborted"
				? "run.aborted"
				: event.payload.reason === "error" || event.payload.reason === "failed"
					? "run.failed"
					: "run.completed",
			{ reason: event.payload.reason, ...(snapshot ? { snapshot } : {}) },
			event.payload.sessionId,
		),
	);
}

import { describe, expect, it } from "vitest";
