		const readSessionManifest = vi.fn().mockResolvedValue(diskManifest);
		(sessionService as Record<string, unknown>).readSessionManifest =
			readSessionManifest;

		await manager.updateSessionConnection(sessionId, {
			providerId: "openai",
			modelId: "codex-test",
		});

