	// ── Turn execution ──────────────────────────────────────────────────

	private async executeTurn(
		session: ActiveSession,
		input: {
			prompt: string;
			mode?: SendSessionInput["mode"];
			userImages?: string[];
			userFiles?: string[];
		},
	): Promise<AgentResult> {
		const preparedInput = await this.prepareTurnInput(session, input);
		const prompt = preparedInput.prompt.trim();
		const images = preparedInput?.userImages?.length;
		const files = preparedInput?.userFiles?.length;
		if (!prompt && !images && !files) throw new Error("prompt cannot be empty");

		if (!session.artifacts && !session.pendingPrompt) {
			session.pendingPrompt = prompt;
		}
		await this.ensureSessionPersisted(session);
		await this.refreshActiveSessionGitMetadata(session);
		await this.syncOAuthCredentials(session);
		await this.markTurnRunning(session);

		try {
			let result = await this.executeAgentTurn(
				session,
				prompt,
				preparedInput.userImages,
				preparedInput.userFiles,
			);

			while (shouldAutoContinueTeamRuns(session, result.finishReason)) {
				const updates = await waitForTeamRunUpdates(session);
				if (updates.length === 0) break;
				const continuationPrompt = buildTeamRunContinuationPrompt(
					session,
					updates,
				);
				result = await this.executeAgentTurn(session, continuationPrompt);
			}

			return result;
		} finally {
			await this.refreshActiveSessionGitMetadata(session);
		}
	}

	private async completeInteractiveTurn(
		session: ActiveSession,
		finishReason: AgentResult["finishReason"],
	): Promise<void> {
		if (hasPendingTeamRunWork(session)) return;
		session.lastInteractiveTurnFinishReason = finishReason;
		await this.markTurnIdle(session);
		session.aborting = false;
	}

	private resolveInteractiveStopStatus(session: ActiveSession): SessionStatus {
		const finishReason = session.lastInteractiveTurnFinishReason;
		if (!finishReason) return "cancelled";

		switch (finishReason) {
			case "completed":
				return "completed";
			case "error":
				return "failed";
			case "aborted":
			case "max_iterations":
			case "mistake_limit":
				return "cancelled";
		}

		const _exhaustive: never = finishReason;
		return _exhaustive;
	}

	private resolveInteractiveStopExitCode(session: ActiveSession): number {
		return session.lastInteractiveTurnFinishReason === "error" ? 1 : 0;
	}

	private async completeAbortedInteractiveTurn(
		session: ActiveSession,
	): Promise<AgentResult> {
		const endedAt = new Date();
		const messages = session.agent.getMessages();
		const usage = createInitialAccumulatedUsage();
		session.persistedMessages = messages;
		session.started = session.started || messages.length > 0;
		this.eventBridge.dispatchAgentEvent(session.sessionId, session.config, {
			type: "done",
			reason: "aborted",
			text: "",
			iterations: 0,
			usage,
		});
		await this.completeInteractiveTurn(session, "aborted");
		return {
			text: "",
			usage,
			messages,
			toolCalls: [],
			iterations: 0,
			finishReason: "aborted",
			model: {
				id: session.config.modelId,
				provider: session.config.providerId,
			},
			startedAt: endedAt,
			endedAt,
			durationMs: 0,
		};
	}

	private async executeAgentTurn(
		session: ActiveSession,
		prompt: string,
		userImages?: string[],
		userFiles?: string[],
	): Promise<AgentResult> {
		const shouldContinue =
			session.started || session.agent.getMessages().length > 0;
		const baselineMessages =
			session.persistedMessages ?? session.agent.getMessages();
		const usageBaseline =
			this.usageBySession.get(session.sessionId) ??
			createInitialAccumulatedUsage();
		const aggregateUsageBaseline =
			this.aggregateUsageBySession.get(session.sessionId) ?? usageBaseline;
		session.turnUsageBaseline = usageBaseline;
		session.turnAggregateUsageBaseline = aggregateUsageBaseline;
		session.turnPrimaryUsage = createInitialAccumulatedUsage();
		session.turnUsageByAgent = new Map<string, SessionAccumulatedUsage>();

		captureModeSwitch(
			session.config.telemetry,
			session.sessionId,
			session.config.mode,
		);
		captureConversationTurnEvent(session.config.telemetry, {
			ulid: session.sessionId,
			provider: session.config.providerId,
			model: session.config.modelId,
			source: "user",
			mode: session.config.mode,
			...this.getSessionAgentTelemetryIdentity(session),
		});

		try {
			const runFn = shouldContinue
				? () => session.agent.continue(prompt, userImages, userFiles)
				: () => session.agent.run(prompt, userImages, userFiles);
			const result = await this.runWithAuthRetry(
				session,
				runFn,
				baselineMessages,
			);

			session.started = true;
			const persistedMessages = withLatestAssistantTurnMetadata(
				result.messages,
				result,
				baselineMessages,
			);
			session.persistedMessages = persistedMessages;
			const teammateTurnUsage = sumUsageTotals(
				session.turnUsageByAgent?.values() ?? [],
			);
			const accumulatedUsage = accumulateUsageTotals(
				usageBaseline,
				result.usage,
			);
			const aggregateTurnUsage = accumulateUsageTotals(
				accumulateUsageTotals(createInitialAccumulatedUsage(), result.usage),
				teammateTurnUsage,
			);
			const aggregateUsage = accumulateUsageTotals(
				aggregateUsageBaseline,
				aggregateTurnUsage,
			);
			this.usageBySession.set(session.sessionId, accumulatedUsage);
			this.aggregateUsageBySession.set(session.sessionId, aggregateUsage);
			await this.persistSessionMetadata(session.sessionId, (current) => ({
				...(current ?? {}),
				totalCost: accumulatedUsage.totalCost,
				aggregatedAgentsCost: aggregateUsage.totalCost,
				usage: accumulatedUsage,
				aggregateUsage,
			}));
			await this.invoke<void>(
				"persistSessionMessages",
				session.sessionId,
				persistedMessages,
				session.config.systemPrompt,
			);
			this.observeTaskCompletionTool(session, result);
			return result;
		} catch (error) {
			captureSdkError(session.config.telemetry, {
				component: "core",
				operation: "session.turn",
				error,
				severity: "error",
				handled: false,
				context: {
					sessionId: session.sessionId,
					providerId: session.config.providerId,
					modelId: session.config.modelId,
				},
			});
			await this.invoke<void>(
				"persistSessionMessages",
				session.sessionId,
				session.agent.getMessages(),
				session.config.systemPrompt,
			);
			throw error;
		} finally {
			session.turnUsageBaseline = undefined;
			session.turnAggregateUsageBaseline = undefined;
			session.turnPrimaryUsage = undefined;
			session.turnUsageByAgent = undefined;
		}
	}

	/**
	 * Anchor `task.completed` telemetry to the assistant's explicit
	 * completion declaration. We emit at most once per session, the moment
	 * a successful `submit_and_exit` tool call is observed in the run
	 * result. This is the SDK analog of original Cline's
	 * `attempt_completion`-driven emission and works for both interactive
	 * and non-interactive sessions.
	 *
	 * `shutdownSession(...)` retains a fallback emission for completed
	 * sessions that finish without an explicit completion-tool observation
	 * (e.g., non-interactive runs not using the yolo preset). This helper
	 * sets `submitAndExitObserved` so the shutdown fallback can suppress a
	 * duplicate emission for the same logical completion.
	 */
	private observeTaskCompletionTool(
		session: ActiveSession,
		result: AgentResult,
	): void {
		if (session.submitAndExitObserved) return;
		const completedWithSubmitAndExit = result.toolCalls.some(
			(call) =>
				call.name === DefaultToolNames.SUBMIT_AND_EXIT &&
				call.error === undefined,
		);
		if (!completedWithSubmitAndExit) return;
		session.submitAndExitObserved = true;
		captureTaskCompleted(session.config.telemetry, {
			ulid: session.sessionId,
			provider: session.config.providerId,
			modelId: session.config.modelId,
			mode: session.config.mode,
			durationMs: Date.now() - Date.parse(session.startedAt),
			source: "submit_and_exit",
			...this.getSessionAgentTelemetryIdentity(session),
		});
	}

	private async prepareTurnInput(
		session: ActiveSession,
		input: {
			prompt: string;
			mode?: SendSessionInput["mode"];
			userImages?: string[];
			userFiles?: string[];
		},
	): Promise<PreparedTurnInput> {
		const mentionBaseDir = resolveWorkspacePath(session.config);
		const normalizedPrompt = normalizeUserInput(input.prompt).trim();
		if (!normalizedPrompt) {
			return {
				prompt: "",
				userImages: input.userImages,
				userFiles: this.resolveAbsoluteFilePaths(
					session.config.cwd,
					input.userFiles,
				),
			};
		}

		const enriched = await enrichPromptWithMentions(
			normalizedPrompt,
			mentionBaseDir,
		);
		emitMentionTelemetry(session.config.telemetry, enriched);

		const prompt = formatModePrompt(
			enriched.prompt,
			input.mode ?? session.config.mode,
		);
		const explicitUserFiles = this.resolveAbsoluteFilePaths(
			session.config.cwd,
			input.userFiles,
		);
		const mentionedFiles = this.resolveAbsoluteFilePaths(
			mentionBaseDir,
			enriched.matchedFiles,
		);
		const mergedUserFiles = Array.from(
			new Set([...explicitUserFiles, ...mentionedFiles]),
		);

		return {
			prompt,
			userImages: input.userImages,
			userFiles: mergedUserFiles.length > 0 ? mergedUserFiles : undefined,
		};
	}

	// ── Session lifecycle ───────────────────────────────────────────────

	private async ensureSessionPersisted(session: ActiveSession): Promise<void> {
		if (session.artifacts) return;
		const workspacePath = resolveWorkspacePath(session.config);
		session.artifacts = (await this.invoke("createRootSessionWithArtifacts", {
			sessionId: session.sessionId,
			source: session.source,
			pid: process.pid,
			interactive: session.interactive,
			provider: session.config.providerId,
			model: session.config.modelId,
			cwd: session.config.cwd,
			workspaceRoot: workspacePath,
			teamName: session.config.teamName,
			enableTools: session.config.enableTools,
			enableSpawn: session.config.enableSpawnAgent,
			enableTeams: session.config.enableAgentTeams,
			prompt: session.pendingPrompt,
			metadata: session.sessionMetadata,
			startedAt: session.startedAt,
		})) as RootSessionArtifacts;
	}

	private async markTurnRunning(session: ActiveSession): Promise<void> {
		if (session.status === "running") return;
		await this.updateStatus(session, "running", null);
	}

	private async refreshActiveSessionGitMetadata(
		session: ActiveSession,
		knownState?: GitWorkspaceState,
	): Promise<void> {
		try {
			const state =
				knownState ??
				(await readGitWorkspaceState(resolveWorkspacePath(session.config)));
			if (!state || !session.artifacts) return;
			if (
				hasCurrentSessionGitMetadata(session.artifacts.manifest.metadata, state)
			) {
				return;
			}
			await this.persistSessionMetadata(session.sessionId, (current) =>
				withSessionGitMetadata(
					{
						...(current ?? {}),
						...(session.sessionMetadata ?? {}),
					},
					state,
				),
			);
		} catch (error) {
			session.config.logger?.debug?.("Failed to refresh session git metadata", {
				sessionId: session.sessionId,
				error,
			});
		}
	}

	private async markTurnPending(session: ActiveSession): Promise<void> {
		if (session.status === "pending") return;
		await this.updateStatus(session, "pending", null);
	}

	private async markTurnIdle(session: ActiveSession): Promise<void> {
		if (session.status === "idle") return;
		await this.updateStatus(session, "idle", null);
	}

	private async persistSessionMetadata(
		sessionId: string,
		resolveMetadata: (
			current: Record<string, unknown> | undefined,
		) => Record<string, unknown> | undefined,
	): Promise<void> {
		const session = this.sessions.get(sessionId);
		const currentManifest =
			(await this.invokeOptionalValue<SessionManifest>(
				"readSessionManifest",
				sessionId,
			)) ?? session?.artifacts?.manifest;
		const metadata = resolveMetadata(
			currentManifest?.metadata as Record<string, unknown> | undefined,
		);
		if (!session?.artifacts) {
			return;
		}
		const result = await this.invokeOptionalValue<{ updated?: boolean }>(
			"updateSession",
			{
				sessionId,
				metadata,
			},
		);
		if (result?.updated === false) {
			return;
		}
		session.sessionMetadata = metadata;
		session.artifacts.manifest.metadata = metadata;
	}

	private async finalizeSingleRun(
		session: ActiveSession,
		finishReason: AgentResult["finishReason"],
	): Promise<void> {
		if (hasPendingTeamRunWork(session)) return;
		const isAborted = finishReason === "aborted" || session.aborting;
		const isError = finishReason === "error";
		await this.shutdownSession(session, {
			status: isAborted ? "cancelled" : isError ? "failed" : "completed",
			exitCode: isError ? 1 : 0,
			shutdownReason: isError ? "session_error" : "session_complete",
			endReason: finishReason,
		});
	}

	private async failSession(session: ActiveSession): Promise<void> {
		await this.shutdownSession(session, {
			status: "failed",
			exitCode: 1,
			shutdownReason: "session_error",
			endReason: "error",
		});
	}

	private async shutdownSession(
		session: ActiveSession,
		input: {
			status: SessionStatus;
			exitCode: number | null;
			shutdownReason: string;
			endReason: string;
		},
	): Promise<void> {
		// Fallback `task.completed` emission for completed sessions that
		// did not observe an explicit `submit_and_exit` tool call. The
		// observer in `executeAgentTurn(...)` already emitted the event in
		// that case, so we suppress here to avoid double-counting.
		if (input.status === "completed" && !session.submitAndExitObserved) {
			captureTaskCompleted(session.config.telemetry, {
				ulid: session.sessionId,
				provider: session.config.providerId,
				modelId: session.config.modelId,
				mode: session.config.mode,
				durationMs: Date.now() - Date.parse(session.startedAt),
				source: "shutdown",
				...this.getSessionAgentTelemetryIdentity(session),
			});
		}
		notifyTeamRunWaiters(session);

		const cleanupErrors: unknown[] = [];
		const recordCleanupError = (stage: string, error: unknown) => {
			cleanupErrors.push(error);
			session.config.logger?.log("Session shutdown cleanup failed", {
				sessionId: session.sessionId,
				stage,
				error,
				severity: "warn",
			});
			captureSdkError(session.config.telemetry, {
				component: "core",
				operation: "session.shutdown_cleanup",
				error,
				severity: "warn",
				handled: true,
				context: {
					sessionId: session.sessionId,
					stage,
					status: input.status,
					shutdownReason: input.shutdownReason,
					providerId: session.config.providerId,
					modelId: session.config.modelId,
				},
			});
		};

		if (session.artifacts) {
			await this.refreshActiveSessionGitMetadata(session);
			try {
				await this.updateStatus(session, input.status, input.exitCode);
			} catch (error) {
				recordCleanupError("update_status", error);
			}
			try {
				await session.agent.shutdown(input.shutdownReason);
			} catch (error) {
				recordCleanupError("agent_shutdown", error);
			}
		}
		try {
			await Promise.resolve(session.runtime.shutdown(input.shutdownReason));
		} catch (error) {
			recordCleanupError("runtime_shutdown", error);
		}
		try {
			await session.pluginSandboxShutdown?.();
		} catch (error) {
			recordCleanupError("plugin_sandbox_shutdown", error);
		}
		this.sessions.delete(session.sessionId);
		this.emit({
			type: "ended",
			payload: {
				sessionId: session.sessionId,
				reason: input.endReason,
				ts: Date.now(),
			},
		});
		if (cleanupErrors.length > 0 && input.status === "failed") {
			throw cleanupErrors[0];
		}
	}

	private async releaseSessionRuntime(
		session: ActiveSession,
		reason: string,
	): Promise<void> {
		const cleanupErrors: unknown[] = [];
		const recordCleanupError = (stage: string, error: unknown) => {
			cleanupErrors.push(error);
			session.config.logger?.log("Session runtime cleanup failed", {
				sessionId: session.sessionId,
				stage,
				error,
				severity: "warn",
			});
			captureSdkError(session.config.telemetry, {
				component: "core",
				operation: "session.runtime_cleanup",
				error,
				severity: "warn",
				handled: true,
				context: {
					sessionId: session.sessionId,
					stage,
					reason,
					providerId: session.config.providerId,
					modelId: session.config.modelId,
				},
			});
		};

		try {
			await session.agent.shutdown(reason);
		} catch (error) {
			recordCleanupError("agent_shutdown", error);
		}
		try {
			await Promise.resolve(session.runtime.shutdown(reason));
		} catch (error) {
			recordCleanupError("runtime_shutdown", error);
		}
		try {
			await session.pluginSandboxShutdown?.();
		} catch (error) {
			recordCleanupError("plugin_sandbox_shutdown", error);
		}
		this.sessions.delete(session.sessionId);
		if (cleanupErrors.length > 0) {
			throw cleanupErrors[0];
		}
	}

	private async updateStatus(
		session: ActiveSession,
		status: SessionStatus,
		exitCode?: number | null,
	): Promise<void> {
		if (!session.artifacts) return;
		const result = await this.invoke<{ updated: boolean; endedAt?: string }>(
			"updateSessionStatus",
			session.sessionId,
			status,
			exitCode,
		);
		if (!result.updated) return;
		const latestManifest = await this.mutateSessionManifest(
			session,
			(manifest) => {
				manifest.status = status;
				if (isNonTerminalSessionStatus(status)) {
					delete manifest.ended_at;
					manifest.exit_code = null;
				} else {
					manifest.ended_at = result.endedAt ?? nowIso();
					manifest.exit_code = typeof exitCode === "number" ? exitCode : null;
				}
			},
		);
		if (!latestManifest) return;
		session.status = status;
		session.updatedAt = result.endedAt ?? nowIso();
		session.endedAt = isNonTerminalSessionStatus(status)
			? null
			: latestManifest.ended_at;
		session.exitCode = latestManifest.exit_code;
		this.emitStatus(session.sessionId, status);
	}

	// ── OAuth & auth ────────────────────────────────────────────────────

	private async runWithAuthRetry(
		session: ActiveSession,
		run: () => Promise<AgentResult>,
		baselineMessages: LlmsProviders.Message[],
	): Promise<AgentResult> {
		try {
			return await run();
		} catch (error) {
			if (
				!isOAuthProvider(session.config.providerId) ||
				!isLikelyAuthError(error)
			) {
				throw error;
			}
			await this.syncOAuthCredentials(session, { forceRefresh: true });
			session.agent.restore(baselineMessages);
			return run();
		}
	}

	private async syncOAuthCredentials(
		session: ActiveSession,
		options?: { forceRefresh?: boolean },
	): Promise<void> {
		let resolved: RuntimeOAuthResolution | null = null;
		try {
			resolved = await this.oauthTokenManager.resolveProviderApiKey({
				providerId: session.config.providerId,
				forceRefresh: options?.forceRefresh,
			});
		} catch (error) {
			if (error instanceof OAuthReauthRequiredError) {
				throw new Error(`${error.providerId} requires re-authentication.`);
			}
			throw error;
		}
		if (!resolved?.apiKey || session.config.apiKey === resolved.apiKey) return;
		session.config.apiKey = resolved.apiKey;
		session.agent.updateConnection({ apiKey: resolved.apiKey });
		session.runtime.delegatedAgentConfigProvider?.updateConnectionDefaults({
			apiKey: resolved.apiKey,
		});
		session.runtime.teamRuntime?.updateTeammateConnections({
			apiKey: resolved.apiKey,
		});
	}

	// ── Utility methods ─────────────────────────────────────────────────

	private getSessionOrThrow(sessionId: string): ActiveSession {
		const session = this.sessions.get(sessionId);
		if (!session) {
			const error = new SessionNotFoundError(sessionId);
			captureSdkError(this.defaultTelemetry, {
				component: "core",
				operation: "session.active_lookup",
				error,
				severity: "warn",
				handled: true,
				context: {
					sessionId,
					activeSessionCount: this.sessions.size,
				},
			});
			throw error;
		}
		return session;
	}

	private resolveAbsoluteFilePaths(cwd: string, paths?: string[]): string[] {
		if (!paths || paths.length === 0) return [];
		const resolved = paths
			.map((p) => p.trim())
			.filter((p) => p.length > 0)
			.map((p) => (isAbsolute(p) ? p : resolve(cwd, p)));
		return Array.from(new Set(resolved));
	}

	private getSessionAgentTelemetryIdentity(session: ActiveSession) {
		return buildTelemetryAgentIdentity({
			agentId: session.agent.getAgentId(),
			conversationId: session.agent.getConversationId(),
			teamId: session.runtime.teamRuntime?.getTeamId(),
			teamName: session.runtime.teamRuntime?.getTeamName(),
			teamRole: session.runtime.teamRuntime ? "lead" : undefined,
		});
	}

	private async seedAggregateUsageFromArtifacts(input: {
		initialUsage: SessionAccumulatedUsage;
		sessionDir: string;
		rootMessagesPath: string;
		manifest: SessionManifest;
	}): Promise<SessionAccumulatedUsage> {
		const teammateUsage = await this.summarizePersistedTeammateUsage(
			input.sessionDir,
			input.rootMessagesPath,
			input.manifest.session_id,
		);
		const aggregateUsage = accumulateUsageTotals(
			input.initialUsage,
			teammateUsage,
		);
		return this.withPersistedAggregateUsageFloor(
			aggregateUsage,
			input.manifest,
		);
	}

	private async summarizePersistedTeammateUsage(
		sessionDir: string,
		rootMessagesPath: string,
		sessionId: string,
	): Promise<SessionAccumulatedUsage> {
		const rootPath = resolve(rootMessagesPath);
		const defaultRootMessagesFilename = `${sessionId}.messages.json`;
		let filenames: string[];
		try {
			filenames = readdirSync(sessionDir);
		} catch {
			return createInitialAccumulatedUsage();
		}

		let usage = createInitialAccumulatedUsage();
		for (const filename of filenames) {
			if (!filename.endsWith(".messages.json")) continue;
			if (filename === defaultRootMessagesFilename) continue;
			const messagesPath = resolve(sessionDir, filename);
			if (messagesPath === rootPath) continue;
			const messages = await readPersistedMessagesFile(messagesPath);
			if (messages.length === 0) continue;
			usage = accumulateUsageTotals(
				usage,
				summarizeUsageFromMessages(messages),
			);
		}
		return usage;
	}

	private withPersistedAggregateUsageFloor(
		usage: SessionAccumulatedUsage,
		manifest: SessionManifest,
	): SessionAccumulatedUsage {
		const persistedAggregateUsage = parseAccumulatedUsage(
			manifest.metadata?.aggregateUsage,
		);
		if (persistedAggregateUsage) {
			return maxAccumulatedUsage(usage, persistedAggregateUsage);
		}
		const aggregatedAgentsCost = manifest.metadata?.aggregatedAgentsCost;
		if (
			typeof aggregatedAgentsCost !== "number" ||
			!Number.isFinite(aggregatedAgentsCost) ||
			aggregatedAgentsCost <= usage.totalCost
		) {
			return usage;
		}
		return { ...usage, totalCost: aggregatedAgentsCost };
	}

	private emitStatus(sessionId: string, status: string): void {
		void this.emitSessionSnapshot(sessionId);
		this.emit({
			type: "status",
			payload: { sessionId, status },
		});
	}

	private async emitSessionSnapshot(sessionId: string): Promise<void> {
		const session = await this.getSession(sessionId);
		if (!session) return;
		this.emit({
			type: "session_snapshot",
			payload: {
				sessionId,
				snapshot: createCoreSessionSnapshot({
					session,
					messages: await this.readSessionMessages(sessionId),
					usage: this.usageBySession.get(sessionId),
					aggregateUsage: this.aggregateUsageBySession.get(sessionId),
				}),
			},
		});
	}

	private emit(event: CoreSessionEvent): void {
		this.events.emit(event);
	}

	private async listRows(limit: number): Promise<SessionRow[]> {
		return this.invoke<SessionRow[]>(
			"listSessions",
			Math.min(Math.max(1, Math.floor(limit)), MAX_SCAN_LIMIT),
		);
	}

	private async getRow(sessionId: string): Promise<SessionRow | undefined> {
		const target = sessionId.trim();
		if (!target) return undefined;
		const rows = await this.listRows(MAX_SCAN_LIMIT);
		return rows.find((row) => row.sessionId === target);
	}

	private async readManifest(
		sessionId: string,
	): Promise<SessionManifest | undefined> {
		const target = sessionId.trim();
		if (!target) return undefined;
		return await this.invokeOptionalValue<SessionManifest>(
			"readSessionManifest",
			target,
		);
	}

	// ── Session service invocation ──────────────────────────────────────

	private invoke<T>(method: string, ...args: unknown[]): Promise<T> {
		return invokeBackend<T>(this.sessionService, method, ...args);
	}

	private invokeOptional(method: string, ...args: unknown[]): Promise<void> {
		return invokeBackendOptional(this.sessionService, method, ...args);
	}

	private invokeOptionalValue<T = unknown>(
		method: string,
		...args: unknown[]
	): Promise<T | undefined> {
		return invokeBackendOptionalValue<T>(this.sessionService, method, ...args);
	}
}

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { readPersistedMessagesFile } from "./runtime-host-support";

const tempDirs: string[] = [];

afterEach(async () => {
	await Promise.allSettled(
		tempDirs.splice(0).map((dir) => rm(dir, { recursive: true, force: true })),
	);
});

describe("readPersistedMessagesFile", () => {
	it("returns persisted messages verbatim, wrappers included", async () => {
		// The user_input wrapper records which mode each message was sent in
		// and session restarts re-seed through this read path, so stripping
		// here would destroy that history a little more on every restart.
		// Display surfaces format for themselves via formatDisplayUserInput.
		const dir = await mkdtemp(join(tmpdir(), "runtime-host-support-"));
		tempDirs.push(dir);
		const messagesPath = join(dir, "messages.json");
		await writeFile(
			messagesPath,
			JSON.stringify([
				{
					role: "user",
					content: '<user_input mode="act">spawn a team of agents</user_input>',
				},
				{
					role: "assistant",
					content: "Working on it.",
				},
				{
					role: "user",
					content: [
						{
							type: "text",
							text: '<user_input mode="plan"><mode_notice>The user switched from act mode to plan mode before sending this message.</mode_notice>\ninspect repo</user_input>',
						},
					],
				},
			]),
			"utf8",
		);

		const messages = await readPersistedMessagesFile(messagesPath);

		expect(messages[0]?.content).toBe(
			'<user_input mode="act">spawn a team of agents</user_input>',
		);
		expect(messages[1]?.content).toBe("Working on it.");
		expect(messages[2]?.content).toEqual([
			{
				type: "text",
				text: '<user_input mode="plan"><mode_notice>The user switched from act mode to plan mode before sending this message.</mode_notice>\ninspect repo</user_input>',
			},
		]);
	});
});

import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import type * as LlmsProviders from "@cline/llms";
import type { HookEventPayload } from "../../hooks";
import type { CoreSessionEvent } from "../../types/events";
import type {
	RuntimeHostSubscribeOptions,
	SessionAccumulatedUsage,
} from "./runtime-host";

export class RuntimeHostEventBus {
	private readonly listeners = new Set<{
		listener: (event: CoreSessionEvent) => void;
		sessionId?: string;
	}>();

	subscribe(
		listener: (event: CoreSessionEvent) => void,
		options?: RuntimeHostSubscribeOptions,
	): () => void {
		const entry = {
			listener,
			sessionId: options?.sessionId?.trim() || undefined,
		};
		this.listeners.add(entry);
		return () => {
			this.listeners.delete(entry);
		};
	}

	emit(event: CoreSessionEvent): void {
		const sessionId = event.payload.sessionId?.trim();
		for (const entry of this.listeners) {
			if (entry.sessionId && entry.sessionId !== sessionId) {
				continue;
			}
			entry.listener(event);
		}
	}

	get size(): number {
		return this.listeners.size;
	}
}

// Returns the persisted messages verbatim. User messages keep their
// runtime-generated <user_input mode="..."> wrappers and <mode_notice>
// elements: they are the durable record of which mode each message was sent
// in, and session restarts re-seed new sessions through this read path, so
// stripping here would launder that history off disk (and out of the model's
// context) a little more on every restart. Display surfaces are responsible
// for their own formatting via formatDisplayUserInput.
export async function readPersistedMessagesFile(
	messagesPath?: string | null,
): Promise<LlmsProviders.Message[]> {
	const path = messagesPath?.trim();
	if (!path || !existsSync(path)) return [];
	try {
		const raw = (await readFile(path, "utf8")).trim();
		if (!raw) return [];
		const parsed = JSON.parse(raw) as unknown;
		if (Array.isArray(parsed)) {
			return parsed as LlmsProviders.Message[];
		}
		if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
			const messages = (parsed as { messages?: unknown }).messages;
			if (Array.isArray(messages)) {
				return messages as LlmsProviders.Message[];
			}
		}
		return [];
	} catch {
		return [];
	}
}

export function cloneAccumulatedUsage(
	usage: SessionAccumulatedUsage | undefined,
): SessionAccumulatedUsage | undefined {
	return usage ? { ...usage } : undefined;
}

type HookAuditBackend = {
	queueSpawnRequest(payload: HookEventPayload): Promise<void>;
	upsertSubagentSessionFromHook(
		payload: HookEventPayload,
	): Promise<string | undefined>;
	appendSubagentHookAudit(
		sessionId: string,
		payload: HookEventPayload,
	): Promise<void>;
	applySubagentStatus(
		sessionId: string,
		payload: HookEventPayload,
	): Promise<void>;
};

export async function replaySubagentHookEvent(
	payload: HookEventPayload,
	backend: HookAuditBackend,
): Promise<void> {
	const shouldTouchSessions =
		payload.hookName === "tool_call" || !!payload.parent_agent_id;
	if (!shouldTouchSessions) {
		return;
	}
	await backend.queueSpawnRequest(payload);
	const subSessionId = await backend.upsertSubagentSessionFromHook(payload);
	if (!subSessionId) {
		return;
	}
	await backend.appendSubagentHookAudit(subSessionId, payload);
	await backend.applySubagentStatus(subSessionId, payload);
}

