		expect(reviewer).toBeDefined();
		if (!reviewer) {
			throw new Error("Expected configured reviewer tool.");
		}

		const output = await reviewer.execute(
			{ prompt: "review this change" },
			{
				agentId: "parent-agent",
				conversationId: "parent-conversation",
				iteration: 1,
			},
