				message: "configured agent running",
			}),
		);
		expect(onSubAgentEnd).toHaveBeenCalledWith(
			expect.objectContaining({
				parentAgentId: "parent-agent",
				result: output,
			}),
		);

		const delegatedConfig = agentConstructorSpy.mock.calls.at(-1)?.[0] as
			| AgentConfig
			| undefined;
