		usage: {
			inputTokens: 0,
			outputTokens: 0,
			cacheReadTokens: 0,
			cacheWriteTokens: 0,
			totalCost: 0,
		},
		...overrides,
	};
}

function makeMessage(
	overrides: Partial<AgentMessage> = {},
	content: AgentMessage["content"] = [],
): AgentMessage {
	return {
		id: "msg_test",
		role: "assistant",
		content,
		createdAt: 1_000_000,
		...overrides,
