				return {
					agentId: "agent_fake",
					runId: "run_fake",
					status: "completed" as const,
					iterations: 1,
					outputText: "",
					messages: [] as readonly AgentMessage[],
					usage: {
						inputTokens: 0,
						outputTokens: 0,
						cacheReadTokens: 0,
						cacheWriteTokens: 0,
						totalCost: 0,
