		});
		const first = session.run("one");
		await Promise.resolve();
		expect(session.canStartRun()).toBe(false);
		await expect(session.continue("two")).rejects.toThrow(/"running"/i);
		release?.();
		await first;
		expect(session.canStartRun()).toBe(true);
	});
});

