	return {
		getAllFlagsAndPayloads: vi.fn(async () => ({
			featureFlags: {
				[TEST_BOOLEAN_FLAG]: true,
			},
			featureFlagPayloads: {
				[TEST_PAYLOAD_FLAG]: 1234,
			},
		})),
		enabled: true,
		getSettings: vi.fn(() => ({ enabled: true, timeoutMs: 1000 })),
		dispose: vi.fn(async () => {}),
		...overrides,
	};
}

