import { mkdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import type { AgentConfig, AgentTool, ITelemetryService } from "@cline/shared";
import { resolveGlobalSettingsPath } from "@cline/shared/storage";
import { z } from "zod";
import { captureTelemetryOptOut } from "./telemetry/core-events";

type AgentExtension = NonNullable<AgentConfig["extensions"]>[number];
type AgentExtensionApi = Parameters<NonNullable<AgentExtension["setup"]>>[0];

const GlobalSettingsStringListSchema = z
	.preprocess(
		(value) =>
			Array.isArray(value)
				? value
						.filter((entry): entry is string => typeof entry === "string")
						.map((entry) => entry.trim())
						.filter(Boolean)
				: undefined,
		z.array(z.string()).optional(),
	)
	.transform((entries) => {
		if (!entries) {
			return undefined;
		}
		const normalized = [...new Set(entries)].sort((left, right) =>
			left.localeCompare(right),
		);
		return normalized.length > 0 ? normalized : undefined;
	});

const GlobalCompactionStrategySchema = z
	.enum(["basic", "agentic"])
	.catch("agentic");

export type GlobalCompactionStrategy = z.infer<
	typeof GlobalCompactionStrategySchema
>;

export const GlobalSettingsSchema = z
	.object({
		telemetryOptOut: z.boolean().default(false).catch(false),
		autoUpdateEnabled: z.boolean().default(true).catch(true),
		compactionStrategy: GlobalCompactionStrategySchema.optional(),
		disabledTools: GlobalSettingsStringListSchema.optional(),
		disabledPlugins: GlobalSettingsStringListSchema.optional(),
	})
	.strip()
	.transform((settings) => {
		const normalized: {
			telemetryOptOut: boolean;
			autoUpdateEnabled: boolean;
			compactionStrategy?: GlobalCompactionStrategy;
			disabledTools?: string[];
			disabledPlugins?: string[];
		} = {
			autoUpdateEnabled: settings.autoUpdateEnabled,
			telemetryOptOut: settings.telemetryOptOut,
		};
		if (settings.compactionStrategy) {
			normalized.compactionStrategy = settings.compactionStrategy;
		}
		if (settings.disabledTools?.length) {
			normalized.disabledTools = settings.disabledTools;
		}
		if (settings.disabledPlugins?.length) {
			normalized.disabledPlugins = settings.disabledPlugins;
		}
		return normalized;
	});

export type GlobalSettings = z.infer<typeof GlobalSettingsSchema>;

export interface WriteGlobalSettingsOptions {
	telemetry?: ITelemetryService;
}

function defaultGlobalSettings(): GlobalSettings {
	return GlobalSettingsSchema.parse({});
}

interface CachedSettings {
	path: string;
	mtimeMs: number;
	size: number;
	value: GlobalSettings;
}

let settingsCache: CachedSettings | undefined;

function invalidateSettingsCache(): void {
	settingsCache = undefined;
}

function freezeSettings(value: GlobalSettings): GlobalSettings {
	if (value.disabledTools) {
		Object.freeze(value.disabledTools);
	}
	if (value.disabledPlugins) {
		Object.freeze(value.disabledPlugins);
	}
	return Object.freeze(value);
}

function loadSettingsFromDisk(filePath: string): GlobalSettings {
	let raw: string;
	try {
		raw = readFileSync(filePath, "utf8");
	} catch {
		return defaultGlobalSettings();
	}
	try {
		const result = GlobalSettingsSchema.safeParse(JSON.parse(raw));
		return result.success ? result.data : defaultGlobalSettings();
	} catch {
		return defaultGlobalSettings();
	}
}

function getCachedSettings(): CachedSettings {
	const filePath = resolveGlobalSettingsPath();
	const stats = statSync(filePath, { throwIfNoEntry: false });
	const mtimeMs = stats?.mtimeMs ?? 0;
	const size = stats?.size ?? 0;

	const cached = settingsCache;
	if (
		cached &&
		cached.path === filePath &&
		cached.mtimeMs === mtimeMs &&
		cached.size === size
	) {
		return cached;
	}

	const value = freezeSettings(
		stats ? loadSettingsFromDisk(filePath) : defaultGlobalSettings(),
	);
	settingsCache = { path: filePath, mtimeMs, size, value };
	return settingsCache;
}

export function readGlobalSettings(): GlobalSettings {
	return getCachedSettings().value;
}

export function writeGlobalSettings(
	settings: z.input<typeof GlobalSettingsSchema>,
	options: WriteGlobalSettingsOptions = {},
): void {
	const filePath = resolveGlobalSettingsPath();
	const previous = readGlobalSettings();
	mkdirSync(dirname(filePath), { recursive: true });
	const normalized = GlobalSettingsSchema.parse(settings);
	if (!previous.telemetryOptOut && normalized.telemetryOptOut) {
		captureTelemetryOptOut(options.telemetry);
	}
	writeFileSync(filePath, `${JSON.stringify(normalized, null, 2)}\n`, "utf8");
	invalidateSettingsCache();
}

export function isTelemetryOptedOutGlobally(): boolean {
	return readGlobalSettings().telemetryOptOut;
}

export function setTelemetryOptOutGlobally(
	telemetryOptOut: boolean,
	options: WriteGlobalSettingsOptions = {},
): void {
	writeGlobalSettings(
		{
			...readGlobalSettings(),
			telemetryOptOut,
		},
		options,
	);
}

export function isAutoUpdateEnabledGlobally(): boolean {
	return readGlobalSettings().autoUpdateEnabled;
}

export function setAutoUpdateEnabledGlobally(
	autoUpdateEnabled: boolean,
	options: WriteGlobalSettingsOptions = {},
): void {
	writeGlobalSettings(
		{
			...readGlobalSettings(),
			autoUpdateEnabled,
		},
		options,
	);
}

export function readCompactionStrategyGlobally(): GlobalCompactionStrategy {
	return readGlobalSettings().compactionStrategy ?? "agentic";
}

export function setCompactionStrategyGlobally(
	compactionStrategy: GlobalCompactionStrategy,
): void {
	writeGlobalSettings({ ...readGlobalSettings(), compactionStrategy });
}

export function resolveDisabledToolNames(
	disabledToolNames?: ReadonlyArray<string>,
): Set<string> {
	return new Set(disabledToolNames ?? readGlobalSettings().disabledTools ?? []);
}

export function resolveDisabledPluginPaths(
	disabledPluginPaths?: ReadonlyArray<string>,
): Set<string> {
	return new Set(
		disabledPluginPaths ?? readGlobalSettings().disabledPlugins ?? [],
	);
}

export function isToolDisabledGlobally(toolName: string): boolean {
	return resolveDisabledToolNames().has(toolName);
}

export function toggleDisabledTool(toolName: string): boolean {
	const settings = readGlobalSettings();
	const disabled = new Set(settings.disabledTools ?? []);
	const wasDisabled = disabled.has(toolName);
	if (wasDisabled) {
		disabled.delete(toolName);
	} else {
		disabled.add(toolName);
	}
	writeGlobalSettings({ ...settings, disabledTools: [...disabled] });
	return !wasDisabled;
}

export function setDisabledTools(
	toolNames: ReadonlyArray<string>,
	disabledValue: boolean,
): void {
	const names = [
		...new Set(toolNames.map((name) => name.trim()).filter(Boolean)),
	];
	if (names.length === 0) {
		return;
	}

	const settings = readGlobalSettings();
	const disabled = resolveDisabledToolNames(settings.disabledTools);
	for (const name of names) {
		if (disabledValue) {
			disabled.add(name);
		} else {
			disabled.delete(name);
		}
	}
	writeGlobalSettings({ ...settings, disabledTools: [...disabled] });
}

export function setToolDisabledGlobally(
	toolName: string,
	disabled: boolean,
): boolean {
	setDisabledTools([toolName], disabled);
	return disabled;
}

export function isPluginDisabledGlobally(pluginPath: string): boolean {
	return resolveDisabledPluginPaths().has(pluginPath);
}

export function setDisabledPlugin(
	pluginPath: string,
	disabledValue: boolean,
): void {
	const path = pluginPath.trim();
	if (!path) {
		return;
	}

	const settings = readGlobalSettings();
	const disabled = resolveDisabledPluginPaths(settings.disabledPlugins);
	if (disabledValue) {
		disabled.add(path);
	} else {
		disabled.delete(path);
	}
	writeGlobalSettings({ ...settings, disabledPlugins: [...disabled] });
}

export function filterDisabledPluginPaths(
	pluginPaths: ReadonlyArray<string>,
	disabledPluginPaths?: ReadonlyArray<string>,
): string[] {
	const disabled = resolveDisabledPluginPaths(disabledPluginPaths);
	if (disabled.size === 0) {
		return [...pluginPaths];
	}
	return pluginPaths.filter((pluginPath) => !disabled.has(pluginPath));
}

export function filterDisabledTools<T extends Pick<AgentTool, "name">>(
	tools: ReadonlyArray<T>,
	disabledToolNames?: ReadonlyArray<string>,
): T[] {
	const disabled = resolveDisabledToolNames(disabledToolNames);
	if (disabled.size === 0) {
		return [...tools];
	}
	return tools.filter((tool) => !disabled.has(tool.name));
}

export function filterExtensionToolRegistrations(
	extensions: AgentConfig["extensions"],
	disabledToolNames?: ReadonlyArray<string>,
): AgentConfig["extensions"] {
	if (!extensions || extensions.length === 0) {
		return extensions;
	}

	const disabled = resolveDisabledToolNames(disabledToolNames);
	if (disabled.size === 0) {
		return extensions;
	}

	return extensions.map((extension) => {
		if (!extension.setup) {
			return extension;
		}

		return {
			...extension,
			setup: (api: AgentExtensionApi, ctx) =>
				extension.setup?.(
					{
						...api,
						registerTool: (tool) => {
							if (!disabled.has(tool.name)) {
								api.registerTool(tool);
							}
						},
					},
					ctx,
				),
		};
	});
}

import type {
	ApiHandler,
	ApiStreamChunk,
	HandlerModelInfo,
	Message,
} from "@cline/llms";
import type { AgentModelEvent, AgentModelRequest } from "@cline/shared";
import { describe, expect, it, vi } from "vitest";
import { createAgentModelFromApiHandler } from "./apihandler-agent-model-adapter";

function fakeHandler(
	chunks: ApiStreamChunk[],
	opts?: { throwAfter?: number },
): ApiHandler & { aborts: (AbortSignal | undefined)[] } {
	const aborts: (AbortSignal | undefined)[] = [];
	return {
		aborts,
		getMessages: () => [],
		getModel: (): HandlerModelInfo => ({ id: "m", info: { id: "m" } }),
		setAbortSignal(signal) {
			aborts.push(signal);
		},
		// eslint-disable-next-line require-yield
		async *createMessage(
			_system: string,
			_messages: Message[],
		): AsyncGenerator<ApiStreamChunk> {
			let i = 0;
			for (const chunk of chunks) {
				if (opts?.throwAfter !== undefined && i === opts.throwAfter) {
					throw new Error("boom");
				}
				yield chunk;
				i++;
			}
		},
	};
}

async function collect(
	stream:
		| AsyncIterable<AgentModelEvent>
		| Promise<AsyncIterable<AgentModelEvent>>,
): Promise<AgentModelEvent[]> {
	const out: AgentModelEvent[] = [];
	for await (const event of await stream) {
		out.push(event);
	}
	return out;
}

const baseRequest: AgentModelRequest = {
	systemPrompt: "sys",
	messages: [
		{
			id: "1",
			role: "user",
			content: [{ type: "text", text: "hi" }],
			createdAt: 0,
		},
	],
	tools: [],
};

describe("createAgentModelFromApiHandler", () => {
	it("maps text + usage chunks to events and appends a finish", async () => {
		const handler = fakeHandler([
			{ type: "text", text: "hello", id: "x" },
			{
				type: "usage",
				inputTokens: 10,
				outputTokens: 5,
				thoughtsTokenCount: 2,
				totalCost: 0.01,
				id: "x",
			},
		]);
		const model = createAgentModelFromApiHandler(handler);
		const events = await collect(model.stream(baseRequest));

		expect(events).toEqual([
			{ type: "text-delta", text: "hello" },
			{
				type: "usage",
				usage: {
					inputTokens: 10,
					outputTokens: 5,
					cacheReadTokens: undefined,
					cacheWriteTokens: undefined,
					reasoningTokenCount: 2,
					totalCost: 0.01,
				},
			},
			{ type: "finish", reason: "stop" },
		]);
	});

	it("maps tool_calls (object args) to a tool-call-delta event", async () => {
		const handler = fakeHandler([
			{
				type: "tool_calls",
				id: "x",
				tool_call: {
					call_id: "c1",
					function: { id: "c1", name: "edit", arguments: { path: "a.ts" } },
				},
			},
		]);
		const model = createAgentModelFromApiHandler(handler);
		const events = await collect(model.stream(baseRequest));

		expect(events[0]).toEqual({
			type: "tool-call-delta",
			toolCallId: "c1",
			toolName: "edit",
			inputText: undefined,
			input: { path: "a.ts" },
		});
		// A turn that ends with tool calls terminates as tool-calls, not stop.
		expect(events.at(-1)).toEqual({ type: "finish", reason: "tool-calls" });
	});

	it("preserves the thought signature on reasoning and tool-call events", async () => {
		const handler = fakeHandler([
			{ type: "reasoning", reasoning: "think", signature: "sig-r", id: "x" },
			{
				type: "tool_calls",
				id: "x",
				signature: "sig-t",
				tool_call: { call_id: "c1", function: { name: "edit", arguments: {} } },
			},
		]);
		const model = createAgentModelFromApiHandler(handler);
		const events = await collect(model.stream(baseRequest));

		const reasoning = events.find((e) => e.type === "reasoning-delta");
		expect(reasoning?.metadata).toMatchObject({ thoughtSignature: "sig-r" });
		const toolCall = events.find((e) => e.type === "tool-call-delta");
		expect(toolCall?.metadata).toMatchObject({ thoughtSignature: "sig-t" });
	});

	it("maps a done chunk with a max-output-tokens incompleteReason to max-tokens", async () => {
		const handler = fakeHandler([
			{
				type: "done",
				success: true,
				incompleteReason: "max_output_tokens",
				id: "x",
			},
		]);
		const model = createAgentModelFromApiHandler(handler);
		const events = await collect(model.stream(baseRequest));
		expect(events.at(-1)).toMatchObject({
			type: "finish",
			reason: "max-tokens",
		});
	});

	it("does not append a finish when the handler emits a done chunk", async () => {
		const handler = fakeHandler([
			{ type: "text", text: "x", id: "x" },
			{ type: "done", success: true, id: "x" },
		]);
		const model = createAgentModelFromApiHandler(handler);
		const events = await collect(model.stream(baseRequest));

		const finishes = events.filter((e) => e.type === "finish");
		expect(finishes).toHaveLength(1);
		expect(finishes[0]).toEqual({
			type: "finish",
			reason: "stop",
			error: undefined,
		});
	});

	it("forwards the abort signal to the handler", async () => {
		const handler = fakeHandler([{ type: "text", text: "x", id: "x" }]);
		const controller = new AbortController();
		const model = createAgentModelFromApiHandler(handler);
		await collect(model.stream({ ...baseRequest, signal: controller.signal }));
		expect(handler.aborts[0]).toBe(controller.signal);
	});

	it("emits a finish(error) when the handler throws", async () => {
		const handler = fakeHandler([{ type: "text", text: "x", id: "x" }], {
			throwAfter: 0,
		});
		const model = createAgentModelFromApiHandler(handler);
		const events = await collect(model.stream(baseRequest));
		expect(events.at(-1)).toMatchObject({
			type: "finish",
			reason: "error",
			error: "boom",
		});
	});

	it("does not emit a second finish when the handler throws after a done chunk", async () => {
		// done -> finish, then the handler throws while flushing.
		const handler = fakeHandler([{ type: "done", success: true, id: "x" }], {
			throwAfter: 1,
		});
		const model = createAgentModelFromApiHandler(handler);
		const events = await collect(model.stream(baseRequest));
		const finishes = events.filter((e) => e.type === "finish");
		expect(finishes).toHaveLength(1);
		expect(finishes[0]).toMatchObject({ type: "finish", reason: "stop" });
	});

	it("resolves the handler lazily from an async factory on stream", async () => {
		const handler = fakeHandler([{ type: "text", text: "lazy", id: "x" }]);
		const factory = vi.fn(async () => handler);
		const model = createAgentModelFromApiHandler(factory);

		// Not built until the stream is consumed.
		expect(factory).not.toHaveBeenCalled();
		const events = await collect(model.stream(baseRequest));
		expect(factory).toHaveBeenCalledTimes(1);
		expect(events[0]).toEqual({ type: "text-delta", text: "lazy" });
	});

	it("converts a rejecting handler factory into a finish(error) event", async () => {
		const factory = vi.fn(async () => {
			throw new Error("no vscode.lm");
		});
		const model = createAgentModelFromApiHandler(factory);
		const events = await collect(model.stream(baseRequest));
		expect(events).toEqual([
			{ type: "finish", reason: "error", error: "no vscode.lm" },
		]);
	});
});

/**
 * Adapter: wrap a custom `ApiHandler` (from the `@cline/llms` handler registry)
 * as an `AgentModel` for the agent runtime.
 *
 * The agent runtime builds models via `createAgentModelFromConfig`, which goes
 * straight to the gateway. Hosts can register provider handlers that need
 * host-only dependencies (e.g. the VS Code `vscode.lm` API) via
 * `registerHandler(providerId, factory)`. Those produce an `ApiHandler`
 * (`createMessage` -> `ApiStreamChunk`), which this adapter converts into the
 * `AgentModel` contract (`stream` -> `AgentModelEvent`).
 *
 * This is the inverse of the gateway's `toApiStreamChunk` in
 * `@cline/llms` `compat.ts`.
 */

import type { ApiHandler, ApiStreamChunk } from "@cline/llms";
import type {
	AgentModel,
	AgentModelEvent,
	AgentModelFinishReason,
	AgentModelRequest,
} from "@cline/shared";
import { agentMessagesToMessages } from "../../runtime/config/agent-message-codec";

type ApiStreamDoneChunk = Extract<ApiStreamChunk, { type: "done" }>;

function toAgentModelEvents(chunk: ApiStreamChunk): AgentModelEvent[] {
	switch (chunk.type) {
		case "text":
			return [{ type: "text-delta", text: chunk.text }];
		case "reasoning":
			// Thought signatures are read as `metadata.thoughtSignature` by
			// downstream adapters (see ai-sdk format), so surface it there.
			return [
				{
					type: "reasoning-delta",
					text: chunk.reasoning,
					metadata: chunk.signature
						? { thoughtSignature: chunk.signature, details: chunk.details }
						: { details: chunk.details },
				},
			];
		case "tool_calls": {
			const fn = chunk.tool_call.function;
			const args = fn.arguments;
			return [
				{
					type: "tool-call-delta",
					toolCallId: chunk.tool_call.call_id ?? fn.id,
					toolName: fn.name,
					inputText: typeof args === "string" ? args : undefined,
					input: typeof args === "string" ? undefined : args,
					// Preserve the thought signature so it isn't dropped downstream.
					...(chunk.signature
						? { metadata: { thoughtSignature: chunk.signature } }
						: {}),
				},
			];
		}
		case "usage":
			return [
				{
					type: "usage",
					usage: {
						inputTokens: chunk.inputTokens,
						outputTokens: chunk.outputTokens,
						cacheReadTokens: chunk.cacheReadTokens,
						cacheWriteTokens: chunk.cacheWriteTokens,
						reasoningTokenCount: chunk.thoughtsTokenCount,
						totalCost: chunk.totalCost,
					},
				},
			];
		case "done":
			// `createMessage` streams typically end by returning; a "done" chunk is
			// optional. Map it to a finish event so the runtime sees a terminal
			// signal even when the handler emits one explicitly.
			return [
				{
					type: "finish",
					reason: doneFinishReason(chunk),
					error: chunk.error,
				},
			];
		default:
			return [];
	}
}

function doneFinishReason(chunk: ApiStreamDoneChunk): AgentModelFinishReason {
	if (chunk.success === false) {
		return "error";
	}
	if (
		chunk.incompleteReason === "max_output_tokens" ||
		chunk.incompleteReason === "max-tokens"
	) {
		return "max-tokens";
	}
	return "stop";
}

/**
 * Resolves the `ApiHandler` to delegate to. A function is supported (and may be
 * async) so handler construction can be deferred to the first `stream` call —
 * which is required for providers registered via `registerAsyncHandler`.
 */
export type ApiHandlerSource =
	| ApiHandler
	| (() => ApiHandler | Promise<ApiHandler>);

/**
 * Build an `AgentModel` that delegates to a registered `ApiHandler`.
 */
export function createAgentModelFromApiHandler(
	source: ApiHandlerSource,
): AgentModel {
	return {
		async *stream(request: AgentModelRequest): AsyncGenerator<AgentModelEvent> {
			let sawFinish = false;
			let sawToolCall = false;
			try {
				// Resolving the handler (e.g. `createHandlerAsync`) can reject — for
				// instance when the host API is unavailable at stream time — so it
				// happens inside the try block to be reported as a terminal finish.
				const handler = typeof source === "function" ? await source() : source;

				// Forward the abort signal so cancellation reaches the handler.
				handler.setAbortSignal?.(request.signal);

				const messages = agentMessagesToMessages(request.messages);
				const tools = request.tools.map((tool) => ({
					name: tool.name,
					description: tool.description,
					inputSchema: tool.inputSchema,
				}));

				for await (const chunk of handler.createMessage(
					request.systemPrompt ?? "",
					messages,
					tools,
				)) {
					for (const event of toAgentModelEvents(chunk)) {
						if (event.type === "finish") {
							sawFinish = true;
						} else if (event.type === "tool-call-delta") {
							sawToolCall = true;
						}
						yield event;
					}
				}
				if (!sawFinish) {
					// Terminating with tool calls is a tool-calls turn (matching the
					// gateway/AI-SDK adapters); otherwise a normal stop.
					yield {
						type: "finish",
						reason: sawToolCall ? "tool-calls" : "stop",
					};
				}
			} catch (error) {
				if (!sawFinish) {
					yield {
						type: "finish",
						reason: request.signal?.aborted ? "aborted" : "error",
						error: error instanceof Error ? error.message : String(error),
					};
				}
			}
		},
	};
}

