		},
	],
	clinePass: [],
};

function cloneRecommendedModels(
	data: ClineRecommendedModelsData,
): ClineRecommendedModelsData {
	return {
		recommended: data.recommended.map((model) => ({
			...model,
			tags: [...model.tags],
		})),
		free: data.free.map((model) => ({ ...model, tags: [...model.tags] })),
		clinePass: data.clinePass.map((model) => ({
			...model,
			tags: [...model.tags],
		})),
	};
}

function normalizeModel(raw: unknown): ClineRecommendedModel | null {
	if (!raw || typeof raw !== "object") return null;
	const data = raw as Record<string, unknown>;
	if (typeof data.id !== "string" || data.id.length === 0) return null;
	return {
		id: data.id,
		name:
			typeof data.name === "string" && data.name.length > 0
				? data.name
				: data.id,
		description: typeof data.description === "string" ? data.description : "",
		tags: Array.isArray(data.tags)
			? data.tags.filter((tag): tag is string => typeof tag === "string")
			: [],
	};
}

function normalizeResponse(raw: unknown): ClineRecommendedModelsData | null {
	if (!raw || typeof raw !== "object") return null;
	const data = raw as Record<string, unknown>;
	const recommendedRaw = Array.isArray(data.recommended)
		? data.recommended
		: [];
	const freeRaw = Array.isArray(data.free) ? data.free : [];
	const clinePassRaw = Array.isArray(data.clinePass) ? data.clinePass : [];
	const recommended = recommendedRaw
		.map(normalizeModel)
		.filter((model): model is ClineRecommendedModel => model !== null);
	const free = freeRaw
		.map(normalizeModel)
		.filter((model): model is ClineRecommendedModel => model !== null);
	const clinePass = clinePassRaw
		.map(normalizeModel)
		.filter((model): model is ClineRecommendedModel => model !== null);
	if (recommended.length === 0 && free.length === 0 && clinePass.length === 0) {
		return null;
	}

	return { recommended, free, clinePass };
}

function getConfiguredApiBaseUrl(
	options: FetchClineRecommendedModelsOptions,
): string {
	const explicitBaseUrl = options.baseUrl?.trim();
	if (explicitBaseUrl) return explicitBaseUrl;

	const fallbackBaseUrl = getClineEnvironmentConfig().apiBaseUrl;
	try {
		const manager =
			options.providerSettingsManager ?? new ProviderSettingsManager();
		const settings = manager.getProviderSettings("cline");
		return settings?.baseUrl?.trim() || fallbackBaseUrl;
	} catch {
		return fallbackBaseUrl;
	}
}

async function fetchWithTimeout(
	fetchImpl: typeof fetch,
	input: string,
	timeoutMs: number,
): Promise<Response> {
	const controller = new AbortController();
	const timer = setTimeout(() => controller.abort(), timeoutMs);
	try {
		return await fetchImpl(input, { signal: controller.signal });
	} finally {
		clearTimeout(timer);
	}
}

export async function fetchClineRecommendedModels(
	options: FetchClineRecommendedModelsOptions = {},
): Promise<ClineRecommendedModelsData> {
	try {
		const base = getConfiguredApiBaseUrl(options);
		const fetchImpl = options.fetchImpl ?? fetch;
		const resp = await fetchWithTimeout(
			fetchImpl,
			`${base}/api/v1/ai/cline/recommended-models`,
			options.timeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS,
		);
		if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
		const json: unknown = await resp.json();
		const data = normalizeResponse(json);
		if (data) return data;
	} catch {
		// Fall back to the bundled list when the remote source is unavailable.
	}

	return cloneRecommendedModels(FALLBACK_CLINE_RECOMMENDED_MODELS);
}

import type { ProviderConfig } from "./provider-settings";
import type {
	BuiltInProviderSummary,
	CreateHandlerInput,
	ProviderConfigDefaults,
	ProviderSelectionConfig,
	RegisteredProviderSummary,
} from "./runtime-types";

interface ConfiguredProviderRecord {
	id: string;
	models: Set<string>;
	defaultModel: string;
	defaults: ProviderConfigDefaults;
}

interface RegisterConfiguredProviderInput {
	id: string;
	models: readonly string[];
	defaultModel?: string;
	defaults?: ProviderConfigDefaults;
}

function cloneDefaults(
	defaults: ProviderConfigDefaults | undefined,
): ProviderConfigDefaults {
	return defaults ? { ...defaults } : {};
}

function resolveApiKey(
	apiKey?: string,
	apiKeyEnv?: string,
): string | undefined {
	if (apiKey) {
		return apiKey;
	}
	if (!apiKeyEnv) {
		return undefined;
	}
	const runtimeProcess = globalThis.process;
	if (!runtimeProcess?.env) {
		return undefined;
	}
	return runtimeProcess.env[apiKeyEnv];
}

function assertNonEmptyModels(
	providerId: string,
	models: readonly string[],
): void {
	if (!models.length) {
		throw new Error(
			`Provider "${providerId}" must include at least one model.`,
		);
	}
}

export function toBuiltInProviderSummary(input: {
	collection: BuiltInProviderSummary["id"] extends string
		? {
				provider: Pick<
					import("@cline/llms").ProviderInfo,
					| "id"
					| "name"
					| "description"
					| "protocol"
					| "baseUrl"
					| "capabilities"
					| "env"
					| "defaultModelId"
				>;
				models: Record<string, unknown>;
			}
		: never;
}): BuiltInProviderSummary {
	const models = Object.keys(input.collection.models);
	return {
		id: input.collection.provider.id,
		name: input.collection.provider.name,
		description: input.collection.provider.description,
		protocol: input.collection.provider.protocol,
		baseUrl: input.collection.provider.baseUrl,
		capabilities: input.collection.provider.capabilities,
		env: input.collection.provider.env,
		models,
		defaultModel: input.collection.provider.defaultModelId,
		modelCount: models.length,
	};
}

export class ConfiguredProviderRegistry {
	private readonly providers = new Map<string, ConfiguredProviderRecord>();

	register(input: RegisterConfiguredProviderInput): void {
		assertNonEmptyModels(input.id, input.models);
		const defaultModel = input.defaultModel ?? input.models[0];
		if (!defaultModel) {
			throw new Error(`Provider "${input.id}" must define a default model.`);
		}
		if (!input.models.includes(defaultModel)) {
			throw new Error(
				`Default model "${defaultModel}" is not included in configured models for "${input.id}".`,
			);
		}
		const existing = this.providers.get(input.id);
		this.providers.set(input.id, {
			id: input.id,
			models: new Set([...(existing?.models ?? []), ...input.models]),
			defaultModel,
			defaults: {
				...(existing?.defaults ?? {}),
				...cloneDefaults(input.defaults),
			},
		});
	}

	registerSelectionConfig(provider: ProviderSelectionConfig): void {
		this.register({
			id: provider.id,
			models: provider.models,
			defaultModel: provider.defaultModel,
			defaults: {
				apiKey: resolveApiKey(provider.apiKey, provider.apiKeyEnv),
				routingProviderId: provider.builtinProviderId,
				baseUrl: provider.baseUrl,
				headers: provider.headers,
				timeoutMs: provider.timeoutMs,
				capabilities: provider.capabilities,
				...cloneDefaults(provider.settings),
			},
		});
	}

	registerModel(providerId: string, modelId: string): void {
		const existing = this.providers.get(providerId);
		if (!existing) {
			this.providers.set(providerId, {
				id: providerId,
				models: new Set([modelId]),
				defaultModel: modelId,
				defaults: {},
			});
			return;
		}
		existing.models.add(modelId);
	}

	createHandlerConfig(input: CreateHandlerInput): ProviderConfig {
		const provider = this.require(input.providerId);
		const modelId = input.modelId ?? provider.defaultModel;
		if (!provider.models.has(modelId)) {
			throw new Error(
				`Model "${modelId}" is not configured for provider "${input.providerId}".`,
			);
		}
		return {
			providerId: input.providerId,
			modelId,
			...provider.defaults,
			...input.overrides,
		};
	}

	list(): RegisteredProviderSummary[] {
		return Array.from(this.providers.values()).map((provider) => ({
			id: provider.id,
			models: Array.from(provider.models),
			defaultModel: provider.defaultModel,
		}));
	}

	getModels(providerId: string): string[] {
		return Array.from(this.require(providerId).models);
	}

	hasProvider(providerId: string): boolean {
		return this.providers.has(providerId);
	}

	hasModel(providerId: string, modelId: string): boolean {
		return this.providers.get(providerId)?.models.has(modelId) ?? false;
	}

	private require(providerId: string): ConfiguredProviderRecord {
		const provider = this.providers.get(providerId);
		if (!provider) {
			throw new Error(
				`Provider "${providerId}" is not configured in this SDK instance.`,
			);
		}
		return provider;
	}
}

