function formatPluginFailure(failure: PluginInitializationFailure): string {
	const label = failure.pluginName ?? failure.pluginPath;
	return `${label}: ${failure.message}`;
}

function logPluginDiagnostics(
	failures: PluginInitializationFailure[],
	warnings: PluginInitializationWarning[],
	logger: CoreSessionConfig["logger"],
): void {
	if (warnings.length > 0) {
		for (const warning of warnings) {
			logger?.log(warning.message, { severity: "warn" });
		}
	}
	if (failures.length === 0) {
		return;
	}
	const preview = failures.slice(0, 3).map(formatPluginFailure).join("; ");
	const suffix = failures.length > 3 ? `; and ${failures.length - 3} more` : "";
	logger?.log(
		`Some plugins failed to initialize. ${preview}${suffix}. Use --verbose for more details.`,
		{ severity: "warn" },
	);
	for (const failure of failures) {
		logger?.log(
			`Plugin initialization failed (${failure.phase}) for ${failure.pluginPath}`,
			{
				severity: "warn",
				stack: failure.stack,
				pluginPath: failure.pluginPath,
				pluginName: failure.pluginName,
			},
		);
	}
}

function resolveReasoningSettings(
	config: CoreSessionConfig,
	storedReasoning: ProviderSettings["reasoning"],
): ProviderSettings["reasoning"] {
	const hasThinking = typeof config.thinking === "boolean";
	const hasEffort = typeof config.reasoningEffort === "string";
	if (!hasThinking && !hasEffort) return storedReasoning;
	return {
		...(storedReasoning ?? {}),
		...(hasThinking ? { enabled: config.thinking } : {}),
		...(hasEffort ? { effort: config.reasoningEffort } : {}),
	};
}

function hasConfigExtension(
	extensions: ReadonlyArray<RuntimeConfigExtensionKind> | undefined,
	kind: RuntimeConfigExtensionKind,
): boolean {
	return hasRuntimeConfigExtension(extensions, kind);
}

function countSeededRootRuns(
	messages: StartSessionInput["initialMessages"],
): number {
	let count = 0;
	for (const message of messages ?? []) {
		if (message.role !== "user") continue;
		const metadata =
			"metadata" in message &&
			message.metadata &&
			typeof message.metadata === "object" &&
			!Array.isArray(message.metadata)
				? (message.metadata as Record<string, unknown>)
				: undefined;
		if (metadata?.kind === "recovery_notice") continue;
		count += 1;
	}
	return count;
}

function buildProviderConfig(
	config: CoreSessionConfig,
	sessionId: string,
	source: StartSessionInput["source"],
	providerSettingsManager: ProviderSettingsManager,
	modelCatalogDefaults?: Partial<ProviderSettings["modelCatalog"]>,
	defaultFetch?: typeof fetch,
): ProviderConfig {
	const stored = providerSettingsManager.getProviderSettings(config.providerId);
	const modelCatalog =
		modelCatalogDefaults || stored?.modelCatalog
			? {
					...(modelCatalogDefaults ?? {}),
					...(stored?.modelCatalog ?? {}),
				}
			: undefined;
	const sessionProviderConfig =
		config.providerConfig?.providerId === config.providerId
			? config.providerConfig
			: undefined;
	const resolvedHeaders = resolveProviderRequestHeaders({
		providerId: config.providerId,
		sessionId,
		source,
		defaultSource: SessionSource.CLI,
		client: {
			name: config.extensionContext?.client?.name,
			version: config.extensionContext?.client?.version,
			versionHeaderFallback: config.headers?.["X-CLIENT-VERSION"],
			platform: config.extensionContext?.client?.platform,
			platformVersion: config.extensionContext?.client?.platformVersion,
			isMultiRoot: config.extensionContext?.client?.isMultiRoot,
		},
		coreVersion: corePackageVersion,
		openAiCodex: {
			accountId: sessionProviderConfig?.accountId ?? stored?.auth?.accountId,
			accessToken:
				sessionProviderConfig?.accessToken ??
				config.apiKey ??
				stored?.auth?.accessToken ??
				stored?.apiKey,
			userAgentVersion: process.env.npm_package_version,
		},
		headers: {
			stored: stored?.headers,
			config: config.headers,
			session: sessionProviderConfig?.headers,
		},
	});
	const settings: ProviderSettings = {
		...(stored ?? {}),
		provider: config.providerId,
		model: config.modelId,
		apiKey: config.apiKey ?? stored?.apiKey,
		baseUrl: config.baseUrl ?? stored?.baseUrl,
		headers: undefined,
		reasoning: resolveReasoningSettings(config, stored?.reasoning),
		modelCatalog,
	};
	const providerConfig: ProviderConfig = {
		...toProviderConfig(settings),
		...(sessionProviderConfig ?? {}),
	};
	if (resolvedHeaders) {
		providerConfig.headers = resolvedHeaders;
	}
	if (config.knownModels) {
		providerConfig.knownModels = config.knownModels;
	}
	if (config.extensionContext) {
		providerConfig.extensionContext = config.extensionContext;
	}
	// Thread a host-provided custom fetch through to the AI gateway providers.
	// Precedence: explicit per-session config > stored provider settings > host default.
	const sessionFetch = (config as { fetch?: typeof fetch }).fetch;
	const resolvedFetch = sessionFetch ?? providerConfig.fetch ?? defaultFetch;
	if (resolvedFetch) {
		providerConfig.fetch = resolvedFetch;
	}
	return providerConfig;
}

export interface PrepareLocalRuntimeBootstrapOptions {
	input: StartSessionInput;
	localRuntime?: LocalRuntimeStartOptions;
	sessionId: string;
	providerSettingsManager: ProviderSettingsManager;
	defaultTelemetry?: ITelemetryService;
	defaultLogger?: BasicLogger;
	defaultCapabilities?: RuntimeCapabilities;
	defaultToolPolicies?: AgentConfig["toolPolicies"];
	/**
	 * Host-level default `fetch` threaded into `ProviderConfig.fetch` so the
	 * AI gateway providers can use a custom HTTP implementation.
	 */
	defaultFetch?: typeof fetch;
	onPluginEvent: (event: { name: string; payload?: unknown }) => void;
	onTeamEvent: (event: TeamEvent) => void;
	createSubAgentLifecycleCallbacks?: (config: CoreSessionConfig) => {
		onSubAgentEvent?: (event: AgentEvent) => void;
		onSubAgentStart?: (context: SubAgentStartContext) => void | Promise<void>;
		onSubAgentEnd?: (context: SubAgentEndContext) => void | Promise<void>;
	};
	createSpawnTool: () => AgentTool;
	readSessionMetadata: () => Promise<Record<string, unknown> | undefined>;
	writeSessionMetadata: (
		metadata: Record<string, unknown>,
	) => Promise<void> | void;
}

export interface LocalRuntimeBootstrap {
	effectiveInput: StartSessionInput;
	config: CoreSessionConfig;
	providerConfig: ProviderConfig;
	workspaceMetadata: string;
	/** Structured git + path metadata generated alongside workspaceMetadata. */
	workspaceInfo: WorkspaceInfo;
	gitState: GitWorkspaceState;
	extensions: AgentConfig["extensions"];
	hooks: AgentHooks | undefined;
	toolPolicies: AgentConfig["toolPolicies"];
	requestToolApproval?: (
		request: ToolApprovalRequest,
	) => Promise<ToolApprovalResult> | ToolApprovalResult;
	pluginSandboxShutdown?: () => Promise<void>;
	runtimeBuilderInput: RuntimeBuilderInput;
}

export async function prepareLocalRuntimeBootstrap(
	options: PrepareLocalRuntimeBootstrapOptions,
): Promise<LocalRuntimeBootstrap> {
	const {
		input,
		sessionId,
		providerSettingsManager,
		defaultTelemetry,
		defaultLogger,
		defaultCapabilities,
		defaultToolPolicies,
		defaultFetch,
		onPluginEvent,
		onTeamEvent,
		createSubAgentLifecycleCallbacks,
		createSpawnTool,
		localRuntime,
		readSessionMetadata,
		writeSessionMetadata,
	} = options;
	const workspacePath = resolveWorkspacePath(input.config);
	const {
		modelCatalogDefaults,
		userInstructionService,
		configExtensions,
		onTeamRestored,
		...localConfigFields
	} = localRuntime ?? {};
	const localConfig =
		Object.keys(localConfigFields).length > 0
			? (localConfigFields as Partial<CoreSessionConfig>)
			: undefined;

	// Generate workspace + git metadata once, early, so it can be forwarded to
	// hooks and extensions. The serialized string goes into CoreSessionConfig
	// as workspaceMetadata; the structured object is kept as workspaceInfo.
	const {
		workspaceInfo,
		workspaceMetadata,
		gitState,
		durationMs,
		vcsType,
		initError,
	} = await buildWorkspaceMetadataWithInfo(workspacePath);
	const configuredExtensionContext = localConfig?.extensionContext;
	const extensionContext: ExtensionContext = {
		...(configuredExtensionContext ?? {}),
		workspace: {
			...workspaceInfo,
			...(configuredExtensionContext?.workspace ?? {}),
		},
		session: {
			...(configuredExtensionContext?.session ?? {}),
			sessionId,
		},
		logger:
			configuredExtensionContext?.logger ??
			localConfig?.logger ??
			defaultLogger,
		telemetry:
			configuredExtensionContext?.telemetry ??
			localConfig?.telemetry ??
			defaultTelemetry,
	};
	emitWorkspaceLifecycleTelemetry({
		telemetry: extensionContext.telemetry,
		rootPath: workspaceInfo.rootPath,
		workspaceInfo,
		rootCount: 1,
		vcsType,
		durationMs,
		initError,
		featureFlagEnabled: true,
	});

	const fileHookExtension = createHookConfigFileExtension({
		cwd: input.config.cwd,
		workspacePath,
		rootSessionId: sessionId,
		logger: localConfig?.logger,
		workspaceInfo,
	});
	const auditHooks = hasRuntimeHooks(localConfig?.hooks)
		? undefined
		: createHookAuditHooks({
				rootSessionId: sessionId,
				workspacePath,
				workspaceInfo,
			});
	const baseHooks = mergeAgentHooks([localConfig?.hooks, auditHooks]);

	let loadedPlugins:
		| Awaited<ReturnType<typeof resolveAndLoadAgentPlugins>>
		| undefined;
	if (hasConfigExtension(configExtensions, "plugins")) {
		try {
			loadedPlugins = await resolveAndLoadAgentPlugins({
				pluginPaths: localConfig?.pluginPaths,
				workspacePath,
				cwd: input.config.cwd,
				onEvent: onPluginEvent,
				providerId: input.config.providerId,
				modelId: input.config.modelId,
				workspaceInfo,
				session: extensionContext.session,
				client: extensionContext.client,
				user: extensionContext.user,
				logger: extensionContext.logger,
				telemetry: extensionContext.telemetry,
				automation: extensionContext.automation,
			});
			logPluginDiagnostics(
				loadedPlugins.failures,
				loadedPlugins.warnings,
				localConfig?.logger,
			);
		} catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			localConfig?.logger?.log?.(
				`plugin loading failed; continuing without plugins (${message})`,
			);
		}
	}

	const builtInExtensions = fileHookExtension ? [fileHookExtension] : undefined;
	const extensions = mergeAgentExtensions(
		builtInExtensions,
		mergeAgentExtensions(
			localConfig?.extensions,
			filterExtensionToolRegistrations(loadedPlugins?.extensions),
		),
	);
	const pluginSkillDirectories = hasConfigExtension(configExtensions, "plugins")
		? resolvePluginSkillDirectoriesFromPaths(loadedPlugins?.pluginPaths ?? [])
		: undefined;
	const baseConfig: CoreSessionConfig = {
		...input.config,
		...(localConfig ?? {}),
		sessionId,
		hooks: baseHooks,
		extensions,
		extensionContext,
		telemetry: extensionContext.telemetry,
		logger: extensionContext.logger,
	};
	const providerConfig = buildProviderConfig(
		baseConfig,
		sessionId,
		input.source,
		providerSettingsManager,
		modelCatalogDefaults,
		defaultFetch,
	);
	const hooks = mergeAgentHooks([
		baseConfig.hooks,
		baseConfig.checkpoint?.enabled === true
			? createCheckpointHooks({
					cwd: baseConfig.cwd,
					sessionId,
					logger: baseConfig.logger,
					createCheckpoint: baseConfig.checkpoint?.createCheckpoint,
					initialRunCount: countSeededRootRuns(input.initialMessages),
					readSessionMetadata,
					writeSessionMetadata,
				})
			: undefined,
	]);
	const config: CoreSessionConfig = {
		...baseConfig,
		providerConfig,
		workspaceMetadata,
		hooks,
	};
	const toolPolicies =
		input.toolPolicies ?? baseConfig.toolPolicies ?? defaultToolPolicies;
	const capabilities = normalizeRuntimeCapabilities(
		defaultCapabilities,
		input.capabilities,
	);
	const requestToolApproval = capabilities?.requestToolApproval;
	const effectiveToolExecutors = capabilities?.toolExecutors;
	const subAgentLifecycleCallbacks = createSubAgentLifecycleCallbacks?.(config);
	const workspaceManager = new InMemoryWorkspaceManager({
		currentWorkspacePath: workspaceInfo.rootPath,
		workspaces: {
			[workspaceInfo.rootPath]: workspaceInfo,
		},
	});

	return {
		effectiveInput: input,
		config,
		providerConfig,
		workspaceMetadata,
		workspaceInfo,
		gitState,
		extensions,
		hooks,
		toolPolicies,
		requestToolApproval,
		pluginSandboxShutdown: loadedPlugins?.shutdown,
		runtimeBuilderInput: {
			config,
			hooks,
			extensions,
			onTeamEvent,
			createSpawnTool,
			onTeamRestored: onTeamRestored,
			onSubAgentEvent: subAgentLifecycleCallbacks?.onSubAgentEvent,
			onSubAgentStart: subAgentLifecycleCallbacks?.onSubAgentStart,
			onSubAgentEnd: subAgentLifecycleCallbacks?.onSubAgentEnd,
			userInstructionService: userInstructionService,
			pluginSkillDirectories,
			configExtensions: configExtensions,
			toolExecutors: effectiveToolExecutors,
			toolPolicies,
			workspaceManager,
			logger: config.logger,
			telemetry: config.telemetry,
			requestToolApproval,
		},
	};
}

import { existsSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { mkdir, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { setClineDir, setHomeDir } from "@cline/shared/storage";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { uninstallMarketplaceEntry } from "./marketplace";

describe("marketplace service", () => {
	let root = "";
	let home = "";
	let originalHome: string | undefined;
	let originalClineDir: string | undefined;

	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "core-marketplace-"));
		home = join(root, "home");
		originalHome = process.env.HOME;
		originalClineDir = process.env.CLINE_DIR;
		process.env.HOME = home;
		process.env.CLINE_DIR = join(home, ".cline");
		setHomeDir(home);
		setClineDir(process.env.CLINE_DIR);
	});

	afterEach(() => {
		if (originalHome === undefined) {
			delete process.env.HOME;
		} else {
			process.env.HOME = originalHome;
		}
		if (originalClineDir === undefined) {
			delete process.env.CLINE_DIR;
		} else {
			process.env.CLINE_DIR = originalClineDir;
		}
		rmSync(root, { recursive: true, force: true });
	});

	it("uninstalls marketplace MCP servers from settings by default", async () => {
		const settingsPath = join(root, "cline_mcp_settings.json");
		await writeFile(
			settingsPath,
			JSON.stringify(
				{
					mcpServers: {
						context7: { transport: { type: "stdio", command: "node" } },
						other: { transport: { type: "stdio", command: "node" } },
					},
				},
				null,
				2,
			),
			"utf8",
		);

		const result = await uninstallMarketplaceEntry(
			{
				id: "context7",
				type: "mcp",
				name: "Context7",
				install: { args: ["context7", "node", "server.js"] },
			},
			{ mcpSettingsPath: settingsPath },
		);

		expect(result).toMatchObject({
			id: "context7",
			type: "mcp",
			status: "uninstalled",
			message: "Uninstalled Context7.",
		});
		const settings = JSON.parse(readFileSync(settingsPath, "utf8")) as {
			mcpServers?: Record<string, unknown>;
		};
		expect(settings.mcpServers?.context7).toBeUndefined();
		expect(settings.mcpServers?.other).toBeDefined();
	});

	it("uninstalls marketplace skills through skills CLI remove", async () => {
		const skillDir = join(home, ".agents", "skills", "review-team");
		await mkdir(skillDir, { recursive: true });
		await writeFile(
			join(skillDir, "SKILL.md"),
			"---\nname: Review\n---\n",
			"utf8",
		);
		const calls: Array<{ command: string; args: string[] }> = [];

		const result = await uninstallMarketplaceEntry(
			{
				id: "review-team",
				type: "skill",
				name: "Review Team",
				install: {
					args: ["github.com/cline/skills@review-team"],
				},
			},
			{
				spawnCommand: async (command, args) => {
					calls.push({ command, args });
					rmSync(skillDir, { recursive: true, force: true });
					return { exitCode: 0, stdout: "removed", stderr: "" };
				},
			},
		);

		expect(result).toMatchObject({
			id: "review-team",
			type: "skill",
			status: "uninstalled",
			message: "Uninstalled Review Team.",
		});
		expect(calls).toEqual([
			{
				command: "npx",
				args: ["-y", "skills@latest", "remove", "review-team", "-g", "-y"],
			},
		]);
		expect(existsSync(skillDir)).toBe(false);
	});

	it("cleans up remaining marketplace skill directories after skills CLI remove succeeds", async () => {
		const clineSkillDir = join(
			process.env.CLINE_DIR ?? "",
			"skills",
			"review-team",
		);
		await mkdir(clineSkillDir, { recursive: true });
		await writeFile(join(clineSkillDir, "SKILL.md"), "# Review Team", "utf8");

		const result = await uninstallMarketplaceEntry(
			{
				id: "review-team",
				type: "skill",
				name: "Review Team",
				install: { args: ["github.com/cline/skills@review-team"] },
			},
			{
				spawnCommand: async () => ({
					exitCode: 0,
					stdout: "removed",
					stderr: "",
				}),
			},
		);

		expect(result.status).toBe("uninstalled");
		expect(result.output).toContain(`Removed: ${clineSkillDir}`);
		expect(existsSync(clineSkillDir)).toBe(false);
	});

	it("uninstalls official marketplace plugins by marketplace slug", async () => {
		const installPath = join(
			home,
			".cline",
			"plugins",
			"_installed",
			"official",
			"goal-123456789abc",
		);
		const entryPath = join(installPath, "package", "index.ts");
		await mkdir(join(installPath, "package"), { recursive: true });
		await writeFile(
			join(installPath, "package.json"),
			JSON.stringify({ name: "goal" }, null, 2),
			"utf8",
		);
		await writeFile(
			entryPath,
			"export default { name: 'goal', manifest: { capabilities: ['tools'] } };",
			"utf8",
		);

		const result = await uninstallMarketplaceEntry({
			id: "goal",
			type: "plugin",
			name: "Goal",
			install: { args: ["goal"] },
		});

		expect(result).toMatchObject({
			id: "goal",
			type: "plugin",
			status: "uninstalled",
			message: "Uninstalled Goal.",
		});
		expect(existsSync(installPath)).toBe(false);
	});
});

import { spawn } from "node:child_process";
import { existsSync, rmSync } from "node:fs";
import { homedir, platform } from "node:os";
import { dirname, join } from "node:path";
import { resolveClineDir, resolveMcpSettingsPath } from "@cline/shared/storage";
import { updateMcpSettingsFileSync } from "../extensions/mcp";
import { parseMcpInstallArgs } from "./mcp-install";
import { uninstallPlugin } from "./plugin-uninstall";

export type MarketplacePrimitiveType = "mcp" | "skill" | "plugin";

export type MarketplaceEntryInput = {
	id: string;
	type: MarketplacePrimitiveType;
	name?: string;
	install?: {
		args?: string[];
	};
};

export type MarketplaceActionResult = {
	id: string;
	type: MarketplacePrimitiveType;
	status: "installed" | "uninstalled";
	message: string;
	output?: string;
};

export type MarketplaceSpawnResult = {
	exitCode: number;
	stdout: string;
	stderr: string;
};

export type MarketplaceSpawnCommand = (
	command: string,
	args: string[],
) => Promise<MarketplaceSpawnResult>;

export type UninstallMarketplaceEntryOptions = {
	deleteMcpServer?: (name: string) => void | Promise<void>;
	mcpSettingsPath?: string;
	spawnCommand?: MarketplaceSpawnCommand;
	workspaceRoot?: string;
};

const MARKETPLACE_COMMAND_TIMEOUT_MS = 120_000;
const MAX_OUTPUT_CHARS = 12_000;
const SECRET_PATTERN =
	/(api[_ -]?key|access[_ -]?token|refresh[_ -]?token|auth(?:orization)?[_ -]?token|token|secret|password|authorization|credential)/i;
const SECRET_KEY_VALUE_PATTERN =
	/((?:^|[^\w])(?:[a-z0-9_]*?(?:api[_ -]?key|access[_ -]?token|refresh[_ -]?token|auth(?:orization)?[_ -]?token|token|secret|password|credential)[a-z0-9_]*)\s*[:=]\s*)(.+)$/gi;
const SECRET_BEARER_VALUE_PATTERN =
	/((?:^|[^\w])authorization\s*[:=]\s*)bearer\s+([^\s,"'}\]]+)/gi;
const SECRET_AUTHORIZATION_VALUE_PATTERN =
	/((?:^|[^\w])authorization\s*[:=])(?!\s*bearer\b)\s*(.+)$/gi;

function getMarketplaceEntryArgs(entry: MarketplaceEntryInput): string[] {
	return entry.install?.args ?? [];
}

function resolveHomeDir(): string {
	return (
		process.env.HOME?.trim() || process.env.USERPROFILE?.trim() || homedir()
	);
}

function trimSkillSegmentEdges(value: string): string {
	let start = 0;
	let end = value.length;
	while (start < end && (value[start] === "." || value[start] === "-")) {
		start++;
	}
	while (end > start && (value[end - 1] === "." || value[end - 1] === "-")) {
		end--;
	}
	return value.slice(start, end);
}

function sanitizeSkillSegment(value: string): string {
	const sanitized = trimSkillSegmentEdges(
		value.toLowerCase().replace(/[^a-z0-9._]+/g, "-"),
	).slice(0, 255);
	return sanitized || "skill";
}

function redactOutput(value: string): string {
	return value
		.split(/\r?\n/)
		.map((line) => {
			if (!SECRET_PATTERN.test(line)) return line;
			return line
				.replace(SECRET_KEY_VALUE_PATTERN, "$1[redacted]")
				.replace(SECRET_BEARER_VALUE_PATTERN, "$1Bearer [redacted]")
				.replace(
					/\b(Bearer)\s+(?!\[redacted\])([^\s,"'}\]]+)/gi,
					"$1 [redacted]",
				)
				.replace(SECRET_AUTHORIZATION_VALUE_PATTERN, "$1 [redacted]")
				.replace(
					/((?:^|[^\w])(?:api\s+key|access\s+token|refresh\s+token|auth(?:orization)?\s+token|secret|password|credential)\s+(?:is\s+)?)(\S+)/gi,
					"$1[redacted]",
				);
		})
		.join("\n")
		.slice(-MAX_OUTPUT_CHARS);
}

function commandOutput(result: MarketplaceSpawnResult): string | undefined {
	const output = redactOutput(
		[result.stdout, result.stderr].filter(Boolean).join("\n"),
	).trim();
	return output.length > 0 ? output : undefined;
}

function quoteCommandPart(value: string): string {
	if (value === "") return '""';
	if (/^[a-zA-Z0-9_./:=@%+,-]+$/.test(value)) return value;
	return JSON.stringify(value);
}

function formatCommand(command: string, args: string[]): string {
	return [command, ...args]
		.map((part) => quoteCommandPart(redactOutput(part).trim()))
		.join(" ");
}

const defaultMarketplaceSpawnCommand: MarketplaceSpawnCommand = async (
	command,
	args,
) =>
	new Promise<MarketplaceSpawnResult>((resolve, reject) => {
		let settled = false;
		let timedOut = false;
		const child = spawn(command, args, {
			env: process.env,
			shell: platform() === "win32",
			stdio: ["ignore", "pipe", "pipe"],
			windowsHide: true,
		});
		let stdout = "";
		let stderr = "";
		const forceKillTimeout = setTimeout(() => {
			if (!settled) child.kill("SIGKILL");
		}, MARKETPLACE_COMMAND_TIMEOUT_MS + 5_000);
		const timeout = setTimeout(() => {
			timedOut = true;
			stderr += `\nTimed out after ${MARKETPLACE_COMMAND_TIMEOUT_MS / 1000}s.`;
			child.kill("SIGTERM");
		}, MARKETPLACE_COMMAND_TIMEOUT_MS);
		forceKillTimeout.unref?.();
		timeout.unref?.();
		child.stdout?.on("data", (chunk) => {
			stdout += String(chunk);
			if (stdout.length > MAX_OUTPUT_CHARS * 2) {
				stdout = stdout.slice(-MAX_OUTPUT_CHARS);
			}
		});
		child.stderr?.on("data", (chunk) => {
			stderr += String(chunk);
			if (stderr.length > MAX_OUTPUT_CHARS * 2) {
				stderr = stderr.slice(-MAX_OUTPUT_CHARS);
			}
		});
		child.once("error", (error) => {
			clearTimeout(timeout);
			clearTimeout(forceKillTimeout);
			reject(error);
		});
		child.once("close", (code, signal) => {
			settled = true;
			clearTimeout(timeout);
			clearTimeout(forceKillTimeout);
			resolve({
				exitCode: timedOut ? 124 : (code ?? (signal === "SIGINT" ? 130 : 1)),
				stdout,
				stderr,
			});
		});
	});

export function marketplaceEntryKey(
	entry: Pick<MarketplaceEntryInput, "id" | "type">,
): string {
	return `${entry.type}:${entry.id}`;
}

export function resolveMarketplaceMcpServerName(
	entry: MarketplaceEntryInput,
): string {
	const args = getMarketplaceEntryArgs(entry);
	if (args.length === 0) {
		throw new Error("Marketplace install args are required.");
	}
	return parseMcpInstallArgs(args).name;
}

export function uninstallMarketplaceMcpServerFromSettings(
	entry: MarketplaceEntryInput,
	options: Pick<UninstallMarketplaceEntryOptions, "mcpSettingsPath"> = {},
): { name: string; deleted: boolean } {
	const name = resolveMarketplaceMcpServerName(entry);
	const settingsPath = options.mcpSettingsPath ?? resolveMcpSettingsPath();
	const deleted = updateMcpSettingsFileSync(settingsPath, (settings) => {
		const servers =
			settings.mcpServers &&
			typeof settings.mcpServers === "object" &&
			!Array.isArray(settings.mcpServers)
				? (settings.mcpServers as Record<string, unknown>)
				: {};
		const hadServer = Object.hasOwn(servers, name);
		if (hadServer) {
			delete servers[name];
		}
		settings.mcpServers = servers;
		return hadServer;
	});
	return { name, deleted };
}

export function getMarketplaceSkillCandidates(
	entry: MarketplaceEntryInput,
): string[] {
	const candidates = new Set<string>();
	const addCandidate = (value: string | undefined) => {
		const normalized = sanitizeSkillSegment(value ?? "");
		if (normalized && normalized !== "skill") {
			candidates.add(normalized);
		}
	};
	addCandidate(entry.id);
	addCandidate(entry.name);
	const installArgs = getMarketplaceEntryArgs(entry);
	for (let index = 0; index < installArgs.length; index++) {
		const arg = installArgs[index];
		if ((arg === "--skill" || arg === "-s") && installArgs[index + 1]) {
			addCandidate(installArgs[index + 1]);
			index++;
			continue;
		}
		const skillFilter = arg.split("@").at(1);
		if (skillFilter) {
			addCandidate(skillFilter);
		}
	}
	return [...candidates];
}

export function getGlobalMarketplaceSkillPaths(skillName: string): string[] {
	return [
		join(resolveClineDir(), "skills", skillName, "SKILL.md"),
		join(resolveHomeDir(), ".agents", "skills", skillName, "SKILL.md"),
	].filter((path, index, paths) => paths.indexOf(path) === index);
}

export function findInstalledGlobalMarketplaceSkillName(
	entry: MarketplaceEntryInput,
): string | undefined {
	if (entry.type !== "skill") return undefined;
	return getMarketplaceSkillCandidates(entry).find((candidate) =>
		getGlobalMarketplaceSkillPaths(candidate).some((path) => existsSync(path)),
	);
}

export function isMarketplaceSkillInstalled(
	entry: MarketplaceEntryInput,
): boolean {
	return findInstalledGlobalMarketplaceSkillName(entry) !== undefined;
}

function removeRemainingMarketplaceSkillPaths(
	entry: MarketplaceEntryInput,
): string[] {
	const removedPaths: string[] = [];
	if (entry.type !== "skill") return removedPaths;
	for (const candidate of getMarketplaceSkillCandidates(entry)) {
		for (const skillPath of getGlobalMarketplaceSkillPaths(candidate)) {
			if (!existsSync(skillPath)) continue;
			const skillDir = dirname(skillPath);
			rmSync(skillDir, { recursive: true, force: true });
			removedPaths.push(skillDir);
		}
	}
	return removedPaths;
}

export async function uninstallMarketplaceSkill(
	entry: MarketplaceEntryInput,
	options: Pick<UninstallMarketplaceEntryOptions, "spawnCommand"> = {},
): Promise<MarketplaceActionResult> {
	const installedName = findInstalledGlobalMarketplaceSkillName(entry);
	if (!installedName) {
		return {
			id: entry.id,
			type: "skill",
			status: "uninstalled",
			message: `${entry.name ?? entry.id} is not installed.`,
		};
	}
	const command = "npx";
	const commandArgs = [
		"-y",
		"skills@latest",
		"remove",
		installedName,
		"-g",
		"-y",
	];
	const displayCommand = formatCommand(command, commandArgs);
	const spawnCommand = options.spawnCommand ?? defaultMarketplaceSpawnCommand;
	let result: MarketplaceSpawnResult;
	try {
		result = await spawnCommand(command, commandArgs);
	} catch (error) {
		throw new Error(
			`Failed to start ${entry.name ?? entry.id} uninstall command:\n${displayCommand}\n${
				error instanceof Error ? error.message : String(error)
			}`,
		);
	}
	const output = commandOutput(result);
	if (result.exitCode !== 0) {
		throw new Error(
			`${entry.name ?? entry.id} uninstall failed with exit code ${result.exitCode}.\nCommand:\n${displayCommand}${
				output ? `\n\n${output}` : ""
			}`,
		);
	}
	const removedPaths = removeRemainingMarketplaceSkillPaths(entry);
	if (isMarketplaceSkillInstalled(entry)) {
		throw new Error(
			`Skill uninstall completed, but ${entry.name ?? entry.id} is still present in Cline's global skills directories.`,
		);
	}
	return {
		id: entry.id,
		type: "skill",
		status: "uninstalled",
		message: `Uninstalled ${entry.name ?? entry.id}.`,
		output:
			[output, ...removedPaths.map((path) => `Removed: ${path}`)]
				.filter(Boolean)
				.join("\n") || undefined,
	};
}

export async function uninstallMarketplacePlugin(
	entry: MarketplaceEntryInput,
	options: Pick<UninstallMarketplaceEntryOptions, "workspaceRoot"> = {},
): Promise<MarketplaceActionResult> {
	const [source] = getMarketplaceEntryArgs(entry);
	const target = source?.trim() || entry.id;
	if (!target) {
		throw new Error("Plugin marketplace uninstalls require a plugin name.");
	}
	const result = await uninstallPlugin({
		name: target,
		workspaceRoot: options.workspaceRoot,
	});
	return {
		id: entry.id,
		type: "plugin",
		status: "uninstalled",
		message: `Uninstalled ${entry.name ?? result.name ?? entry.id}.`,
		output: [
			`Path: ${result.installPath}`,
			...result.removedPaths.map((path) => `Removed: ${path}`),
		].join("\n"),
	};
}

export async function uninstallMarketplaceEntry(
	entry: MarketplaceEntryInput,
	options: UninstallMarketplaceEntryOptions = {},
): Promise<MarketplaceActionResult> {
	if (entry.type === "mcp") {
		const name = resolveMarketplaceMcpServerName(entry);
		if (options.deleteMcpServer) {
			await options.deleteMcpServer(name);
		} else {
			uninstallMarketplaceMcpServerFromSettings(entry, options);
		}
		return {
			id: entry.id,
			type: entry.type,
			status: "uninstalled",
			message: `Uninstalled ${entry.name ?? name ?? entry.id}.`,
		};
	}
	if (entry.type === "skill") {
		return uninstallMarketplaceSkill(entry, options);
	}
	if (entry.type === "plugin") {
		return uninstallMarketplacePlugin(entry, options);
	}
	throw new Error(`Unsupported marketplace entry type: ${entry.type}`);
}

