import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, isAbsolute, relative, resolve } from "node:path";
import type {
	AgentConfig,
	AgentExtensionMcpServer,
	AgentTool,
} from "@cline/shared";
import {
	type McpServerRegistration,
	resolveDefaultMcpSettingsPath,
	resolvePluginMcpServerRegistrations,
} from "../extensions/mcp";
import { loadSandboxedPlugins } from "../extensions/plugin/plugin-sandbox";

type AgentExtension = NonNullable<AgentConfig["extensions"]>[number];
type AgentExtensionApi = Parameters<NonNullable<AgentExtension["setup"]>>[0];
type AgentExtensionWithPath = AgentExtension & { __clinePluginPath?: string };

export interface PluginMcpSettingsMutation {
	name: string;
	pluginName: string;
	pluginPath: string;
	action: "created" | "updated" | "skipped" | "removed" | "disabled";
	reason?: string;
}

export interface PluginMcpSettingsSyncResult {
	mutations: PluginMcpSettingsMutation[];
	failures: Array<{
		pluginPath: string;
		pluginName?: string;
		message: string;
	}>;
}

export interface SyncPluginMcpServersToSettingsOptions {
	pluginPaths: ReadonlyArray<string>;
	cwd?: string;
	workspacePath?: string;
	settingsPath?: string;
	providerId?: string;
	modelId?: string;
}

export interface RemovePluginMcpServersFromSettingsOptions {
	pluginPaths?: ReadonlyArray<string>;
	pluginNames?: ReadonlyArray<string>;
	settingsPath?: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isPathWithin(parentPath: string, childPath: string): boolean {
	const relativePath = relative(resolve(parentPath), resolve(childPath));
	return (
		relativePath === "" ||
		(!relativePath.startsWith("..") && !isAbsolute(relativePath))
	);
}

function readRawSettings(filePath: string): Record<string, unknown> {
	if (!existsSync(filePath)) {
		return { mcpServers: {} };
	}
	try {
		const parsed = JSON.parse(readFileSync(filePath, "utf8"));
		if (isRecord(parsed)) {
			return parsed;
		}
	} catch (error) {
		throw new Error(
			`Invalid MCP settings at "${filePath}": ${
				error instanceof Error ? error.message : String(error)
			}`,
		);
	}
	throw new Error(`Invalid MCP settings at "${filePath}": expected an object`);
}

function getServers(
	settings: Record<string, unknown>,
): Record<string, unknown> {
	if (isRecord(settings.mcpServers)) {
		return { ...settings.mcpServers };
	}
	return {};
}

function writeRawSettings(
	filePath: string,
	settings: Record<string, unknown>,
	servers: Record<string, unknown>,
): void {
	mkdirSync(dirname(filePath), { recursive: true });
	writeFileSync(
		filePath,
		`${JSON.stringify({ ...settings, mcpServers: servers }, null, 2)}\n`,
		"utf8",
	);
}

function collectOwnerInputs(input: RemovePluginMcpServersFromSettingsOptions): {
	pluginPaths: string[];
	pluginNames: string[];
} {
	return {
		pluginPaths: [
			...new Set(
				(input.pluginPaths ?? [])
					.map((path) => path.trim())
					.filter((path) => path.length > 0),
			),
		],
		pluginNames: [
			...new Set(
				(input.pluginNames ?? [])
					.map((name) => name.trim())
					.filter((name) => name.length > 0),
			),
		],
	};
}

function getMetadata(record: unknown): Record<string, unknown> | undefined {
	if (!isRecord(record)) {
		return undefined;
	}
	const metadata = record.metadata;
	return isRecord(metadata) ? metadata : undefined;
}

function isPluginOwnedRecord(
	record: unknown,
	input: {
		pluginName?: string;
		pluginPath?: string;
		pluginPaths?: ReadonlyArray<string>;
		pluginNames?: ReadonlyArray<string>;
	},
): boolean {
	const metadata = getMetadata(record);
	if (!metadata || metadata.source !== "plugin") {
		return false;
	}
	const recordPluginName =
		typeof metadata.pluginName === "string"
			? metadata.pluginName
			: typeof metadata.plugin === "string"
				? metadata.plugin
				: undefined;
	const recordPluginPath =
		typeof metadata.pluginPath === "string" ? metadata.pluginPath : undefined;

	if (input.pluginName && recordPluginName === input.pluginName) {
		if (!input.pluginPath || recordPluginPath === input.pluginPath) {
			return true;
		}
	}
	if (
		recordPluginPath &&
		input.pluginPath &&
		(recordPluginPath === input.pluginPath ||
			isPathWithin(input.pluginPath, recordPluginPath) ||
			isPathWithin(recordPluginPath, input.pluginPath))
	) {
		return true;
	}
	if (
		recordPluginName &&
		input.pluginNames?.some((name) => name === recordPluginName)
	) {
		return true;
	}
	if (
		recordPluginPath &&
		input.pluginPaths?.some(
			(path) =>
				recordPluginPath === path ||
				isPathWithin(path, recordPluginPath) ||
				isPathWithin(recordPluginPath, path),
		)
	) {
		return true;
	}
	return false;
}

function createSettingsEntry(input: {
	registration: McpServerRegistration;
	pluginName: string;
	pluginPath: string;
	existing?: Record<string, unknown>;
	disabled?: boolean;
}): Record<string, unknown> {
	const existingOauth = isRecord(input.existing?.oauth)
		? { oauth: input.existing.oauth }
		: {};
	const transport =
		input.registration.transport.type === "stdio" &&
		input.registration.transport.cwd === undefined
			? {
					...input.registration.transport,
					cwd: dirname(input.pluginPath),
				}
			: input.registration.transport;
	return {
		transport,
		...(input.disabled ? { disabled: true } : {}),
		...existingOauth,
		metadata: {
			...(input.registration.metadata ?? {}),
			source: "plugin",
			pluginName: input.pluginName,
			pluginPath: input.pluginPath,
		},
	};
}

async function collectPluginMcpServers(
	options: SyncPluginMcpServersToSettingsOptions,
): Promise<{
	plugins: Array<{
		pluginName: string;
		pluginPath: string;
	}>;
	servers: Array<{
		pluginName: string;
		pluginPath: string;
		server: AgentExtensionMcpServer;
	}>;
	failures: PluginMcpSettingsSyncResult["failures"];
}> {
	if (options.pluginPaths.length === 0) {
		return { plugins: [], servers: [], failures: [] };
	}
	const sandboxed = await loadSandboxedPlugins({
		pluginPaths: [...options.pluginPaths],
		cwd: options.cwd,
		providerId: options.providerId,
		modelId: options.modelId,
		workspaceInfo: options.workspacePath
			? { rootPath: options.workspacePath }
			: undefined,
	});
	try {
		const plugins: Array<{
			pluginName: string;
			pluginPath: string;
		}> = [];
		const servers: Array<{
			pluginName: string;
			pluginPath: string;
			server: AgentExtensionMcpServer;
		}> = [];
		const failures: PluginMcpSettingsSyncResult["failures"] = (
			sandboxed.failures ?? []
		).map((failure) => ({
			pluginPath: failure.pluginPath,
			pluginName: failure.pluginName,
			message: failure.message,
		}));
		for (const extension of sandboxed.extensions ?? []) {
			const pluginPath = (extension as AgentExtensionWithPath)
				.__clinePluginPath;
			if (!pluginPath) {
				continue;
			}
			if (!extension.setup) {
				plugins.push({
					pluginName: extension.name,
					pluginPath,
				});
				continue;
			}
			const mcpServers: AgentExtensionMcpServer[] = [];
			const api: AgentExtensionApi = {
				registerTool: (_tool: AgentTool) => {},
				registerCommand: () => {},
				registerMessageBuilder: () => {},
				registerRule: () => {},
				registerProvider: () => {},
				registerAutomationEventType: () => {},
				registerMcpServer: (server) => {
					if (!extension.manifest.capabilities.includes("mcp")) {
						throw new Error('registerMcpServer requires the "mcp" capability');
					}
					mcpServers.push(server);
				},
			};
			try {
				await extension.setup(api, {
					workspaceInfo: options.workspacePath
						? { rootPath: options.workspacePath }
						: undefined,
				});
			} catch (error) {
				failures.push({
					pluginPath,
					pluginName: extension.name,
					message: error instanceof Error ? error.message : String(error),
				});
				continue;
			}
			plugins.push({
				pluginName: extension.name,
				pluginPath,
			});
			for (const server of mcpServers) {
				servers.push({
					pluginName: extension.name,
					pluginPath,
					server: {
						...server,
						metadata: {
							...(server.metadata ?? {}),
							source: "plugin",
							pluginName: extension.name,
							pluginPath,
						},
					},
				});
			}
		}
		return { plugins, servers, failures };
	} finally {
		await sandboxed.shutdown().catch(() => {
			// Best-effort cleanup after contribution discovery.
		});
	}
}

export async function syncPluginMcpServersToSettings(
	options: SyncPluginMcpServersToSettingsOptions,
): Promise<PluginMcpSettingsSyncResult> {
	const settingsPath = options.settingsPath ?? resolveDefaultMcpSettingsPath();
	const result: PluginMcpSettingsSyncResult = {
		mutations: [],
		failures: [],
	};
	let collected: Awaited<ReturnType<typeof collectPluginMcpServers>>;
	try {
		collected = await collectPluginMcpServers(options);
	} catch (error) {
		for (const pluginPath of options.pluginPaths) {
			result.failures.push({
				pluginPath,
				message: error instanceof Error ? error.message : String(error),
			});
		}
		return result;
	}
	result.failures.push(...collected.failures);

	let settings: Record<string, unknown>;
	try {
		settings = readRawSettings(settingsPath);
	} catch (error) {
		for (const pluginPath of options.pluginPaths) {
			result.failures.push({
				pluginPath,
				message: error instanceof Error ? error.message : String(error),
			});
		}
		return result;
	}
	const servers = getServers(settings);
	const declaredNamesByPluginPath = new Map<string, Set<string>>();
	const pluginNameByPath = new Map<string, string>();
	for (const plugin of collected.plugins) {
		declaredNamesByPluginPath.set(plugin.pluginPath, new Set());
		pluginNameByPath.set(plugin.pluginPath, plugin.pluginName);
	}
	const resolved = resolvePluginMcpServerRegistrations(
		collected.servers.map((entry) => ({
			server: entry.server,
			owner: entry,
			ownerLabel: entry.pluginName,
		})),
	);

	for (const resolution of resolved) {
		const owner = resolution.owner;
		if (!declaredNamesByPluginPath.has(owner.pluginPath)) {
			declaredNamesByPluginPath.set(owner.pluginPath, new Set());
		}
		if (resolution.name) {
			declaredNamesByPluginPath.get(owner.pluginPath)?.add(resolution.name);
		}
		if (!resolution.registration) {
			result.mutations.push({
				name: resolution.name,
				pluginName: owner.pluginName,
				pluginPath: owner.pluginPath,
				action: "skipped",
				reason: resolution.loadError ?? "invalid MCP server registration",
			});
			continue;
		}

		const existing = servers[resolution.registration.name];
		if (existing !== undefined) {
			if (
				!isPluginOwnedRecord(existing, {
					pluginName: owner.pluginName,
					pluginPath: owner.pluginPath,
				})
			) {
				result.mutations.push({
					name: resolution.registration.name,
					pluginName: owner.pluginName,
					pluginPath: owner.pluginPath,
					action: "skipped",
					reason: "MCP server name is already configured",
				});
				continue;
			}
		}

		servers[resolution.registration.name] = createSettingsEntry({
			registration: resolution.registration,
			pluginName: owner.pluginName,
			pluginPath: owner.pluginPath,
			existing: isRecord(existing) ? existing : undefined,
		});
		result.mutations.push({
			name: resolution.registration.name,
			pluginName: owner.pluginName,
			pluginPath: owner.pluginPath,
			action: existing === undefined ? "created" : "updated",
		});
	}

	for (const [serverName, record] of Object.entries(servers)) {
		const metadata = getMetadata(record);
		const pluginPath =
			typeof metadata?.pluginPath === "string" ? metadata.pluginPath : "";
		const declaredNames = declaredNamesByPluginPath.get(pluginPath);
		if (
			declaredNames &&
			isPluginOwnedRecord(record, { pluginPath }) &&
			!declaredNames.has(serverName)
		) {
			delete servers[serverName];
			result.mutations.push({
				name: serverName,
				pluginName:
					typeof metadata?.pluginName === "string"
						? metadata.pluginName
						: (pluginNameByPath.get(pluginPath) ?? "plugin"),
				pluginPath,
				action: "removed",
				reason: "plugin no longer declares this MCP server",
			});
		}
	}

	if (result.mutations.some((mutation) => mutation.action !== "skipped")) {
		try {
			writeRawSettings(settingsPath, settings, servers);
		} catch (error) {
			for (const pluginPath of options.pluginPaths) {
				result.failures.push({
					pluginPath,
					message: error instanceof Error ? error.message : String(error),
				});
			}
		}
	}
	return result;
}

export function disablePluginMcpServersInSettings(
	options: RemovePluginMcpServersFromSettingsOptions,
): PluginMcpSettingsMutation[] {
	const settingsPath = options.settingsPath ?? resolveDefaultMcpSettingsPath();
	let settings: Record<string, unknown>;
	try {
		settings = readRawSettings(settingsPath);
	} catch {
		return [];
	}
	const servers = getServers(settings);
	const ownerInput = collectOwnerInputs(options);
	const mutations: PluginMcpSettingsMutation[] = [];
	for (const [serverName, record] of Object.entries(servers)) {
		if (!isRecord(record) || !isPluginOwnedRecord(record, ownerInput)) {
			continue;
		}
		const metadata = getMetadata(record);
		servers[serverName] = { ...record, disabled: true };
		mutations.push({
			name: serverName,
			pluginName:
				typeof metadata?.pluginName === "string"
					? metadata.pluginName
					: "plugin",
			pluginPath:
				typeof metadata?.pluginPath === "string" ? metadata.pluginPath : "",
			action: "disabled",
		});
	}
	if (mutations.length > 0) {
		writeRawSettings(settingsPath, settings, servers);
	}
	return mutations;
}

export function removePluginMcpServersFromSettings(
	options: RemovePluginMcpServersFromSettingsOptions,
): PluginMcpSettingsMutation[] {
	const settingsPath = options.settingsPath ?? resolveDefaultMcpSettingsPath();
	let settings: Record<string, unknown>;
	try {
		settings = readRawSettings(settingsPath);
	} catch {
		return [];
	}
	const servers = getServers(settings);
	const ownerInput = collectOwnerInputs(options);
	const mutations: PluginMcpSettingsMutation[] = [];
	for (const [serverName, record] of Object.entries(servers)) {
		if (!isPluginOwnedRecord(record, ownerInput)) {
			continue;
		}
		const metadata = getMetadata(record);
		delete servers[serverName];
		mutations.push({
			name: serverName,
			pluginName:
				typeof metadata?.pluginName === "string"
					? metadata.pluginName
					: "plugin",
			pluginPath:
				typeof metadata?.pluginPath === "string" ? metadata.pluginPath : "",
			action: "removed",
		});
	}
	if (mutations.length > 0) {
		writeRawSettings(settingsPath, settings, servers);
	}
	return mutations;
}

import { stat } from "node:fs/promises";
import { isAbsolute, relative, resolve } from "node:path";
import type { AgentConfig, AgentTool } from "@cline/shared";
import { resolveAgentPluginPaths } from "../extensions/plugin/plugin-config-loader";
import type {
	PluginInitializationFailure,
	PluginInitializationWarning,
} from "../extensions/plugin/plugin-load-report";
import { loadSandboxedPlugins } from "../extensions/plugin/plugin-sandbox";
import { resolveDisabledToolNames } from "./global-settings";

type AgentExtension = NonNullable<AgentConfig["extensions"]>[number];
type AgentExtensionApi = Parameters<NonNullable<AgentExtension["setup"]>>[0];
type AgentExtensionWithPath = AgentExtension & { __clinePluginPath?: string };

function isPathWithin(parentPath: string, childPath: string): boolean {
	const relativePath = relative(resolve(parentPath), resolve(childPath));
	return (
		relativePath === "" ||
		(!relativePath.startsWith("..") && !isAbsolute(relativePath))
	);
}

export interface PluginToolSummary {
	name: string;
	pluginName: string;
	path: string;
	source: "workspace-plugin" | "global-plugin";
	enabled: boolean;
	description?: string;
}

export interface ListPluginToolsResult {
	tools: PluginToolSummary[];
	failures: PluginInitializationFailure[];
	warnings: PluginInitializationWarning[];
}

type PluginToolDescriptor = Omit<PluginToolSummary, "enabled">;
type PluginToolDescriptorCacheEntry = {
	tools: PluginToolDescriptor[];
	failures: PluginInitializationFailure[];
	warnings: PluginInitializationWarning[];
};

const MAX_PLUGIN_TOOL_DESCRIPTOR_CACHE_ENTRIES = 32;
const pluginToolDescriptorCache = new Map<
	string,
	PluginToolDescriptorCacheEntry
>();

function cachePluginToolDescriptors(
	key: string,
	entry: PluginToolDescriptorCacheEntry,
): void {
	if (
		!pluginToolDescriptorCache.has(key) &&
		pluginToolDescriptorCache.size >= MAX_PLUGIN_TOOL_DESCRIPTOR_CACHE_ENTRIES
	) {
		const oldestKey = pluginToolDescriptorCache.keys().next().value;
		if (oldestKey) {
			pluginToolDescriptorCache.delete(oldestKey);
		}
	}
	pluginToolDescriptorCache.set(key, entry);
}

async function buildPluginToolDescriptorCacheKey(input: {
	pluginPaths: ReadonlyArray<string>;
	workspacePath: string;
	cwd?: string;
	providerId?: string;
	modelId?: string;
}): Promise<string> {
	const pathStats = await Promise.all(
		input.pluginPaths.map(async (pluginPath) => {
			try {
				const stats = await stat(pluginPath);
				return `${pluginPath}:${stats.mtimeMs}:${stats.size}`;
			} catch {
				return `${pluginPath}:missing`;
			}
		}),
	);
	return JSON.stringify({
		workspacePath: input.workspacePath,
		cwd: input.cwd,
		providerId: input.providerId,
		modelId: input.modelId,
		pathStats,
	});
}

function withEnabledState(
	tools: readonly PluginToolDescriptor[],
	disabled: ReadonlySet<string>,
): PluginToolSummary[] {
	return tools.map((tool) => ({
		...tool,
		enabled: !disabled.has(tool.name),
	}));
}

function sortPluginToolDescriptors(
	tools: PluginToolDescriptor[],
): PluginToolDescriptor[] {
	return tools.sort((left, right) => {
		const nameOrder = left.name.localeCompare(right.name);
		if (nameOrder !== 0) {
			return nameOrder;
		}
		return left.path.localeCompare(right.path);
	});
}

async function collectPluginContributions(
	extension: AgentExtension,
	workspaceInfo?: { rootPath: string },
): Promise<{
	tools: AgentTool[];
}> {
	if (!extension.setup) {
		return { tools: [] };
	}

	const tools: AgentTool[] = [];
	const api: AgentExtensionApi = {
		registerTool: (tool) => tools.push(tool),
		registerCommand: () => {},
		registerMessageBuilder: () => {},
		registerRule: () => {},
		registerProvider: () => {},
		registerAutomationEventType: () => {},
		registerMcpServer: (_server) => {
			if (!extension.manifest.capabilities.includes("mcp")) {
				throw new Error('registerMcpServer requires the "mcp" capability');
			}
		},
	};
	await extension.setup(api, { workspaceInfo });
	return { tools };
}

export async function listPluginToolsWithDiagnostics(input: {
	workspacePath: string;
	cwd?: string;
	disabledToolNames?: ReadonlyArray<string>;
	providerId?: string;
	modelId?: string;
}): Promise<ListPluginToolsResult> {
	const pluginPaths = resolveAgentPluginPaths({
		workspacePath: input.workspacePath,
		cwd: input.cwd,
	});
	const disabled = resolveDisabledToolNames(input.disabledToolNames);
	if (pluginPaths.length === 0) {
		return { tools: [], failures: [], warnings: [] };
	}

	const cacheKey = await buildPluginToolDescriptorCacheKey({
		pluginPaths,
		workspacePath: input.workspacePath,
		cwd: input.cwd,
		providerId: input.providerId,
		modelId: input.modelId,
	});
	const cached = pluginToolDescriptorCache.get(cacheKey);
	if (cached) {
		return {
			tools: withEnabledState(cached.tools, disabled),
			failures: cached.failures,
			warnings: cached.warnings,
		};
	}

	const tools: PluginToolDescriptor[] = [];
	let failures: PluginInitializationFailure[] = [];
	let warnings: PluginInitializationWarning[] = [];
	let sandboxed: Awaited<ReturnType<typeof loadSandboxedPlugins>> | undefined;

	try {
		sandboxed = await loadSandboxedPlugins({
			pluginPaths,
			cwd: input.cwd,
			providerId: input.providerId,
			modelId: input.modelId,
			workspaceInfo: { rootPath: input.workspacePath },
		});
		failures = [...sandboxed.failures];
		warnings = [...sandboxed.warnings];
		for (const extension of sandboxed.extensions ?? []) {
			const pluginPath = (extension as AgentExtensionWithPath)
				.__clinePluginPath;
			if (!pluginPath) {
				continue;
			}
			const pluginSource = isPathWithin(input.workspacePath, pluginPath)
				? "workspace-plugin"
				: "global-plugin";
			let contributions: Awaited<ReturnType<typeof collectPluginContributions>>;
			try {
				contributions = await collectPluginContributions(extension, {
					rootPath: input.workspacePath,
				});
			} catch (error) {
				failures.push({
					pluginPath,
					pluginName: extension.name,
					phase: "setup",
					message: error instanceof Error ? error.message : String(error),
					stack: error instanceof Error ? error.stack : undefined,
				});
				continue;
			}
			for (const tool of contributions.tools) {
				tools.push({
					name: tool.name,
					pluginName: extension.name,
					path: pluginPath,
					source: pluginSource,
					description: tool.description?.trim() || undefined,
				});
			}
		}
	} catch (error) {
		failures = pluginPaths.map((pluginPath) => ({
			pluginPath,
			phase: "load" as const,
			message: error instanceof Error ? error.message : String(error),
			stack: error instanceof Error ? error.stack : undefined,
		}));
	} finally {
		await sandboxed?.shutdown().catch(() => {
			// Best effort cleanup after contribution discovery.
		});
	}

	const sortedTools = sortPluginToolDescriptors(tools);
	cachePluginToolDescriptors(cacheKey, {
		tools: sortedTools,
		failures,
		warnings,
	});
	return {
		tools: withEnabledState(sortedTools, disabled),
		failures,
		warnings,
	};
}

export async function listPluginTools(input: {
	workspacePath: string;
	cwd?: string;
	disabledToolNames?: ReadonlyArray<string>;
	providerId?: string;
	modelId?: string;
}): Promise<PluginToolSummary[]> {
	return (await listPluginToolsWithDiagnostics(input)).tools;
}

import { chmodSync, existsSync, mkdtempSync, rmSync } from "node:fs";
import { mkdir, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { setClineDir, setHomeDir } from "@cline/shared/storage";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { readGlobalSettings, writeGlobalSettings } from "./global-settings";
import { uninstallPlugin } from "./plugin-uninstall";

describe("plugin uninstall service", () => {
	let root = "";
	let home = "";
	let originalHome: string | undefined;
	let originalClineDir: string | undefined;
	let originalClineDataDir: string | undefined;
	let originalGlobalSettingsPath: string | undefined;
	let originalMcpSettingsPath: string | undefined;

	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "core-plugin-uninstall-"));
		home = join(root, "home");
		originalHome = process.env.HOME;
		originalClineDir = process.env.CLINE_DIR;
		originalClineDataDir = process.env.CLINE_DATA_DIR;
		originalGlobalSettingsPath = process.env.CLINE_GLOBAL_SETTINGS_PATH;
		originalMcpSettingsPath = process.env.CLINE_MCP_SETTINGS_PATH;
		process.env.HOME = home;
		process.env.CLINE_DIR = join(home, ".cline");
		process.env.CLINE_DATA_DIR = join(home, ".cline", "data");
		process.env.CLINE_GLOBAL_SETTINGS_PATH = join(
			home,
			".cline",
			"data",
			"settings",
			"global-settings.json",
		);
		setHomeDir(home);
		setClineDir(process.env.CLINE_DIR);
	});

	afterEach(() => {
		if (originalHome === undefined) {
			delete process.env.HOME;
		} else {
			process.env.HOME = originalHome;
		}
		if (originalClineDir === undefined) {
			delete process.env.CLINE_DIR;
		} else {
			process.env.CLINE_DIR = originalClineDir;
		}
		if (originalClineDataDir === undefined) {
			delete process.env.CLINE_DATA_DIR;
		} else {
			process.env.CLINE_DATA_DIR = originalClineDataDir;
		}
		if (originalGlobalSettingsPath === undefined) {
			delete process.env.CLINE_GLOBAL_SETTINGS_PATH;
		} else {
			process.env.CLINE_GLOBAL_SETTINGS_PATH = originalGlobalSettingsPath;
		}
		if (originalMcpSettingsPath === undefined) {
			delete process.env.CLINE_MCP_SETTINGS_PATH;
		} else {
			process.env.CLINE_MCP_SETTINGS_PATH = originalMcpSettingsPath;
		}
		rmSync(root, { recursive: true, force: true });
	});

	it("uninstalls an installed package plugin by package name", async () => {
		const installPath = join(
			home,
			".cline",
			"plugins",
			"_installed",
			"local",
			"bundled-skills-demo-123456789abc",
		);
		const entryPath = join(installPath, "package", "index.ts");
		await mkdir(join(installPath, "package"), { recursive: true });
		await writeFile(
			join(installPath, "package.json"),
			JSON.stringify(
				{
					name: "cline-installed-plugin-test",
					cline: {
						plugins: [{ paths: ["./package/index.ts"] }],
					},
				},
				null,
				2,
			),
			"utf8",
		);
		await writeFile(
			join(installPath, "package", "package.json"),
			JSON.stringify({ name: "cline-internal-bundled-skills-demo" }, null, 2),
			"utf8",
		);
		await writeFile(
			entryPath,
			"export default { name: 'demo', manifest: { capabilities: ['skills'] } };",
			"utf8",
		);
		writeGlobalSettings({
			disabledPlugins: [entryPath, "/tmp/other-plugin.ts"],
		});

		const result = await uninstallPlugin({
			name: "cline-internal-bundled-skills-demo",
		});

		expect(result.installPath).toBe(installPath);
		expect(existsSync(installPath)).toBe(false);
		expect(readGlobalSettings()).toEqual({
			autoUpdateEnabled: true,
			disabledPlugins: ["/tmp/other-plugin.ts"],
			telemetryOptOut: false,
		});
	});

	it("uninstalls a direct plugin file by path", async () => {
		const pluginPath = join(home, ".cline", "plugins", "direct-plugin.ts");
		await mkdir(join(home, ".cline", "plugins"), { recursive: true });
		await writeFile(
			pluginPath,
			"export default { name: 'direct', manifest: { capabilities: ['tools'] } };",
			"utf8",
		);

		const result = await uninstallPlugin({ path: pluginPath });

		expect(result.installPath).toBe(pluginPath);
		expect(existsSync(pluginPath)).toBe(false);
	});

	it.skipIf(process.platform === "win32")(
		"keeps plugin files when MCP settings cleanup fails",
		async () => {
			const pluginPath = join(home, ".cline", "plugins", "mcp-plugin.ts");
			const settingsPath = join(root, "cline_mcp_settings.json");
			process.env.CLINE_MCP_SETTINGS_PATH = settingsPath;
			await mkdir(join(home, ".cline", "plugins"), { recursive: true });
			await writeFile(
				pluginPath,
				"export default { name: 'mcp-plugin', manifest: { capabilities: ['mcp'] } };",
				"utf8",
			);
			await writeFile(
				settingsPath,
				JSON.stringify(
					{
						mcpServers: {
							smoke: {
								transport: {
									type: "stdio",
									command: process.execPath,
									args: ["-e", "process.exit(0)"],
								},
								metadata: {
									source: "plugin",
									pluginName: "mcp-plugin",
									pluginPath,
								},
							},
						},
					},
					null,
					2,
				),
				"utf8",
			);
			chmodSync(settingsPath, 0o444);

			try {
				await expect(uninstallPlugin({ path: pluginPath })).rejects.toThrow();
			} finally {
				chmodSync(settingsPath, 0o644);
			}

			expect(existsSync(pluginPath)).toBe(true);
		},
	);

	// chmod-based deletion failure cannot be simulated on Windows, where read-only
	// directory permissions do not prevent removing files inside them.
	it.skipIf(process.platform === "win32")(
		"keeps disabled plugin settings if file deletion fails",
		async () => {
			const pluginRoot = join(home, ".cline", "plugins");
			const pluginPath = join(pluginRoot, "locked-plugin.ts");
			await mkdir(pluginRoot, { recursive: true });
			await writeFile(
				pluginPath,
				"export default { name: 'locked', manifest: { capabilities: ['tools'] } };",
				"utf8",
			);
			writeGlobalSettings({ disabledPlugins: [pluginPath] });
			chmodSync(pluginRoot, 0o555);

			try {
				await expect(uninstallPlugin({ path: pluginPath })).rejects.toThrow();
				expect(existsSync(pluginPath)).toBe(true);
				expect(readGlobalSettings()).toEqual({
					autoUpdateEnabled: true,
					disabledPlugins: [pluginPath],
					telemetryOptOut: false,
				});
			} finally {
				chmodSync(pluginRoot, 0o755);
			}
		},
	);

	it("reports unmatched names clearly", async () => {
		await expect(uninstallPlugin({ name: "missing-plugin" })).rejects.toThrow(
			/No plugin found matching "missing-plugin"/,
		);
	});
});

import {
	existsSync,
	readdirSync,
	readFileSync,
	rmdirSync,
	rmSync,
	statSync,
} from "node:fs";
import {
	basename,
	dirname,
	extname,
	isAbsolute,
	join,
	relative,
	resolve,
	sep,
} from "node:path";
import {
	discoverPluginModulePaths,
	resolvePluginConfigSearchPaths,
} from "@cline/shared/storage";
import { readGlobalSettings, writeGlobalSettings } from "./global-settings";
import { removePluginMcpServersFromSettings } from "./plugin-mcp-settings";

export interface PluginUninstallOptions {
	name?: string;
	path?: string;
	cwd?: string;
	workspaceRoot?: string;
}

export interface PluginUninstallResult {
	name: string;
	installPath: string;
	removedPaths: string[];
	entryPaths: string[];
}

interface PluginUninstallCandidate {
	installPath: string;
	entryPaths: string[];
	names: string[];
	installed: boolean;
}

const INSTALLS_DIRECTORY_NAME = "_installed";
const PACKAGE_DIRECTORY_NAME = "package";
const INSTALL_KIND_DEPTHS = new Map<string, number>([
	["git", 2],
	["local", 1],
	["npm", 1],
	["official", 1],
	["remote", 1],
]);

function normalizeMatchValue(value: string): string {
	return value.trim().toLowerCase();
}

function addName(names: Set<string>, value: string | undefined): void {
	const trimmed = value?.trim();
	if (!trimmed) {
		return;
	}
	names.add(trimmed);
}

function stripInstallHash(value: string): string {
	return value.replace(/-[0-9a-f]{12}$/i, "");
}

function withoutExtension(value: string): string {
	const extension = extname(value);
	return extension ? value.slice(0, -extension.length) : value;
}

function readPackageName(packageJsonPath: string): string | undefined {
	if (!existsSync(packageJsonPath)) {
		return undefined;
	}
	try {
		const parsed = JSON.parse(readFileSync(packageJsonPath, "utf8")) as {
			name?: unknown;
		};
		return typeof parsed.name === "string" ? parsed.name.trim() : undefined;
	} catch {
		return undefined;
	}
}

function isInsidePath(childPath: string, parentPath: string): boolean {
	const relativePath = relative(parentPath, childPath);
	return (
		relativePath === "" ||
		(!relativePath.startsWith("..") && !isAbsolute(relativePath))
	);
}

function resolveInstalledRootFromPath(filePath: string): string | undefined {
	const absolutePath = resolve(filePath);
	const parts = absolutePath.split(sep);
	const installedIndex = parts.lastIndexOf(INSTALLS_DIRECTORY_NAME);
	if (installedIndex < 0) {
		return undefined;
	}
	const kind = parts[installedIndex + 1];
	if (!kind) {
		return undefined;
	}
	const depth = INSTALL_KIND_DEPTHS.get(kind) ?? 1;
	const endIndex = installedIndex + 2 + depth;
	if (parts.length < endIndex) {
		return undefined;
	}
	const root = parts.slice(0, endIndex).join(sep) || sep;
	return existsSync(root) ? root : undefined;
}

function safeReadDir(directoryPath: string) {
	try {
		return readdirSync(directoryPath, { withFileTypes: true });
	} catch {
		return [];
	}
}

function collectInstalledRoots(pluginRoot: string): string[] {
	const installedRoot = join(pluginRoot, INSTALLS_DIRECTORY_NAME);
	if (!existsSync(installedRoot)) {
		return [];
	}
	const roots: string[] = [];
	for (const kindEntry of safeReadDir(installedRoot)) {
		if (!kindEntry.isDirectory()) {
			continue;
		}
		const kindPath = join(installedRoot, kindEntry.name);
		if (kindEntry.name === "git") {
			for (const hostEntry of safeReadDir(kindPath)) {
				if (!hostEntry.isDirectory()) {
					continue;
				}
				const hostPath = join(kindPath, hostEntry.name);
				for (const installEntry of safeReadDir(hostPath)) {
					if (installEntry.isDirectory()) {
						roots.push(join(hostPath, installEntry.name));
					}
				}
			}
			continue;
		}
		for (const installEntry of safeReadDir(kindPath)) {
			if (installEntry.isDirectory()) {
				roots.push(join(kindPath, installEntry.name));
			}
		}
	}
	return roots.sort((left, right) => left.localeCompare(right));
}

function discoverEntriesWithin(root: string): string[] {
	try {
		return discoverPluginModulePaths(root);
	} catch {
		return [];
	}
}

function createInstalledCandidate(
	installPath: string,
): PluginUninstallCandidate {
	const entryPaths = discoverEntriesWithin(installPath);
	const names = new Set<string>();
	addName(names, basename(installPath));
	addName(names, stripInstallHash(basename(installPath)));
	addName(names, readPackageName(join(installPath, "package.json")));
	addName(
		names,
		readPackageName(join(installPath, PACKAGE_DIRECTORY_NAME, "package.json")),
	);
	for (const entryPath of entryPaths) {
		addName(names, basename(entryPath));
		addName(names, withoutExtension(basename(entryPath)));
	}
	return {
		installPath,
		entryPaths,
		names: [...names].sort((left, right) => left.localeCompare(right)),
		installed: true,
	};
}

function resolveDirectPluginInstallPath(
	filePath: string,
	pluginRoots: string[],
): string | undefined {
	const absolutePath = resolve(filePath);
	const pluginRoot = pluginRoots.find((root) =>
		isInsidePath(absolutePath, root),
	);
	if (!pluginRoot) {
		return undefined;
	}
	let current = dirname(absolutePath);
	while (current !== pluginRoot && current !== dirname(current)) {
		if (existsSync(join(current, "package.json"))) {
			return current;
		}
		current = dirname(current);
	}
	const filename = basename(absolutePath);
	if (
		(filename === "index.ts" || filename === "index.js") &&
		dirname(absolutePath) !== pluginRoot
	) {
		return dirname(absolutePath);
	}
	return absolutePath;
}

function createDirectCandidate(
	entryPath: string,
	pluginRoots: string[],
): PluginUninstallCandidate | undefined {
	const installPath = resolveDirectPluginInstallPath(entryPath, pluginRoots);
	if (!installPath) {
		return undefined;
	}
	const names = new Set<string>();
	addName(names, basename(entryPath));
	addName(names, withoutExtension(basename(entryPath)));
	addName(names, basename(installPath));
	addName(names, withoutExtension(basename(installPath)));
	addName(names, readPackageName(join(installPath, "package.json")));
	return {
		installPath,
		entryPaths: [entryPath],
		names: [...names].sort((left, right) => left.localeCompare(right)),
		installed: false,
	};
}

function getPluginRoots(options: PluginUninstallOptions): string[] {
	const workspaceRoot =
		options.workspaceRoot?.trim() || options.cwd?.trim() || process.cwd();
	return resolvePluginConfigSearchPaths(workspaceRoot).filter((directory) =>
		existsSync(directory),
	);
}

function collectCandidates(pluginRoots: string[]): PluginUninstallCandidate[] {
	const candidatesByInstallPath = new Map<string, PluginUninstallCandidate>();

	for (const pluginRoot of pluginRoots) {
		for (const installPath of collectInstalledRoots(pluginRoot)) {
			candidatesByInstallPath.set(
				installPath,
				createInstalledCandidate(installPath),
			);
		}
		for (const entryPath of discoverEntriesWithin(pluginRoot)) {
			const installedRoot = resolveInstalledRootFromPath(entryPath);
			if (installedRoot) {
				if (!candidatesByInstallPath.has(installedRoot)) {
					candidatesByInstallPath.set(
						installedRoot,
						createInstalledCandidate(installedRoot),
					);
				}
				continue;
			}
			const directCandidate = createDirectCandidate(entryPath, pluginRoots);
			if (directCandidate) {
				candidatesByInstallPath.set(
					directCandidate.installPath,
					directCandidate,
				);
			}
		}
	}

	return [...candidatesByInstallPath.values()].sort((left, right) =>
		left.installPath.localeCompare(right.installPath),
	);
}

function candidateMatchesName(
	candidate: PluginUninstallCandidate,
	name: string,
): boolean {
	const normalizedName = normalizeMatchValue(name);
	if (!normalizedName) {
		return false;
	}
	if (normalizeMatchValue(candidate.installPath) === normalizedName) {
		return true;
	}
	return candidate.names.some(
		(candidateName) => normalizeMatchValue(candidateName) === normalizedName,
	);
}

function findCandidateByPath(
	path: string,
	candidates: PluginUninstallCandidate[],
	pluginRoots: string[],
): PluginUninstallCandidate | undefined {
	const absolutePath = resolve(path);
	for (const candidate of candidates) {
		if (isInsidePath(absolutePath, candidate.installPath)) {
			return candidate;
		}
		if (
			candidate.entryPaths.some(
				(entryPath) => resolve(entryPath) === absolutePath,
			)
		) {
			return candidate;
		}
	}
	const installedRoot = resolveInstalledRootFromPath(absolutePath);
	if (installedRoot) {
		return createInstalledCandidate(installedRoot);
	}
	if (existsSync(absolutePath)) {
		return createDirectCandidate(absolutePath, pluginRoots);
	}
	return undefined;
}

function cleanupDisabledPluginPaths(candidate: PluginUninstallCandidate): void {
	const settings = readGlobalSettings();
	const disabledPlugins = settings.disabledPlugins;
	if (!disabledPlugins?.length) {
		return;
	}
	const remaining = disabledPlugins.filter((pluginPath) => {
		const absolutePath = resolve(pluginPath);
		if (isInsidePath(absolutePath, candidate.installPath)) {
			return false;
		}
		return !candidate.entryPaths.some(
			(entryPath) => resolve(entryPath) === absolutePath,
		);
	});
	if (remaining.length === disabledPlugins.length) {
		return;
	}
	writeGlobalSettings({ ...settings, disabledPlugins: remaining });
}

function cleanupEmptyInstallParents(installPath: string): void {
	let current = dirname(installPath);
	while (
		current !== dirname(current) &&
		basename(current) !== INSTALLS_DIRECTORY_NAME
	) {
		try {
			rmdirSync(current);
		} catch {
			return;
		}
		current = dirname(current);
	}
}

function describeCandidate(candidate: PluginUninstallCandidate): string {
	const primaryName = candidate.names[0] ?? basename(candidate.installPath);
	return `${primaryName} at ${candidate.installPath}`;
}

export async function uninstallPlugin(
	options: PluginUninstallOptions,
): Promise<PluginUninstallResult> {
	const pluginRoots = getPluginRoots(options);
	const candidates = collectCandidates(pluginRoots);
	const explicitPath = options.path?.trim();
	const requestedName = options.name?.trim();

	let candidate: PluginUninstallCandidate | undefined;
	if (explicitPath) {
		candidate = findCandidateByPath(explicitPath, candidates, pluginRoots);
		if (!candidate) {
			throw new Error(`No plugin found at ${explicitPath}`);
		}
	} else {
		if (!requestedName) {
			throw new Error("plugin uninstall requires a plugin name");
		}
		const matches = candidates.filter((item) =>
			candidateMatchesName(item, requestedName),
		);
		if (matches.length === 0) {
			throw new Error(`No plugin found matching "${requestedName}"`);
		}
		if (matches.length > 1) {
			throw new Error(
				`Multiple plugins match "${requestedName}": ${matches.map(describeCandidate).join(", ")}`,
			);
		}
		candidate = matches[0];
	}

	const stats = statSync(candidate.installPath, { throwIfNoEntry: false });
	if (!stats) {
		throw new Error(
			`Plugin install path does not exist: ${candidate.installPath}`,
		);
	}
	removePluginMcpServersFromSettings({
		pluginPaths: [candidate.installPath, ...candidate.entryPaths],
		pluginNames: candidate.names,
	});
	rmSync(candidate.installPath, {
		recursive: stats.isDirectory(),
		force: true,
	});
	cleanupDisabledPluginPaths(candidate);
	if (candidate.installed) {
		cleanupEmptyInstallParents(candidate.installPath);
	}
	return {
		name:
			requestedName || candidate.names[0] || basename(candidate.installPath),
		installPath: candidate.installPath,
		removedPaths: [candidate.installPath],
		entryPaths: candidate.entryPaths,
	};
}

import {
	existsSync,
	mkdirSync,
	readFileSync,
	renameSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import * as LlmsModels from "@cline/llms";
import {
	ApiFormatSchema,
	type ModelCapability,
	ModelCapabilitySchema,
	type ModelInfo,
	type ProviderCapability,
	ProviderCapabilitySchema,
	type ProviderClient,
	ProviderClientSchema,
	type ProviderModel,
	type ProviderProtocol,
	ProviderProtocolSchema,
} from "@cline/shared";
import { z } from "zod";
import { sdkDebug } from "../../logging/early-logger";
import type {
	ProviderSettings,
	StoredProviderSettings,
} from "../../types/provider-settings";
import type { ProviderSettingsManager } from "../storage/provider-settings-manager";

const OptionalPositiveFiniteNumberSchema = z
	.number()
	.finite()
	.positive()
	.optional()
	.catch(undefined);
const OptionalNonNegativeFiniteNumberSchema = z
	.number()
	.finite()
	.nonnegative()
	.optional()
	.catch(undefined);

export const StoredModelEntrySchema = z
	.object({
		id: z.string().optional(),
		name: z.string().optional(),
		maxTokens: OptionalPositiveFiniteNumberSchema,
		contextWindow: OptionalPositiveFiniteNumberSchema,
		maxInputTokens: OptionalPositiveFiniteNumberSchema,
		capabilities: z.array(ModelCapabilitySchema).optional(),
		supportsVision: z.boolean().optional(),
		supportsAttachments: z.boolean().optional(),
		supportsReasoning: z.boolean().optional(),
		inputPrice: OptionalNonNegativeFiniteNumberSchema,
		outputPrice: OptionalNonNegativeFiniteNumberSchema,
		cacheReadsPrice: OptionalNonNegativeFiniteNumberSchema,
		cacheWritesPrice: OptionalNonNegativeFiniteNumberSchema,
		temperature: OptionalNonNegativeFiniteNumberSchema,
		apiFormat: ApiFormatSchema.optional(),
		isR1FormatRequired: z.boolean().optional(),
	})
	.passthrough();

export type StoredModelEntry = z.infer<typeof StoredModelEntrySchema>;

export const StoredProviderMetadataSchema = z
	.object({
		name: z.string(),
		baseUrl: z.string(),
		defaultModelId: z.string().optional(),
		protocol: ProviderProtocolSchema.optional(),
		client: ProviderClientSchema.optional(),
		capabilities: z.array(ProviderCapabilitySchema).optional(),
		modelsSourceUrl: z.string().optional(),
	})
	.passthrough();

export const StoredProviderEntrySchema = z
	.object({
		provider: StoredProviderMetadataSchema.optional(),
		models: z.record(z.string(), StoredModelEntrySchema).optional(),
	})
	.passthrough();

export type StoredProviderEntry = z.infer<typeof StoredProviderEntrySchema>;

export const StoredModelsFileSchema = z.object({
	version: z.literal(1),
	providers: z.record(z.string(), StoredProviderEntrySchema),
});

export type StoredModelsFile = z.infer<typeof StoredModelsFileSchema>;

const StoredModelsFileEnvelopeSchema = z.object({
	version: z.literal(1),
	providers: z.record(z.string(), z.unknown()),
});

const LOADED_MODELS_REGISTRY_PATHS = new Set<string>();

function titleCaseFromId(id: string): string {
	return id
		.split(/[-_]/)
		.filter(Boolean)
		.map((part) => part.charAt(0).toUpperCase() + part.slice(1))
		.join(" ");
}

export function resolveModelsRegistryPath(
	manager: ProviderSettingsManager,
): string {
	return join(dirname(manager.getFilePath()), "models.json");
}

export function emptyModelsFile(): StoredModelsFile {
	return { version: 1, providers: {} };
}

export function parseModelsFile(input: unknown): StoredModelsFile {
	const result = StoredModelsFileEnvelopeSchema.safeParse(input);
	if (!result.success) {
		sdkDebug(
			"models.json content is not a valid models file envelope; starting from an empty registry",
		);
		return emptyModelsFile();
	}

	const providers: StoredModelsFile["providers"] = {};
	for (const [providerId, entry] of Object.entries(result.data.providers)) {
		const provider = StoredProviderEntrySchema.safeParse(entry);
		if (provider.success) {
			providers[providerId] = provider.data;
		} else {
			sdkDebug(
				`models.json: dropping invalid entry for provider=${providerId}`,
			);
		}
	}
	return { version: 1, providers };
}

export function readModelsFileSync(filePath: string): StoredModelsFile {
	if (!existsSync(filePath)) {
		return emptyModelsFile();
	}
	try {
		const raw = readFileSync(filePath, "utf8");
		return parseModelsFile(JSON.parse(raw) as unknown);
	} catch {
		// The file exists but could not be read/parsed. Falling back to an
		// empty registry is required for reads, but callers that then WRITE
		// the empty state back would permanently destroy the user's data —
		// leave a trace so that is diagnosable.
		sdkDebug(
			`models.json at ${filePath} exists but is unreadable or invalid JSON; treating as an empty registry`,
		);
	}
	return emptyModelsFile();
}

export async function readModelsFile(
	filePath: string,
): Promise<StoredModelsFile> {
	try {
		const raw = await readFile(filePath, "utf8");
		return parseModelsFile(JSON.parse(raw) as unknown);
	} catch (error) {
		if ((error as NodeJS.ErrnoException | undefined)?.code !== "ENOENT") {
			sdkDebug(
				`models.json at ${filePath} exists but is unreadable or invalid JSON; treating as an empty registry`,
			);
		}
	}
	return emptyModelsFile();
}

// Stage to a pid-unique temp file and rename into place (mirrors
// ProviderSettingsManager.write). Concurrent Cline processes (CLI, extension,
// hub) share models.json; a bare writeFileSync lets readers catch a partial
// file, which read paths treat as an empty registry — and the next
// read-modify-write would persist that loss.
export function writeModelsFileSync(
	filePath: string,
	state: StoredModelsFile,
): void {
	mkdirSync(dirname(filePath), { recursive: true });
	const parsed = StoredModelsFileSchema.parse(state);
	const tempPath = `${filePath}.${process.pid}.tmp`;
	try {
		writeFileSync(tempPath, `${JSON.stringify(parsed, null, 2)}\n`, "utf8");
		renameSync(tempPath, filePath);
	} catch (error) {
		rmSync(tempPath, { force: true });
		throw error;
	}
}

export async function writeModelsFile(
	filePath: string,
	state: StoredModelsFile,
): Promise<void> {
	await mkdir(dirname(filePath), { recursive: true });
	const parsed = StoredModelsFileSchema.parse(state);
	const tempPath = `${filePath}.${process.pid}.tmp`;
	try {
		await writeFile(tempPath, `${JSON.stringify(parsed, null, 2)}\n`, "utf8");
		await rename(tempPath, filePath);
	} catch (error) {
		await rm(tempPath, { force: true }).catch(() => {});
		throw error;
	}
}

export function toProviderModel(
	modelId: string,
	info: {
		name?: string;
		capabilities?: string[];
		thinkingConfig?: unknown;
	},
): ProviderModel {
	return {
		id: modelId,
		name: info.name ?? modelId,
		supportsAttachments: info.capabilities?.includes("files"),
		supportsVision: info.capabilities?.includes("images"),
		supportsReasoning:
			info.capabilities?.includes("reasoning") || info.thinkingConfig != null,
	};
}

function toProviderCapabilities(
	capabilities: ProviderCapability[] | undefined,
): Array<"reasoning" | "prompt-cache" | "tools"> | undefined {
	if (!capabilities || capabilities.length === 0) {
		return undefined;
	}
	const next = new Set<"reasoning" | "prompt-cache" | "tools">();
	if (capabilities.includes("reasoning")) {
		next.add("reasoning");
	}
	if (capabilities.includes("prompt-cache")) {
		next.add("prompt-cache");
	}
	if (capabilities.includes("tools")) {
		next.add("tools");
	}
	return next.size > 0 ? [...next] : undefined;
}

function toModelCapabilities(
	capabilities: ProviderCapability[] | undefined,
): Array<
	"streaming" | "tools" | "reasoning" | "prompt-cache" | "images" | "files"
> {
	const next = new Set<
		"streaming" | "tools" | "reasoning" | "prompt-cache" | "images" | "files"
	>();
	if (!capabilities || capabilities.length === 0) {
		return [...next];
	}
	if (capabilities.includes("streaming")) next.add("streaming");
	if (capabilities.includes("tools")) next.add("tools");
	if (capabilities.includes("reasoning")) next.add("reasoning");
	if (capabilities.includes("prompt-cache")) next.add("prompt-cache");
	if (capabilities.includes("vision")) {
		next.add("images");
		next.add("files");
	}
	return [...next];
}

function isCompleteProviderMetadata(
	provider: StoredProviderEntry["provider"],
): provider is NonNullable<StoredProviderEntry["provider"]> {
	return (
		provider != null &&
		typeof provider.name === "string" &&
		typeof provider.baseUrl === "string"
	);
}

function resolveProviderProtocol(
	protocol: ProviderProtocol | undefined,
	fallback: ProviderProtocol | undefined,
): ProviderProtocol {
	return protocol ?? fallback ?? "openai-chat";
}

function resolveProviderClient(
	client: ProviderClient | undefined,
	protocol: ProviderProtocol,
	fallback: ProviderClient | undefined,
): ProviderClient {
	return (
		client ??
		fallback ??
		(protocol === "openai-responses" ? "openai" : "openai-compatible")
	);
}

function toStoredModelInfo(
	modelId: string,
	model: StoredModelEntry | undefined,
	fallbackCapabilities?: ModelInfo["capabilities"],
): ModelInfo {
	const capabilities = new Set<ModelCapability>(
		model?.capabilities ?? fallbackCapabilities ?? [],
	);
	if (model?.supportsVision !== undefined) {
		if (model.supportsVision) capabilities.add("images");
		else capabilities.delete("images");
	}
	if (model?.supportsAttachments !== undefined) {
		if (model.supportsAttachments) capabilities.add("files");
		else capabilities.delete("files");
	}
	if (model?.supportsReasoning !== undefined) {
		if (model.supportsReasoning) capabilities.add("reasoning");
		else capabilities.delete("reasoning");
	}

	const apiFormat = model?.isR1FormatRequired ? "r1" : model?.apiFormat;
	const hasPricing =
		model?.inputPrice !== undefined ||
		model?.outputPrice !== undefined ||
		model?.cacheReadsPrice !== undefined ||
		model?.cacheWritesPrice !== undefined;
	return {
		id: modelId,
		name: model?.name ?? modelId,
		...(model?.maxTokens !== undefined ? { maxTokens: model.maxTokens } : {}),
		...(model?.contextWindow !== undefined
			? { contextWindow: model.contextWindow }
			: {}),
		...(model?.maxInputTokens !== undefined
			? { maxInputTokens: model.maxInputTokens }
			: {}),
		...(capabilities.size > 0 ? { capabilities: [...capabilities] } : {}),
		...(model?.temperature !== undefined
			? { temperature: model.temperature }
			: {}),
		...(apiFormat !== undefined ? { apiFormat } : {}),
		...(hasPricing
			? {
					pricing: {
						...(model?.inputPrice !== undefined
							? { input: model.inputPrice }
							: {}),
						...(model?.outputPrice !== undefined
							? { output: model.outputPrice }
							: {}),
						...(model?.cacheReadsPrice !== undefined
							? { cacheRead: model.cacheReadsPrice }
							: {}),
						...(model?.cacheWritesPrice !== undefined
							? { cacheWrite: model.cacheWritesPrice }
							: {}),
					},
				}
			: {}),
	};
}

function registerCustomModels(
	providerId: string,
	models: StoredProviderEntry["models"] | undefined,
): void {
	for (const [modelKey, model] of Object.entries(models ?? {})) {
		const modelId = model.id?.trim() || modelKey.trim();
		if (!modelId) {
			continue;
		}
		LlmsModels.registerModel(
			providerId,
			modelId,
			toStoredModelInfo(modelId, model),
		);
	}
}

function modelInfoWithDefaults(
	modelId: string,
	info: ModelInfo | undefined,
	capabilities: ModelInfo["capabilities"] | undefined,
): ModelInfo {
	return {
		...(info ?? {}),
		id: modelId,
		name: info?.name ?? modelId,
		capabilities: info?.capabilities ?? capabilities,
	};
}

function getGeneratedModelsForProvider(
	providerId: string,
): Record<string, ModelInfo> {
	const generated = Object.assign(
		{},
		...LlmsModels.resolveProviderModelCatalogKeys(providerId).map(
			(catalogKey) => LlmsModels.getGeneratedModelsForProvider(catalogKey),
		),
	);
	return generated as Record<string, ModelInfo>;
}

export function registerProviderSettingsProvider(
	settings: ProviderSettings,
): void {
	const providerId = settings.provider.trim();
	if (!providerId || LlmsModels.isBuiltInProviderId(providerId)) {
		return;
	}

	const baseUrl = settings.baseUrl?.trim();
	if (!baseUrl) {
		return;
	}

	const existingCollection = LlmsModels.MODEL_COLLECTIONS_BY_PROVIDER_ID[
		providerId
	] as LlmsModels.ModelCollection | undefined;
	const generatedModels = getGeneratedModelsForProvider(providerId);
	const modelCapabilities = toModelCapabilities(settings.capabilities);
	const fallbackCapabilities =
		modelCapabilities.length > 0 ? modelCapabilities : undefined;
	const modelId = settings.model?.trim();
	const models: Record<string, ModelInfo> = {
		...generatedModels,
		...(existingCollection?.models ?? {}),
	};

	if (modelId) {
		models[modelId] = modelInfoWithDefaults(
			modelId,
			models[modelId],
			fallbackCapabilities,
		);
	}

	const modelIds = Object.keys(models).filter(Boolean);
	const defaultModelId = modelId || modelIds[0];
	if (!defaultModelId) {
		return;
	}
	const protocol = resolveProviderProtocol(
		settings.protocol,
		existingCollection?.provider.protocol,
	);
	const client = resolveProviderClient(
		settings.client,
		protocol,
		existingCollection?.provider.client,
	);

	LlmsModels.registerProvider({
		provider: {
			id: providerId,
			name: existingCollection?.provider.name ?? titleCaseFromId(providerId),
			description: existingCollection?.provider.description,
			protocol,
			client,
			baseUrl,
			modelsSourceUrl: existingCollection?.provider.modelsSourceUrl,
			defaultModelId,
			capabilities:
				toProviderCapabilities(settings.capabilities) ??
				existingCollection?.provider.capabilities,
			source: "file",
		},
		models,
	});
}

export function registerConfiguredProvidersFromSettings(
	state: StoredProviderSettings,
): void {
	for (const entry of Object.values(state.providers)) {
		registerProviderSettingsProvider(entry.settings);
	}
}

/**
 * Custom Provider Registry
 *
 * This module manages the registration of custom OpenAI-compatible providers and
 * their models based on local JSON files. It provides functions to read/write the models
 * registry file and to register providers with the LlmsModels system.
 */
export function registerCustomProvider(
	providerId: string,
	entry: StoredProviderEntry,
): void {
	const storedModels = entry.models ?? {};
	if (!isCompleteProviderMetadata(entry.provider)) {
		registerCustomModels(providerId, storedModels);
		return;
	}

	const modelCapabilities = toModelCapabilities(entry.provider.capabilities);
	const modelEntries = Object.entries(storedModels)
		.map(([modelKey, model]) => ({
			id: model.id?.trim() || modelKey.trim(),
			model,
		}))
		.filter(({ id }) => id.length > 0);
	const defaultModelId =
		entry.provider.defaultModelId?.trim() || modelEntries[0]?.id || "default";
	const protocol = resolveProviderProtocol(entry.provider.protocol, undefined);
	const client = resolveProviderClient(
		entry.provider.client,
		protocol,
		undefined,
	);
	const normalizedModels = Object.fromEntries(
		modelEntries.map(({ id, model }) => [
			id,
			{
				...toStoredModelInfo(
					id,
					model,
					modelCapabilities.length > 0 ? modelCapabilities : undefined,
				),
				status: "active" as const,
			},
		]),
	);

	LlmsModels.registerProvider({
		provider: {
			id: providerId,
			name: entry.provider.name.trim() || titleCaseFromId(providerId),
			protocol,
			client,
			baseUrl: entry.provider.baseUrl,
			modelsSourceUrl: entry.provider.modelsSourceUrl,
			defaultModelId,
			capabilities: toProviderCapabilities(entry.provider.capabilities),
			source: "file",
		},
		models: normalizedModels,
	});
}

/**
 * Apply a single provider's updated models.json entry to the live @cline/llms
 * registry. Unlike {@link ensureCustomProvidersLoadedSync}, which loads a
 * models.json path at most once per process, this applies on every call so
 * writes made after startup are reflected immediately: models removed from the
 * entry are unregistered, and the remaining entry is (re-)registered.
 */
export function syncStoredProviderRegistration(
	providerId: string,
	previous: StoredProviderEntry | undefined,
	next: StoredProviderEntry | undefined,
): void {
	const nextModels = next?.models ?? {};
	const removedModelIds = new Set<string>();
	for (const [modelKey, model] of Object.entries(previous?.models ?? {})) {
		if (Object.hasOwn(nextModels, modelKey)) {
			continue;
		}
		const modelId = model.id?.trim() || modelKey.trim();
		if (modelId) {
			removedModelIds.add(modelId);
			LlmsModels.unregisterModel(providerId, modelId);
		}
	}
	if (!next) {
		return;
	}
	const liveCollection = LlmsModels.getProviderCollectionSync(providerId);
	registerCustomProvider(providerId, next);
	// For entries with complete provider metadata, registerCustomProvider
	// replaces the live collection with one built from models.json alone.
	// Merge back models that came from other sources (generated catalog,
	// providers.json settings), letting the fresh models.json entries win and
	// dropping models removed by this write.
	const registered = LlmsModels.getProviderCollectionSync(providerId);
	if (liveCollection && registered && registered !== liveCollection) {
		const preservedModels = Object.fromEntries(
			Object.entries(liveCollection.models).filter(
				([modelId]) => !removedModelIds.has(modelId),
			),
		);
		LlmsModels.registerProvider({
			...registered,
			models: { ...preservedModels, ...registered.models },
		});
	}
}

/**
 * Load models.json into the @cline/llms registry at most once per path per
 * process; subsequent calls are no-ops. It does NOT re-read the file after
 * writes — use {@link syncStoredProviderRegistration} to reflect a write in
 * the live registry.
 */
export function ensureCustomProvidersLoadedSync(
	manager: ProviderSettingsManager,
): void {
	const modelsPath = resolveModelsRegistryPath(manager);
	if (LOADED_MODELS_REGISTRY_PATHS.has(modelsPath)) {
		return;
	}
	const state = readModelsFileSync(modelsPath);
	for (const [providerId, entry] of Object.entries(state.providers)) {
		registerCustomProvider(providerId, entry);
	}
	LOADED_MODELS_REGISTRY_PATHS.add(modelsPath);
}

export async function ensureCustomProvidersLoaded(
	manager: ProviderSettingsManager,
): Promise<void> {
	const modelsPath = resolveModelsRegistryPath(manager);
	if (LOADED_MODELS_REGISTRY_PATHS.has(modelsPath)) {
		return;
	}
	const state = await readModelsFile(modelsPath);
	for (const [providerId, entry] of Object.entries(state.providers)) {
		registerCustomProvider(providerId, entry);
	}
	LOADED_MODELS_REGISTRY_PATHS.add(modelsPath);
}

