					},
					models: {
						alpha: {
							name: "Alpha",
						},
					},
				},
			},
		});
	});

	it("falls back to an empty registry when the file shape is malformed", () => {
		expect(
			parseModelsFile({
				version: 1,
				providers: [],
			}),
		).toEqual({ version: 1, providers: {} });
	});
});

