function mergeFields(
	baseFields: ProviderConfigFields["fields"],
	metadataFields: ProviderConfigFieldMetadata["fields"],
): ProviderConfigFields["fields"] {
	const fields: ProviderConfigFields["fields"] = {};
	for (const field of FIELD_KEYS) {
		const base = baseFields[field];
		const metadata = metadataFields[field];
		if (base || metadata) fields[field] = { ...base, ...metadata };
	}
	return fields;
}

function applyProviderConfigFieldMetadata(
	config: ProviderConfigFields,
): ProviderConfigFields {
	const metadata = PROVIDER_CONFIG_FIELD_METADATA[config.providerId];
	if (!metadata) return config;

	return {
		...config,
		description: metadata.description ?? config.description,
		fields:
			metadata.mode === "replace"
				? metadata.fields
				: mergeFields(config.fields, metadata.fields),
	};
}

const EDITABLE_BASE_URL_PROVIDER_IDS = new Set([
	"ollama",
	"lmstudio",
	"litellm",
	"openai-compatible",
]);

function shouldExposeBaseUrlField(
	providerId: string,
	collection: LlmsModels.ModelCollection | undefined,
): boolean {
	if (!collection?.provider.baseUrl) return false;
	if (collection.provider.source !== "system") return true;
	return EDITABLE_BASE_URL_PROVIDER_IDS.has(providerId);
}

/**
 * Project a provider into the inputs a configure-dialog should render.
 *
 * No fields are marked "required". `llms` no longer pre-flights credentials,
 * so a missing API key surfaces as the provider's own auth error rather than
 * a synthetic SDK failure. UIs may still require fields client-side if they
 * want, but the runtime does not.
 *
 * - OAuth providers (`cline`, `oca`, `openai-codex`) return `authMethod:
 *   "oauth"` with no fields; the configure UI should route to the OAuth
 *   login flow instead.
 * - Local auth providers return `authMethod: "local"` with no fields. The
 *   configure UI should show provider-specific local readiness instead.
 * - All other providers return `apiKey`. Built-in local/proxy-style providers
 *   with user-supplied endpoints, plus user-added providers with saved
 *   endpoints, also return a pre-filled `baseUrl` field.
 *
 * Returns the same fallback shape for unknown providers (single `apiKey`
 * input, no default base URL) so callers can render a reasonable configure
 * dialog without per-id branches.
 */
export function getProviderConfigFields(
	providerId: string,
): ProviderConfigFields {
	const id = LlmsModels.normalizeProviderId(providerId);
	if (isOAuthProvider(id)) {
		return { providerId: id, authMethod: "oauth", fields: {} };
	}

	const collection = LlmsModels.MODEL_COLLECTIONS_BY_PROVIDER_ID[id];
	if (collection?.provider.capabilities?.includes("local-auth")) {
		return { providerId: id, authMethod: "local", fields: {} };
	}

	const defaultBaseUrl = collection?.provider.baseUrl;
	const fields: ProviderConfigFields["fields"] = {
		apiKey: {},
	};
	if (shouldExposeBaseUrlField(id, collection)) {
		fields.baseUrl = { defaultValue: defaultBaseUrl };
	}

	return applyProviderConfigFieldMetadata({
		providerId: id,
		authMethod: "api-key",
		fields,
	});
}

import {
	existsSync,
	mkdirSync,
	readdirSync,
	rmdirSync,
	rmSync,
	unlinkSync,
} from "node:fs";
import { dirname, join } from "node:path";
import {
	parseSubSessionId,
	parseTeamTaskSubSessionId,
} from "../session/models/session-graph";

export function nowIso(): string {
	return new Date().toISOString();
}

export function unlinkIfExists(path: string | null | undefined): void {
	if (!path || !existsSync(path)) {
		return;
	}
	try {
		unlinkSync(path);
	} catch {
		// Best effort cleanup.
	}
}

export interface SessionArtifactPaths {
	messagesPath: string;
}

function childArtifactFileStem(sessionId: string): {
	rootSessionId: string;
	fileStem: string;
} {
	const teamTask = parseTeamTaskSubSessionId(sessionId);
	if (teamTask) {
		return {
			rootSessionId: teamTask.rootSessionId,
			fileStem: `${teamTask.agentId}__${teamTask.teamTaskId}`,
		};
	}

	const subagent = parseSubSessionId(sessionId);
	if (subagent) {
		return {
			rootSessionId: subagent.rootSessionId,
			fileStem: subagent.agentId,
		};
	}

	return {
		rootSessionId: sessionId,
		fileStem: sessionId,
	};
}

export class SessionArtifacts {
	constructor(private readonly ensureSessionsDir: () => string) {}

	public sessionArtifactsDir(sessionId: string): string {
		return join(this.ensureSessionsDir(), sessionId);
	}

	public ensureSessionArtifactsDir(sessionId: string): string {
		const dir = this.sessionArtifactsDir(sessionId);
		if (!existsSync(dir)) {
			mkdirSync(dir, { recursive: true });
		}
		return dir;
	}

	public sessionMessagesPath(sessionId: string): string {
		return join(
			this.sessionArtifactsDir(sessionId),
			`${sessionId}.messages.json`,
		);
	}

	public sessionCompactionPath(sessionId: string): string {
		return join(
			this.sessionArtifactsDir(sessionId),
			`${sessionId}.compaction.json`,
		);
	}

	public sessionManifestPath(sessionId: string, ensureDir = false): string {
		const base = ensureDir
			? this.ensureSessionArtifactsDir(sessionId)
			: this.sessionArtifactsDir(sessionId);
		return join(base, `${sessionId}.json`);
	}

	public removeSessionDirIfEmpty(sessionId: string): void {
		let dir = this.sessionArtifactsDir(sessionId);
		const sessionsDir = this.ensureSessionsDir();
		while (dir.startsWith(sessionsDir) && dir !== sessionsDir) {
			if (!existsSync(dir)) {
				dir = dirname(dir);
				continue;
			}
			try {
				if (readdirSync(dir).length > 0) {
					break;
				}
				rmdirSync(dir);
			} catch {
				// Best-effort cleanup.
				break;
			}
			dir = dirname(dir);
		}
	}

	public removeSessionDir(sessionId: string): void {
		this.removeDir(this.sessionArtifactsDir(sessionId));
	}

	public removeDir(dir: string): void {
		if (!existsSync(dir)) {
			return;
		}
		try {
			rmSync(dir, { recursive: true, force: true });
		} catch {
			// Best-effort cleanup.
		}
	}

	public subagentArtifactPaths(
		sessionId: string,
		subAgentId: string,
		activeTeamTaskSessionId?: string,
	): SessionArtifactPaths {
		void subAgentId;
		void activeTeamTaskSessionId;
		const { rootSessionId, fileStem } = childArtifactFileStem(sessionId);
		const dir = this.sessionArtifactsDir(rootSessionId);
		return {
			messagesPath: join(dir, `${fileStem}.messages.json`),
		};
	}
}

