const MAX_TITLE_LENGTH = 120;

export function normalizeTitle(title?: string | null): string | undefined {
	const trimmed = title?.trim();
	return trimmed ? trimmed.slice(0, MAX_TITLE_LENGTH) : undefined;
}

export function deriveTitleFromPrompt(
	prompt?: string | null,
): string | undefined {
	// Titles are display-only, so runtime-generated notice elements are
	// stripped here rather than inside normalizeUserInput -- that function also
	// sanitizes model-bound prompts (prepareTurnInput), where the notice must
	// survive to reach the model.
	const normalized = stripModeNotices(normalizeUserInput(prompt ?? "")).trim();
	if (!normalized) return undefined;
	return normalizeTitle(normalized.split("\n")[0]?.trim());
}

export function sanitizeMetadata(
	metadata: Record<string, unknown> | null | undefined,
): Record<string, unknown> | undefined {
	if (!metadata) return undefined;
	const next = { ...metadata };
	const title = normalizeTitle(
		typeof next.title === "string" ? next.title : undefined,
	);
	if (title) {
		next.title = title;
	} else {
		delete next.title;
	}
	return Object.keys(next).length > 0 ? next : undefined;
}

export function resolveMetadataWithTitle(input: {
	metadata?: Record<string, unknown> | null;
	title?: string | null;
	prompt?: string | null;
}): Record<string, unknown> | undefined {
	const base = sanitizeMetadata(input.metadata) ?? {};
	const title =
		input.title !== undefined
			? normalizeTitle(input.title)
			: deriveTitleFromPrompt(input.prompt);
	if (title) base.title = title;
	return Object.keys(base).length > 0 ? base : undefined;
}

export type MessagesFileContext = {
	agent: "lead" | "subagent" | "teammate";
	sessionId: string;
	taskType?: string;
};

export function resolveMessagesFileContext(
	sessionId: string,
): MessagesFileContext {
	const teamTaskMatch = parseTeamTaskSubSessionId(sessionId);
	if (teamTaskMatch) {
		return {
			agent: "teammate",
			sessionId: teamTaskMatch.rootSessionId,
			taskType: "team",
		};
	}
	const subSessionMatch = parseSubSessionId(sessionId);
	if (subSessionMatch) {
		return {
			agent: "subagent",
			sessionId: subSessionMatch.rootSessionId,
			taskType: "subagent_task",
		};
	}
	return {
		agent: "lead",
		sessionId,
	};
}

export function buildMessagesFilePayload(input: {
	updatedAt: string;
	context: MessagesFileContext;
	messages: LlmsProviders.MessageWithMetadata[];
	systemPrompt?: string;
}): {
	version: 1;
	updated_at: string;
	agent: "lead" | "subagent" | "teammate";
	sessionId: string;
	taskType?: string;
	messages: StoredMessageWithMetadata[];
	system_prompt?: string;
} {
	return {
		version: 1,
		updated_at: input.updatedAt,
		agent: input.context.agent,
		sessionId: input.context.sessionId,
		...(input.context.taskType ? { taskType: input.context.taskType } : {}),
		messages: normalizeStoredMessagesForPersistence(input.messages),
		...(input.systemPrompt ? { system_prompt: input.systemPrompt } : {}),
	};
}

export function writeEmptyMessagesFile(
	path: string,
	startedAt: string,
	context: MessagesFileContext,
): void {
	mkdirSync(dirname(path), { recursive: true });
	writeFileSync(
		path,
		`${JSON.stringify(
			buildMessagesFilePayload({
				updatedAt: startedAt,
				context,
				messages: [],
			}),
			null,
			2,
		)}\n`,
		"utf8",
	);
}

export function buildManifestFromRow(
	row: SessionRow,
	overrides?: {
		status?: SessionStatus;
		endedAt?: string;
		exitCode?: number;
		metadata?: Record<string, unknown>;
	},
): SessionManifest {
	return SessionManifestSchema.parse({
		version: 1,
		session_id: row.sessionId,
		source: row.source,
		pid: row.pid,
		started_at: row.startedAt,
		ended_at: overrides?.endedAt ?? row.endedAt ?? undefined,
		exit_code: overrides?.exitCode ?? row.exitCode ?? undefined,
		status: (overrides?.status ?? row.status) as SessionStatus,
		interactive: row.interactive,
		provider: row.provider,
		model: row.model,
		cwd: row.cwd,
		workspace_root: row.workspaceRoot,
		team_name: row.teamName ?? undefined,
		enable_tools: row.enableTools,
		enable_spawn: row.enableSpawn,
		enable_teams: row.enableTeams,
		prompt: row.prompt ?? undefined,
		metadata: overrides?.metadata ?? row.metadata ?? undefined,
		messages_path: row.messagesPath ?? undefined,
	});
}

export async function withOccRetry<TFetch, TResult>(
	load: () => Promise<TFetch | undefined>,
	update: (loaded: TFetch) => Promise<TResult>,
	maxRetries: number,
): Promise<TResult | { updated: false }> {
	let attempt = 0;
	while (true) {
		const loaded = await load();
		if (loaded === undefined) {
			return { updated: false };
		}
		const result = await update(loaded);
		if (
			typeof result === "object" &&
			result !== null &&
			"updated" in result &&
			(result as { updated?: boolean }).updated === false
		) {
			attempt += 1;
			if (attempt >= maxRetries) {
				return result as TResult;
			}
			continue;
		}
		return result;
	}
}

import type { ITelemetryService } from "@cline/shared";
import { resolveDocumentsExtensionPath } from "@cline/shared/storage";
import { listHookConfigFiles } from "../hooks/hook-file-config";
import type { CoreSessionConfig } from "../types/config";
import {
	captureHookDiscovery,
	captureMentionFailed,
	captureMentionSearchResults,
	captureMentionUsed,
	captureTaskCreated,
	captureTaskRestarted,
	type TelemetryAgentIdentityProperties,
} from "./telemetry/core-events";
import type { enrichPromptWithMentions } from "./workspace";

/**
 * Emits local-only session creation telemetry (task.created/restarted and
 * hook discovery). The transport-agnostic `session.started` event is
 * emitted from `ClineCore.start` so it fires for every backend (local,
 * hub, remote) at the outer API boundary.
 */
export function emitSessionCreationTelemetry(
	config: CoreSessionConfig,
	sessionId: string,
	isRestart: boolean,
	workspacePath: string,
	agentIdentity?: Partial<TelemetryAgentIdentityProperties>,
): void {
	if (isRestart) {
		captureTaskRestarted(config.telemetry, {
			ulid: sessionId,
			apiProvider: config.providerId,
			...agentIdentity,
		});
	} else {
		captureTaskCreated(config.telemetry, {
			ulid: sessionId,
			apiProvider: config.providerId,
			...agentIdentity,
		});
	}
	captureHookDiscoveryTelemetry(config.telemetry, { workspacePath });
}

export function captureHookDiscoveryTelemetry(
	telemetry: ITelemetryService | undefined,
	options: { workspacePath: string },
): void {
	const globalHooksDir = resolveDocumentsExtensionPath("Hooks");
	const entries = listHookConfigFiles(options.workspacePath);
	const counts = new Map<string, { global: number; workspace: number }>();
	for (const entry of entries) {
		const hookName = entry.hookEventName ?? "unknown";
		const current = counts.get(hookName) ?? { global: 0, workspace: 0 };
		if (
			entry.path === globalHooksDir ||
			entry.path.startsWith(`${globalHooksDir}/`)
		) {
			current.global += 1;
		} else {
			current.workspace += 1;
		}
		counts.set(hookName, current);
	}
	for (const [hookName, count] of counts.entries()) {
		captureHookDiscovery(telemetry, hookName, count.global, count.workspace);
	}
}

export function emitMentionTelemetry(
	telemetry: ITelemetryService | undefined,
	enriched: Awaited<ReturnType<typeof enrichPromptWithMentions>>,
): void {
	for (const mention of enriched.mentions) {
		captureMentionSearchResults(
			telemetry,
			mention,
			enriched.matchedFiles.includes(mention) ? 1 : 0,
			"file",
			!enriched.matchedFiles.includes(mention),
		);
	}
	for (const matched of enriched.matchedFiles) {
		captureMentionUsed(telemetry, "file", matched.length);
	}
	for (const ignored of enriched.ignoredMentions) {
		captureMentionFailed(telemetry, "file", "not_found", ignored);
	}
}

