import type { Meter } from "@opentelemetry/api";
import type { Logger as OpenTelemetryLogger } from "@opentelemetry/api-logs";
import type { LoggerProvider } from "@opentelemetry/sdk-logs";
import type { MeterProvider } from "@opentelemetry/sdk-metrics";
import type {
	ITelemetryAdapter,
	TelemetryMetadata,
	TelemetryPrimitive,
	TelemetryProperties,
} from "./ITelemetryAdapter";

type FlatTelemetryAttributes = Record<string, string | number | boolean>;

export interface OpenTelemetryAdapterOptions {
	readonly metadata: TelemetryMetadata;
	readonly meterProvider?: MeterProvider | null;
	readonly loggerProvider?: LoggerProvider | null;
	readonly name?: string;
	readonly enabled?: boolean | (() => boolean);
	readonly distinctId?: string;
	readonly commonProperties?: TelemetryProperties;
}

export class OpenTelemetryAdapter implements ITelemetryAdapter {
	readonly name: string;

	private readonly metadata: TelemetryMetadata;
	private readonly meter: Meter | null;
	private readonly logger: OpenTelemetryLogger | null;
	private readonly enabled: boolean | (() => boolean);
	private distinctId?: string;
	private commonProperties: TelemetryProperties;
	private counters = new Map<string, ReturnType<Meter["createCounter"]>>();
	private histograms = new Map<string, ReturnType<Meter["createHistogram"]>>();
	private gauges = new Map<
		string,
		ReturnType<Meter["createObservableGauge"]>
	>();
	private gaugeValues = new Map<
		string,
		Map<string, { value: number; attributes?: TelemetryProperties }>
	>();
	private readonly meterProvider?: MeterProvider | null;
	private readonly loggerProvider?: LoggerProvider | null;

	constructor(options: OpenTelemetryAdapterOptions) {
		this.name = options.name ?? "OpenTelemetryAdapter";
		this.metadata = { ...options.metadata };
		this.meterProvider = options.meterProvider;
		this.loggerProvider = options.loggerProvider;
		this.meter = options.meterProvider?.getMeter("cline") ?? null;
		this.logger = options.loggerProvider?.getLogger("cline") ?? null;
		this.enabled = options.enabled ?? true;
		this.distinctId = options.distinctId;
		this.commonProperties = options.commonProperties
			? { ...options.commonProperties }
			: {};
	}

	emit(event: string, properties?: TelemetryProperties): void {
		if (!this.isEnabled()) {
			return;
		}
		this.emitLog(event, properties, false);
	}

	emitRequired(event: string, properties?: TelemetryProperties): void {
		this.emitLog(event, properties, true);
	}

	recordCounter(
		name: string,
		value: number,
		attributes?: TelemetryProperties,
		description?: string,
		required = false,
	): void {
		if (!this.meter || (!required && !this.isEnabled())) {
			return;
		}

		let counter = this.counters.get(name);
		if (!counter) {
			counter = this.meter.createCounter(
				name,
				description ? { description } : undefined,
			);
			this.counters.set(name, counter);
		}

		counter.add(
			value,
			this.flattenProperties(this.buildAttributes(attributes)),
		);
	}

	recordHistogram(
		name: string,
		value: number,
		attributes?: TelemetryProperties,
		description?: string,
		required = false,
	): void {
		if (!this.meter || (!required && !this.isEnabled())) {
			return;
		}

		let histogram = this.histograms.get(name);
		if (!histogram) {
			histogram = this.meter.createHistogram(
				name,
				description ? { description } : undefined,
			);
			this.histograms.set(name, histogram);
		}

		histogram.record(
			value,
			this.flattenProperties(this.buildAttributes(attributes)),
		);
	}

	recordGauge(
		name: string,
		value: number | null,
		attributes?: TelemetryProperties,
		description?: string,
		required = false,
	): void {
		if (!this.meter || (!required && !this.isEnabled())) {
			return;
		}

		const mergedAttributes = this.buildAttributes(attributes);
		const attrKey = JSON.stringify(mergedAttributes);
		const existingSeries = this.gaugeValues.get(name);

		if (value === null) {
			if (existingSeries) {
				existingSeries.delete(attrKey);
				if (existingSeries.size === 0) {
					this.gaugeValues.delete(name);
					this.gauges.delete(name);
				}
			}
			return;
		}

		let series = existingSeries;
		if (!series) {
			series = new Map();
			this.gaugeValues.set(name, series);
		}

		if (!this.gauges.has(name)) {
			const gauge = this.meter.createObservableGauge(
				name,
				description ? { description } : undefined,
			);
			gauge.addCallback((observableResult) => {
				for (const data of this.snapshotGaugeSeries(name)) {
					observableResult.observe(
						data.value,
						this.flattenProperties(data.attributes),
					);
				}
			});
			this.gauges.set(name, gauge);
		}

		series.set(attrKey, { value, attributes: mergedAttributes });
	}

	isEnabled(): boolean {
		return typeof this.enabled === "function" ? this.enabled() : this.enabled;
	}

	setDistinctId(distinctId?: string): void {
		this.distinctId = distinctId;
	}

	setCommonProperties(properties: TelemetryProperties): void {
		this.commonProperties = { ...properties };
	}

	updateCommonProperties(properties: TelemetryProperties): void {
		this.commonProperties = {
			...this.commonProperties,
			...properties,
		};
	}

	async flush(): Promise<void> {
		await Promise.all([
			this.meterProvider?.forceFlush?.(),
			this.loggerProvider?.forceFlush?.(),
		]);
	}

	async dispose(): Promise<void> {
		await Promise.all([
			this.meterProvider?.shutdown?.(),
			this.loggerProvider?.shutdown?.(),
		]);
	}

	private emitLog(
		event: string,
		properties: TelemetryProperties | undefined,
		required: boolean,
	): void {
		if (!this.logger) {
			return;
		}

		const attributes = this.flattenProperties(
			this.buildAttributes(properties, required),
		);
		this.logger.emit({
			severityText: "INFO",
			body: event,
			attributes,
		});
	}

	private buildAttributes(
		properties?: TelemetryProperties,
		required = false,
	): TelemetryProperties {
		return {
			...this.commonProperties,
			...this.metadata,
			...properties,
			...(this.distinctId ? { distinct_id: this.distinctId } : {}),
			...(required ? { _required: true } : {}),
		};
	}

	private snapshotGaugeSeries(
		name: string,
	): Array<{ value: number; attributes?: TelemetryProperties }> {
		const series = this.gaugeValues.get(name);
		if (!series) {
			return [];
		}
		return Array.from(series.values(), (entry) => ({
			value: entry.value,
			attributes: entry.attributes ? { ...entry.attributes } : undefined,
		}));
	}

	private flattenProperties(
		properties?: TelemetryProperties,
		prefix = "",
		seen: WeakSet<object> = new WeakSet(),
		depth = 0,
	): FlatTelemetryAttributes {
		if (!properties) {
			return {};
		}

		const flattened: FlatTelemetryAttributes = {};
		const maxArraySize = 100;
		const maxDepth = 10;

		for (const [key, value] of Object.entries(properties)) {
			if (key === "__proto__" || key === "constructor" || key === "prototype") {
				continue;
			}

			const fullKey = prefix ? `${prefix}.${key}` : key;

			if (value === null || value === undefined) {
				flattened[fullKey] = String(value);
				continue;
			}

			if (Array.isArray(value)) {
				const limited =
					value.length > maxArraySize ? value.slice(0, maxArraySize) : value;
				try {
					flattened[fullKey] = JSON.stringify(limited);
				} catch {
					flattened[fullKey] = "[UnserializableArray]";
				}
				if (value.length > maxArraySize) {
					flattened[`${fullKey}_truncated`] = true;
					flattened[`${fullKey}_original_length`] = value.length;
				}
				continue;
			}

			if (typeof value === "object") {
				if (value instanceof Date) {
					flattened[fullKey] = value.toISOString();
					continue;
				}
				if (value instanceof Error) {
					flattened[fullKey] = value.message;
					continue;
				}
				if (seen.has(value)) {
					flattened[fullKey] = "[Circular]";
					continue;
				}
				if (depth >= maxDepth) {
					flattened[fullKey] = "[MaxDepthExceeded]";
					continue;
				}

				seen.add(value);
				Object.assign(
					flattened,
					this.flattenProperties(
						value as TelemetryProperties,
						fullKey,
						seen,
						depth + 1,
					),
				);
				continue;
			}

			if (isTelemetryPrimitive(value)) {
				flattened[fullKey] = value;
				continue;
			}

			try {
				flattened[fullKey] = JSON.stringify(value);
			} catch {
				flattened[fullKey] = String(value);
			}
		}

		return flattened;
	}
}

function isTelemetryPrimitive(
	value: unknown,
): value is Exclude<TelemetryPrimitive, null | undefined> {
	return (
		typeof value === "string" ||
		typeof value === "number" ||
		typeof value === "boolean"
	);
}

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { BasicLogger } from "@cline/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { writeGlobalSettings } from "../global-settings";
import {
	createConfiguredTelemetryService,
	createOpenTelemetryTelemetryService,
	OpenTelemetryProvider,
} from "./OpenTelemetryProvider";
import { TelemetryService } from "./TelemetryService";

describe("createOpenTelemetryTelemetryService", () => {
	const previousGlobalSettingsPath = process.env.CLINE_GLOBAL_SETTINGS_PATH;
	let tempRoot: string | undefined;

	beforeEach(() => {
		tempRoot = mkdtempSync(join(tmpdir(), "core-telemetry-settings-"));
		process.env.CLINE_GLOBAL_SETTINGS_PATH = join(
			tempRoot,
			"global-settings.json",
		);
	});

	afterEach(() => {
		process.env.CLINE_GLOBAL_SETTINGS_PATH = previousGlobalSettingsPath;
		if (tempRoot) {
			rmSync(tempRoot, { recursive: true, force: true });
			tempRoot = undefined;
		}
		vi.restoreAllMocks();
	});

	it("logs a provider creation event during bootstrap", async () => {
		const captureRequired = vi
			.spyOn(TelemetryService.prototype, "captureRequired")
			.mockImplementation(() => {});

		const { provider } = createOpenTelemetryTelemetryService({
			metadata: {
				extension_version: "1.2.3",
				cline_type: "cli",
				platform: "terminal",
				platform_version: process.version,
				os_type: process.platform,
				os_version: "unknown",
			},
			enabled: true,
			logsExporter: "console",
			metricsExporter: "otlp",
			otlpProtocol: "http/json",
			otlpEndpoint: "http://localhost:4318",
			serviceName: "cline-cli",
			serviceVersion: "1.2.3",
		});

		expect(captureRequired).toHaveBeenCalledWith(
			"telemetry.provider_created",
			expect.objectContaining({
				provider: "opentelemetry",
				enabled: true,
				logsExporter: "console",
				metricsExporter: "otlp",
				otlpProtocol: "http/json",
				hasOtlpEndpoint: true,
				serviceName: "cline-cli",
				serviceVersion: "1.2.3",
			}),
		);

		await provider.dispose();
	});

	it("defers the provider creation event until emitProviderCreated is called", async () => {
		const captureRequired = vi
			.spyOn(TelemetryService.prototype, "captureRequired")
			.mockImplementation(() => {});

		const { provider, emitProviderCreated } =
			createOpenTelemetryTelemetryService({
				metadata: {
					extension_version: "1.2.3",
					cline_type: "cli",
					platform: "terminal",
					platform_version: process.version,
					os_type: process.platform,
					os_version: "unknown",
				},
				enabled: true,
				logsExporter: "console",
				serviceName: "cline-cli",
				serviceVersion: "1.2.3",
				deferProviderCreatedEvent: true,
			});

		expect(captureRequired).not.toHaveBeenCalled();

		emitProviderCreated();

		expect(captureRequired).toHaveBeenCalledWith(
			"telemetry.provider_created",
			expect.objectContaining({
				provider: "opentelemetry",
				serviceName: "cline-cli",
			}),
		);

		await provider.dispose();
	});

	it("registers a tracer provider when tracesExporter is set", async () => {
		const { provider } = createOpenTelemetryTelemetryService({
			metadata: {
				extension_version: "1.2.3",
				cline_type: "cli",
				platform: "terminal",
				platform_version: process.version,
				os_type: process.platform,
				os_version: "unknown",
			},
			enabled: true,
			tracesExporter: "console",
			logsExporter: "console",
			metricsExporter: "console",
			serviceName: "cline-test",
		});

		expect(provider.tracerProvider).not.toBeNull();
		const span = provider.getTracer("test").startSpan("verify.tracing");
		span.end();
		await provider.dispose();
	});

	it("does not create an OTEL provider when disabled", () => {
		const providerSpy = vi.spyOn(
			OpenTelemetryProvider.prototype,
			"createTelemetryService",
		);

		const { telemetry, provider } = createConfiguredTelemetryService({
			metadata: {
				extension_version: "1.2.3",
				cline_type: "cli",
				platform: "terminal",
				platform_version: process.version,
				os_type: process.platform,
				os_version: "unknown",
			},
			enabled: false,
		});

		expect(provider).toBeUndefined();
		expect(providerSpy).not.toHaveBeenCalled();
		expect(telemetry).toBeInstanceOf(TelemetryService);
	});

	it("does not create configured telemetry when globally opted out", () => {
		writeGlobalSettings({ telemetryOptOut: true });
		const logger: BasicLogger = {
			debug: vi.fn(),
			log: vi.fn(),
			error: vi.fn(),
		};
		const providerSpy = vi.spyOn(
			OpenTelemetryProvider.prototype,
			"createTelemetryService",
		);

		const { telemetry, provider } = createConfiguredTelemetryService({
			metadata: {
				extension_version: "1.2.3",
				cline_type: "cli",
				platform: "terminal",
				platform_version: process.version,
				os_type: process.platform,
				os_version: "unknown",
			},
			commonProperties: {
				organization_id: "org-1",
			},
			distinctId: "distinct-1",
			enabled: true,
			logsExporter: "console",
			logger,
		});
		telemetry.updateMetadata({ cline_type: "cli-updated" });
		telemetry.updateCommonProperties({ member_id: "member-1" });

		telemetry.capture({
			event: "session.started",
			properties: { sessionId: "session-1" },
		});

		expect(provider).toBeUndefined();
		expect(providerSpy).not.toHaveBeenCalled();
		expect(telemetry.isEnabled()).toBe(false);
		expect(Reflect.get(telemetry, "addAdapter")).toBeUndefined();
		expect(Reflect.get(telemetry, "distinctId")).toBe("distinct-1");
		expect(Reflect.get(telemetry, "metadata")).toEqual(
			expect.objectContaining({
				cline_type: "cli-updated",
				platform: "terminal",
			}),
		);
		expect(Reflect.get(telemetry, "commonProperties")).toEqual({
			organization_id: "org-1",
			member_id: "member-1",
		});
		expect(logger.log).not.toHaveBeenCalled();
	});

	it("preserves metadata when disabled", () => {
		const metadata = {
			extension_version: "1.0.0",
			cline_type: "kanban",
			platform: "kanban",
			platform_version: "v22.0.0",
			os_type: "darwin",
			os_version: "15.0",
		};
		const { telemetry } = createConfiguredTelemetryService({
			metadata,
			enabled: false,
		});
		const spy = vi.fn();
		(Reflect.get(telemetry, "adapters") as unknown[]).push({
			name: "test",
			emit: spy,
			emitRequired: spy,
			isEnabled: () => true,
			recordCounter: vi.fn(),
			recordHistogram: vi.fn(),
			recordGauge: vi.fn(),
			flush: async () => {},
			dispose: async () => {},
		});
		telemetry.captureRequired("test.event", {});
		expect(spy).toHaveBeenCalledWith(
			"test.event",
			expect.objectContaining({
				cline_type: "kanban",
				platform: "kanban",
			}),
		);
	});

	it("preserves metadata in the enabled (OTEL) path", async () => {
		const metadata = {
			extension_version: "1.0.0",
			cline_type: "kanban",
			platform: "kanban",
			platform_version: "v22.0.0",
			os_type: "darwin",
			os_version: "15.0",
		};
		const { telemetry, provider } = createOpenTelemetryTelemetryService({
			metadata,
			enabled: true,
			logsExporter: "console",
		});
		const spy = vi.fn();
		(Reflect.get(telemetry, "adapters") as unknown[]).push({
			name: "test",
			emit: spy,
			emitRequired: spy,
			isEnabled: () => true,
			recordCounter: vi.fn(),
			recordHistogram: vi.fn(),
			recordGauge: vi.fn(),
			flush: async () => {},
			dispose: async () => {},
		});
		telemetry.captureRequired("test.event", {});
		expect(spy).toHaveBeenCalledWith(
			"test.event",
			expect.objectContaining({
				cline_type: "kanban",
				platform: "kanban",
			}),
		);
		await provider.dispose();
	});

	it("delivers metadata to the OTEL logger without duplication", async () => {
		const otelEmit = vi.fn();
		const provider = new OpenTelemetryProvider({
			enabled: true,
		});
		// Replace the loggerProvider with a mock so we can inspect emit calls
		Reflect.set(provider, "loggerProvider", {
			getLogger: () => ({ emit: otelEmit }),
			forceFlush: async () => {},
			shutdown: async () => {},
		});

		const metadata = {
			extension_version: "1.0.0",
			cline_type: "kanban",
			platform: "kanban",
			platform_version: "v22.0.0",
			os_type: "darwin",
			os_version: "15.0",
		};

		const telemetry = provider.createTelemetryService({ metadata });

		telemetry.captureRequired("test.otel_event", { custom_prop: "value" });

		expect(otelEmit).toHaveBeenCalledTimes(1);
		const emittedAttributes = otelEmit.mock.calls[0][0].attributes;

		// Metadata fields must be present
		expect(emittedAttributes).toMatchObject({
			cline_type: "kanban",
			platform: "kanban",
			extension_version: "1.0.0",
			custom_prop: "value",
		});

		// Verify no key appears more than once (flattened object can't have
		// duplicate keys, but this guards against nested duplication patterns
		// like metadata appearing under a sub-prefix)
		const keys = Object.keys(emittedAttributes);
		const metadataKeys = Object.keys(metadata);
		for (const mk of metadataKeys) {
			const occurrences = keys.filter((k) => k === mk || k.endsWith(`.${mk}`));
			expect(
				occurrences,
				`metadata key "${mk}" should appear exactly once, found: ${occurrences.join(", ")}`,
			).toHaveLength(1);
		}

		await provider.dispose();
	});

	it("propagates updateMetadata to OTEL logger output", async () => {
		const otelEmit = vi.fn();
		const provider = new OpenTelemetryProvider({
			enabled: true,
		});
		Reflect.set(provider, "loggerProvider", {
			getLogger: () => ({ emit: otelEmit }),
			forceFlush: async () => {},
			shutdown: async () => {},
		});

		const metadata = {
			extension_version: "1.0.0",
			cline_type: "kanban",
			platform: "kanban",
			platform_version: "v22.0.0",
			os_type: "darwin",
			os_version: "15.0",
		};

		const telemetry = provider.createTelemetryService({ metadata });

		// Update metadata after construction
		telemetry.updateMetadata({ cline_type: "kanban-updated" });

		telemetry.captureRequired("test.updated_event", {});

		// The OTEL logger should see the updated value
		const emittedAttributes =
			otelEmit.mock.calls[otelEmit.mock.calls.length - 1][0].attributes;
		expect(emittedAttributes.cline_type).toBe("kanban-updated");

		await provider.dispose();
	});

	it("preserves logger when disabled", () => {
		const logger: BasicLogger = {
			debug: vi.fn(),
			log: vi.fn(),
			error: vi.fn(),
		};
		const { telemetry } = createConfiguredTelemetryService({
			metadata: {
				extension_version: "1.0.0",
				cline_type: "kanban",
				platform: "kanban",
				platform_version: "v22.0.0",
				os_type: "darwin",
				os_version: "15.0",
			},
			enabled: false,
			logger,
		});

		telemetry.capture({
			event: "session.started",
			properties: { sessionId: "session-1" },
		});

		expect(logger.log).toHaveBeenCalledWith(
			"telemetry.event",
			expect.objectContaining({
				event: "session.started",
			}),
		);
	});

	it("attaches the logger adapter when creating configured telemetry", () => {
		const logger: BasicLogger = {
			debug: vi.fn(),
			log: vi.fn(),
			error: vi.fn(),
		};
		const { telemetry, provider } = createConfiguredTelemetryService({
			metadata: {
				extension_version: "1.2.3",
				cline_type: "cli",
				platform: "terminal",
				platform_version: process.version,
				os_type: process.platform,
				os_version: "unknown",
			},
			enabled: true,
			logsExporter: "console",
			logger,
		});

		telemetry.capture({
			event: "session.started",
			properties: { sessionId: "session-1" },
		});

		expect(logger.log).toHaveBeenCalledWith(
			"telemetry.event",
			expect.objectContaining({
				event: "session.started",
			}),
		);

		return provider?.dispose();
	});
});

