import { resolveCoreDistinctId } from "./distinct-id";
import {
	OpenTelemetryAdapter,
	type OpenTelemetryAdapterOptions,
} from "./OpenTelemetryAdapter";
import { TelemetryService } from "./TelemetryService";

type OpenTelemetryExporterKind = "console" | "otlp";
type OpenTelemetryProtocol = "http/json";

class OptedOutTelemetryService implements ITelemetryService {
	private distinctId?: string;
	private metadata: Partial<TelemetryMetadata>;
	private commonProperties: TelemetryProperties;

	constructor(
		options: {
			metadata?: Partial<TelemetryMetadata>;
			distinctId?: string;
			commonProperties?: TelemetryProperties;
		} = {},
	) {
		this.distinctId = options.distinctId;
		this.metadata = { ...(options.metadata ?? {}) };
		this.commonProperties = { ...(options.commonProperties ?? {}) };
	}

	setDistinctId(distinctId?: string): void {
		this.distinctId = distinctId;
	}
	setMetadata(metadata: Partial<TelemetryMetadata>): void {
		this.metadata = { ...metadata };
	}
	updateMetadata(metadata: Partial<TelemetryMetadata>): void {
		this.metadata = {
			...this.metadata,
			...metadata,
		};
	}
	setCommonProperties(properties: TelemetryProperties): void {
		this.commonProperties = { ...properties };
	}
	updateCommonProperties(properties: TelemetryProperties): void {
		this.commonProperties = {
			...this.commonProperties,
			...properties,
		};
	}
	isEnabled(): boolean {
		return false;
	}
	capture(input: { properties?: TelemetryProperties }): void {
		this.resolveProperties(input.properties);
	}
	captureRequired(_event: string, properties?: TelemetryProperties): void {
		this.resolveProperties(properties);
	}
	recordCounter(): void {}
	recordHistogram(): void {}
	recordGauge(): void {}
	async flush(): Promise<void> {}
	async dispose(): Promise<void> {}

	private resolveProperties(
		properties?: TelemetryProperties,
	): TelemetryProperties {
		return {
			...this.commonProperties,
			...properties,
			...this.metadata,
			...(this.distinctId ? { distinct_id: this.distinctId } : {}),
		};
	}
}

export interface OpenTelemetryProviderOptions
	extends Omit<
		OpenTelemetryClientConfig,
		"enabled" | "logsExporter" | "metricsExporter" | "tracesExporter"
	> {
	serviceName?: string;
	serviceVersion?: string;
	enabled?: boolean;
	logsExporter?: string | OpenTelemetryExporterKind[];
	metricsExporter?: string | OpenTelemetryExporterKind[];
	tracesExporter?: string | OpenTelemetryExporterKind[];
	metricExportIntervalMs?: number;
	logMaxQueueSize?: number;
	logBatchSize?: number;
	logBatchTimeoutMs?: number;
}

export interface CreateOpenTelemetryTelemetryServiceOptions
	extends OpenTelemetryProviderOptions,
		Pick<
			OpenTelemetryAdapterOptions,
			"name" | "distinctId" | "commonProperties"
		> {
	metadata: TelemetryMetadata;
	logger?: BasicLogger;
	/**
	 * Skip the automatic `telemetry.provider_created` event during construction
	 * and expose it as {@link ConfiguredTelemetryHandle.emitProviderCreated}
	 * instead. Metadata is stamped onto events at capture time, so hosts that
	 * resolve identity metadata asynchronously (e.g. over the host bridge) defer
	 * the event until that metadata is applied.
	 */
	deferProviderCreatedEvent?: boolean;
}

export class OpenTelemetryProvider {
	readonly meterProvider: MeterProvider | null;
	readonly loggerProvider: LoggerProvider | null;
	readonly tracerProvider: NodeTracerProvider | null;
	private readonly options: OpenTelemetryProviderOptions;

	constructor(options: OpenTelemetryProviderOptions = {}) {
		this.options = options;
		const resource = resourceFromAttributes({
			[ATTR_SERVICE_NAME]: options.serviceName ?? "cline",
			...(options.serviceVersion
				? { [ATTR_SERVICE_VERSION]: options.serviceVersion }
				: {}),
		});

		this.meterProvider = this.createMeterProvider(resource);
		this.loggerProvider = this.createLoggerProvider(resource);
		this.tracerProvider = this.createTracerProvider(resource);

		if (this.meterProvider) {
			metrics.setGlobalMeterProvider(this.meterProvider);
		}
		if (this.loggerProvider) {
			logs.setGlobalLoggerProvider(this.loggerProvider);
		}
		if (this.tracerProvider) {
			this.tracerProvider.register();
		}
	}

	/**
	 * Returns a tracer for manual spans. Requires {@link OpenTelemetryProviderOptions.tracesExporter}
	 * so that a {@link NodeTracerProvider} is registered.
	 */
	getTracer(name = "cline", version?: string): Tracer {
		return trace.getTracer(name, version ?? this.options.serviceVersion);
	}

	createAdapter(
		options: Omit<
			OpenTelemetryAdapterOptions,
			"meterProvider" | "loggerProvider"
		>,
	): OpenTelemetryAdapter {
		return new OpenTelemetryAdapter({
			...options,
			meterProvider: this.meterProvider,
			loggerProvider: this.loggerProvider,
		});
	}

	createTelemetryService(
		options: Omit<
			CreateOpenTelemetryTelemetryServiceOptions,
			keyof OpenTelemetryProviderOptions
		>,
	): ITelemetryService {
		const adapter = this.createAdapter({
			name: options.name,
			enabled: this.options.enabled,
			metadata: options.metadata,
		});
		return new TelemetryService({
			...options,
			adapters: [adapter],
			distinctId: resolveCoreDistinctId(options.distinctId),
		});
	}

	async forceFlush(): Promise<void> {
		await Promise.all([
			this.meterProvider?.forceFlush?.(),
			this.loggerProvider?.forceFlush?.(),
			this.tracerProvider?.forceFlush?.(),
		]);
	}

	async dispose(): Promise<void> {
		await Promise.all([
			this.meterProvider?.shutdown?.(),
			this.loggerProvider?.shutdown?.(),
			this.tracerProvider?.shutdown?.(),
		]);
	}

	private createMeterProvider(
		resource: ReturnType<typeof resourceFromAttributes>,
	): MeterProvider | null {
		const exporters = normalizeExporters(this.options.metricsExporter);
		if (exporters.length === 0) {
			return null;
		}

		const interval = Math.max(
			1_000,
			this.options.metricExportIntervalMs ??
				this.options.metricExportInterval ??
				60_000,
		);
		const timeout = Math.min(30_000, Math.floor(interval * 0.8));
		const readers = exporters
			.map((exporter) =>
				createMetricReader(exporter, {
					endpoint: this.options.otlpEndpoint,
					headers: this.options.otlpHeaders,
					insecure: this.options.otlpInsecure ?? false,
					protocol: "http/json",
					interval,
					timeout,
				}),
			)
			.filter((reader): reader is MetricReader => reader !== null);

		if (readers.length === 0) {
			return null;
		}

		return new MeterProvider({
			resource,
			readers,
		});
	}

	private createTracerProvider(
		resource: ReturnType<typeof resourceFromAttributes>,
	): NodeTracerProvider | null {
		const exporters = normalizeExporters(this.options.tracesExporter);
		if (exporters.length === 0) {
			return null;
		}

		const traceEndpoint =
			this.options.otlpTracesEndpoint ?? this.options.otlpEndpoint;
		const traceHeaders =
			this.options.otlpTracesHeaders ?? this.options.otlpHeaders;

		const processors: SpanProcessor[] = [];
		for (const exporter of exporters) {
			const processor = createSpanProcessor(exporter, {
				endpoint: traceEndpoint,
				headers: traceHeaders,
				insecure: this.options.otlpInsecure ?? false,
				protocol: "http/json",
			});
			if (processor) {
				processors.push(processor);
			}
		}
		if (processors.length === 0) {
			return null;
		}

		return new NodeTracerProvider({ resource, spanProcessors: processors });
	}

	private createLoggerProvider(
		resource: ReturnType<typeof resourceFromAttributes>,
	): LoggerProvider | null {
		const exporters = normalizeExporters(this.options.logsExporter);
		if (exporters.length === 0) {
			return null;
		}

		const processors = exporters
			.map((exporter) => {
				const logExporter = createLogExporter(exporter, {
					endpoint: this.options.otlpEndpoint,
					headers: this.options.otlpHeaders,
					insecure: this.options.otlpInsecure ?? false,
					protocol: "http/json",
				});
				if (!logExporter) {
					return null;
				}
				return new BatchLogRecordProcessor(logExporter, {
					maxQueueSize: this.options.logMaxQueueSize ?? 2048,
					maxExportBatchSize: this.options.logBatchSize ?? 512,
					scheduledDelayMillis:
						this.options.logBatchTimeoutMs ??
						this.options.logBatchTimeout ??
						5000,
				});
			})
			.filter((p): p is BatchLogRecordProcessor => p !== null);
		if (processors.length === 0) {
			return null;
		}
		return new LoggerProvider({ resource, processors });
	}
}

export function createOpenTelemetryTelemetryService(
	options: CreateOpenTelemetryTelemetryServiceOptions,
): {
	provider: OpenTelemetryProvider;
	telemetry: ITelemetryService;
	emitProviderCreated: () => void;
} {
	const provider = new OpenTelemetryProvider(options);
	const telemetry = provider.createTelemetryService(options);
	const emitProviderCreated = () => {
		telemetry.captureRequired("telemetry.provider_created", {
			provider: "opentelemetry",
			enabled: options.enabled ?? true,
			logsExporter: Array.isArray(options.logsExporter)
				? options.logsExporter.join(",")
				: options.logsExporter,
			metricsExporter: Array.isArray(options.metricsExporter)
				? options.metricsExporter.join(",")
				: options.metricsExporter,
			tracesExporter: Array.isArray(options.tracesExporter)
				? options.tracesExporter.join(",")
				: options.tracesExporter,
			otlpProtocol: options.otlpProtocol,
			hasOtlpEndpoint: Boolean(options.otlpEndpoint),
			serviceName: options.serviceName,
			serviceVersion: options.serviceVersion,
		});
	};
	if (!options.deferProviderCreatedEvent) {
		emitProviderCreated();
	}
	return {
		provider,
		telemetry,
		emitProviderCreated,
	};
}

export function createConfiguredTelemetryService(
	options: CreateOpenTelemetryTelemetryServiceOptions,
): {
	provider?: OpenTelemetryProvider;
	telemetry: ITelemetryService;
	emitProviderCreated?: () => void;
} {
	if (isTelemetryOptedOutGlobally()) {
		return {
			telemetry: new OptedOutTelemetryService(options),
		};
	}

	if (options.enabled !== true) {
		return {
			telemetry: new TelemetryService({
				...options,
				distinctId: resolveCoreDistinctId(options.distinctId),
			}),
		};
	}

	return createOpenTelemetryTelemetryService(options);
}

/**
 * Telemetry service plus the lifecycle closures (`flush`, `dispose`) every
 * host needs to drive the underlying provider during shutdown. Returned by
 * {@link createConfiguredTelemetryHandle} so detached daemons, the VS Code
 * extension, and the CLI can share one canonical implementation of the
 * "best-effort flush; settle dispose" semantics instead of each
 * re-implementing the same closures.
 */
export interface ConfiguredTelemetryHandle {
	readonly telemetry: ITelemetryService;
	/**
	 * The underlying OpenTelemetry provider, when telemetry is enabled.
	 * `undefined` when telemetry is disabled or opted out so callers can
	 * detect the inactive case without inspecting `enabled` themselves.
	 */
	readonly provider?: OpenTelemetryProvider;
	/**
	 * Best-effort flush of any pending telemetry batches. Errors are
	 * swallowed so callers can `await` this in shutdown paths without
	 * blocking deactivation on a misbehaving exporter.
	 */
	flush: () => Promise<void>;
	/** Disposes the telemetry service and its provider concurrently. */
	dispose: () => Promise<void>;
	/**
	 * Emits the `telemetry.provider_created` event. Only present when the
	 * handle was created with `deferProviderCreatedEvent: true` and telemetry
	 * is enabled; the host must call it once its identity metadata is applied.
	 */
	emitProviderCreated?: () => void;
}

/**
 * Builds a {@link ConfiguredTelemetryHandle} so hosts (CLI, VS Code, hub
 * daemon) share one canonical flush/dispose implementation. Without a
 * shared helper each host re-derived the same closures and they tended
 * to drift; this factory keeps the lifecycle uniform across hosts.
 */
export function createConfiguredTelemetryHandle(
	options: CreateOpenTelemetryTelemetryServiceOptions,
): ConfiguredTelemetryHandle {
	const { telemetry, provider, emitProviderCreated } =
		createConfiguredTelemetryService(options);

	const flush = async (): Promise<void> => {
		const candidate = provider as
			| { forceFlush?: () => Promise<void> }
			| undefined;
		if (candidate && typeof candidate.forceFlush === "function") {
			try {
				await candidate.forceFlush();
			} catch {
				// best-effort flush; swallow to avoid blocking shutdown paths
			}
		}
	};

	const dispose = async (): Promise<void> => {
		await Promise.allSettled([telemetry.dispose(), provider?.dispose()]);
	};

	return {
		telemetry,
		provider,
		flush,
		dispose,
		...(options.deferProviderCreatedEvent && emitProviderCreated
			? { emitProviderCreated }
			: {}),
	};
}

function normalizeExporters(
	exporters: OpenTelemetryProviderOptions["logsExporter"],
): OpenTelemetryExporterKind[] {
	if (!exporters) {
		return [];
	}
	const values = Array.isArray(exporters) ? exporters : exporters.split(",");
	return values
		.map((value) => value.trim())
		.filter(
			(value): value is OpenTelemetryExporterKind =>
				value === "console" || value === "otlp",
		);
}

function createLogExporter(
	exporter: OpenTelemetryExporterKind,
	options: {
		endpoint?: string;
		headers?: Record<string, string>;
		insecure: boolean;
		protocol: OpenTelemetryProtocol;
	},
): LogRecordExporter | null {
	if (exporter === "console") {
		return new ConsoleLogRecordExporter();
	}
	if (!options.endpoint) {
		return null;
	}

	const endpoint = ensurePathSuffix(options.endpoint, "/v1/logs");
	return new OTLPLogExporterHttp({
		url: endpoint,
		headers: options.headers,
	});
}

function createSpanProcessor(
	exporter: OpenTelemetryExporterKind,
	options: {
		endpoint?: string;
		headers?: Record<string, string>;
		insecure: boolean;
		protocol: OpenTelemetryProtocol;
	},
): SpanProcessor | null {
	if (exporter === "console") {
		return new SimpleSpanProcessor(new ConsoleSpanExporter());
	}
	if (!options.endpoint) {
		return null;
	}

	const endpoint = ensurePathSuffix(options.endpoint, "/v1/traces");
	return new BatchSpanProcessor(
		new OTLPTraceExporter({
			url: endpoint,
			headers: options.headers,
		}),
	);
}

function createMetricReader(
	exporter: OpenTelemetryExporterKind,
	options: {
		endpoint?: string;
		headers?: Record<string, string>;
		insecure: boolean;
		protocol: OpenTelemetryProtocol;
		interval: number;
		timeout: number;
	},
): MetricReader | null {
	if (exporter === "console") {
		return new PeriodicExportingMetricReader({
			exporter: new ConsoleMetricExporter(),
			exportIntervalMillis: options.interval,
			exportTimeoutMillis: options.timeout,
		});
	}
	if (!options.endpoint) {
		return null;
	}

	const endpoint = ensurePathSuffix(options.endpoint, "/v1/metrics");
	return new PeriodicExportingMetricReader({
		exporter: new OTLPMetricExporterHttp({
			url: endpoint,
			headers: options.headers,
		}),
		exportIntervalMillis: options.interval,
		exportTimeoutMillis: options.timeout,
	});
}

function ensurePathSuffix(endpoint: string, suffix: string): string {
	const url = new URL(endpoint);
	const normalized = url.pathname.endsWith("/")
		? url.pathname.slice(0, -1)
		: url.pathname;
	url.pathname = normalized.endsWith(suffix)
		? normalized
		: `${normalized}${suffix}`;
	return url.toString();
}

import { describe, expect, it, vi } from "vitest";
import { TelemetryLoggerSink } from "./TelemetryLoggerSink";

describe("TelemetryLoggerSink", () => {
	it("logs events and metrics through the provided logger", async () => {
		const logger = {
			debug: vi.fn(),
			log: vi.fn(),
		};
		const sink = new TelemetryLoggerSink({ logger });

		sink.emit("session.started", { sessionId: "s1" });
		sink.emitRequired("user.opt_out", { reason: "manual" });
		sink.recordCounter("cline.session.starts.total", 1, {
			sessionId: "s1",
		});

		expect(logger.log).toHaveBeenCalledWith("telemetry.event", {
			telemetrySink: "TelemetryLoggerSink",
			event: "session.started",
			properties: { sessionId: "s1" },
		});
		expect(logger.log).toHaveBeenCalledWith("telemetry.required_event", {
			telemetrySink: "TelemetryLoggerSink",
			severity: "warn",
			event: "user.opt_out",
			properties: { reason: "manual" },
		});
		expect(logger.debug).toHaveBeenCalledWith("telemetry.metric", {
			telemetrySink: "TelemetryLoggerSink",
			instrument: "counter",
			name: "cline.session.starts.total",
			value: 1,
			attributes: { sessionId: "s1" },
			description: undefined,
			required: false,
		});

		await sink.flush();
		await sink.dispose();
	});
});

import type { BasicLogger } from "@cline/shared";
import type {
	ITelemetryAdapter,
	TelemetryProperties,
} from "./ITelemetryAdapter";

/**
 * {@link ITelemetryAdapter} implementation that forwards telemetry to a {@link BasicLogger}.
 *
 * This is intentionally named *Sink* (not "adapter") to distinguish it from host logging bridges
 * such as the CLI Pino bundle: it consumes telemetry events and writes them to the injected logger.
 */
export interface TelemetryLoggerSinkOptions {
	logger?: BasicLogger;
	name?: string;
	enabled?: boolean | (() => boolean);
}

export class TelemetryLoggerSink implements ITelemetryAdapter {
	readonly name: string;

	private readonly logger?: BasicLogger;
	private readonly enabled: boolean | (() => boolean);

	constructor(options: TelemetryLoggerSinkOptions = {}) {
		this.name = options.name ?? "TelemetryLoggerSink";
		this.logger = options.logger;
		this.enabled = options.enabled ?? true;
	}

	emit(event: string, properties?: TelemetryProperties): void {
		if (!this.isEnabled()) {
			return;
		}
		this.logger?.log("telemetry.event", {
			telemetrySink: this.name,
			event,
			properties,
		});
	}

	emitRequired(event: string, properties?: TelemetryProperties): void {
		this.logger?.log("telemetry.required_event", {
			telemetrySink: this.name,
			severity: "warn",
			event,
			properties,
		});
	}

	recordCounter(
		name: string,
		value: number,
		attributes?: TelemetryProperties,
		description?: string,
		required?: boolean,
	): void {
		if (!required && !this.isEnabled()) {
			return;
		}
		this.logger?.debug("telemetry.metric", {
			telemetrySink: this.name,
			instrument: "counter",
			name,
			value,
			attributes,
			description,
			required: required === true,
		});
	}

	recordHistogram(
		name: string,
		value: number,
		attributes?: TelemetryProperties,
		description?: string,
		required?: boolean,
	): void {
		if (!required && !this.isEnabled()) {
			return;
		}
		this.logger?.debug("telemetry.metric", {
			telemetrySink: this.name,
			instrument: "histogram",
			name,
			value,
			attributes,
			description,
			required: required === true,
		});
	}

	recordGauge(
		name: string,
		value: number | null,
		attributes?: TelemetryProperties,
		description?: string,
		required?: boolean,
	): void {
		if (!required && !this.isEnabled()) {
			return;
		}
		this.logger?.debug("telemetry.metric", {
			telemetrySink: this.name,
			instrument: "gauge",
			name,
			value,
			attributes,
			description,
			required: required === true,
		});
	}

	isEnabled(): boolean {
		return typeof this.enabled === "function" ? this.enabled() : this.enabled;
	}

	async flush(): Promise<void> {}

	async dispose(): Promise<void> {}
}

import type { BasicLogger } from "@cline/shared";
import { describe, expect, it, vi } from "vitest";
import type { ITelemetryAdapter } from "./ITelemetryAdapter";
import { TelemetryService } from "./TelemetryService";

describe("TelemetryService", () => {
	it("merges metadata and forwards calls to adapters", async () => {
		const { adapter, emit, recordCounter } = createAdapter();
		const service = new TelemetryService({
			adapters: [adapter],
			metadata: {
				extension_version: "1.2.3",
				cline_type: "cli",
			},
			distinctId: "distinct-1",
			commonProperties: {
				organization_id: "org-1",
			},
		});

		service.capture({
			event: "session.started",
			properties: { sessionId: "session-1" },
		});
		service.recordCounter("cline.session.starts.total", 1, {
			sessionId: "session-1",
		});
		await service.flush();
		await service.dispose();

		expect(emit).toHaveBeenCalledWith(
			"session.started",
			expect.objectContaining({
				sessionId: "session-1",
				organization_id: "org-1",
				extension_version: "1.2.3",
				cline_type: "cli",
				distinct_id: "distinct-1",
			}),
		);
		expect(recordCounter).toHaveBeenCalledWith(
			"cline.session.starts.total",
			1,
			expect.objectContaining({
				sessionId: "session-1",
				distinct_id: "distinct-1",
			}),
			undefined,
			false,
		);
	});

	it("mirrors telemetry events into the logger when provided", () => {
		const logger: BasicLogger = {
			debug: vi.fn(),
			log: vi.fn(),
			error: vi.fn(),
		};
		const service = new TelemetryService({
			logger,
			metadata: {
				extension_version: "1.2.3",
				cline_type: "cli",
			},
			distinctId: "distinct-1",
		});

		service.capture({
			event: "session.started",
			properties: { sessionId: "session-1" },
		});
		service.captureRequired("user.opt_out", { reason: "manual" });
		service.recordCounter("cline.session.starts.total", 1, {
			sessionId: "session-1",
		});

		expect(logger.log).toHaveBeenCalledWith(
			"telemetry.event",
			expect.objectContaining({
				telemetrySink: "TelemetryLoggerSink",
				event: "session.started",
				properties: expect.objectContaining({
					sessionId: "session-1",
					extension_version: "1.2.3",
					distinct_id: "distinct-1",
				}),
			}),
		);
		expect(logger.log).toHaveBeenCalledWith(
			"telemetry.required_event",
			expect.objectContaining({
				telemetrySink: "TelemetryLoggerSink",
				severity: "warn",
				event: "user.opt_out",
				properties: expect.objectContaining({
					reason: "manual",
					extension_version: "1.2.3",
				}),
			}),
		);
		expect(logger.debug).toHaveBeenCalledWith(
			"telemetry.metric",
			expect.objectContaining({
				telemetrySink: "TelemetryLoggerSink",
				instrument: "counter",
				name: "cline.session.starts.total",
			}),
		);
	});
});

function createAdapter(): {
	adapter: ITelemetryAdapter;
	emit: ReturnType<typeof vi.fn>;
	recordCounter: ReturnType<typeof vi.fn>;
} {
	const emit = vi.fn();
	const recordCounter = vi.fn();
	return {
		adapter: {
			name: "test",
			emit,
			emitRequired: vi.fn(),
			recordCounter,
			recordHistogram: vi.fn(),
			recordGauge: vi.fn(),
			isEnabled: vi.fn(() => true),
			flush: vi.fn().mockResolvedValue(undefined),
			dispose: vi.fn().mockResolvedValue(undefined),
		},
		emit,
		recordCounter,
	};
}

import type {
	BasicLogger,
	ITelemetryService,
	TelemetryMetadata,
	TelemetryProperties,
} from "@cline/shared";
import type { ITelemetryAdapter } from "./ITelemetryAdapter";
import { TelemetryLoggerSink } from "./TelemetryLoggerSink";

export interface TelemetryServiceOptions {
	adapters?: ITelemetryAdapter[];
	metadata?: Partial<TelemetryMetadata>;
	distinctId?: string;
	commonProperties?: TelemetryProperties;
	logger?: BasicLogger;
}

export class TelemetryService implements ITelemetryService {
	private adapters: ITelemetryAdapter[];
	private metadata: Partial<TelemetryMetadata>;
	private distinctId?: string;
	private commonProperties: TelemetryProperties;

	constructor(options: TelemetryServiceOptions = {}) {
		this.adapters = [...(options.adapters ?? [])];
		if (options.logger) {
			this.adapters.push(new TelemetryLoggerSink({ logger: options.logger }));
		}
		this.metadata = { ...(options.metadata ?? {}) };
		this.distinctId = options.distinctId;
		this.commonProperties = { ...(options.commonProperties ?? {}) };
	}

	addAdapter(adapter: ITelemetryAdapter): void {
		this.adapters.push(adapter);
	}

	setDistinctId(distinctId?: string): void {
		this.distinctId = distinctId;
	}

	setMetadata(metadata: Partial<TelemetryMetadata>): void {
		this.metadata = { ...metadata };
	}

	updateMetadata(metadata: Partial<TelemetryMetadata>): void {
		this.metadata = {
			...this.metadata,
			...metadata,
		};
	}

	setCommonProperties(properties: TelemetryProperties): void {
		this.commonProperties = { ...properties };
	}

	updateCommonProperties(properties: TelemetryProperties): void {
		this.commonProperties = {
			...this.commonProperties,
			...properties,
		};
	}

	isEnabled(): boolean {
		return this.adapters.some((adapter) => adapter.isEnabled());
	}

	capture(input: { event: string; properties?: TelemetryProperties }): void {
		const properties = this.buildAttributes(input.properties);
		for (const adapter of this.adapters) {
			adapter.emit(input.event, properties);
		}
	}

	captureRequired(event: string, properties?: TelemetryProperties): void {
		const merged = this.buildAttributes(properties);
		for (const adapter of this.adapters) {
			adapter.emitRequired(event, merged);
		}
	}

	recordCounter(
		name: string,
		value: number,
		attributes?: TelemetryProperties,
		description?: string,
		required = false,
	): void {
		const merged = this.buildAttributes(attributes);
		for (const adapter of this.adapters) {
			adapter.recordCounter(name, value, merged, description, required);
		}
	}

	recordHistogram(
		name: string,
		value: number,
		attributes?: TelemetryProperties,
		description?: string,
		required = false,
	): void {
		const merged = this.buildAttributes(attributes);
		for (const adapter of this.adapters) {
			adapter.recordHistogram(name, value, merged, description, required);
		}
	}

	recordGauge(
		name: string,
		value: number | null,
		attributes?: TelemetryProperties,
		description?: string,
		required = false,
	): void {
		const merged = this.buildAttributes(attributes);
		for (const adapter of this.adapters) {
			adapter.recordGauge(name, value, merged, description, required);
		}
	}

	async flush(): Promise<void> {
		await Promise.all(this.adapters.map((adapter) => adapter.flush()));
	}

	async dispose(): Promise<void> {
		await Promise.all(this.adapters.map((adapter) => adapter.dispose()));
	}

	private buildAttributes(
		properties?: TelemetryProperties,
	): TelemetryProperties {
		return {
			...this.commonProperties,
			...properties,
			...this.metadata,
			...(this.distinctId ? { distinct_id: this.distinctId } : {}),
		};
	}
}

