import type { MessageWithMetadata } from "@cline/llms";
import { describe, expect, it } from "vitest";
import { getCurrentContextSize, summarizeUsageFromMessages } from "./usage";

function assistant(
	metrics?: MessageWithMetadata["metrics"],
): MessageWithMetadata {
	return {
		role: "assistant",
		content: "ok",
		...(metrics ? { metrics } : {}),
	};
}

function user(): MessageWithMetadata {
	return { role: "user", content: "hi" };
}

describe("getCurrentContextSize", () => {
	it("returns undefined when there is no assistant message", () => {
		expect(getCurrentContextSize([user()])).toBeUndefined();
		expect(getCurrentContextSize([])).toBeUndefined();
	});

	it("returns undefined when the latest assistant message has no metrics", () => {
		expect(getCurrentContextSize([user(), assistant()])).toBeUndefined();
	});

	it("uses the latest assistant call's inputTokens", () => {
		const messages: MessageWithMetadata[] = [
			user(),
			assistant({ inputTokens: 100, outputTokens: 10 }),
			user(),
			assistant({ inputTokens: 5000, outputTokens: 50 }),
		];

		expect(getCurrentContextSize(messages)).toBe(5000);
	});

	it("ignores user messages after the latest assistant message", () => {
		expect(
			getCurrentContextSize([assistant({ inputTokens: 250 }), user()]),
		).toBe(250);
	});

	it("returns undefined when inputTokens is zero", () => {
		expect(
			getCurrentContextSize([assistant({ inputTokens: 0, outputTokens: 0 })]),
		).toBeUndefined();
	});

	it("does not double-count cache token details", () => {
		expect(
			getCurrentContextSize([
				assistant({ inputTokens: 9096, cacheReadTokens: 9090 }),
			]),
		).toBe(9096);
		expect(
			getCurrentContextSize([
				assistant({ inputTokens: 6538, cacheWriteTokens: 6535 }),
			]),
		).toBe(6538);
	});
});

describe("summarizeUsageFromMessages", () => {
	it("sums additive per-message cost", () => {
		expect(
			summarizeUsageFromMessages([
				assistant({ inputTokens: 100, outputTokens: 10, cost: 0.01 }),
				assistant({ inputTokens: 200, outputTokens: 20, cost: 0.02 }),
			]).totalCost,
		).toBe(0.03);
	});
});

import type * as LlmsProviders from "@cline/llms";
import type { SessionAccumulatedUsage } from "../runtime/host/runtime-host";

export function createInitialAccumulatedUsage(): SessionAccumulatedUsage {
	return {
		inputTokens: 0,
		outputTokens: 0,
		cacheReadTokens: 0,
		cacheWriteTokens: 0,
		totalCost: 0,
	};
}

export function accumulateUsageTotals(
	baseline: SessionAccumulatedUsage,
	usage: {
		inputTokens?: number;
		outputTokens?: number;
		cacheReadTokens?: number;
		cacheWriteTokens?: number;
		totalCost?: number;
	},
): SessionAccumulatedUsage {
	return {
		inputTokens: baseline.inputTokens + Math.max(0, usage.inputTokens ?? 0),
		outputTokens: baseline.outputTokens + Math.max(0, usage.outputTokens ?? 0),
		cacheReadTokens:
			baseline.cacheReadTokens + Math.max(0, usage.cacheReadTokens ?? 0),
		cacheWriteTokens:
			baseline.cacheWriteTokens + Math.max(0, usage.cacheWriteTokens ?? 0),
		totalCost: baseline.totalCost + Math.max(0, usage.totalCost ?? 0),
	};
}

export function sumUsageTotals(
	usages: Iterable<SessionAccumulatedUsage>,
): SessionAccumulatedUsage {
	let total = createInitialAccumulatedUsage();
	for (const usage of usages) {
		total = accumulateUsageTotals(total, usage);
	}
	return total;
}

function asNumber(value: unknown): number {
	return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

export function summarizeUsageFromMessages(
	messages: LlmsProviders.Message[],
): SessionAccumulatedUsage {
	let usage = createInitialAccumulatedUsage();
	for (const message of messages) {
		const metrics = (message as LlmsProviders.MessageWithMetadata).metrics;
		if (!metrics) {
			continue;
		}
		usage = accumulateUsageTotals(usage, {
			inputTokens: asNumber(metrics.inputTokens),
			outputTokens: asNumber(metrics.outputTokens),
			cacheReadTokens: asNumber(metrics.cacheReadTokens),
			cacheWriteTokens: asNumber(metrics.cacheWriteTokens),
			totalCost: asNumber(metrics.cost),
		});
	}
	return usage;
}

/**
 * Current model context-window usage, derived from the latest assistant LLM
 * call. Provider usage is normalized so `inputTokens` is already the full
 * prompt size, including any cache-read/cache-write portions. Do not add cache
 * fields back on top.
 */
export function getCurrentContextSize(
	messages: readonly LlmsProviders.Message[],
): number | undefined {
	for (let i = messages.length - 1; i >= 0; i -= 1) {
		const message = messages[i] as
			| LlmsProviders.MessageWithMetadata
			| undefined;
		if (message?.role !== "assistant") continue;
		const inputTokens = asNumber(message.metrics?.inputTokens);
		return inputTokens > 0 ? inputTokens : undefined;
	}
	return undefined;
}

