import type { SqliteSessionStore } from "../../services/storage/sqlite-session-store";
import type { SessionMessagesArtifactUploader } from "../../types/session";
import {
	type CreateRootSessionInput,
	patchSqliteRow,
	SESSION_SELECT_COLUMNS,
	type SessionRow,
	stringifyMetadata,
