export interface CoreSessionCheckpointSnapshot {
	enabled?: boolean;
	latest?: CheckpointEntry;
	history: CheckpointEntry[];
}

export interface CoreSessionSnapshot {
	version: 1;
	sessionId: string;
	source: SessionRecord["source"];
	status: SessionRecord["status"];
	createdAt: string;
	updatedAt: string;
	endedAt?: string | null;
	exitCode?: number | null;
	interactive: boolean;
	workspace: {
		cwd: string;
		root: string;
	};
	model: {
		providerId: string;
		modelId: string;
	};
	capabilities: {
		enableTools: boolean;
		enableSpawn: boolean;
		enableTeams: boolean;
	};
	lineage: {
		parentSessionId?: string;
		parentAgentId?: string;
		agentId?: string;
